async function generateUniqueCode(prefix: string, table: string, column: string, tenantId: number): Promise<string> {
  const { rows } = await pool.query(
    `SELECT ${column} FROM ${table} WHERE ${column} IS NOT NULL AND tenant_id = $1 ORDER BY id DESC LIMIT 1`,
    [tenantId]
  );
  let nextNum = 1;
  if (rows.length > 0 && rows[0][column]) {
    const match = rows[0][column].match(/(\d+)$/);
    if (match) nextNum = parseInt(match[1]) + 1;
  }
  return `${prefix}${nextNum.toString().padStart(5, "0")}`;
}

function findApplicableRate(rateCards: any[], shiftDate: Date, siteId: number | null, employeeId: number | null): any | null {
  const candidates = rateCards.filter(rc => {
    const from = new Date(rc.effectiveFrom);
    const to = rc.effectiveTo ? new Date(rc.effectiveTo) : new Date("2099-12-31");
    if (shiftDate < from || shiftDate > to) return false;
    if (rc.siteId && rc.siteId !== siteId) return false;
    if (rc.employeeId && rc.employeeId !== employeeId) return false;
    return true;
  });

  const scored = candidates.map(rc => {
    let score = 0;
    if (rc.employeeId && rc.siteId) score = 4;
    else if (rc.employeeId) score = 3;
    else if (rc.siteId) score = 2;
    else score = 1;
    return { rc, score };
  });

  scored.sort((a, b) => b.score - a.score);
  return scored.length > 0 ? scored[0].rc : null;
}

function getClientMeta(req: Request): { ipAddress: string | null; userAgent: string | null } {
  const ip = (req.headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() || req.socket?.remoteAddress || null;
  const userAgent = (req.headers["user-agent"] as string) || null;
  return { ipAddress: ip || null, userAgent };
}

