function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (req.isAuthenticated()) return next();
  if ((req as any).user && (req as any).jwtAuth) return next();
  res.status(401).json({ message: "Unauthorized" });
}

function validatePassword(password: string): { valid: boolean; message: string } {
  if (!password || password.length < 8) return { valid: false, message: "Password must be at least 8 characters long" };
  if (!/[A-Z]/.test(password)) return { valid: false, message: "Password must contain at least one uppercase letter" };
  if (!/[a-z]/.test(password)) return { valid: false, message: "Password must contain at least one lowercase letter" };
  if (!/[0-9]/.test(password)) return { valid: false, message: "Password must contain at least one number" };
  return { valid: true, message: "" };
}

function requireRole(...roles: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const isSession = req.isAuthenticated();
    const isJwt = (req as any).user && (req as any).jwtAuth;
    if (!isSession && !isJwt) return res.status(401).json({ message: "Unauthorized" });
    const user = (req as any).user as User;
    if (!roles.includes(user.role)) return res.status(403).json({ message: "Forbidden" });
    next();
  };
}

async function archiveCurrentAgreement(supplierId: number, reason: string): Promise<boolean> {
  const supplier = await storage.getSupplier(supplierId);
  if (!supplier || supplier.selfBillingAgreementStatus !== "active") return false;

  const tenant = await storage.getTenant(supplier.tenantId);
  const defaultTemplate = tenant ? await storage.getDefaultTemplate(tenant.id, "self_billing_agreement") : null;

  await storage.createAgreementArchive({
    tenantId: supplier.tenantId,
    supplierId: supplier.id,
    agreementRef: supplier.selfBillingAgreementRef,
    signatoryName: supplier.selfBillingSignatoryName,
    signatoryPosition: supplier.selfBillingSignatoryPosition,
    signedAt: supplier.selfBillingAcceptedAt,
    expiryDate: supplier.selfBillingExpiryDate,
    signatureData: supplier.selfBillingSignatureData,
    signedIp: supplier.selfBillingSignedIp,
    archivedReason: reason,
    templateId: defaultTemplate?.id ?? null,
    buyerSignatoryName: tenant?.selfBillingSignatoryName ?? null,
    buyerSignatoryPosition: tenant?.selfBillingSignatoryPosition ?? null,
    buyerSignatureData: tenant?.selfBillingSignatureData ?? null,
  });

  await storage.updateSupplier(supplierId, {
    selfBillingAgreementStatus: "none",
    selfBillingSignatoryName: null,
    selfBillingSignatoryPosition: null,
    selfBillingAcceptedAt: null,
    selfBillingExpiryDate: null,
    selfBillingSignatureData: null,
    selfBillingSignedIp: null,
    selfBillingAgreementRef: null,
  });

  return true;
}

function generateAgreementRef(signingDate: Date): string {
  const randomAlphaNum = () => Math.random().toString(36).substring(2, 8).toUpperCase();
  const dateStr = `${signingDate.getFullYear()}${String(signingDate.getMonth() + 1).padStart(2, "0")}${String(signingDate.getDate()).padStart(2, "0")}`;
  return `SBA-${randomAlphaNum()}-${dateStr}-${randomAlphaNum()}`;
}

function haversineDistanceMetres(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371000;
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function buildSupplierAddress(address?: string | null, city?: string | null, postcode?: string | null): string {
  if (!address) return [city, postcode].filter(Boolean).join(", ");
  const addr = address.trim();
  const parts = [addr];
  if (city && !addr.toLowerCase().includes(city.toLowerCase())) parts.push(city);
  if (postcode && !addr.includes(postcode)) parts.push(postcode);
  return parts.filter(Boolean).join(", ");
}

function getSupplierAddressForPeriod(supplier: any, _invoicePeriodEnd: string): string {
  const hasAgreementAddr = !!supplier.agreementRegisteredAddress;
  const hasCurrentAddr = !!supplier.registeredOfficeAddress;

  if (hasAgreementAddr) {
    return buildSupplierAddress(supplier.agreementRegisteredAddress, supplier.agreementRegisteredCity, supplier.agreementRegisteredPostcode);
  }

  if (hasCurrentAddr) {
    return buildSupplierAddress(supplier.registeredOfficeAddress, supplier.registeredOfficeCity, supplier.registeredOfficePostcode);
  }

  return buildSupplierAddress(supplier.address, supplier.city, supplier.postcode);
}

