  app.get("/api/subdomain-check/:subdomain", async (req, res) => {
    try {
      const { subdomain } = req.params;
      const normalized = subdomain.toLowerCase().replace(/[^a-z0-9-]/g, "");
      if (normalized.length < 3) return res.json({ available: false, reason: "Must be at least 3 characters" });
      if (normalized.length > 30) return res.json({ available: false, reason: "Must be 30 characters or less" });
      const reserved = ["app", "api", "admin", "www", "mail", "ftp", "test", "staging", "demo"];
      if (reserved.includes(normalized)) return res.json({ available: false, reason: "This subdomain is reserved" });
      const existing = await storage.getTenantBySubdomain(normalized);
      res.json({ available: !existing, subdomain: normalized });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/tenant-onboarding", async (req, res) => {
    try {
      const { account, company, subdomain, planId, teamMembers } = req.body;
      if (!account?.email || !account?.password || !account?.firstName || !account?.lastName) {
        return res.status(400).json({ message: "Account details are required" });
      }
      if (!company?.name) return res.status(400).json({ message: "Company name is required" });
      const pwCheck = validatePassword(account.password);
      if (!pwCheck.valid) return res.status(400).json({ message: pwCheck.message });

      if (subdomain) {
        const existingSub = await storage.getTenantBySubdomain(subdomain);
        if (existingSub) return res.status(400).json({ message: "Subdomain already taken" });
      }

      const slug = subdomain || company.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
      const trialEndsAt = new Date();
      trialEndsAt.setDate(trialEndsAt.getDate() + 14);

      const tenant = await storage.createTenant({
        name: company.name,
        tradingName: company.tradingName || null,
        slug,
        subdomain: subdomain || null,
        industry: "security",
        addressLine1: company.addressLine1 || null,
        addressLine2: company.addressLine2 || null,
        city: company.city || null,
        county: company.county || null,
        postcode: company.postcode || null,
        phone: company.phone || null,
        email: account.email,
        website: company.website || null,
        companyRegNumber: company.companyRegNumber || null,
        companyStatus: company.companyStatus || null,
        vatNumber: company.vatNumber || null,
        siaAcsNumber: company.siaAcsNumber || null,
        planId: planId || null,
        trialEndsAt,
        onboardingCompleted: true,
      });

      const hashed = await bcrypt.hash(account.password, 10);
      const username = account.username || account.email.split("@")[0];
      const user = await storage.createUser({
        username,
        email: account.email.trim().toLowerCase(),
        password: hashed,
        firstName: account.firstName,
        lastName: account.lastName,
        role: "tenant_admin",
        tenantId: tenant.id,
      });

      if (teamMembers && Array.isArray(teamMembers)) {
        for (const member of teamMembers) {
          if (!member.email) continue;
          const token = crypto.randomUUID();
          const expiresAt = new Date();
          expiresAt.setDate(expiresAt.getDate() + 7);
          await storage.createTenantInvitation({
            tenantId: tenant.id,
            email: member.email,
            firstName: member.firstName || null,
            lastName: member.lastName || null,
            role: member.role || "employee",
            token,
            invitedBy: user.id,
            expiresAt,
          });
        }
      }

      req.login(user, (err) => {
        if (err) return res.status(500).json({ message: "Account created but login failed" });
        const { password: _, ...safeUser } = user;
        res.status(201).json({ user: safeUser, tenant });
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

