  app.post("/api/employee/request-change", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee not found" });
      const { changeType, details } = req.body;
      if (!changeType || !details) return res.status(400).json({ message: "changeType and details are required" });
      const allowedChangeTypes = ["phone", "address"];
      if (!allowedChangeTypes.includes(changeType)) return res.status(400).json({ message: "Invalid change type" });
      const detailsStr = Object.entries(details).map(([k, v]) => `${k}: ${v}`).join(", ");
      await pool.query(
        `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
         VALUES ($1, $2, 'profile_change_request', 'profile', $3, $4, $5, $6)`,
        [employee.id, user.tenantId, `Profile Change Request: ${changeType}`, `Employee requested ${changeType} change. Details: ${detailsStr}`, user.id, `${user.firstName || ""} ${user.lastName || ""}`.trim()]
      );
      const admins = await pool.query(
        `SELECT u.id FROM users u WHERE u.tenant_id = $1 AND u.role = 'admin' LIMIT 5`,
        [user.tenantId]
      );
      for (const admin of admins.rows) {
        await storage.createNotification({
          userId: admin.id,
          type: "profile_change_request",
          title: `Profile Change Request from ${user.firstName || ""} ${user.lastName || ""}`.trim(),
          body: `Employee requested ${changeType} change. Details: ${detailsStr}`,
          relatedId: employee.id.toString(),
        });
      }
      res.json({ message: "Change request submitted successfully.", status: "pending" });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

