  // HR Admin onboarding management
  app.get("/api/admin/onboardings", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "compliance_manager", "training_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json([]);
      const records = await storage.getOnboardingsByTenant(user.tenantId);
      const now = new Date();
      const enriched = await Promise.all(records.map(async (r) => {
        const empUser = r.userId ? await storage.getUser(r.userId) : null;
        let urgency: "on_track" | "approaching" | "overdue" = "on_track";
        let daysUntilDeadline: number | null = null;
        const activeStatuses = ["invited", "in_progress"];
        if (r.deadline && activeStatuses.includes(r.status || "")) {
          const msUntil = r.deadline.getTime() - now.getTime();
          daysUntilDeadline = Math.ceil(msUntil / (1000 * 60 * 60 * 24));
          if (daysUntilDeadline <= 0) urgency = "overdue";
          else if (daysUntilDeadline <= 3) urgency = "approaching";
          else urgency = "on_track";
        }
        return {
          ...r,
          employeeName: empUser ? `${empUser.firstName} ${empUser.lastName}` : "Unknown",
          employeeEmail: empUser?.email || "",
          urgency,
          daysUntilDeadline,
        };
      }));
      res.json(enriched);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.patch("/api/admin/onboardings/:id/review", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "compliance_manager", "training_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const record = await storage.getOnboardingRecord(id);
      if (!record) return res.status(404).json({ message: "Onboarding record not found" });
      if (record.tenantId !== user.tenantId) return res.status(403).json({ message: "Forbidden" });
      const { status, reviewNotes } = req.body;
      const updated = await storage.updateOnboarding(id, {
        status, reviewNotes, reviewedBy: user.id, reviewedAt: new Date(),
        ...(status === "completed" ? { completedAt: new Date() } : {}),
      });
      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: `onboarding_${status}`, entityType: "onboarding",
        entityId: String(id), details: { reviewNotes },
      });

      if (status === "completed" && record.userId && record.tenantId) {
        const employee = await storage.getEmployeeByUserId(record.userId);
        if (employee) {
          const NEW_STARTER_POLICIES = [
            { policyName: "Lone Worker Policy", policyType: "lone_worker" },
            { policyName: "GDPR & Data Protection Policy", policyType: "gdpr" },
            { policyName: "Company Handbook", policyType: "handbook" },
          ];
          for (const policy of NEW_STARTER_POLICIES) {
            const existing = await pool.query(
              "SELECT id FROM employee_policies WHERE employee_id = $1 AND policy_type = $2 AND tenant_id = $3 LIMIT 1",
              [employee.id, policy.policyType, record.tenantId]
            );
            if (existing.rows.length === 0) {
              await pool.query(
                `INSERT INTO employee_policies (employee_id, tenant_id, policy_name, policy_type, version, issued_by, notes)
                 VALUES ($1, $2, $3, $4, $5, $6, $7)`,
                [employee.id, record.tenantId, policy.policyName, policy.policyType, "1.0", user.id, "Auto-issued on onboarding approval"]
              );
            }
          }
          await storage.createAuditLog({
            tenantId: record.tenantId, userId: user.id,
            action: "new_starter_policy_pack_issued", entityType: "employee",
            entityId: String(employee.id), details: { policies: NEW_STARTER_POLICIES.map(p => p.policyName) },
          });
        }
      }

      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

