  app.post("/api/bank-details/request-change", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee not found" });
      const { accountName, bankName, sortCode, accountNumber, buildingSocietyRef } = req.body;
      if (!accountName || !bankName || !sortCode || !accountNumber) {
        return res.status(400).json({ message: "Account name, bank name, sort code, and account number are required" });
      }

      const pending = await storage.createPendingBankChange({
        employeeId: employee.id,
        requestedByUserId: user.id,
        accountName,
        bankName,
        sortCode,
        accountNumber,
        buildingSocietyRef: buildingSocietyRef || null,
        status: "pending",
        reviewedByUserId: null,
        reviewedAt: null,
        reviewNote: null,
      });

      await pool.query(
        `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
         VALUES ($1, $2, 'bank_change_requested', 'profile', $3, $4, $5, $6)`,
        [employee.id, user.tenantId, 'Bank Details Change Requested', `Employee requested bank details update. Pending admin approval. Bank: ${bankName}, Account: ****${accountNumber.slice(-4)}`, user.id, `${(user as any).firstName || ""} ${(user as any).lastName || ""}`.trim()]
      ).catch(() => {});

      const adminUsers = user.tenantId ? await storage.getUsersByTenant(user.tenantId) : [];
      const admins = adminUsers.filter((u: any) => ["super_admin","tenant_admin","ceo","hr_manager","payroll_manager"].includes(u.role));
      const employeeName = `${(user as any).firstName || ""} ${(user as any).lastName || ""}`.trim() || "An employee";
      for (const admin of admins) {
        await storage.createNotification({
          userId: admin.id,
          type: "bank_change_request",
          title: "Bank Details Change Request",
          body: `${employeeName} has requested a bank details update. Bank: ${bankName}, Account: ****${accountNumber.slice(-4)}`,
          link: `/admin/employees/${employee.id}`,
          relatedEntityType: "employee",
          relatedEntityId: String(employee.id),
          metadata: { pendingBankChangeId: pending.id, bankName, accountNumber: "****" + accountNumber.slice(-4), employeeId: employee.id, userId: user.id },
        });
      }
      res.json({ message: "Bank details change request submitted. An admin will review and apply the changes.", status: "pending", pendingId: pending.id });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

