  app.post("/api/admin/pending-bank-changes/:id/approve", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      if (!["super_admin","tenant_admin","ceo","hr_manager","payroll_manager","admin"].includes((user as any).role)) {
        return res.status(403).json({ message: "Forbidden" });
      }
      const id = parseInt(req.params.id);
      const { note } = req.body;

      const existing = await storage.getPendingBankChange(id);
      if (!existing) return res.status(404).json({ message: "Pending bank change not found" });
      if (existing.status !== "pending") {
        return res.status(409).json({ message: `Bank change request has already been ${existing.status}` });
      }
      if ((user as any).role !== "super_admin" && user.tenantId) {
        const { rows: empRows } = await pool.query("SELECT tenant_id FROM employees WHERE id = $1", [existing.employeeId]);
        if (!empRows.length || empRows[0].tenant_id !== user.tenantId) {
          return res.status(403).json({ message: "Forbidden: cross-tenant access denied" });
        }
      }

      const change = await storage.approvePendingBankChange(id, user.id, note);
      if (!change) return res.status(404).json({ message: "Pending bank change not found" });

      await storage.createNotification({
        userId: change.requestedByUserId,
        type: "bank_change_request",
        title: "Bank Details Update Approved",
        body: `Your bank details change request has been approved and applied to your account.`,
        link: "/my-profile",
        relatedEntityType: "employee",
        relatedEntityId: String(change.employeeId),
        metadata: { status: "approved", reviewedBy: user.id },
      });

      await pool.query(
        `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
         VALUES ($1, $2, 'bank_change_approved', 'profile', $3, $4, $5, $6)`,
        [change.employeeId, user.tenantId, 'Bank Details Change Approved', `Admin approved bank details change request #${id}${note ? `: ${note}` : ""}`, user.id, `${(user as any).firstName || ""} ${(user as any).lastName || ""}`.trim()]
      ).catch(() => {});

      res.json({ message: "Bank change approved and applied", change });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

