  app.get("/api/employee/notifications/trigger", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.json({ triggered: 0 });
      let triggered = 0;
      const now = new Date();
      const in24h = new Date(now.getTime() + 24 * 60 * 60 * 1000);
      const shifts = await storage.getShiftsByEmployee(employee.id);
      for (const shift of shifts) {
        if (shift.status !== "scheduled") continue;
        const shiftDate = new Date(shift.date);
        const [h, m] = (shift.startTime || "00:00").split(":").map(Number);
        shiftDate.setHours(h, m, 0, 0);
        if (shiftDate > now && shiftDate <= in24h) {
          const existing = await pool.query(
            `SELECT id FROM notifications WHERE user_id = $1 AND type = 'shift_reminder' AND metadata->>'shiftId' = $2 AND created_at > NOW() - INTERVAL '23 hours'`,
            [user.id, String(shift.id)]
          );
          if (existing.rows.length === 0) {
            const site = shift.siteId ? await storage.getSite(shift.siteId) : null;
            await storage.createNotification({
              userId: user.id,
              type: "shift_reminder",
              title: "Shift Starting Soon",
              body: `Your shift "${shift.title || "Shift"}" starts at ${shift.startTime} tomorrow${site ? ` at ${site.name}` : ""}.`,
              link: "/my-shifts",
              relatedEntityType: "shift",
              relatedEntityId: String(shift.id),
              metadata: { shiftId: shift.id, shiftDate: shift.date, startTime: shift.startTime },
            });
            triggered++;
          }
        }
      }
      const docs = await storage.getDocuments(employee.id);
      const in30Days = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
      for (const doc of docs) {
        if (!doc.expiryDate) continue;
        const expiry = new Date(doc.expiryDate);
        if (expiry > now && expiry <= in30Days) {
          const existing = await pool.query(
            `SELECT id FROM notifications WHERE user_id = $1 AND type = 'document_expiry' AND metadata->>'documentId' = $2 AND created_at > NOW() - INTERVAL '6 days'`,
            [user.id, String(doc.id)]
          );
          if (existing.rows.length === 0) {
            const daysLeft = Math.ceil((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
            await storage.createNotification({
              userId: user.id,
              type: "document_expiry",
              title: "Document Expiring Soon",
              body: `Your ${doc.documentType.replace(/_/g, " ")} document expires in ${daysLeft} day${daysLeft !== 1 ? "s" : ""}. Please upload a replacement.`,
              link: "/my-documents",
              relatedEntityType: "document",
              relatedEntityId: String(doc.id),
              metadata: { documentId: doc.id, documentType: doc.documentType, expiryDate: doc.expiryDate, daysLeft },
            });
            triggered++;
          }
        }
      }
      res.json({ triggered });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

