  app.post("/api/admin/employees/:id/send-invitation", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const tenantFilter = user.role !== "super_admin" ? user.tenantId! : undefined;
      const employee = await storage.getEmployee(id, tenantFilter);
      if (!employee) return res.status(404).json({ message: "Employee not found" });
      if (!employee.portalAccessEnabled) return res.status(400).json({ message: "Portal access is not enabled for this employee" });
      const empUser = employee.userId ? await storage.getUser(employee.userId) : null;
      if (!empUser) return res.status(400).json({ message: "Employee has no user account" });
      const portalEmail = (employee.portalEmail || empUser.email).trim().toLowerCase();
      if (!portalEmail) return res.status(400).json({ message: "No portal email set" });
      const token = crypto.randomBytes(32).toString("hex");
      const effectiveTenantId = user.tenantId ?? employee.tenantId;
      const tenantRecord = effectiveTenantId ? await storage.getTenant(effectiveTenantId) as Tenant | undefined : undefined;
      const defaultDeadlineDays = tenantRecord?.onboardingDeadlineDays ?? 7;
      const expiresAt = new Date(Date.now() + defaultDeadlineDays * 24 * 60 * 60 * 1000);
      const onboardingDeadline = new Date(Date.now() + defaultDeadlineDays * 24 * 60 * 60 * 1000);
      await storage.createEmployeeInvitation({
        employeeId: id,
        email: portalEmail,
        token,
        expiresAt,
        createdBy: user.id,
      });
      await storage.updateEmployee(id, {
        portalInvitationSentAt: new Date(),
        portalInvitationAccepted: false,
      });
      if (empUser.id) {
        let existingOnboarding = await storage.getOnboardingByUserId(empUser.id);
        if (!existingOnboarding) {
          existingOnboarding = await storage.createOnboarding({
            userId: empUser.id,
            tenantId: effectiveTenantId ?? undefined,
            status: "invited",
            currentStep: 1,
            deadline: onboardingDeadline,
          });
        } else {
          await storage.updateOnboarding(existingOnboarding.id, { deadline: onboardingDeadline });
        }
      }
      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: user.tenantId!,
        userId: user.id,
        action: "employee_portal_invitation_sent",
        entityType: "employee",
        entityId: String(id),
        details: { email: portalEmail, expiresAt: expiresAt.toISOString(), deadline: onboardingDeadline.toISOString() },
        ipAddress: meta.ipAddress,
      });
      const inviteLink = `${req.protocol}://${req.get("host") || "localhost"}/accept-invite?token=${token}`;
      res.json({ success: true, message: "Invitation sent successfully", inviteLink, email: portalEmail });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/admin/employees/:id/send-reminder", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const employee = await storage.getEmployee(id);
      if (!employee) return res.status(404).json({ message: "Employee not found" });
      if (user.tenantId != null && employee.tenantId !== user.tenantId) return res.status(404).json({ message: "Employee not found" });
      const alreadyAccepted = await storage.hasEmployeeAcceptedAnyInvitation(id);
      if (alreadyAccepted) return res.status(400).json({ message: "Employee has already accepted the invitation" });
      const latest = await storage.getLatestEmployeeInvitation(id);
      if (!latest) return res.status(400).json({ message: "No invitation found. Send an invitation first." });
      const token = crypto.randomBytes(32).toString("hex");
      const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
      await storage.updateEmployeeInvitation(latest.id, { token, expiresAt, reminderSentAt: new Date() } as any);
      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: user.tenantId!,
        userId: user.id,
        action: "employee_portal_reminder_sent",
        entityType: "employee",
        entityId: String(id),
        details: {},
        ipAddress: meta.ipAddress,
      });
      const inviteLink = `${req.protocol}://${req.get("host") || "localhost"}/accept-invite?token=${token}`;
      res.json({ message: "Reminder sent", inviteLink });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/admin/employees/:id/reset-password", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const employee = await storage.getEmployee(id);
      if (!employee) return res.status(404).json({ message: "Employee not found" });
      if (user.tenantId != null && employee.tenantId !== user.tenantId) return res.status(404).json({ message: "Employee not found" });
      if (!employee.userId) return res.status(400).json({ message: "Employee has no portal account yet" });
      const token = crypto.randomBytes(32).toString("hex");
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);
      await storage.deletePasswordResetTokensByUserId(employee.userId);
      await storage.createPasswordResetToken({ userId: employee.userId, token, expiresAt });
      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: user.tenantId!,
        userId: user.id,
        action: "employee_password_reset_requested",
        entityType: "employee",
        entityId: String(id),
        details: {},
        ipAddress: meta.ipAddress,
      });
      const resetLink = `${req.protocol}://${req.get("host") || "localhost"}/reset-password?token=${token}`;
      res.json({ message: "Password reset link created", resetLink });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/admin/employees", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });

      const { firstName, lastName, email, username, phone, jobTitle, department, employmentType, startDate, dateOfBirth, nationalInsurance, gender, nationality, addressLine1, addressLine2, city, county, postcode, country, siaLicenseNumber, siaLicenseType, siaExpiryDate, dbsCertificateNumber, dbsIssueDate, supplierId } = req.body;

      if (!firstName || !lastName || !email || !username) {
        return res.status(400).json({ message: "First name, last name, email, and username are required" });
      }

      const existingUser = await storage.getUserByUsername(username, user.tenantId);
      if (existingUser) return res.status(400).json({ message: "Username already exists" });

      const existingEmail = await storage.getUserByEmail(email, user.tenantId);
      if (existingEmail) return res.status(400).json({ message: "Email already exists" });

      const hashedPassword = await bcrypt.hash("Password123!", 10);
      const newUser = await storage.createUser({
        username,
        password: hashedPassword,
        email,
        firstName,
        lastName,
        phone: phone || null,
        role: "employee",
        tenantId: user.tenantId,
        isActive: true,
      });

      const employee = await storage.createEmployee({
        userId: newUser.id,
        tenantId: user.tenantId,
        supplierId: supplierId ? parseInt(supplierId) : null,
        jobTitle: jobTitle || null,
        department: department || null,
        employmentType: employmentType || "full_time",
        startDate: startDate || null,
        dateOfBirth: dateOfBirth || null,
        nationalInsurance: nationalInsurance || null,
        gender: gender || null,
        nationality: nationality || null,
        addressLine1: addressLine1 || null,
        addressLine2: addressLine2 || null,
        city: city || null,
        county: county || null,
        postcode: postcode || null,
        country: country || "United Kingdom",
        siaLicenseNumber: siaLicenseNumber || null,
        siaLicenseType: siaLicenseType || null,
        siaExpiryDate: siaExpiryDate || null,
        dbsCertificateNumber: dbsCertificateNumber || null,
        dbsIssueDate: dbsIssueDate || null,
      });

      await pool.query(
        `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
         VALUES ($1, $2, 'employee_created', 'onboarding', 'Employee Record Created', $3, $4, $5)`,
        [employee.id, user.tenantId, `Employee ${firstName} ${lastName} added to the system`, user.id, `${(user as any).firstName || ""} ${(user as any).lastName || ""}`.trim()]
      );

      if (startDate) {
        try {
          const tenant = await storage.getTenant(user.tenantId) as any;
          const probationWeeks = tenant?.defaultProbationWeeks ?? 12;
          const start = new Date(startDate);
          const review = new Date(start.getTime() + probationWeeks * 7 * 24 * 60 * 60 * 1000);
          const reviewDate = review.toISOString().split("T")[0];
          await storage.createProbationRecord({
            employeeId: employee.id,
            tenantId: user.tenantId,
            startDate,
            reviewDate,
            status: "active",
          });
        } catch (probErr) {
          console.error("[probation] Failed to auto-create probation record:", probErr);
        }
      }

      res.status(201).json({ ...employee, firstName, lastName, email });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.patch("/api/admin/employees/:id", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const employee = await storage.getEmployee(id);
      if (!employee) return res.status(404).json({ message: "Employee not found" });
      if (user.tenantId != null && employee.tenantId !== user.tenantId) return res.status(404).json({ message: "Employee not found" });

      const { firstName, lastName, email, phone, drivingLicenceNumber, ...employeeFields } = req.body;

      if (firstName !== undefined || lastName !== undefined || email !== undefined || phone !== undefined) {
        if (employee.userId) {
          const userUpdate: Record<string, any> = {};
          if (firstName !== undefined) userUpdate.firstName = firstName;
          if (lastName !== undefined) userUpdate.lastName = lastName;
          if (email !== undefined) userUpdate.email = email;
          if (phone !== undefined) userUpdate.phone = phone || null;
          await storage.updateUser(String(employee.userId), userUpdate);
        }
      }

      const allowedFields = [
        "jobTitle", "department", "employmentType", "startDate", "dateOfBirth",
        "nationalInsurance", "maritalStatus", "gender", "nationality", "placeOfBirth", "addressLine1", "addressLine2",
        "city", "county", "postcode", "country", "supplierId",
        "siaLicenseNumber", "siaLicenseType", "siaExpiryDate",
        "dbsCertificateNumber", "dbsIssueDate", "hasFirstAid", "firstAidExpiry",
        "hourlyRate", "uniformSize", "bootSize", "equipmentNotes", "employeeNumber",
        "officerStep", "vettingStartDate", "vettingCompleteAt", "contractEndDate",
        "sageId", "phone", "secondPhone", "photoUrl", "ethnicOrigin", "paymentType",
        "permitType", "officerType", "livingFrom",
        "previousAddressLine1", "previousAddressLine2", "previousCity", "previousCounty",
        "previousPostcode", "previousLivingFrom", "previousLivingTo", "carOwner",
      ];
      const empUpdate: Record<string, any> = {};
      for (const key of allowedFields) {
        if (employeeFields[key] !== undefined) {
          if (key === "supplierId") {
            empUpdate[key] = employeeFields[key] ? parseInt(employeeFields[key]) : null;
          } else if (key === "hasFirstAid") {
            empUpdate[key] = !!employeeFields[key];
          } else if (key === "officerStep") {
            empUpdate[key] = employeeFields[key] === null || employeeFields[key] === "" ? 0 : parseInt(employeeFields[key]);
          } else if (key === "vettingCompleteAt") {
            empUpdate[key] = employeeFields[key] ? new Date(employeeFields[key]) : null;
          } else {
            empUpdate[key] = employeeFields[key] === "" ? null : employeeFields[key];
          }
        }
      }

      if (Object.keys(empUpdate).length > 0) {
        await storage.updateEmployee(id, empUpdate);
      }

      if (drivingLicenceNumber !== undefined) {
        const extras = await staffProfileStorage.getStaffProfileExtras(id);
        const existing = extras.drivingLicences[0];
        const licenceNumber = typeof drivingLicenceNumber === "string" ? drivingLicenceNumber.trim() : "";
        if (licenceNumber) {
          if (existing) {
            await staffProfileStorage.updateDrivingLicence(existing.id, id, { licenceNumber });
          } else {
            await staffProfileStorage.createDrivingLicence({
              employeeId: id,
              tenantId: employee.tenantId,
              licenceNumber,
            });
          }
        }
      }

      const updatedEmployee = await storage.getEmployee(id);
      const empUser = updatedEmployee?.userId ? await storage.getUser(updatedEmployee.userId) : null;
      let supplierName: string | null = null;
      if (updatedEmployee?.supplierId) {
        const supplier = await storage.getSupplier(updatedEmployee.supplierId);
        supplierName = supplier?.companyName || null;
      }

      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: user.tenantId!,
        userId: user.id,
        action: "employee_updated",
        entityType: "employee",
        entityId: String(id),
        details: { updatedFields: [...Object.keys(empUpdate), ...(firstName !== undefined ? ["firstName"] : []), ...(lastName !== undefined ? ["lastName"] : []), ...(email !== undefined ? ["email"] : []), ...(phone !== undefined ? ["phone"] : [])] },
        ipAddress: meta.ipAddress,
      });

      res.json({
        ...updatedEmployee,
        firstName: empUser?.firstName || "",
        lastName: empUser?.lastName || "",
        email: empUser?.email || "",
        phone: empUser?.phone || "",
        supplierName,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

