  app.get("/api/admin/employees/:id/bs7858", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "hr_manager", "compliance_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });

      const employeeId = parseInt(req.params.id);
      const employee = await storage.getEmployee(employeeId);
      if (!employee || employee.tenantId !== user.tenantId) return res.status(404).json({ message: "Employee not found" });

      const empUser = employee.userId ? await storage.getUser(employee.userId) : null;
      const vetting = await storage.getVettingRecords(employeeId);
      const docs = await storage.getDocuments(employeeId);
      const refs = await storage.getReferences(employeeId);
      const empHistory = await storage.getEmploymentHistory(employeeId);

      const idDocs = docs.filter(d => ["passport", "driving_license", "national_id", "identity", "proof_of_identity"].includes(d.documentType?.toLowerCase() || ""));
      const rtwDocs = docs.filter(d => ["right_to_work", "visa", "work_permit", "biometric_residence"].includes(d.documentType?.toLowerCase() || ""));
      const addressDocs = docs.filter(d => ["proof_of_address", "utility_bill", "council_tax", "bank_statement"].includes(d.documentType?.toLowerCase() || ""));
      const qualDocs = docs.filter(d => ["qualification", "certificate", "training_cert", "sia_license_doc"].includes(d.documentType?.toLowerCase() || ""));

      const dbsCheck = vetting.find(v => v.checkType?.toLowerCase().includes("dbs"));
      const refChecks = vetting.filter(v => v.checkType?.toLowerCase().includes("reference"));
      const creditCheck = vetting.find(v => v.checkType?.toLowerCase().includes("credit"));

      const fiveYearsCovered = empHistory.length > 0;
      const refsCompleted = refs.filter(r => (r as any).status === "verified" || (r as any).status === "completed").length;

      const checks = [
        {
          id: "identity_verification",
          name: "Identity Verification",
          category: "identity",
          status: idDocs.some(d => d.isVerified) ? "passed" : idDocs.length > 0 ? "pending" : "not_started",
          details: idDocs.length > 0 ? `${idDocs.length} document(s) on file${idDocs.some(d => d.isVerified) ? " - verified" : " - awaiting verification"}` : "No identity documents uploaded",
        },
        {
          id: "right_to_work",
          name: "Right to Work (UK)",
          category: "identity",
          status: rtwDocs.some(d => d.isVerified) ? "passed" : rtwDocs.length > 0 ? "pending" : "not_started",
          details: rtwDocs.length > 0 ? `${rtwDocs.length} RTW document(s)${rtwDocs.some(d => d.isVerified) ? " - verified" : " - awaiting verification"}` : "No right-to-work documents uploaded",
        },
        {
          id: "dbs_check",
          name: "DBS (Criminal Record) Check",
          category: "criminal",
          status: dbsCheck?.status === "passed" ? "passed" : dbsCheck ? "pending" : employee.dbsCertificateNumber ? "passed" : "not_started",
          details: employee.dbsCertificateNumber ? `Certificate: ${employee.dbsCertificateNumber} (Issued: ${employee.dbsIssueDate || "N/A"})` : dbsCheck ? `Status: ${dbsCheck.status}` : "No DBS check initiated",
        },
        {
          id: "employment_history",
          name: "5-Year Employment History",
          category: "history",
          status: fiveYearsCovered ? "passed" : empHistory.length > 0 ? "pending" : "not_started",
          details: empHistory.length > 0 ? `${empHistory.length} employment record(s) on file` : "No employment history recorded",
        },
        {
          id: "reference_checks",
          name: "Reference Checks",
          category: "references",
          status: refsCompleted >= 2 ? "passed" : refs.length > 0 ? "pending" : "not_started",
          details: refs.length > 0 ? `${refsCompleted}/${refs.length} references verified` : "No references provided",
        },
        {
          id: "address_verification",
          name: "Address Verification (5 years)",
          category: "identity",
          status: addressDocs.some(d => d.isVerified) ? "passed" : addressDocs.length > 0 ? "pending" : employee.addressLine1 ? "pending" : "not_started",
          details: addressDocs.length > 0 ? `${addressDocs.length} proof of address document(s)` : employee.addressLine1 ? "Address on file, awaiting documentary proof" : "No address information",
        },
        {
          id: "credit_check",
          name: "Credit Check",
          category: "financial",
          status: creditCheck?.status === "passed" ? "passed" : creditCheck ? "pending" : "not_started",
          details: creditCheck ? `Status: ${creditCheck.status}${creditCheck.completedDate ? ` (Completed: ${creditCheck.completedDate})` : ""}` : "No credit check initiated",
        },
        {
          id: "sia_license",
          name: "SIA License Verification",
          category: "qualifications",
          status: (() => {
            if (!employee.siaLicenseNumber) return "not_started";
            if (isEmployeeSiaRegisterValid(employee)) return "passed";
            if (employee.siaExpiryDate && new Date(employee.siaExpiryDate) > new Date()) return "pending";
            return "expired";
          })(),
          details: (() => {
            if (!employee.siaLicenseNumber) return "No SIA license on file";
            const parts = [
              `${employee.siaLicenseType || "SIA"} - ${employee.siaLicenseNumber}`,
              employee.siaExpiryDate ? `Expires: ${employee.siaExpiryDate}` : null,
            ];
            if (employee.siaLastVerifiedAt) {
              parts.push(`Register checked: ${new Date(employee.siaLastVerifiedAt).toLocaleDateString("en-GB")}`);
              parts.push(`Register status: ${employee.siaRegisterStatus || "unknown"}`);
              if (employee.siaRegisterHolderName) parts.push(`Register name: ${employee.siaRegisterHolderName}`);
            } else {
              parts.push("Not yet verified against SIA public register");
            }
            return parts.filter(Boolean).join(" · ");
          })(),
        },
        {
          id: "qualifications",
          name: "Qualification Verification",
          category: "qualifications",
          status: qualDocs.some(d => d.isVerified) ? "passed" : qualDocs.length > 0 ? "pending" : "not_started",
          details: qualDocs.length > 0 ? `${qualDocs.length} qualification document(s)` : "No qualifications uploaded",
        },
      ];

      const passed = checks.filter(c => c.status === "passed").length;
      const total = checks.length;
      const overallStatus = passed === total ? "compliant" : passed > 0 ? "partial" : "non_compliant";

      res.json({
        checks,
        summary: {
          passed,
          total,
          percentage: Math.round((passed / total) * 100),
          overallStatus,
        },
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

