  app.patch("/api/employee-pay-rates/:id", requireRole(...payRateRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });
      const id = parseInt(req.params.id);
      const updates: Record<string, any> = {};
      const fieldMap: Record<string, string> = { hourlyRate: "hourly_rate", effectiveFrom: "effective_from", effectiveTo: "effective_to", reason: "reason" };
      for (const [key, col] of Object.entries(fieldMap)) {
        if (req.body[key] !== undefined) updates[col] = req.body[key] || null;
      }
      if (Object.keys(updates).length === 0) return res.status(400).json({ message: "No fields to update" });
      const fields = Object.keys(updates).map((k, i) => `${k} = $${i + 1}`);
      const values = [...Object.values(updates), id, user.tenantId];
      const idx = Object.keys(updates).length + 1;
      const { rows } = await pool.query(`UPDATE employee_pay_rates SET ${fields.join(", ")} WHERE id = $${idx} AND tenant_id = $${idx + 1} RETURNING *`, values);
      if (rows.length === 0) return res.status(404).json({ message: "Pay rate not found" });

      const empId = rows[0].employee_id;
      const { rows: latestRate } = await pool.query(
        `SELECT * FROM employee_pay_rates WHERE employee_id = $1 AND tenant_id = $2 ORDER BY effective_from DESC LIMIT 1`,
        [empId, user.tenantId]
      );
      if (latestRate.length > 0) {
        await storage.updateEmployee(empId, { hourlyRate: String(latestRate[0].hourly_rate) } as any);
      }

      res.json(rows[0]);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

