  app.patch("/api/admin/probation-records/:id", requireRole(...probationRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });
      const id = parseInt(req.params.id);
      const { status, outcomeNotes, extendedReviewDate, reviewDate } = req.body;
      const updates: Record<string, any> = {};
      if (status) updates.status = status;
      if (outcomeNotes !== undefined) updates.outcomeNotes = outcomeNotes;
      if (extendedReviewDate !== undefined) updates.extendedReviewDate = extendedReviewDate || null;
      if (reviewDate) updates.reviewDate = reviewDate;
      if (status && status !== "active") {
        updates.reviewedBy = (user as any).id;
        updates.reviewedAt = new Date();
      }
      const updated = await storage.updateProbationRecord(id, user.tenantId, updates as any);
      if (!updated) return res.status(404).json({ message: "Probation record not found or access denied" });

      if (status === "failed") {
        try {
          const { rows: empRows } = await pool.query(
            `SELECT e.id, u.first_name || ' ' || u.last_name AS name
             FROM probation_records pr
             JOIN employees e ON pr.employee_id = e.id
             JOIN users u ON e.user_id = u.id
             WHERE pr.id = $1`,
            [id]
          );
          const empName = empRows[0]?.name || "Unknown Employee";
          await storage.createAuditLog({
            tenantId: user.tenantId,
            userId: user.id,
            action: "probation_failed",
            entityType: "probation_record",
            entityId: String(id),
            details: { outcomeNotes, employeeName: empName },
          });
          const { rows: managers } = await pool.query(
            `SELECT id FROM users WHERE tenant_id = $1 AND role IN ('super_admin','tenant_admin','ceo','operations_manager','admin','hr_manager') AND is_active = true LIMIT 10`,
            [user.tenantId]
          );
          const body = `Probation for ${empName} has been marked as FAILED. A formal process may be required. Review the outcome notes for details.`;
          for (const manager of managers) {
            await pool.query(
              `INSERT INTO notifications (user_id, type, title, body, link, related_entity_type, related_entity_id, metadata, created_at)
               VALUES ($1, 'probation_failed', 'Probation Failed — Action Required', $2, '/probation', 'probation_record', $3, $4, NOW())`,
              [manager.id, body, String(id), JSON.stringify({ probationId: id, employeeName: empName, outcome: "failed" })]
            );
          }
        } catch (notifErr) {
          console.error("[probation] Failed to send failure notifications:", notifErr);
        }
      }

      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

