  app.post("/api/admin/employees/merge", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const { primaryId, secondaryIds } = req.body;
      if (!primaryId || !Array.isArray(secondaryIds) || secondaryIds.length === 0) {
        return res.status(400).json({ message: "Primary ID and secondary IDs are required" });
      }

      const primary = await storage.getEmployee(primaryId, user.tenantId!);
      if (!primary) return res.status(404).json({ message: "Primary employee not found" });

      const mergedResults: any[] = [];
      const client = await pool.connect();
      try {
        await client.query("BEGIN");

        for (const secId of secondaryIds) {
          const secondary = await storage.getEmployee(secId, user.tenantId!);
          if (!secondary || secondary.id === primaryId) continue;

          const beforeState = { ...secondary };

          await client.query("UPDATE shifts SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE documents SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE bank_details SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE employment_history SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query('UPDATE "references" SET employee_id = $1 WHERE employee_id = $2', [primaryId, secId]);
          await client.query("UPDATE vetting_records SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE ops_checks SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE invoices SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE payroll_run_items SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE emergency_contacts SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE pending_bank_changes SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE employee_policies SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE employee_audit_trail SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE employee_pay_rates SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE employee_invitations SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE time_off_requests SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);
          await client.query("UPDATE employee_availability SET employee_id = $1 WHERE employee_id = $2", [primaryId, secId]);

          await client.query(
            `UPDATE employees SET is_merged = true, merged_into_id = $1, merged_at = NOW(), updated_at = NOW() WHERE id = $2`,
            [primaryId, secId]
          );

          mergedResults.push({ secondaryId: secId, beforeState });
        }

        await client.query("COMMIT");
      } catch (txErr) {
        await client.query("ROLLBACK");
        throw txErr;
      } finally {
        client.release();
      }

      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "employee_merge",
        entityType: "employee",
        entityId: String(primaryId),
        details: {
          primaryId,
          secondaryIds,
          mergedCount: mergedResults.length,
          mergedRecords: mergedResults.map(r => ({
            secondaryId: r.secondaryId,
            beforeState: {
              id: r.beforeState.id,
              externalId: r.beforeState.externalId,
              supplierId: r.beforeState.supplierId,
            },
          })),
        },
        ipAddress: meta.ipAddress,
      });

      res.json({ success: true, mergedCount: mergedResults.length, primaryId });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/admin/employees/bulk-purge", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const { ids } = req.body;
      if (!Array.isArray(ids) || ids.length === 0) return res.status(400).json({ message: "No IDs provided" });
      if (ids.length > 500) return res.status(400).json({ message: "Maximum 500 records per batch" });

      const employeeIds = ids.map((id: any) => parseInt(id)).filter((id: number) => !isNaN(id));
      let purged = 0;
      const purgedDetails: any[] = [];
      const client = await pool.connect();
      try {
        await client.query("BEGIN");

        for (const empId of employeeIds) {
          const { rows: empRows } = await client.query(
            `SELECT e.id, e.external_id, e.supplier_id, e.user_id, COALESCE(u.email, '') AS email
             FROM employees e LEFT JOIN users u ON e.user_id = u.id
             WHERE e.id = $1 AND e.tenant_id = $2`,
            [empId, user.tenantId]
          );
          if (empRows.length === 0) continue;
          const emp = empRows[0];

          if (emp.external_id) continue;
          if (!emp.email.includes("@placeholder.local")) continue;

          const { rows: shiftCheck } = await client.query("SELECT COUNT(*)::int AS cnt FROM shifts WHERE employee_id = $1", [empId]);
          if (shiftCheck[0].cnt > 0) continue;

          purgedDetails.push({ id: emp.id, externalId: emp.external_id, supplierId: emp.supplier_id });

          await client.query("DELETE FROM payroll_run_items WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM emergency_contacts WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM vetting_records WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM documents WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM bank_details WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM employment_history WHERE employee_id = $1", [empId]);
          await client.query('DELETE FROM "references" WHERE employee_id = $1', [empId]);
          await client.query("DELETE FROM pending_bank_changes WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM employee_invitations WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM employee_policies WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM employee_audit_trail WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM employee_pay_rates WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM time_off_requests WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM employee_availability WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM ops_checks WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM invoices WHERE employee_id = $1", [empId]);
          await client.query("DELETE FROM employees WHERE id = $1 AND tenant_id = $2", [empId, user.tenantId]);

          if (emp.user_id) {
            await client.query("DELETE FROM onboarding_records WHERE user_id = $1", [emp.user_id]);
            await client.query("DELETE FROM password_reset_tokens WHERE user_id = $1", [emp.user_id]);
            await client.query("DELETE FROM notifications WHERE user_id = $1", [emp.user_id]);
            await client.query("DELETE FROM audit_logs WHERE user_id = $1", [emp.user_id]);
            await client.query("DELETE FROM data_consents WHERE user_id = $1", [emp.user_id]);
            await client.query("DELETE FROM data_erasure_requests WHERE user_id = $1", [emp.user_id]);
            await client.query("DELETE FROM sessions WHERE sess::text LIKE $1", [`%${emp.user_id}%`]);
            await client.query("DELETE FROM users WHERE id = $1 AND tenant_id = $2", [emp.user_id, user.tenantId]);
          }
          purged++;
        }

        await client.query("COMMIT");
      } catch (txErr) {
        await client.query("ROLLBACK");
        throw txErr;
      } finally {
        client.release();
      }

      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "employee_bulk_purge",
        entityType: "employee",
        entityId: null,
        details: { purgedCount: purged, requestedIds: employeeIds, purgedDetails },
        ipAddress: meta.ipAddress,
      });

      res.json({ purged, total: employeeIds.length });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

