  app.get("/api/sites", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json([]);

      if (!req.query.page && !req.query.search && !req.query.clientId) {
        const allSites = await storage.getSitesByTenant(user.tenantId);
        return res.json(allSites);
      }

      const page = Math.max(1, parseInt(req.query.page as string) || 1);
      const limit = Math.min(200, Math.max(1, parseInt(req.query.limit as string) || 50));
      const offset = (page - 1) * limit;
      const search = (req.query.search as string || "").trim();
      const clientFilter = req.query.clientId as string || "";

      let conditions = ["s.tenant_id = $1"];
      let params: any[] = [user.tenantId];
      let paramIdx = 2;

      if (search) {
        conditions.push(`(s.name ILIKE $${paramIdx} OR s.address ILIKE $${paramIdx} OR s.city ILIKE $${paramIdx} OR s.postcode ILIKE $${paramIdx} OR c.company_name ILIKE $${paramIdx})`);
        params.push(`%${search}%`);
        paramIdx++;
      }

      if (clientFilter === "unassigned") {
        conditions.push("s.client_id IS NULL");
      } else if (clientFilter && clientFilter !== "all") {
        conditions.push(`s.client_id = $${paramIdx}`);
        params.push(parseInt(clientFilter));
        paramIdx++;
      }

      const whereClause = conditions.join(" AND ");

      const countResult = await pool.query(
        `SELECT COUNT(*) as total,
                COUNT(*) FILTER (WHERE s.is_active = true) as active,
                COUNT(*) FILTER (WHERE s.client_id IS NOT NULL) as with_client
         FROM sites s LEFT JOIN clients c ON s.client_id = c.id
         WHERE ${whereClause}`,
        params
      );

      const totalCountResult = await pool.query(
        "SELECT COUNT(*) as total FROM sites WHERE tenant_id = $1",
        [user.tenantId]
      );

      const sitesResult = await pool.query(
        `SELECT s.id, s.tenant_id as "tenantId", s.name, s.address, s.city, s.postcode,
                s.latitude, s.longitude, s.client_id as "clientId",
                c.company_name as "clientName",
                s.client_contact as "clientContact", s.client_email as "clientEmail",
                s.client_phone as "clientPhone", s.contract_ref as "contractRef",
                s.is_active as "isActive", s.notes, s.site_code as "siteCode",
                s.geofence_radius_metres as "geofenceRadiusMetres"
         FROM sites s LEFT JOIN clients c ON s.client_id = c.id
         WHERE ${whereClause}
         ORDER BY s.name ASC
         LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`,
        [...params, limit, offset]
      );

      const stats = countResult.rows[0];
      res.json({
        sites: sitesResult.rows,
        pagination: {
          page,
          limit,
          total: parseInt(stats.total),
          totalPages: Math.ceil(parseInt(stats.total) / limit),
        },
        stats: {
          total: parseInt(totalCountResult.rows[0].total),
          filtered: parseInt(stats.total),
          active: parseInt(stats.active),
          withClient: parseInt(stats.with_client),
        },
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

