  app.post("/api/shifts/bulk-finance", requireRole("super_admin", "tenant_admin", "ceo", "accountant", "operations_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const { shiftIds, action, note } = req.body;
      if (!Array.isArray(shiftIds) || shiftIds.length === 0) {
        return res.status(400).json({ message: "shiftIds array is required" });
      }
      if (action !== "approve" && action !== "reject") {
        return res.status(400).json({ message: "action must be 'approve' or 'reject'" });
      }
      if (action === "reject" && (!note || !note.trim())) {
        return res.status(400).json({ message: "A rejection reason is required" });
      }

      const now = new Date();
      const processed: number[] = [];
      const skipped: number[] = [];
      const errors: string[] = [];

      for (const id of shiftIds) {
        try {
          const shift = await storage.getShift(id);
          if (!shift) { skipped.push(id); errors.push(`Shift ${id} not found`); continue; }
          if (action === "approve" && shift.financeStatus === "approved") { skipped.push(id); continue; }
          if (action === "reject" && shift.financeStatus === "rejected") { skipped.push(id); continue; }

          await storage.updateShift(id, {
            financeStatus: action === "approve" ? "approved" : "rejected",
            financeApprovedBy: user.id,
            financeApprovedAt: now,
            financeNote: note?.trim() || null,
          } as any);

          if (user.tenantId != null) {
            await storage.createAuditLog({
              tenantId: user.tenantId,
              userId: user.id,
              action: action === "approve" ? "shift_finance_approved" : "shift_finance_rejected",
              entityType: "shift",
              entityId: String(id),
              details: { bulkAction: true, note: note?.trim() || null },
            });
          }
          processed.push(id);
        } catch (e: any) {
          skipped.push(id);
          errors.push(`Shift ${id}: ${e.message}`);
        }
      }

      res.json({ processed, skipped, errors });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

