  // Compliance dashboard data
  app.get("/api/admin/compliance", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "compliance_manager", "training_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json({ employees: [], summary: {} });
      const emps = await storage.getEmployeesByTenant(user.tenantId);
      const complianceData = await Promise.all(emps.map(async (e) => {
        const empUser = e.userId ? await storage.getUser(e.userId) : null;
        const vetting = await storage.getVettingRecords(e.id);
        const docs = await storage.getDocuments(e.id);
        const siaValid = e.siaExpiryDate ? new Date(e.siaExpiryDate) > new Date() : false;
        const dbsValid = !!e.dbsCertificateNumber;
        const firstAidValid = e.firstAidExpiry ? new Date(e.firstAidExpiry) > new Date() : false;
        return {
          id: e.id,
          name: empUser ? `${empUser.firstName} ${empUser.lastName}` : "Unknown",
          email: empUser?.email || "",
          siaLicenseNumber: e.siaLicenseNumber,
          siaExpiryDate: e.siaExpiryDate,
          siaValid,
          dbsCertificateNumber: e.dbsCertificateNumber,
          dbsIssueDate: e.dbsIssueDate,
          dbsValid,
          hasFirstAid: e.hasFirstAid,
          firstAidExpiry: e.firstAidExpiry,
          firstAidValid,
          vettingRecords: vetting,
          documentCount: docs.length,
          isFullyCompliant: siaValid && dbsValid,
        };
      }));
      const summary = {
        totalEmployees: complianceData.length,
        fullyCompliant: complianceData.filter(c => c.isFullyCompliant).length,
        siaExpiring: complianceData.filter(c => {
          if (!c.siaExpiryDate) return false;
          const expiry = new Date(c.siaExpiryDate);
          const thirtyDays = new Date();
          thirtyDays.setDate(thirtyDays.getDate() + 30);
          return expiry <= thirtyDays && expiry > new Date();
        }).length,
        siaExpired: complianceData.filter(c => !c.siaValid && c.siaLicenseNumber).length,
        missingDbs: complianceData.filter(c => !c.dbsValid).length,
      };
      res.json({ employees: complianceData, summary });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });


  app.get("/api/suppliers/:supplierId/employees", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "controller", "scheduler"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplierId = parseInt(req.params.supplierId);
      if (isNaN(supplierId)) return res.status(400).json({ message: "Invalid supplier ID" });
      const supplier = await storage.getSupplier(supplierId);
      if (!supplier || supplier.tenantId !== user.tenantId) {
        return res.status(404).json({ message: "Supplier not found" });
      }
      const officerEmployees = await storage.getEmployeesBySupplier(supplierId);
      const enriched = await Promise.all(officerEmployees.map(async (emp) => {
        const empUser = emp.userId ? await storage.getUser(emp.userId) : null;
        const firstName = empUser?.firstName || "";
        const lastName = empUser?.lastName || "";
        // Keep officers selectable for scheduling even if the linked user is inactive
        // (common after import/onboarding). Sort active first on the client via isActive.
        return {
          id: emp.id,
          firstName,
          lastName,
          isActive: empUser?.isActive ?? true,
          employeeNumber: emp.employeeNumber || null,
          jobTitle: emp.jobTitle || null,
        };
      }));
      const sorted = enriched
        .filter((e) => e.firstName || e.lastName || e.employeeNumber)
        .sort((a, b) => {
          if (a.isActive !== b.isActive) return a.isActive ? -1 : 1;
          return `${a.firstName} ${a.lastName}`.localeCompare(`${b.firstName} ${b.lastName}`);
        });
      res.json(sorted);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/employees/inhouse", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "controller", "scheduler"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json([]);
      const emps = await storage.getEmployeesByTenant(user.tenantId);
      const inhouseEmps = emps.filter(e => !e.supplierId);
      const enriched = await Promise.all(inhouseEmps.map(async (e) => {
        const empUser = e.userId ? await storage.getUser(e.userId) : null;
        if (empUser && !empUser.isActive) return null;
        return {
          id: e.id,
          firstName: empUser?.firstName || "",
          lastName: empUser?.lastName || "",
        };
      }));
      res.json(enriched.filter(Boolean));
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

