  // Export suppliers to a Xero Contacts import CSV (ContactsTemplate column layout)
  app.get("/api/admin/suppliers/export-xero", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant context" });
      const tenantId = typeof user.tenantId === "string" ? parseInt(user.tenantId, 10) : user.tenantId;
      if (Number.isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant context" });

      const allSuppliers = await storage.getSuppliersByTenant(tenantId);

      const escCsv = (v: any) => {
        const s = String(v ?? "");
        if (s.includes(",") || s.includes('"') || s.includes("\n") || s.includes("\r")) {
          return `"${s.replace(/"/g, '""')}"`;
        }
        return s;
      };

      const isPlaceholderEmail = (email?: string | null) =>
        !!email && /@placeholder\.local$/i.test(email.trim());

      // Official Xero "ContactsTemplate.csv" column layout
      const headers = [
        "*ContactName", "AccountNumber", "EmailAddress", "FirstName", "LastName",
        "POAttentionTo", "POAddressLine1", "POAddressLine2", "POAddressLine3", "POAddressLine4",
        "POCity", "PORegion", "POPostalCode", "POCountry",
        "SAAttentionTo", "SAAddressLine1", "SAAddressLine2", "SAAddressLine3", "SAAddressLine4",
        "SACity", "SARegion", "SAPostalCode", "SACountry",
        "PhoneNumber", "FaxNumber", "MobileNumber", "DDINumber", "SkypeName",
        "BankAccountName", "BankAccountNumber", "BankAccountParticulars",
        "TaxNumber", "AccountsReceivableTaxCodeName", "AccountsPayableTaxCodeName",
        "Website", "Discount",
      ];

      const sorted = [...allSuppliers].sort((a, b) =>
        (a.companyName || "").localeCompare(b.companyName || ""));

      const rows = sorted.map((s) => {
        const contact = (s.contactName || "").trim();
        const spaceIdx = contact.indexOf(" ");
        const firstName = spaceIdx === -1 ? contact : contact.slice(0, spaceIdx);
        const lastName = spaceIdx === -1 ? "" : contact.slice(spaceIdx + 1).trim();
        const email = isPlaceholderEmail(s.email) ? "" : (s.email || "");
        const bankAccountNumber = [s.sortCode, s.accountNumber]
          .filter((v) => v && String(v).trim().length > 0)
          .join(" ")
          .trim();

        return [
          s.companyName || "",                 // *ContactName
          s.supplierCode || "",                // AccountNumber
          email,                               // EmailAddress
          firstName,                           // FirstName
          lastName,                            // LastName
          contact,                             // POAttentionTo
          s.registeredOfficeAddress || "",     // POAddressLine1
          "",                                  // POAddressLine2
          "",                                  // POAddressLine3
          "",                                  // POAddressLine4
          s.registeredOfficeCity || "",        // POCity
          "",                                  // PORegion
          s.registeredOfficePostcode || "",    // POPostalCode
          s.registeredOfficeCountry || "",     // POCountry
          "",                                  // SAAttentionTo
          "",                                  // SAAddressLine1
          "",                                  // SAAddressLine2
          "",                                  // SAAddressLine3
          "",                                  // SAAddressLine4
          "",                                  // SACity
          "",                                  // SARegion
          "",                                  // SAPostalCode
          "",                                  // SACountry
          s.phone || "",                       // PhoneNumber
          "",                                  // FaxNumber
          "",                                  // MobileNumber
          "",                                  // DDINumber
          "",                                  // SkypeName
          s.accountName || "",                 // BankAccountName
          bankAccountNumber,                   // BankAccountNumber
          "",                                  // BankAccountParticulars
          s.vatNumber || "",                   // TaxNumber
          "",                                  // AccountsReceivableTaxCodeName
          "",                                  // AccountsPayableTaxCodeName
          "",                                  // Website
          "",                                  // Discount
        ].map(escCsv);
      });

      const csvContent = [headers.map(escCsv), ...rows]
        .map((r) => r.join(","))
        .join("\r\n");

      const fileName = `xero-contacts-${new Date().toISOString().slice(0, 10)}.csv`;
      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
      res.send(csvContent);
    } catch (err: any) {
      console.error("[GET /api/admin/suppliers/export-xero]", err);
      res.status(500).json({ message: err?.message ?? "Failed to export suppliers" });
    }
  });

