  app.patch("/api/suppliers/:id", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (req.body.billingFrequency && !["weekly", "fortnightly", "monthly"].includes(req.body.billingFrequency)) {
        return res.status(400).json({ message: "Invalid billing frequency. Must be weekly, fortnightly, or monthly." });
      }
      const existing = await storage.getSupplier(parseInt(req.params.id));
      if (!existing) return res.status(404).json({ message: "Supplier not found" });
      if (user.tenantId != null && existing.tenantId !== user.tenantId) {
        return res.status(404).json({ message: "Supplier not found" });
      }
      const body = { ...req.body };
      if (body.approvedAt && typeof body.approvedAt === "string") {
        body.approvedAt = new Date(body.approvedAt);
      } else if (body.approvedAt === null || body.approvedAt === "") {
        body.approvedAt = null;
      }
      if (body.approvedAt && existing.incorporationDate && existing.incorporationDate.trim()) {
        const parts = existing.incorporationDate.split("/");
        const incDate = parts.length === 3
          ? new Date(parseInt(parts[2]), parseInt(parts[1]) - 1, parseInt(parts[0]))
          : new Date(existing.incorporationDate);
        if (!isNaN(incDate.getTime()) && body.approvedAt < incDate) {
          return res.status(400).json({ message: `Onboarding date cannot be before the company incorporation date (${existing.incorporationDate})` });
        }
      }
      const updated = await storage.updateSupplier(parseInt(req.params.id), body);
      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: "supplier_updated", entityType: "supplier",
        entityId: req.params.id, details: req.body,
      });
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

