  app.delete("/api/suppliers/:id", requireRole("super_admin", "tenant_admin"), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const existing = await storage.getSupplier(id);
      if (!existing) return res.status(404).json({ message: "Supplier not found" });
      if (user.tenantId != null && existing.tenantId !== user.tenantId) return res.status(404).json({ message: "Supplier not found" });

      await pool.query(`DELETE FROM supplier_document_audit WHERE document_id IN (SELECT id FROM supplier_documents WHERE supplier_id = $1)`, [id]);
      await pool.query(`DELETE FROM supplier_documents WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM supplier_policies WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM supplier_pending_changes WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM supplier_audit_events WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM supplier_login_activity WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM supplier_field_requests WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM rate_cards WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM invoice_line_items WHERE invoice_id IN (SELECT id FROM invoices WHERE supplier_id = $1)`, [id]);
      await pool.query(`DELETE FROM invoices WHERE supplier_id = $1`, [id]);
      await pool.query(`DELETE FROM audit_logs WHERE entity_type = 'supplier' AND entity_id = $1`, [String(id)]);
      await pool.query(`UPDATE shifts SET supplier_id = NULL WHERE supplier_id = $1`, [id]);
      await pool.query(`UPDATE employees SET supplier_id = NULL WHERE supplier_id = $1`, [id]);
      if (existing.userId) {
        await pool.query(`DELETE FROM user_sessions WHERE "userId" = $1`, [existing.userId]);
        await pool.query(`DELETE FROM password_reset_tokens WHERE user_id = $1`, [existing.userId]);
        await pool.query(`DELETE FROM users WHERE id = $1`, [existing.userId]);
      }
      await storage.deleteSupplier(id);

      await storage.createAuditLog({
        tenantId: user.tenantId!,
        userId: user.id,
        action: "supplier_deleted",
        entityType: "supplier",
        entityId: String(id),
        details: { supplierName: existing.companyName, deletedBy: user.id },
      });
      res.json({ success: true });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

