  app.get("/api/suppliers/:id/activity", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager", "hr_manager", "compliance_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const supplier = await storage.getSupplier(id);
      if (!supplier) return res.status(404).json({ message: "Supplier not found" });
      if (user.tenantId != null && supplier.tenantId !== user.tenantId) return res.status(404).json({ message: "Supplier not found" });

      const [auditLogsList, loginActivity, tenantUsers] = await Promise.all([
        storage.getAuditLogs(user.tenantId!),
        storage.getSupplierLoginActivityBySupplierId(id),
        storage.getUsersByTenant(user.tenantId!),
      ]);
      const userNameById = new Map<string, string>();
      for (const u of tenantUsers) {
        userNameById.set(u.id, `${u.firstName} ${u.lastName}`.trim() || u.username);
      }
      for (const a of loginActivity) {
        if (!userNameById.has(a.userId)) {
          const u = await storage.getUser(a.userId);
          if (u) userNameById.set(u.id, `${u.firstName} ${u.lastName}`.trim() || u.username);
        }
      }
      const resolveUserName = (userId: string | null | undefined, details: unknown): string => {
        if (userId && userNameById.has(userId)) return userNameById.get(userId)!;
        if (details && typeof details === "object" && details !== null && "createdBy" in details) {
          const createdBy = (details as { createdBy?: string }).createdBy;
          if (createdBy && userNameById.has(createdBy)) return userNameById.get(createdBy)!;
        }
        return userId ?? "—";
      };

      const supplierAuditLogs = auditLogsList.filter((l) => l.entityType === "supplier" && l.entityId === String(id));
      const combined = [
        ...supplierAuditLogs.map((l) => ({
          type: "audit" as const,
          ...l,
          userName: resolveUserName(l.userId ?? null, l.details),
        })),
        ...loginActivity.map((a) => ({
          type: "login" as const,
          id: a.id,
          createdAt: a.createdAt,
          ipAddress: a.ipAddress,
          userAgent: a.userAgent,
          location: a.location,
          userName: userNameById.get(a.userId) ?? a.userId,
        })),
      ].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
      res.json(combined.slice(0, 200));
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

