  app.get("/api/suppliers/:supplierId/agreement-archives/:archiveId/pdf", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplierId = parseInt(req.params.supplierId);
      const archiveId = parseInt(req.params.archiveId);
      const supplier = await storage.getSupplier(supplierId);
      if (!supplier) return res.status(404).json({ message: "Supplier not found" });
      if (user.tenantId != null && supplier.tenantId !== user.tenantId) return res.status(404).json({ message: "Supplier not found" });
      const archive = await storage.getAgreementArchive(archiveId);
      if (!archive || archive.supplierId !== supplierId) return res.status(404).json({ message: "Archive not found" });
      const tenant = await storage.getTenant(supplier.tenantId);
      if (!tenant) return res.status(404).json({ message: "Tenant not found" });

      const template = archive.templateId ? await storage.getDocumentTemplate(archive.templateId) : await storage.getDefaultTemplate(tenant.id, "self_billing_agreement");
      const buyerAddress = [tenant.addressLine1, tenant.addressLine2, tenant.city, tenant.county, tenant.postcode].filter(Boolean).join(", ");

      const pdfBuffer = await generateSelfBillingAgreementPdf({
        agreementRef: archive.agreementRef || `SBA-${archive.id}`,
        buyerName: tenant.name || "Company",
        buyerAddress: buyerAddress || undefined,
        buyerVatNumber: tenant.vatNumber || undefined,
        buyerCompanyRegNumber: tenant.companyRegNumber || undefined,
        supplierName: supplier.companyName,
        supplierAddress: supplier.agreementRegisteredAddress
          ? buildSupplierAddress(supplier.agreementRegisteredAddress, supplier.agreementRegisteredCity, supplier.agreementRegisteredPostcode)
          : buildSupplierAddress(supplier.address, supplier.city, supplier.postcode),
        supplierVatNumber: supplier.vatNumber || undefined,
        supplierCompanyRegNumber: supplier.companyRegNumber || undefined,
        signatoryName: archive.signatoryName || "N/A",
        signatoryPosition: archive.signatoryPosition || "N/A",
        signedDate: archive.signedAt ? new Date(archive.signedAt).toISOString() : undefined,
        expiryDate: archive.expiryDate ? new Date(archive.expiryDate).toISOString() : undefined,
        signatureImage: archive.signatureData || undefined,
        signedIp: archive.signedIp || undefined,
        signedTimestamp: archive.signedAt ? new Date(archive.signedAt).toISOString() : undefined,
        buyerSignatoryName: archive.buyerSignatoryName || tenant.selfBillingSignatoryName || undefined,
        buyerSignatoryPosition: archive.buyerSignatoryPosition || tenant.selfBillingSignatoryPosition || undefined,
        buyerSignatureImage: archive.buyerSignatureData || tenant.selfBillingSignatureData || undefined,
        buyerSignatureDate: archive.signedAt ? new Date(archive.signedAt).toISOString() : undefined,
      }, template || null);
      res.set({ "Content-Type": "application/pdf", "Content-Disposition": `inline; filename="SBA-${archive.agreementRef || archiveId}.pdf"` });
      res.send(pdfBuffer);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

