  // Request that supplier provide/update a specific profile field (admin)
  app.post("/api/suppliers/:id/request-field", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplierId = parseInt(req.params.id);
      const { fieldKey, message } = req.body as { fieldKey?: string; message?: string };
      if (!fieldKey || typeof fieldKey !== "string") return res.status(400).json({ message: "fieldKey is required" });
      const supplier = await storage.getSupplier(supplierId);
      if (!supplier) return res.status(404).json({ message: "Supplier not found" });
      if (user.tenantId != null && supplier.tenantId !== user.tenantId) return res.status(404).json({ message: "Supplier not found" });
      const fieldLabel = getSupplierFieldLabel(fieldKey);

      if (fieldKey === "selfBillingSignatureRequest") {
        await archiveCurrentAgreement(supplierId, "admin_reset");
        await storage.createAuditLog({
          tenantId: user.tenantId!,
          userId: user.id,
          action: "supplier_sba_reset",
          entityType: "supplier",
          entityId: String(supplierId),
          details: { reason: message?.trim() || "New signature requested by admin" },
        });
        const supplierUserId = supplier.userId;
        if (supplierUserId) {
          await storage.createNotification({
            userId: supplierUserId,
            type: "field_request",
            title: "New Self-Billing Agreement signature required",
            body: message?.trim() || "Your Self-Billing Agreement requires a new signature. Please sign the agreement in your supplier portal.",
            link: "/self-billing-agreement",
            relatedEntityType: "supplier",
            relatedEntityId: String(supplierId),
            metadata: { fieldKey, fieldLabel },
          });
        }
        const portalBaseUrl = process.env.APP_BASE_URL ? `${process.env.APP_BASE_URL.replace(/\/$/, "")}/supplier-portal` : undefined;
        await emailService.sendSupplierFieldRequest({
          to: supplier.email,
          contactName: supplier.contactName,
          companyName: supplier.companyName,
          fieldLabel: "Self-Billing Agreement signature",
          message: message?.trim() || "Your Self-Billing Agreement requires a new signature. Please log in to your supplier portal and sign the agreement.",
          portalBaseUrl,
        });
        return res.json({ message: "Self-Billing Agreement reset — supplier must re-sign" });
      }

      const requestRecord = await storage.createSupplierFieldRequest({
        supplierId,
        fieldKey,
        message: message?.trim() || null,
        requestedBy: user.id,
      });
      const supplierUserId = supplier.userId;
      if (supplierUserId) {
        await storage.createNotification({
          userId: supplierUserId,
          type: "field_request",
          title: `Please provide: ${fieldLabel}`,
          body: message?.trim() || `We need you to provide or update "${fieldLabel}" in your supplier profile.`,
          link: "/supplier-portal",
          relatedEntityType: "supplier",
          relatedEntityId: String(supplierId),
          metadata: { fieldKey, fieldLabel, requestId: requestRecord.id },
        });
      }
      const portalBaseUrl = process.env.APP_BASE_URL ? `${process.env.APP_BASE_URL.replace(/\/$/, "")}/supplier-portal` : undefined;
      await emailService.sendSupplierFieldRequest({
        to: supplier.email,
        contactName: supplier.contactName,
        companyName: supplier.companyName,
        fieldLabel,
        message: message?.trim(),
        portalBaseUrl,
      });
      res.json({ message: "Field request sent", requestId: requestRecord.id });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

