  app.patch("/api/supplier-portal/me", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });
      const canEditDirectly = supplier.status === "draft" || supplier.status === "info_required" || supplier.status === "pending" || supplier.status === "submitted";
      const directAllowed = [
        "contactName", "email", "phone", "address", "city", "postcode",
        "registeredOfficeAddress", "registeredOfficeCity", "registeredOfficePostcode",
        "tradingSameAsRegistered", "tradingAddress", "tradingCity", "tradingPostcode",
        "financeContactName", "financeContactEmail", "natureOfSupply",
        "vatNumber", "vatStatus", "nonVatReason", "nonVatDeclarationAccepted",
        "companyRegNumber", "bankName", "accountName", "sortCode", "accountNumber",
        "whoEmploysWorkers", "umbrellaName", "umbrellaCrn", "subcontractorName", "subcontractorCrn",
        "subcontractingYes", "payeCompliance", "rtwCompliance", "nmwCompliance",
      ];
      const payload: Record<string, unknown> = {};
      for (const key of directAllowed) {
        if (req.body[key] !== undefined) payload[key] = req.body[key];
      }
      if (Object.keys(payload).length === 0) return res.status(400).json({ message: "No allowed fields to update" });
      if (canEditDirectly) {
        const fieldChanges = Object.keys(payload).map((field) => ({
          field,
          oldValue: (supplier as Record<string, unknown>)[field],
          newValue: payload[field],
        }));
        await storage.updateSupplier(supplier.id, payload as Record<string, unknown>);
        const meta = getClientMeta(req);
        await storage.createAuditLog({
          tenantId: supplier.tenantId!,
          userId: user.id,
          action: "supplier_profile_updated",
          entityType: "supplier",
          entityId: String(supplier.id),
          details: { updatedFields: Object.keys(payload) },
          ipAddress: meta.ipAddress,
        });
        await storage.createSupplierProfileChangeLog({
          supplierId: supplier.id,
          userId: user.id,
          action: "direct_edit",
          fieldChanges,
        });
        const openFieldRequests = await storage.getSupplierFieldRequests(supplier.id, { pendingOnly: true });
        for (const fr of openFieldRequests) {
          if (payload[fr.fieldKey] !== undefined) {
            await storage.updateSupplierFieldRequest(fr.id, { completedAt: new Date() });
          }
        }
        return res.json({ message: "Profile updated" });
      }
      const changeType = req.body.changeType as string | undefined; // "vat" | "bank" for dedicated requests
      const pendingPayload: Record<string, unknown> = { ...payload };
      if (changeType === "vat") {
        const vatFields = { vatStatus: payload.vatStatus, vatNumber: payload.vatNumber, nonVatReason: payload.nonVatReason, nonVatDeclarationAccepted: payload.nonVatDeclarationAccepted };
        const evidenceDocumentIds = (req.body.evidenceDocumentIds as number[] | undefined) ?? [];
        const docs = await storage.getSupplierDocuments(supplier.id);
        const validEvidence = docs.filter((d) => ["vat_evidence", "sample_vat_invoice", "non_vat_declaration"].includes(d.documentType) && evidenceDocumentIds.includes(d.id));
        if (validEvidence.length === 0) return res.status(400).json({ message: "VAT change request requires at least one supporting document (VAT evidence, sample VAT invoice, or Non-VAT declaration). Upload the document first, then submit with evidenceDocumentIds." });
        Object.assign(pendingPayload, vatFields, { changeType: "vat", evidenceDocumentIds });
      } else if (changeType === "bank") {
        const bankProofDocumentId = req.body.bankProofDocumentId as number | undefined;
        if (bankProofDocumentId == null) return res.status(400).json({ message: "Bank change request requires bankProofDocumentId (upload a bank proof document first)." });
        const docs = await storage.getSupplierDocuments(supplier.id);
        const bankDoc = docs.find((d) => d.id === bankProofDocumentId && d.documentType === "bank_proof");
        if (!bankDoc) return res.status(400).json({ message: "Bank proof document not found or not of type bank_proof." });
        const threeMonthsAgo = new Date(); threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);
        const docCreated = bankDoc.createdAt ? new Date(bankDoc.createdAt) : null;
        if (!docCreated || docCreated < threeMonthsAgo) return res.status(400).json({ message: "Bank proof must be dated within the last 3 months. Please upload a fresh bank proof." });
        const bankFields = { bankName: payload.bankName, accountName: payload.accountName, sortCode: payload.sortCode, accountNumber: payload.accountNumber };
        Object.assign(pendingPayload, bankFields, { changeType: "bank", bankProofDocumentId });
      } else {
        for (const key of ["vatStatus", "nonVatReason", "nonVatDeclarationAccepted"]) if (pendingPayload[key] !== undefined) delete pendingPayload[key];
      }
      const generalPendingAllowed = [
        "contactName", "email", "phone", "address", "city", "postcode",
        "registeredOfficeAddress", "registeredOfficeCity", "registeredOfficePostcode",
        "tradingSameAsRegistered", "tradingAddress", "tradingCity", "tradingPostcode",
        "financeContactName", "financeContactEmail", "natureOfSupply",
        "companyRegNumber",
        "bankName", "accountName", "sortCode", "accountNumber", "vatNumber",
        "whoEmploysWorkers", "umbrellaName", "umbrellaCrn", "subcontractorName", "subcontractorCrn",
        "subcontractingYes", "payeCompliance", "rtwCompliance", "nmwCompliance",
      ];
      const allowedKeys = changeType === "vat"
        ? ["changeType", "evidenceDocumentIds", "vatStatus", "vatNumber", "nonVatReason", "nonVatDeclarationAccepted"]
        : changeType === "bank"
          ? ["changeType", "bankProofDocumentId", "bankName", "accountName", "sortCode", "accountNumber"]
          : generalPendingAllowed;
      const filtered: Record<string, unknown> = {};
      for (const key of allowedKeys) { if (pendingPayload[key] !== undefined) filtered[key] = pendingPayload[key]; }
      const dataKeys = Object.keys(filtered).filter((k) => !["changeType", "evidenceDocumentIds", "bankProofDocumentId"].includes(k));
      if (dataKeys.length === 0) return res.status(400).json({ message: "No fields with changes to submit." });
      const finalPayload = filtered;
      await storage.createSupplierPendingChange({
        supplierId: supplier.id,
        userId: user.id,
        payload: finalPayload,
        status: "pending",
      });
      const openFieldRequests = await storage.getSupplierFieldRequests(supplier.id, { pendingOnly: true });
      for (const fr of openFieldRequests) {
        if (finalPayload[fr.fieldKey] !== undefined) {
          await storage.updateSupplierFieldRequest(fr.id, { completedAt: new Date() });
        }
      }
      const meta = getClientMeta(req);
      const auditAction = changeType === "vat" ? "supplier_vat_change_requested" : changeType === "bank" ? "supplier_bank_change_requested" : "supplier_change_requested";
      await storage.createAuditLog({
        tenantId: supplier.tenantId!,
        userId: user.id,
        action: auditAction,
        entityType: "supplier",
        entityId: String(supplier.id),
        details: changeType === "vat" ? { newVatStatus: finalPayload.vatStatus, newVatNumber: finalPayload.vatNumber } : changeType === "bank" ? { newAccountName: finalPayload.accountName } : finalPayload,
        ipAddress: meta.ipAddress,
      });
      if (supplier.tenantId != null) {
        const tenantUsers = await storage.getUsersByTenant(supplier.tenantId);
        const admins = tenantUsers.filter((u) => ["super_admin", "tenant_admin", "hr_manager"].includes(u.role));
        const adminEmails = admins.map((u) => u.email).filter(Boolean);
        const appBaseUrl = `${req.protocol}://${req.get("host") || "localhost"}`;
        await emailService.sendAdminSupplierChangeNotification({
          toEmails: [...new Set(adminEmails)],
          supplierName: supplier.companyName,
          supplierId: supplier.id,
          appBaseUrl,
        });
        for (const admin of admins) {
          await storage.createNotification({
            userId: admin.id,
            type: "supplier_change_pending",
            title: "Supplier change pending review",
            body: `${supplier.companyName} has submitted profile changes for your approval.`,
            link: `/suppliers/${supplier.id}`,
            relatedEntityType: "supplier",
            relatedEntityId: String(supplier.id),
            metadata: { supplierId: supplier.id, supplierName: supplier.companyName },
          });
        }
      }
      res.json({ message: "Change request submitted for approval" });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/supplier-portal/submit-onboarding", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });
      if (supplier.status === "suspended") {
        return res.status(403).json({ message: "Your supplier account is suspended. You cannot submit onboarding. Please contact the administrator." });
      }
      if (supplier.status !== "draft" && supplier.status !== "info_required") {
        return res.status(400).json({ message: "Onboarding can only be submitted when status is Draft or Info Required" });
      }
      const docs = await storage.getSupplierDocuments(supplier.id);
      const uploadedTypes = Array.from(new Set(docs.map((d) => d.documentType)));
      const readiness = getSubmitOnboardingReadiness(supplier, uploadedTypes);
      if (!readiness.ok) {
        return res.status(400).json({
          message: readiness.message,
          ...(readiness.missingDocumentTypes && { missingDocumentTypes: readiness.missingDocumentTypes }),
        });
      }
      const updated = await storage.updateSupplier(supplier.id, {
        status: "submitted",
        submittedAt: new Date(),
        submittedBy: user.id,
      });
      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: supplier.tenantId!,
        userId: user.id,
        action: "supplier_onboarding_submitted",
        entityType: "supplier",
        entityId: String(supplier.id),
        details: { submittedBy: user.id },
        ipAddress: meta.ipAddress,
      });
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

