  app.post("/api/supplier-portal/documents", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });
      const { documentType, fileName, fileUrl, fileSize, mimeType, displayName, expiryDate, notes } = req.body;
      if (!documentType || !fileName || !fileUrl) return res.status(400).json({ message: "documentType, fileName, and fileUrl required" });
      if (documentType === "other" && !displayName?.trim()) return res.status(400).json({ message: "Document name is required when uploading an 'Other' document." });
      const allowedForChangeRequest = ["bank_proof", "vat_evidence", "sample_vat_invoice", "non_vat_declaration"];
      const canUploadOnboarding = supplier.status === "draft" || supplier.status === "info_required" || supplier.status === "pending" || supplier.status === "submitted";
      const canUploadChangeRequest = (supplier.status === "approved" || supplier.status === "active") && (allowedForChangeRequest.includes(documentType) || documentType === "other");
      if (!canUploadOnboarding && !canUploadChangeRequest) {
        return res.status(400).json({ message: "Documents can only be uploaded during onboarding, after submission (e.g. to replace rejected docs), or for VAT/bank change requests (approved suppliers)." });
      }
      const doc = await storage.createSupplierDocument({
        supplierId: supplier.id,
        documentType,
        fileName,
        fileUrl,
        fileSize: fileSize ?? null,
        mimeType: mimeType ?? null,
        uploadedBy: user.id,
        displayName: displayName ?? null,
        expiryDate: expiryDate ?? null,
        notes: notes ?? null,
      });
      await storage.createSupplierDocumentAudit({
        documentId: doc.id,
        action: "uploaded",
        userId: user.id,
        details: {},
      });
      const meta = getClientMeta(req);
      await storage.createAuditLog({
        tenantId: supplier.tenantId!,
        userId: user.id,
        action: "supplier_document_uploaded",
        entityType: "supplier",
        entityId: String(supplier.id),
        details: { documentType, fileName, documentId: doc.id },
        ipAddress: meta.ipAddress,
      });
      res.status(201).json(doc);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

