  function computeSupplierCutoffDate(supplierVisibilityMonths: number | null | undefined, tenantVisibilityMonths: number | null | undefined): string | null {
    const months = supplierVisibilityMonths ?? tenantVisibilityMonths ?? null;
    if (months === null || months <= 0) return null;
    const cutoff = new Date();
    cutoff.setMonth(cutoff.getMonth() - months);
    return cutoff.toISOString().slice(0, 10);
  }

  async function getSupplierCutoff(supplier: { dataVisibilityMonths: number | null; tenantId: number | null }): Promise<string | null> {
    if (!supplier.tenantId) return null;
    const tenant = await storage.getTenant(supplier.tenantId);
    return computeSupplierCutoffDate(supplier.dataVisibilityMonths, tenant?.supplierDataVisibilityMonths);
  }

  function isInvoiceWithinCutoff(invoice: { periodEnd?: string | null }, cutoffDate: string | null): boolean {
    if (!cutoffDate) return true;
    const periodEnd = invoice.periodEnd;
    return !periodEnd || periodEnd >= cutoffDate;
  }

  function buildSupplierTimesheetFilters(query: any, tenantId: number, supplierId: number, cutoffDate?: string | null) {
    const statusFilter = query.status as string || null;
    const search = (query.search as string || "").trim().toLowerCase();
    const dateFromRaw = query.dateFrom as string || null;
    const dateToRaw = query.dateTo as string || null;
    let dateFrom = dateFromRaw && /^\d{4}-\d{2}-\d{2}$/.test(dateFromRaw) ? dateFromRaw : null;
    const dateTo = dateToRaw && /^\d{4}-\d{2}-\d{2}$/.test(dateToRaw) ? dateToRaw : null;

    if (cutoffDate) {
      if (!dateFrom || dateFrom < cutoffDate) {
        dateFrom = cutoffDate;
      }
    }

    const conditions: string[] = ["sh.tenant_id = $1", "sh.supplier_id = $2"];
    const params: any[] = [tenantId, supplierId];
    let paramIdx = 3;

    if (statusFilter && statusFilter !== "all") {
      if (statusFilter === "pending") {
        conditions.push(`(sh.supplier_approval_status = 'pending' OR sh.supplier_approval_status IS NULL)`);
      } else {
        conditions.push(`sh.supplier_approval_status = $${paramIdx}`);
        params.push(statusFilter);
        paramIdx++;
      }
    }
    if (search) {
      conditions.push(`(LOWER(COALESCE(si.name, '')) LIKE $${paramIdx} OR LOWER(COALESCE(u.first_name || ' ' || u.last_name, '')) LIKE $${paramIdx} OR LOWER(COALESCE(sh.title, '')) LIKE $${paramIdx} OR sh.date::text LIKE $${paramIdx})`);
      params.push(`%${search}%`);
      paramIdx++;
    }
    if (dateFrom) {
      conditions.push(`sh.date >= $${paramIdx}`);
      params.push(dateFrom);
      paramIdx++;
    }
    if (dateTo) {
      conditions.push(`sh.date <= $${paramIdx}`);
      params.push(dateTo);
      paramIdx++;
    }

    return { conditions, params, paramIdx, dateFrom, dateTo };
  }

  app.get("/api/supplier-portal/timesheets", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const tenant = await storage.getTenant(supplier.tenantId!);
      const cutoffDate = computeSupplierCutoffDate(supplier.dataVisibilityMonths, tenant?.supplierDataVisibilityMonths);

      const page = Math.max(1, parseInt(req.query.page as string) || 1);
      const limit = Math.min(100, Math.max(1, parseInt(req.query.limit as string) || 50));
      const offset = (page - 1) * limit;

      const { conditions, params, paramIdx, dateFrom, dateTo } = buildSupplierTimesheetFilters(req.query, supplier.tenantId!, supplier.id, cutoffDate);
      const whereClause = conditions.join(" AND ");

      const statsConditions: string[] = ["tenant_id = $1", "supplier_id = $2"];
      const statsParams: any[] = [supplier.tenantId, supplier.id];
      let statsIdx = 3;
      if (dateFrom) { statsConditions.push(`date >= $${statsIdx}`); statsParams.push(dateFrom); statsIdx++; }
      if (dateTo) { statsConditions.push(`date <= $${statsIdx}`); statsParams.push(dateTo); statsIdx++; }
      const statsWhere = statsConditions.join(" AND ");

      const [dataResult, countResult, statsResult] = await Promise.all([
        pool.query(
          `SELECT sh.id, sh.title, sh.date::text AS date, CASE WHEN sh.start_time LIKE '____-__-__ %' THEN SUBSTRING(sh.start_time FROM 12 FOR 5) ELSE LEFT(sh.start_time, 5) END AS start_time, CASE WHEN sh.end_time LIKE '____-__-__ %' THEN SUBSTRING(sh.end_time FROM 12 FOR 5) ELSE LEFT(sh.end_time, 5) END AS end_time,
            sh.break_minutes, sh.status, sh.notes, sh.supplier_approval_status, sh.supplier_approval_comment, sh.supplier_approved_at,
            COALESCE(si.name, sh.title, 'Unknown Site') AS site_name, COALESCE(si.city, '') AS site_city,
            COALESCE(u.first_name || ' ' || u.last_name, 'Unassigned') AS employee_name
          FROM shifts sh
          LEFT JOIN sites si ON sh.site_id = si.id
          LEFT JOIN employees e ON sh.employee_id = e.id
          LEFT JOIN users u ON e.user_id = u.id
          WHERE ${whereClause}
          ORDER BY sh.date DESC, sh.start_time DESC
          LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`,
          [...params, limit, offset]
        ),
        pool.query(
          `SELECT COUNT(*)::int AS total FROM shifts sh
          LEFT JOIN sites si ON sh.site_id = si.id
          LEFT JOIN employees e ON sh.employee_id = e.id
          LEFT JOIN users u ON e.user_id = u.id
          WHERE ${whereClause}`,
          params
        ),
        pool.query(
          `SELECT
            COUNT(*)::int AS total,
            COUNT(*) FILTER (WHERE supplier_approval_status = 'pending' OR supplier_approval_status IS NULL)::int AS pending,
            COUNT(*) FILTER (WHERE supplier_approval_status = 'approved')::int AS approved,
            COUNT(*) FILTER (WHERE supplier_approval_status = 'disputed')::int AS disputed
          FROM shifts WHERE ${statsWhere}`,
          statsParams
        ),
      ]);

      const data = dataResult.rows.map((r: any) => ({
        id: r.id,
        title: r.title,
        date: r.date,
        startTime: r.start_time,
        endTime: r.end_time,
        breakMinutes: r.break_minutes || 0,
        status: r.status,
        notes: r.notes,
        siteName: r.site_name,
        siteCity: r.site_city,
        employeeName: r.employee_name,
        supplierApprovalStatus: r.supplier_approval_status,
        supplierApprovalComment: r.supplier_approval_comment,
        supplierApprovedAt: r.supplier_approved_at,
      }));

      res.json({
        data,
        total: countResult.rows[0]?.total || 0,
        page,
        limit,
        stats: statsResult.rows[0] || { total: 0, pending: 0, approved: 0, disputed: 0 },
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/supplier-portal/timesheets/download", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const tenant = await storage.getTenant(supplier.tenantId!);
      const cutoffDate = computeSupplierCutoffDate(supplier.dataVisibilityMonths, tenant?.supplierDataVisibilityMonths);

      const format = (req.query.format as string || "csv").toLowerCase();
      if (format !== "csv" && format !== "pdf") {
        return res.status(400).json({ message: "Invalid format. Use 'csv' or 'pdf'." });
      }
      const { conditions, params, paramIdx } = buildSupplierTimesheetFilters(req.query, supplier.tenantId!, supplier.id, cutoffDate);
      const whereClause = conditions.join(" AND ");

      const dataResult = await pool.query(
        `SELECT sh.date::text AS date, CASE WHEN sh.start_time LIKE '____-__-__ %' THEN SUBSTRING(sh.start_time FROM 12 FOR 5) ELSE LEFT(sh.start_time, 5) END AS start_time, CASE WHEN sh.end_time LIKE '____-__-__ %' THEN SUBSTRING(sh.end_time FROM 12 FOR 5) ELSE LEFT(sh.end_time, 5) END AS end_time,
          sh.break_minutes, sh.status, sh.supplier_approval_status,
          COALESCE(si.name, sh.title, 'Unknown Site') AS site_name,
          COALESCE(u.first_name || ' ' || u.last_name, 'Unassigned') AS employee_name
        FROM shifts sh
        LEFT JOIN sites si ON sh.site_id = si.id
        LEFT JOIN employees e ON sh.employee_id = e.id
        LEFT JOIN users u ON e.user_id = u.id
        WHERE ${whereClause}
        ORDER BY sh.date ASC, sh.start_time ASC
        LIMIT 50000`,
        params
      );

      const rows = dataResult.rows.map((r: any) => {
        const [sh, sm] = (r.start_time || "00:00").split(":").map(Number);
        const [eh, em] = (r.end_time || "00:00").split(":").map(Number);
        let totalMins = (eh * 60 + em) - (sh * 60 + sm);
        if (totalMins < 0) totalMins += 24 * 60;
        totalMins -= r.break_minutes || 0;
        const hours = (totalMins / 60).toFixed(2);
        return {
          date: r.date,
          startTime: r.start_time?.substring(0, 5) || "",
          endTime: r.end_time?.substring(0, 5) || "",
          hours,
          siteName: r.site_name,
          employeeName: r.employee_name,
          shiftStatus: r.status || "scheduled",
          approvalStatus: r.supplier_approval_status || "pending",
        };
      });

      if (format === "pdf") {
        const PDFDocument = (await import("pdfkit")).default;
        const doc = new PDFDocument({ size: "A4", layout: "landscape", margin: 40 });
        const chunks: Buffer[] = [];
        doc.on("data", (chunk: Buffer) => chunks.push(chunk));
        doc.on("end", () => {
          const pdfBuffer = Buffer.concat(chunks);
          res.setHeader("Content-Type", "application/pdf");
          res.setHeader("Content-Disposition", `attachment; filename="timesheets_${supplier.companyName?.replace(/[^a-zA-Z0-9]/g, "_") || "export"}.pdf"`);
          res.send(pdfBuffer);
        });

        doc.fontSize(16).font("Helvetica-Bold").text(supplier.companyName || "Supplier", { align: "center" });
        doc.moveDown(0.3);
        doc.fontSize(10).font("Helvetica").text("Timesheet Report", { align: "center" });
        const dateFrom = req.query.dateFrom as string;
        const dateTo = req.query.dateTo as string;
        if (dateFrom || dateTo) {
          doc.fontSize(9).text(`Period: ${dateFrom || "Start"} to ${dateTo || "Present"}`, { align: "center" });
        }
        doc.fontSize(8).text(`Generated: ${new Date().toLocaleDateString("en-GB")} | Total Records: ${rows.length}`, { align: "center" });
        doc.moveDown(0.8);

        const colWidths = [70, 45, 45, 45, 200, 130, 70, 65];
        const headers = ["Date", "Start", "End", "Hours", "Site", "Officer", "Status", "Approval"];
        const startX = 40;
        let y = doc.y;

        doc.font("Helvetica-Bold").fontSize(7);
        doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 16).fill("#1F3A5F");
        let x = startX;
        headers.forEach((h, i) => {
          doc.fillColor("#FFFFFF").text(h, x + 3, y + 4, { width: colWidths[i] - 6, align: "left" });
          x += colWidths[i];
        });
        y += 16;
        doc.fillColor("#000000").font("Helvetica").fontSize(7);

        let totalHours = 0;
        for (let ri = 0; ri < rows.length; ri++) {
          if (y > 540) {
            doc.addPage();
            y = 40;
            doc.font("Helvetica-Bold").fontSize(7);
            doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 16).fill("#1F3A5F");
            x = startX;
            headers.forEach((h, i) => {
              doc.fillColor("#FFFFFF").text(h, x + 3, y + 4, { width: colWidths[i] - 6, align: "left" });
              x += colWidths[i];
            });
            y += 16;
            doc.fillColor("#000000").font("Helvetica").fontSize(7);
          }

          const row = rows[ri];
          totalHours += parseFloat(row.hours);
          const bgColor = ri % 2 === 0 ? "#FFFFFF" : "#F5F5F5";
          doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 14).fill(bgColor);
          doc.fillColor("#000000");

          const vals = [row.date, row.startTime, row.endTime, row.hours, row.siteName, row.employeeName, row.shiftStatus, row.approvalStatus];
          x = startX;
          vals.forEach((v, i) => {
            doc.text(String(v), x + 3, y + 3, { width: colWidths[i] - 6, align: "left", height: 14, ellipsis: true });
            x += colWidths[i];
          });
          y += 14;
        }

        y += 6;
        doc.font("Helvetica-Bold").fontSize(9);
        doc.text(`Total: ${rows.length} shifts | ${totalHours.toFixed(2)} hours`, startX, y);

        doc.end();
        return;
      }

      const csvHeaders = "Date,Start Time,End Time,Hours,Site,Officer,Shift Status,Approval Status";
      const csvRows = rows.map(r => {
        const escapeCsv = (s: string) => `"${String(s).replace(/"/g, '""')}"`;
        return [r.date, r.startTime, r.endTime, r.hours, escapeCsv(r.siteName), escapeCsv(r.employeeName), r.shiftStatus, r.approvalStatus].join(",");
      });
      const csvContent = [csvHeaders, ...csvRows].join("\n");

      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", `attachment; filename="timesheets_${supplier.companyName?.replace(/[^a-zA-Z0-9]/g, "_") || "export"}.csv"`);
      res.send(csvContent);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/supplier-portal/timesheets/billed", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const tenant = await storage.getTenant(supplier.tenantId!);
      const cutoffDate = computeSupplierCutoffDate(supplier.dataVisibilityMonths, tenant?.supplierDataVisibilityMonths);

      let periodStart = req.query.periodStart as string || null;
      const periodEnd = req.query.periodEnd as string || null;

      if (cutoffDate) {
        if (!periodStart || periodStart < cutoffDate) periodStart = cutoffDate;
      }

      const conditions: string[] = ["i.supplier_id = $1", "i.tenant_id = $2"];
      const params: any[] = [supplier.id, supplier.tenantId];
      let idx = 3;
      if (periodStart) { conditions.push(`i.period_end >= $${idx}`); params.push(periodStart); idx++; }
      if (periodEnd) { conditions.push(`i.period_start <= $${idx}`); params.push(periodEnd); idx++; }

      const invoiceResult = await pool.query(
        `SELECT i.id, i.invoice_number, i.period_start, i.period_end, i.status,
          i.subtotal, i.vat_amount, i.total_amount
        FROM invoices i
        WHERE ${conditions.join(" AND ")}
        ORDER BY i.period_start DESC`,
        params
      );

      const invoices = [];
      for (const inv of invoiceResult.rows) {
        const lineResult = await pool.query(
          `SELECT li.shift_id, li.description, li.hours, li.rate, li.subtotal, li.vat_rate, li.vat_amount, li.line_total,
            sh.date::text AS shift_date,
            CASE WHEN sh.start_time LIKE '____-__-__ %' THEN SUBSTRING(sh.start_time FROM 12 FOR 5) ELSE LEFT(sh.start_time, 5) END AS start_time,
            CASE WHEN sh.end_time LIKE '____-__-__ %' THEN SUBSTRING(sh.end_time FROM 12 FOR 5) ELSE LEFT(sh.end_time, 5) END AS end_time,
            sh.break_minutes,
            COALESCE(si.name, sh.title, 'Unknown Site') AS site_name,
            COALESCE(u.first_name || ' ' || u.last_name, 'Unassigned') AS employee_name
          FROM invoice_line_items li
          LEFT JOIN shifts sh ON li.shift_id = sh.id
          LEFT JOIN sites si ON sh.site_id = si.id
          LEFT JOIN employees e ON sh.employee_id = e.id
          LEFT JOIN users u ON e.user_id = u.id
          WHERE li.invoice_id = $1
          ORDER BY sh.date ASC, sh.start_time ASC`,
          [inv.id]
        );

        const totalHours = lineResult.rows.reduce((sum: number, r: any) => sum + parseFloat(r.hours || "0"), 0);

        invoices.push({
          invoiceId: inv.id,
          invoiceNumber: inv.invoice_number,
          periodStart: inv.period_start,
          periodEnd: inv.period_end,
          status: inv.status,
          subtotal: parseFloat(inv.subtotal || "0"),
          vatAmount: parseFloat(inv.vat_amount || "0"),
          totalAmount: parseFloat(inv.total_amount || "0"),
          totalHours: parseFloat(totalHours.toFixed(2)),
          shifts: lineResult.rows.map((r: any) => ({
            shiftId: r.shift_id,
            date: r.shift_date,
            startTime: r.start_time,
            endTime: r.end_time,
            breakMinutes: parseInt(r.break_minutes || "0"),
            hours: parseFloat(r.hours || "0"),
            rate: parseFloat(r.rate || "0"),
            amount: parseFloat(r.subtotal || "0"),
            siteName: r.site_name,
            employeeName: r.employee_name,
          })),
        });
      }

      res.json(invoices);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/supplier-portal/timesheets/billed/:invoiceId/pdf", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const invoiceId = parseInt(req.params.invoiceId);
      const invoice = await storage.getInvoice(invoiceId);
      if (!invoice || invoice.supplierId !== supplier.id) return res.status(404).json({ message: "Invoice not found" });

      const cutoffDate = await getSupplierCutoff(supplier);
      if (!isInvoiceWithinCutoff(invoice, cutoffDate)) return res.status(403).json({ message: "This invoice is outside your data visibility window" });

      const lineResult = await pool.query(
        `SELECT li.hours, li.rate, li.subtotal,
          sh.date::text AS shift_date,
          CASE WHEN sh.start_time LIKE '____-__-__ %' THEN SUBSTRING(sh.start_time FROM 12 FOR 5) ELSE LEFT(sh.start_time, 5) END AS start_time,
          CASE WHEN sh.end_time LIKE '____-__-__ %' THEN SUBSTRING(sh.end_time FROM 12 FOR 5) ELSE LEFT(sh.end_time, 5) END AS end_time,
          sh.break_minutes,
          COALESCE(si.name, sh.title, 'Unknown Site') AS site_name,
          COALESCE(u.first_name || ' ' || u.last_name, 'Unassigned') AS employee_name
        FROM invoice_line_items li
        LEFT JOIN shifts sh ON li.shift_id = sh.id
        LEFT JOIN sites si ON sh.site_id = si.id
        LEFT JOIN employees e ON sh.employee_id = e.id
        LEFT JOIN users u ON e.user_id = u.id
        WHERE li.invoice_id = $1
        ORDER BY sh.date ASC, sh.start_time ASC`,
        [invoiceId]
      );

      const PDFDocument = (await import("pdfkit")).default;
      const doc = new PDFDocument({ size: "A4", layout: "landscape", margin: 40 });
      const chunks: Buffer[] = [];
      doc.on("data", (chunk: Buffer) => chunks.push(chunk));
      const pdfReady = new Promise<Buffer>((resolve) => {
        doc.on("end", () => resolve(Buffer.concat(chunks)));
      });

      doc.fontSize(16).font("Helvetica-Bold").text(`Timesheet — ${supplier.companyName}`, { align: "center" });
      doc.moveDown(0.3);
      doc.fontSize(10).font("Helvetica").text(`Invoice: ${invoice.invoiceNumber} | Period: ${invoice.periodStart} to ${invoice.periodEnd} | Total Shifts: ${lineResult.rows.length}`, { align: "center" });
      doc.moveDown(0.8);

      const colWidths = [75, 200, 130, 50, 50, 50, 55, 60];
      const headers = ["Date", "Site", "Officer", "Start", "End", "Hours", "Rate", "Amount"];
      const startX = 40;
      let y = doc.y;

      doc.font("Helvetica-Bold").fontSize(7);
      doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 16).fill("#1F3A5F");
      let x = startX;
      headers.forEach((h, i) => {
        doc.fillColor("#FFFFFF").text(h, x + 3, y + 4, { width: colWidths[i] - 6, align: "left" });
        x += colWidths[i];
      });
      y += 18;

      doc.font("Helvetica").fontSize(7).fillColor("#333");
      let totalHours = 0;
      let totalAmount = 0;
      for (const r of lineResult.rows) {
        if (y > 520) {
          doc.addPage({ layout: "landscape" });
          y = 40;
          doc.font("Helvetica-Bold").fontSize(7);
          doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 16).fill("#1F3A5F");
          x = startX;
          headers.forEach((h, i) => {
            doc.fillColor("#FFFFFF").text(h, x + 3, y + 4, { width: colWidths[i] - 6, align: "left" });
            x += colWidths[i];
          });
          y += 18;
          doc.font("Helvetica").fontSize(7).fillColor("#333");
        }
        const hrs = parseFloat(r.hours || "0");
        const amt = parseFloat(r.subtotal || "0");
        totalHours += hrs;
        totalAmount += amt;
        x = startX;
        const rowBg = lineResult.rows.indexOf(r) % 2 === 0 ? "#FFFFFF" : "#F8F9FA";
        doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 14).fill(rowBg);
        doc.fillColor("#333");
        const vals = [r.shift_date || "", r.site_name, r.employee_name, r.start_time || "", r.end_time || "", hrs.toFixed(2), `£${parseFloat(r.rate || "0").toFixed(2)}`, `£${amt.toFixed(2)}`];
        vals.forEach((v, i) => {
          doc.text(v, x + 3, y + 3, { width: colWidths[i] - 6, align: "left", height: 14, ellipsis: true });
          x += colWidths[i];
        });
        y += 14;
      }

      y += 4;
      doc.font("Helvetica-Bold").fontSize(8).fillColor("#1F3A5F");
      doc.text(`Total: ${totalHours.toFixed(2)} hours | £${totalAmount.toFixed(2)}`, startX, y);

      doc.end();
      const pdfBuffer = await pdfReady;

      const sanitizedName = supplier.companyName?.replace(/[^a-zA-Z0-9]/g, "_").replace(/_+/g, "_").replace(/^_|_$/g, "") || "Supplier";
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="Timesheet_${invoice.invoiceNumber || invoiceId}_${sanitizedName}.pdf"`);
      res.send(pdfBuffer);
    } catch (err: any) {
      if (!res.headersSent) res.status(500).json({ message: err.message });
    }
  });

  app.patch("/api/supplier-portal/timesheets/:id/approve", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const shiftId = parseInt(req.params.id);
      const allShifts = await storage.getShiftsByTenant(supplier.tenantId!);
      const shift = allShifts.find(s => s.id === shiftId && s.supplierId === supplier.id);
      if (!shift) return res.status(404).json({ message: "Shift not found or not assigned to your company" });

      if (!["scheduled", "in_progress", "completed"].includes(shift.status)) {
        return res.status(400).json({ message: "Only scheduled, in-progress, or completed shifts can be approved. Current status: " + shift.status });
      }

      if (shift.supplierApprovalStatus === "approved") {
        return res.status(400).json({ message: "This timesheet has already been approved" });
      }

      const wasNotCompleted = shift.status !== "completed";
      const updateData: any = {
        supplierApprovalStatus: "approved",
        supplierApprovalComment: null,
        supplierApprovedAt: new Date(),
        supplierApprovedBy: user.id,
      };
      if (wasNotCompleted) {
        updateData.status = "completed";
        updateData.checkOutTime = new Date().toISOString();
      }

      const updated = await storage.updateShift(shiftId, updateData);

      await storage.createAuditLog({
        tenantId: supplier.tenantId!,
        userId: user.id,
        action: "supplier_timesheet_approved",
        entityType: "shift",
        entityId: String(shiftId),
        details: { supplierId: supplier.id, supplierName: supplier.companyName },
      });

      if (wasNotCompleted) {
        await storage.createAuditLog({
          tenantId: supplier.tenantId!,
          userId: user.id,
          action: "shift_completed_via_supplier_approval",
          entityType: "shift",
          entityId: String(shiftId),
          details: { supplierId: supplier.id, supplierName: supplier.companyName, previousStatus: shift.status },
        });
      }

      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.patch("/api/supplier-portal/timesheets/:id/dispute", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const shiftId = parseInt(req.params.id);
      const { comment } = req.body;
      if (!comment || !comment.trim()) return res.status(400).json({ message: "A comment is required when disputing a timesheet entry" });

      const allShifts = await storage.getShiftsByTenant(supplier.tenantId!);
      const shift = allShifts.find(s => s.id === shiftId && s.supplierId === supplier.id);
      if (!shift) return res.status(404).json({ message: "Shift not found or not assigned to your company" });

      if (shift.status !== "completed") {
        return res.status(400).json({ message: "Only completed shifts can be disputed. Current status: " + shift.status });
      }

      if (shift.supplierApprovalStatus === "approved") {
        return res.status(400).json({ message: "This timesheet has already been approved and cannot be disputed. Contact admin to revoke approval first." });
      }

      const updated = await storage.updateShift(shiftId, {
        supplierApprovalStatus: "disputed",
        supplierApprovalComment: comment.trim(),
        supplierApprovedAt: new Date(),
        supplierApprovedBy: user.id,
      });

      await storage.createAuditLog({
        tenantId: supplier.tenantId!,
        userId: user.id,
        action: "supplier_timesheet_disputed",
        entityType: "shift",
        entityId: String(shiftId),
        details: { supplierId: supplier.id, supplierName: supplier.companyName, comment: comment.trim() },
      });

      await storage.createNotification({
        tenantId: supplier.tenantId!,
        userId: "admin",
        type: "timesheet_disputed",
        title: "Timesheet Disputed",
        message: `${supplier.companyName} has disputed a timesheet for shift #${shiftId}: ${comment.trim()}`,
        data: { shiftId, supplierId: supplier.id, comment: comment.trim() },
      });

      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // ── Admin Supplier Timesheets endpoint ──

  app.get("/api/admin/supplier-timesheets", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json({ data: [], total: 0, page: 1, limit: 50, stats: { total: 0, pending: 0, approved: 0, disputed: 0 }, suppliers: [] });

      const page = Math.max(1, parseInt(req.query.page as string) || 1);
      const limit = Math.min(100, Math.max(1, parseInt(req.query.limit as string) || 50));
      const offset = (page - 1) * limit;
      const statusFilter = req.query.status as string || null;
      const supplierIdFilter = req.query.supplierId ? parseInt(req.query.supplierId as string) : null;
      const search = (req.query.search as string || "").trim().toLowerCase();
      const periodStart = req.query.periodStart as string || null;
      const periodEnd = req.query.periodEnd as string || null;

      const conditions: string[] = ["sh.tenant_id = $1", "sh.supplier_id IS NOT NULL"];
      const params: any[] = [user.tenantId];
      let paramIdx = 2;

      if (statusFilter && statusFilter !== "all") {
        if (statusFilter === "pending") {
          conditions.push(`(sh.supplier_approval_status = 'pending' OR sh.supplier_approval_status IS NULL)`);
        } else {
          conditions.push(`sh.supplier_approval_status = $${paramIdx}`);
          params.push(statusFilter);
          paramIdx++;
        }
      }
      if (supplierIdFilter) {
        conditions.push(`sh.supplier_id = $${paramIdx}`);
        params.push(supplierIdFilter);
        paramIdx++;
      }
      if (periodStart) {
        conditions.push(`sh.date >= $${paramIdx}`);
        params.push(periodStart);
        paramIdx++;
      }
      if (periodEnd) {
        conditions.push(`sh.date <= $${paramIdx}`);
        params.push(periodEnd);
        paramIdx++;
      }
      if (search) {
        conditions.push(`(LOWER(COALESCE(si.name, '')) LIKE $${paramIdx} OR LOWER(COALESCE(u.first_name || ' ' || u.last_name, '')) LIKE $${paramIdx} OR LOWER(COALESCE(su.company_name, '')) LIKE $${paramIdx} OR LOWER(COALESCE(sh.title, '')) LIKE $${paramIdx} OR sh.date::text LIKE $${paramIdx})`);
        params.push(`%${search}%`);
        paramIdx++;
      }

      const whereClause = conditions.join(" AND ");

      const joinClause = `FROM shifts sh
          LEFT JOIN sites si ON sh.site_id = si.id
          LEFT JOIN employees e ON sh.employee_id = e.id
          LEFT JOIN users u ON e.user_id = u.id
          LEFT JOIN suppliers su ON sh.supplier_id = su.id`;

      const needsJoinForCount = !!search;
      const countFrom = needsJoinForCount ? joinClause : `FROM shifts sh`;
      const countConditions = needsJoinForCount ? conditions : conditions.filter(c => !c.includes('si.') && !c.includes('u.') && !c.includes('su.company'));
      const countWhere = needsJoinForCount ? whereClause : countConditions.join(" AND ");
      const countParams = needsJoinForCount ? params : params.filter((_, i) => i < (needsJoinForCount ? params.length : params.length));

      const [dataResult, countResult, statsResult, suppliersResult] = await Promise.all([
        pool.query(
          `SELECT sh.*, COALESCE(si.name, sh.title, 'Unknown Site') AS site_name, COALESCE(si.city, '') AS site_city,
            COALESCE(u.first_name || ' ' || u.last_name, 'Unassigned') AS employee_name,
            COALESCE(su.company_name, 'Unknown Supplier') AS supplier_name
          ${joinClause}
          WHERE ${whereClause}
          ORDER BY sh.date DESC, sh.start_time DESC
          LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`,
          [...params, limit, offset]
        ),
        pool.query(
          `SELECT COUNT(*)::int AS total ${countFrom}
          WHERE ${countWhere}`,
          needsJoinForCount ? params : params
        ),
        pool.query(
          `SELECT
            COUNT(*)::int AS total,
            COUNT(*) FILTER (WHERE sh.supplier_approval_status = 'pending' OR sh.supplier_approval_status IS NULL)::int AS pending,
            COUNT(*) FILTER (WHERE sh.supplier_approval_status = 'approved')::int AS approved,
            COUNT(*) FILTER (WHERE sh.supplier_approval_status = 'disputed')::int AS disputed
          ${countFrom}
          WHERE ${countWhere}`,
          needsJoinForCount ? params : params
        ),
        pool.query(
          `SELECT su.id, su.company_name FROM suppliers su
          WHERE su.tenant_id = $1 AND EXISTS (SELECT 1 FROM shifts sh WHERE sh.supplier_id = su.id AND sh.tenant_id = $1)
          ORDER BY su.company_name`,
          [user.tenantId]
        ),
      ]);

      const data = dataResult.rows.map((r: any) => ({
        id: r.id,
        title: r.title,
        date: r.date,
        startTime: r.start_time,
        endTime: r.end_time,
        breakMinutes: r.break_minutes || 0,
        status: r.status,
        notes: r.notes,
        siteName: r.site_name,
        siteCity: r.site_city,
        employeeName: r.employee_name,
        supplierName: r.supplier_name,
        supplierId: r.supplier_id,
        supplierApprovalStatus: r.supplier_approval_status,
        supplierApprovalComment: r.supplier_approval_comment,
        supplierApprovedAt: r.supplier_approved_at,
      }));

      res.json({
        data,
        total: countResult.rows[0].total,
        page,
        limit,
        stats: statsResult.rows[0],
        suppliers: suppliersResult.rows.map((r: any) => ({ id: r.id, name: r.company_name })),
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  const adminTimesheetRoles = ["super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager", "hr_manager"] as const;

  app.get("/api/admin/supplier-timesheets/billed", requireRole(...adminTimesheetRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json([]);

      const supplierIdParam = req.query.supplierId ? parseInt(req.query.supplierId as string) : null;

      if (supplierIdParam) {
        const supplier = await storage.getSupplier(supplierIdParam);
        if (!supplier || supplier.tenantId !== user.tenantId) return res.status(404).json({ message: "Supplier not found" });
      }

      const periodStart = req.query.periodStart as string || null;
      const periodEnd = req.query.periodEnd as string || null;

      const conditions: string[] = ["i.tenant_id = $1"];
      const params: any[] = [user.tenantId];
      let idx = 2;
      if (supplierIdParam) { conditions.push(`i.supplier_id = $${idx}`); params.push(supplierIdParam); idx++; }
      if (periodStart) { conditions.push(`i.period_end >= $${idx}`); params.push(periodStart); idx++; }
      if (periodEnd) { conditions.push(`i.period_start <= $${idx}`); params.push(periodEnd); idx++; }

      const invoiceResult = await pool.query(
        `SELECT i.id, i.invoice_number, i.period_start, i.period_end, i.status,
          i.subtotal, i.vat_amount, i.total_amount, i.supplier_id,
          COALESCE(s.company_name, 'Unknown Supplier') AS supplier_name
        FROM invoices i
        LEFT JOIN suppliers s ON i.supplier_id = s.id
        WHERE ${conditions.join(" AND ")}
        ORDER BY i.period_start DESC`,
        params
      );

      const invoices = [];
      for (const inv of invoiceResult.rows) {
        const lineResult = await pool.query(
          `SELECT li.shift_id, li.hours, li.rate, li.subtotal,
            sh.date::text AS shift_date,
            CASE WHEN sh.start_time LIKE '____-__-__ %' THEN SUBSTRING(sh.start_time FROM 12 FOR 5) ELSE LEFT(sh.start_time, 5) END AS start_time,
            CASE WHEN sh.end_time LIKE '____-__-__ %' THEN SUBSTRING(sh.end_time FROM 12 FOR 5) ELSE LEFT(sh.end_time, 5) END AS end_time,
            sh.break_minutes,
            COALESCE(si.name, sh.title, 'Unknown Site') AS site_name,
            COALESCE(u.first_name || ' ' || u.last_name, 'Unassigned') AS employee_name
          FROM invoice_line_items li
          LEFT JOIN shifts sh ON li.shift_id = sh.id
          LEFT JOIN sites si ON sh.site_id = si.id
          LEFT JOIN employees e ON sh.employee_id = e.id
          LEFT JOIN users u ON e.user_id = u.id
          WHERE li.invoice_id = $1
          ORDER BY sh.date ASC, sh.start_time ASC`,
          [inv.id]
        );

        const totalHours = lineResult.rows.reduce((sum: number, r: any) => sum + parseFloat(r.hours || "0"), 0);

        invoices.push({
          invoiceId: inv.id,
          invoiceNumber: inv.invoice_number,
          supplierName: inv.supplier_name,
          periodStart: inv.period_start,
          periodEnd: inv.period_end,
          status: inv.status,
          subtotal: parseFloat(inv.subtotal || "0"),
          vatAmount: parseFloat(inv.vat_amount || "0"),
          totalAmount: parseFloat(inv.total_amount || "0"),
          totalHours: parseFloat(totalHours.toFixed(2)),
          shifts: lineResult.rows.map((r: any) => ({
            shiftId: r.shift_id,
            date: r.shift_date,
            startTime: r.start_time,
            endTime: r.end_time,
            breakMinutes: parseInt(r.break_minutes || "0"),
            hours: parseFloat(r.hours || "0"),
            rate: parseFloat(r.rate || "0"),
            amount: parseFloat(r.subtotal || "0"),
            siteName: r.site_name,
            employeeName: r.employee_name,
          })),
        });
      }

      res.json(invoices);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/admin/supplier-timesheets/billed/:invoiceId/pdf", requireRole(...adminTimesheetRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });

      const invoiceId = parseInt(req.params.invoiceId);
      const invoice = await storage.getInvoice(invoiceId);
      if (!invoice || invoice.tenantId !== user.tenantId) return res.status(404).json({ message: "Invoice not found" });

      const supplier = await storage.getSupplier(invoice.supplierId);
      if (!supplier) return res.status(404).json({ message: "Supplier not found" });

      const lineResult = await pool.query(
        `SELECT li.hours, li.rate, li.subtotal,
          sh.date::text AS shift_date,
          CASE WHEN sh.start_time LIKE '____-__-__ %' THEN SUBSTRING(sh.start_time FROM 12 FOR 5) ELSE LEFT(sh.start_time, 5) END AS start_time,
          CASE WHEN sh.end_time LIKE '____-__-__ %' THEN SUBSTRING(sh.end_time FROM 12 FOR 5) ELSE LEFT(sh.end_time, 5) END AS end_time,
          sh.break_minutes,
          COALESCE(si.name, sh.title, 'Unknown Site') AS site_name,
          COALESCE(u.first_name || ' ' || u.last_name, 'Unassigned') AS employee_name
        FROM invoice_line_items li
        LEFT JOIN shifts sh ON li.shift_id = sh.id
        LEFT JOIN sites si ON sh.site_id = si.id
        LEFT JOIN employees e ON sh.employee_id = e.id
        LEFT JOIN users u ON e.user_id = u.id
        WHERE li.invoice_id = $1
        ORDER BY sh.date ASC, sh.start_time ASC`,
        [invoiceId]
      );

      const PDFDocument = (await import("pdfkit")).default;
      const doc = new PDFDocument({ size: "A4", layout: "landscape", margin: 40 });
      const chunks: Buffer[] = [];
      doc.on("data", (chunk: Buffer) => chunks.push(chunk));
      const pdfReady = new Promise<Buffer>((resolve) => {
        doc.on("end", () => resolve(Buffer.concat(chunks)));
      });

      doc.fontSize(16).font("Helvetica-Bold").text(`Timesheet — ${supplier.companyName}`, { align: "center" });
      doc.moveDown(0.3);
      doc.fontSize(10).font("Helvetica").text(`Invoice: ${invoice.invoiceNumber} | Period: ${invoice.periodStart} to ${invoice.periodEnd} | Total Shifts: ${lineResult.rows.length}`, { align: "center" });
      doc.moveDown(0.8);

      const colWidths = [75, 200, 130, 50, 50, 50, 55, 60];
      const headers = ["Date", "Site", "Officer", "Start", "End", "Hours", "Rate", "Amount"];
      const startX = 40;
      let y = doc.y;

      doc.font("Helvetica-Bold").fontSize(7);
      doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 16).fill("#1F3A5F");
      let x = startX;
      headers.forEach((h, i) => {
        doc.fillColor("#FFFFFF").text(h, x + 3, y + 4, { width: colWidths[i] - 6, align: "left" });
        x += colWidths[i];
      });
      y += 18;

      doc.font("Helvetica").fontSize(7).fillColor("#333");
      let totalHours = 0;
      let totalAmount = 0;
      for (const r of lineResult.rows) {
        if (y > 520) {
          doc.addPage({ layout: "landscape" });
          y = 40;
          doc.font("Helvetica-Bold").fontSize(7);
          doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 16).fill("#1F3A5F");
          x = startX;
          headers.forEach((h, i) => {
            doc.fillColor("#FFFFFF").text(h, x + 3, y + 4, { width: colWidths[i] - 6, align: "left" });
            x += colWidths[i];
          });
          y += 18;
          doc.font("Helvetica").fontSize(7).fillColor("#333");
        }
        const hrs = parseFloat(r.hours || "0");
        const amt = parseFloat(r.subtotal || "0");
        totalHours += hrs;
        totalAmount += amt;
        x = startX;
        const rowBg = lineResult.rows.indexOf(r) % 2 === 0 ? "#FFFFFF" : "#F8F9FA";
        doc.rect(startX, y, colWidths.reduce((a, b) => a + b, 0), 14).fill(rowBg);
        doc.fillColor("#333");
        const vals = [r.shift_date || "", r.site_name, r.employee_name, r.start_time || "", r.end_time || "", hrs.toFixed(2), `£${parseFloat(r.rate || "0").toFixed(2)}`, `£${amt.toFixed(2)}`];
        vals.forEach((v, i) => {
          doc.text(v, x + 3, y + 3, { width: colWidths[i] - 6, align: "left", height: 14, ellipsis: true });
          x += colWidths[i];
        });
        y += 14;
      }

      y += 4;
      doc.font("Helvetica-Bold").fontSize(8).fillColor("#1F3A5F");
      doc.text(`Total: ${totalHours.toFixed(2)} hours | £${totalAmount.toFixed(2)}`, startX, y);

      doc.end();
      const pdfBuffer = await pdfReady;

      const sanitizedName = supplier.companyName?.replace(/[^a-zA-Z0-9]/g, "_").replace(/_+/g, "_").replace(/^_|_$/g, "") || "Supplier";
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="Timesheet_${invoice.invoiceNumber || invoiceId}_${sanitizedName}.pdf"`);
      res.send(pdfBuffer);
    } catch (err: any) {
      if (!res.headersSent) res.status(500).json({ message: err.message });
    }
  });

