  app.post("/api/disputes", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const { shiftId, reason } = req.body;
      if (!shiftId || !reason?.trim()) {
        return res.status(400).json({ message: "Shift ID and reason are required" });
      }

      const existingDispute = await storage.getDisputeByShift(shiftId);
      if (existingDispute) {
        return res.status(400).json({ message: "A dispute already exists for this shift" });
      }

      const dispute = await storage.createDispute({
        tenantId: supplier.tenantId!,
        shiftId,
        supplierId: supplier.id,
        reason: reason.trim(),
        createdBy: user.id,
      });

      await storage.createDisputeMessage({
        disputeId: dispute.id,
        userId: user.id,
        userName: supplier.companyName || supplier.contactName || "Supplier",
        message: reason.trim(),
      });

      await storage.updateShift(shiftId, {
        supplierApprovalStatus: "disputed",
        supplierApprovalComment: reason.trim(),
        supplierApprovedAt: new Date(),
        supplierApprovedBy: user.id,
      });

      await storage.createAuditLog({
        tenantId: supplier.tenantId!,
        userId: user.id,
        action: "dispute_created",
        entityType: "dispute",
        entityId: String(dispute.id),
        details: { shiftId, supplierId: supplier.id, reason: reason.trim() },
      });

      const adminUsers = await storage.getUsersByTenant(supplier.tenantId!);
      const adminRoles = ["super_admin", "tenant_admin", "admin", "operations_manager", "accountant", "hr_manager"];
      for (const admin of adminUsers.filter(u => adminRoles.includes(u.role))) {
        await storage.createNotification({
          userId: admin.id,
          type: "dispute_created",
          title: "New Timesheet Dispute",
          body: `${supplier.companyName} has raised a dispute on shift #${shiftId}: ${reason.trim().substring(0, 100)}`,
          link: "/disputes",
          relatedEntityType: "dispute",
          relatedEntityId: String(dispute.id),
          metadata: { shiftId, supplierId: supplier.id },
        });
      }

      res.json(dispute);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

