  app.get("/api/rate-cards", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json([]);
      const cards = await storage.getRateCardsByTenant(user.tenantId);
      const supplierIds = [...new Set(cards.map(c => c.supplierId).filter(Boolean))];
      const supplierNameMap = new Map<number, string>();
      for (const sid of supplierIds) {
        const supplier = await storage.getSupplier(sid as number);
        if (supplier) supplierNameMap.set(sid as number, supplier.companyName);
      }
      const employeeIds = [...new Set(cards.map(c => c.employeeId).filter(Boolean))];
      const employeeNameMap = new Map<number, string>();
      for (const eid of employeeIds) {
        const emp = await storage.getEmployee(eid as number);
        if (emp && emp.userId) {
          const empUser = await storage.getUser(emp.userId);
          if (empUser) employeeNameMap.set(eid as number, `${empUser.firstName} ${empUser.lastName}`);
        }
      }
      const siteIds = [...new Set(cards.map(c => c.siteId).filter(Boolean))];
      const siteNameMap = new Map<number, string>();
      for (const sid of siteIds) {
        const site = await storage.getSite(sid as number);
        if (site) siteNameMap.set(sid as number, site.name);
      }
      const enriched = cards.map(c => ({
        ...c,
        supplierName: c.supplierId ? supplierNameMap.get(c.supplierId) || null : null,
        employeeName: c.employeeId ? employeeNameMap.get(c.employeeId) || null : null,
        siteName: c.siteId ? siteNameMap.get(c.siteId) || null : null,
      }));
      res.json(enriched);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/rate-cards", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "accountant"), async (req, res) => {
    try {
      const user = req.user as User;
      const { supplierId, roleType, siteId, effectiveFrom } = req.body;

      const { employeeId } = req.body;
      if (supplierId && roleType && effectiveFrom) {
        const existingCards = await storage.getRateCardsBySupplier(supplierId);
        const matchingCards = existingCards.filter(rc => {
          if (rc.roleType !== roleType) return false;
          const rcSiteId = rc.siteId || null;
          const newSiteId = siteId || null;
          if (rcSiteId !== newSiteId) return false;
          const rcEmployeeId = rc.employeeId || null;
          const newEmployeeId = employeeId || null;
          if (rcEmployeeId !== newEmployeeId) return false;
          if (rc.effectiveTo) return false;
          return true;
        });

        const dayBefore = new Date(effectiveFrom);
        dayBefore.setDate(dayBefore.getDate() - 1);
        const expiryDate = dayBefore.toISOString().split("T")[0];

        for (const existing of matchingCards) {
          await storage.updateRateCard(existing.id, { effectiveTo: expiryDate });
        }
      }

      const card = await storage.createRateCard({
        ...req.body,
        tenantId: user.tenantId,
        createdBy: user.id,
      });

      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: "rate_card_created", entityType: "rate_card",
        entityId: String(card.id), details: req.body,
      });
      res.json(card);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

