  app.post("/api/invoices/record-payment", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "accountant", "payroll_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant associated" });

      const { invoiceIds, bankTransactionId, bankReference, datePaid } = req.body;
      if (!invoiceIds || !Array.isArray(invoiceIds) || invoiceIds.length === 0) {
        return res.status(400).json({ message: "At least one invoice ID is required" });
      }

      const invoices = [];
      for (const id of invoiceIds) {
        const inv = await storage.getInvoice(id);
        if (!inv) return res.status(404).json({ message: `Invoice ${id} not found` });
        if (inv.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
        if (inv.status === "paid") return res.status(400).json({ message: `Invoice ${inv.invoiceNumber} is already paid` });
        invoices.push(inv);
      }

      const paidInvoiceIds: number[] = [];
      const client = await pool.connect();
      try {
        await client.query("BEGIN");

        if (bankTransactionId) {
          const txCheck = await client.query(
            `SELECT id, amount, allocated_amount, supplier_id, transaction_date FROM bank_transactions WHERE id = $1 AND tenant_id = $2`,
            [bankTransactionId, user.tenantId]
          );
          if (txCheck.rows.length === 0) throw new Error("Bank transaction not found");
          const bankTx = txCheck.rows[0];
          const txnAmount = Math.abs(parseFloat(bankTx.amount));
          const currentAllocated = parseFloat(bankTx.allocated_amount || "0");
          let remaining = txnAmount - currentAllocated;

          if (remaining < 0.01) {
            throw new Error("This bank transaction is already fully allocated");
          }

          if (bankTx.supplier_id) {
            const mismatch = invoices.find(inv => inv.supplierId !== bankTx.supplier_id);
            if (mismatch) {
              throw new Error(`Invoice ${mismatch.invoiceNumber} belongs to a different supplier than the selected bank transaction`);
            }
          }

          const totalInvoiceAmount = invoices.reduce((sum, inv) => sum + parseFloat(inv.totalAmount), 0);
          if (totalInvoiceAmount > remaining + 0.01) {
            throw new Error(`Selected invoices total £${totalInvoiceAmount.toFixed(2)} exceeds remaining £${remaining.toFixed(2)} on this transaction`);
          }

          for (const inv of invoices) {
            const invAmount = parseFloat(inv.totalAmount);
            const allocAmount = Math.min(invAmount, remaining);
            if (allocAmount < 0.01) break;

            await client.query(
              `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, invoice_id, supplier_id, amount, allocated_by, notes)
               VALUES ($1, $2, $3, $4, $5, $6, $7)`,
              [user.tenantId, bankTransactionId, inv.id, inv.supplierId, allocAmount.toFixed(2), user.id, `Allocated from bank txn #${bankTransactionId}`]
            );

            remaining -= allocAmount;

            const totalPaidResult = await client.query(
              `SELECT COALESCE(SUM(amount::numeric), 0) as total_paid FROM bank_transaction_allocations WHERE invoice_id = $1`,
              [inv.id]
            );
            const totalPaid = parseFloat(totalPaidResult.rows[0].total_paid);
            if (totalPaid >= invAmount - 0.01) {
              await client.query(
                `UPDATE invoices SET status = 'paid', paid_at = NOW(), paid_by = $1, payment_date = $2 WHERE id = $3`,
                [user.id, bankTx.transaction_date, inv.id]
              );
            }

            paidInvoiceIds.push(inv.id);
          }

          const actualAllocResult = await client.query(
            `SELECT COALESCE(SUM(amount::numeric), 0) as total FROM bank_transaction_allocations WHERE bank_transaction_id = $1`,
            [bankTransactionId]
          );
          const newAllocated = parseFloat(actualAllocResult.rows[0].total);
          const fullyAllocated = newAllocated >= txnAmount - 0.01;
          await client.query(
            `UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2 WHERE id = $3`,
            [newAllocated.toFixed(2), fullyAllocated, bankTransactionId]
          );
        } else {
          if (!bankReference?.trim()) throw new Error("Bank reference is required");
          if (!datePaid) throw new Error("Date paid is required");

          const supplierGroups = new Map<number, typeof invoices>();
          for (const inv of invoices) {
            const sid = inv.supplierId!;
            if (!supplierGroups.has(sid)) supplierGroups.set(sid, []);
            supplierGroups.get(sid)!.push(inv);
          }

          for (const [supplierId, groupInvoices] of supplierGroups) {
            const totalAmount = groupInvoices.reduce((sum, inv) => sum + parseFloat(inv.totalAmount), 0);

            const txResult = await client.query(
              `INSERT INTO bank_transactions (tenant_id, transaction_date, description, amount, type, reference, is_allocated, allocated_amount, supplier_id, import_batch_id)
               VALUES ($1, $2, $3, $4, 'debit', $5, true, $6, $7, $8) RETURNING id`,
              [user.tenantId, datePaid, "Manual payment entry", (-totalAmount).toFixed(2), bankReference.trim(), totalAmount.toFixed(2), supplierId, `manual-${Date.now()}`]
            );
            const bankTxId = txResult.rows[0].id;

            for (const inv of groupInvoices) {
              await client.query(
                `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, invoice_id, supplier_id, amount, allocated_by, notes)
                 VALUES ($1, $2, $3, $4, $5, $6, $7)`,
                [user.tenantId, bankTxId, inv.id, supplierId, inv.totalAmount, user.id, `Manual payment - ${bankReference.trim()}`]
              );

              await client.query(
                `UPDATE invoices SET status = 'paid', paid_at = NOW(), paid_by = $1, payment_date = $2 WHERE id = $3`,
                [user.id, datePaid, inv.id]
              );

              paidInvoiceIds.push(inv.id);
            }
          }
        }

        await client.query("COMMIT");
      } catch (txErr) {
        await client.query("ROLLBACK");
        throw txErr;
      } finally {
        client.release();
      }

      for (const inv of invoices) {
        await storage.createAuditLog({
          tenantId: user.tenantId!, userId: user.id,
          action: "invoice_payment_recorded", entityType: "invoice",
          entityId: String(inv.id),
          details: { invoiceNumber: inv.invoiceNumber, totalAmount: inv.totalAmount, bankReference: bankReference.trim(), datePaid },
        });
      }

      res.json({ success: true, paidInvoiceIds, count: paidInvoiceIds.length });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/invoices/:id/credit-note", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "accountant"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant associated" });

      const invoiceId = parseInt(req.params.id);
      const { reason } = req.body;
      if (!reason?.trim()) {
        return res.status(400).json({ message: "A reason is required for issuing a credit note" });
      }

      const invoice = await storage.getInvoice(invoiceId);
      if (!invoice) return res.status(404).json({ message: "Invoice not found" });
      if (invoice.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
      if (invoice.status === "cancelled") return res.status(400).json({ message: "Invoice is already cancelled" });

      const tenant = await storage.getTenant(user.tenantId);
      const tenantPrefix = (tenant?.name || "GRD").substring(0, 3).toUpperCase();
      const periodLabel = invoice.periodStart ? new Date(invoice.periodStart).toISOString().substring(0, 7).replace("-", "") : new Date().toISOString().substring(0, 7).replace("-", "");
      const maxResult = await pool.query("SELECT COUNT(*) as cnt FROM credit_notes WHERE tenant_id = $1", [user.tenantId]);
      const nextNum = parseInt(maxResult.rows[0]?.cnt || "0") + 1;
      const creditNoteNumber = `CN-${tenantPrefix}-${periodLabel}-${String(nextNum).padStart(4, "0")}`;

      const note = await storage.createCreditNote({
        tenantId: user.tenantId,
        invoiceId,
        creditNoteNumber,
        reason: reason.trim(),
        subtotal: String(invoice.subtotal || "0"),
        vatRate: String(invoice.vatRate || "0"),
        vatAmount: String(invoice.vatAmount || "0"),
        totalAmount: String(invoice.totalAmount || "0"),
        status: "issued",
        issuedBy: user.id,
        issuedAt: new Date(),
      });

      await pool.query("DELETE FROM invoice_line_items WHERE invoice_id = $1", [invoiceId]);

      await storage.updateInvoice(invoiceId, { status: "cancelled" } as any);

      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: "credit_note_issued", entityType: "credit_note",
        entityId: String(note.id),
        details: {
          creditNoteNumber,
          invoiceId,
          invoiceNumber: invoice.invoiceNumber,
          reason: reason.trim(),
          totalAmount: invoice.totalAmount,
        },
      });

      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: "invoice_cancelled", entityType: "invoice",
        entityId: String(invoiceId),
        details: {
          invoiceNumber: invoice.invoiceNumber,
          creditNoteNumber,
          reason: reason.trim(),
        },
      });

      res.json({ ...note, invoiceNumber: invoice.invoiceNumber });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

