  // ── Invoice Deletion (Safe Cascade) ──

  const INVOICE_DELETE_ROLES = ["super_admin", "tenant_admin", "ceo", "admin", "accountant"] as const;

  async function cascadeDeleteInvoice(client: any, invoiceId: number, tenantId: number) {
    const inv = await client.query(
      `SELECT i.*, COALESCE(s.company_name, 'Unknown') as supplier_name
       FROM invoices i LEFT JOIN suppliers s ON i.supplier_id = s.id
       WHERE i.id = $1 AND i.tenant_id = $2`,
      [invoiceId, tenantId]
    );
    if (inv.rows.length === 0) return null;
    const invoice = inv.rows[0];

    const cnIds = await client.query("SELECT id FROM credit_notes WHERE invoice_id = $1", [invoiceId]);
    const cnCount = cnIds.rows.length;
    if (cnCount > 0) {
      const ids = cnIds.rows.map((r: any) => r.id);
      await client.query("DELETE FROM credit_note_line_items WHERE credit_note_id = ANY($1)", [ids]);
      await client.query("DELETE FROM credit_notes WHERE invoice_id = $1", [invoiceId]);
    }

    const dnIds = await client.query("SELECT id FROM debit_notes WHERE invoice_id = $1", [invoiceId]);
    const dnCount = dnIds.rows.length;
    if (dnCount > 0) {
      const dnIdList = dnIds.rows.map((r: any) => r.id);
      await client.query("DELETE FROM debit_note_line_items WHERE debit_note_id = ANY($1)", [dnIdList]);
      await client.query("DELETE FROM debit_notes WHERE invoice_id = $1", [invoiceId]);
    }

    const allocResult = await client.query("DELETE FROM bank_transaction_allocations WHERE invoice_id = $1 RETURNING id, bank_transaction_id, amount", [invoiceId]);
    const allocCount = allocResult.rowCount || 0;

    await client.query("UPDATE auto_classification_suggestions SET invoice_id = NULL WHERE invoice_id = $1", [invoiceId]);

    const lineResult = await client.query("DELETE FROM invoice_line_items WHERE invoice_id = $1 RETURNING id", [invoiceId]);
    const lineCount = lineResult.rowCount || 0;

    await client.query("DELETE FROM invoices WHERE id = $1", [invoiceId]);

    return {
      invoiceId,
      invoiceNumber: invoice.invoice_number,
      supplierName: invoice.supplier_name,
      totalAmount: invoice.total_amount,
      status: invoice.status,
      creditNotesRemoved: cnCount,
      debitNotesRemoved: dnCount,
      allocationsRemoved: allocCount,
      lineItemsRemoved: lineCount,
      deallocatedTransactions: allocResult.rows || [],
    };
  }

  app.delete("/api/invoices/:id", requireRole(...INVOICE_DELETE_ROLES), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant associated" });
      const invoiceId = parseInt(req.params.id);
      if (isNaN(invoiceId)) return res.status(400).json({ message: "Invalid invoice ID" });

      const client = await pool.connect();
      try {
        await client.query("BEGIN");
        const result = await cascadeDeleteInvoice(client, invoiceId, user.tenantId);
        if (!result) {
          await client.query("ROLLBACK");
          return res.status(404).json({ message: "Invoice not found" });
        }

        await client.query(
          `INSERT INTO audit_logs (tenant_id, user_id, action, entity_type, entity_id, details, created_at)
           VALUES ($1, $2, $3, $4, $5, $6, NOW())`,
          [user.tenantId, user.id, "invoice_deleted", "invoice", String(invoiceId),
           JSON.stringify({
             invoiceNumber: result.invoiceNumber,
             supplierName: result.supplierName,
             totalAmount: result.totalAmount,
             status: result.status,
             allocationsRemoved: result.allocationsRemoved,
             creditNotesRemoved: result.creditNotesRemoved,
             lineItemsRemoved: result.lineItemsRemoved,
           })]
        );

        await client.query("COMMIT");
        res.json({ message: "Invoice deleted successfully", ...result });
      } catch (err) {
        await client.query("ROLLBACK");
        throw err;
      } finally {
        client.release();
      }
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/invoices/bulk-delete", requireRole(...INVOICE_DELETE_ROLES), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant associated" });

      const { supplierId, month, invoiceIds } = req.body;
      if (!supplierId && !month && (!invoiceIds || invoiceIds.length === 0)) {
        return res.status(400).json({ message: "At least one filter (supplierId, month, or invoiceIds) is required" });
      }

      let conditions = ["i.tenant_id = $1"];
      let params: any[] = [user.tenantId];
      let paramIdx = 2;

      if (invoiceIds && invoiceIds.length > 0) {
        conditions.push(`i.id = ANY($${paramIdx})`);
        params.push(invoiceIds);
        paramIdx++;
      }
      if (supplierId) {
        conditions.push(`i.supplier_id = $${paramIdx}`);
        params.push(supplierId);
        paramIdx++;
      }
      if (month) {
        conditions.push(`(i.period_start IS NOT NULL AND TO_CHAR(i.period_start, 'YYYY-MM') = $${paramIdx})`);
        params.push(month);
        paramIdx++;
      }

      const invoicesResult = await pool.query(
        `SELECT i.id, i.invoice_number, COALESCE(s.company_name, 'Unknown') as supplier_name, i.total_amount, i.status
         FROM invoices i LEFT JOIN suppliers s ON i.supplier_id = s.id
         WHERE ${conditions.join(" AND ")} ORDER BY i.id`,
        params
      );

      if (invoicesResult.rows.length === 0) {
        return res.status(404).json({ message: "No invoices found matching the criteria" });
      }

      const client = await pool.connect();
      try {
        await client.query("BEGIN");

        const results: any[] = [];
        let totalAllocationsRemoved = 0;
        let totalAmountDeleted = 0;

        for (const inv of invoicesResult.rows) {
          const result = await cascadeDeleteInvoice(client, inv.id, user.tenantId);
          if (result) {
            results.push(result);
            totalAllocationsRemoved += result.allocationsRemoved;
            totalAmountDeleted += parseFloat(result.totalAmount || "0");
          }
        }

        await client.query(
          `INSERT INTO audit_logs (tenant_id, user_id, action, entity_type, entity_id, details, created_at)
           VALUES ($1, $2, $3, $4, $5, $6, NOW())`,
          [user.tenantId, user.id, "invoices_bulk_deleted", "invoice", "bulk",
           JSON.stringify({
             invoiceCount: results.length,
             totalAmount: totalAmountDeleted.toFixed(2),
             allocationsRemoved: totalAllocationsRemoved,
             supplierId: supplierId || null,
             month: month || null,
             invoiceNumbers: results.map(r => r.invoiceNumber),
           })]
        );

        await client.query("COMMIT");
        res.json({
          message: `${results.length} invoice(s) deleted successfully`,
          deletedCount: results.length,
          totalAmountDeleted: totalAmountDeleted.toFixed(2),
          totalAllocationsRemoved,
          invoices: results.map(r => ({
            invoiceId: r.invoiceId,
            invoiceNumber: r.invoiceNumber,
            supplierName: r.supplierName,
            totalAmount: r.totalAmount,
            allocationsRemoved: r.allocationsRemoved,
          })),
        });
      } catch (err) {
        await client.query("ROLLBACK");
        throw err;
      } finally {
        client.release();
      }
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // ── Document Templates ──

  const TEMPLATE_ROLES = ["super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "accountant"] as const;

  function getDefaultAgreementSections(buyerName: string, supplierName: string, isVat: boolean) {
    return [
      { heading: "1. Purpose and Legal Basis", text: `This agreement establishes a self-billing procedure as provided for under Section 29 of the Value Added Tax Act 1994 and Regulations 13(3) and 13(3A) to 13(3F) of the VAT Regulations 1995. Under this arrangement, the Customer shall prepare invoices on behalf of the Supplier for all supplies of goods and/or services covered by this agreement, in compliance with HMRC VAT Notice 700/62.\nVAT will be applied at the standard rate (currently 20%) where the Supplier is VAT registered, or at 0% where the Supplier is not VAT registered.` },
      { heading: "2. Scope of Supplies", text: `This agreement covers all supplies of security staffing, guarding services, and related labour services provided by the Supplier to the Customer, including but not limited to:\n  • Security officer deployments and shift-based labour supply\n  • Event security and temporary staffing\n  • Any ancillary services agreed between the parties` },
      { heading: "3. Obligations of the Customer (Self-Biller)", text: `The Customer agrees to:\n  • Issue self-billed invoices for all supplies made by the Supplier for the duration of this agreement (VAT Notice 700/62, Section 4.1)\n  • Issue a copy of each self-billed invoice to the Supplier\n  • Complete self-billed invoices showing the Supplier's name, address and VAT registration number, together with all the details that constitute a full VAT invoice\n  • Make a new self-billing agreement if the Customer's VAT registration number changes\n  • Keep the names, addresses and VAT registration numbers of all suppliers with whom self-billing agreements exist\n  • Account for the VAT shown on all self-billed invoices in the appropriate VAT return\n  • Complete payment to the Supplier within the agreed payment terms` },
      { heading: "4. Obligations of the Supplier (Self-Billee)", text: `The Supplier agrees to:\n  • Accept invoices raised by the Customer on their behalf for the duration of this agreement\n  • Not raise invoices for the transactions covered by this agreement\n  • Notify the Customer immediately if there is any change to the Supplier's VAT registration status\n  • Notify the Customer immediately if the Supplier sells or transfers their business as a going concern\n  • Accept each self-billed invoice created by the Customer\n  • Keep records of all self-billed invoices received for a minimum of 6 years\n  • Approve or dispute timesheet entries within the agreed timeframe` },
      { heading: "5. VAT Compliance", text: `• The current rate of VAT applicable is 20% (standard rate) unless otherwise stated\n  • The Customer will verify the Supplier's VAT registration number before issuing any self-billed invoices\n  • Each self-billed invoice will include the statement: "The VAT shown is your output tax due to HMRC"\n  • The Customer must be VAT registered for the duration of this agreement\n  • Any changes to VAT status must be communicated in writing without delay\n  • Input tax may only be claimed on self-billed invoices where the conditions in VAT Notice 700/62 are met` },
      { heading: "6. Adjustments: Debit Notes and Credit Notes", text: `In accordance with VAT Notice 700/62, Section 4.5:\n  • The Customer shall not reduce the value of a supply for which a self-billed invoice has already been raised by reducing the total shown on a subsequent invoice\n  • Where the value of a supply needs to be adjusted, the Customer shall issue a self-billed debit note\n  • Where a self-billed invoice overstates the amount due, the Customer shall issue a self-billed credit note referencing the original invoice\n  • The Supplier agrees not to issue credit notes, debit notes, or any adjusting documents for supplies covered by this agreement` },
      { heading: "7. Electronic Invoicing", text: `In accordance with HMRC VAT Notice 700/63 (Electronic Invoicing):\n  • The Supplier consents to receiving self-billed invoices in electronic format via the Gardeo platform\n  • Electronic invoices issued under this agreement are the legal documents for VAT purposes\n  • The Gardeo platform ensures the authenticity of origin, the integrity of content, and legibility through business controls\n  • All electronic invoices contain the same information as would be required on paper invoices` },
      { heading: "8. Third Party Outsourcing", text: `In accordance with VAT Notice 700/62, Section 4.4: the Customer may use the Gardeo workforce management platform as a third-party service provider to issue self-billed invoices on the Customer's behalf. The Customer remains responsible for ensuring that invoices are issued correctly, for maintaining self-billing agreements, and for producing records for HMRC inspection.` },
      { heading: "9. Duration and Renewal", text: `• This agreement is valid for 12 months from the date of signing\n  • The agreement may be renewed by mutual consent for further 12-month periods\n  • The Customer will review this agreement before its expiry\n  • Both parties must avoid self-billing at any time when a valid written agreement is not in place` },
      { heading: "10. Termination", text: `Either party may terminate this agreement by giving 30 days' written notice to the other party. Termination is automatic and immediate if:\n  • The Customer ceases to be VAT registered\n  • Either party goes into administration, receivership, or liquidation\n  • The Supplier transfers the business as a going concern\nUpon termination, the Customer shall issue any outstanding self-billed invoices within 14 days.` },
      { heading: "11. Record Keeping", text: `In accordance with HMRC VAT Notice 700/21 (Record Keeping):\n  • Both parties agree to keep all self-billed invoices, credit notes, debit notes, and records relating to this agreement for a minimum of 6 years\n  • Records must be complete, up to date, and allow correct calculation of VAT payable or claimable\n  • These records must be made available for inspection by HMRC visiting officers on request\n  • Digital records maintained through the Gardeo platform satisfy the requirements for functional compatible software under Making Tax Digital` },
      { heading: "12. Governing Law", text: "This agreement shall be governed by and construed in accordance with the laws of England and Wales. Any disputes arising under this agreement shall be subject to the exclusive jurisdiction of the courts of England and Wales." },
    ];
  }

  async function ensureDefaultTemplates(tenantId: number) {
    const existing = await storage.getDocumentTemplatesByTenant(tenantId);
    if (existing.length === 0) {
      await storage.createDocumentTemplate({
        tenantId,
        name: "Standard Self-Billing Agreement",
        documentType: "self_billing_agreement",
        isDefault: true,
        headerTitle: "SELF-BILLING AGREEMENT",
        headerSubtitle: "In accordance with HMRC VAT Notice 700/62",
        sections: getDefaultAgreementSections("", "", true),
        footerText: null,
        complianceText: "VAT Notice 700/62 — Self-billing | VAT Notice 700/21 — Record keeping | VAT Notice 700/63 — Electronic invoicing | VATREC5010 — Full VAT invoice details\nLegal Basis: Value Added Tax Act 1994, Section 29 | VAT Regulations 1995, Regulations 13(3) and 13(3A) to 13(3F)",
        paymentTermsText: null,
      });
      await storage.createDocumentTemplate({
        tenantId,
        name: "Standard Self-Billing Invoice",
        documentType: "self_billing_invoice",
        isDefault: true,
        headerTitle: "SELF-BILLED INVOICE",
        headerSubtitle: "SELF-BILLING",
        sections: null,
        footerText: "This self-billed invoice has been prepared by the buyer under a self-billing arrangement.",
        complianceText: "This self-billed invoice is issued in accordance with HMRC VAT Notice 700/62.\nCompliant with: VAT Notice 700/62 | VAT Notice 700/21 | VAT Notice 700/63 | VATREC5010\nGenerated electronically by Gardeo Workforce Management Platform",
        paymentTermsText: "Payment due within 30 days of invoice date.",
        invoiceFormat: "detailed",
      });
      await storage.createDocumentTemplate({
        tenantId,
        name: "Summary Self-Billing Invoice",
        documentType: "self_billing_invoice",
        isDefault: false,
        headerTitle: "SELF-BILLED INVOICE",
        headerSubtitle: "SELF-BILLING",
        sections: null,
        footerText: "This self-billed invoice has been prepared by the buyer under a self-billing arrangement.",
        complianceText: "This self-billed invoice is issued in accordance with HMRC VAT Notice 700/62.\nCompliant with: VAT Notice 700/62 | VAT Notice 700/21 | VAT Notice 700/63 | VATREC5010\nGenerated electronically by Gardeo Workforce Management Platform",
        paymentTermsText: "Payment due within 30 days of invoice date.",
        invoiceFormat: "summary",
      });
    }
    const tsTemplates = existing.filter(t => t.documentType === "timesheet");
    const hasTimesheetTemplates = tsTemplates.length > 0;
    const hasDetailedTimesheet = tsTemplates.some(t => (t as any).invoiceFormat === "detailed");
    if (hasTimesheetTemplates && !hasDetailedTimesheet) {
      await storage.createDocumentTemplate({
        tenantId,
        name: "Timesheet Detailed",
        documentType: "timesheet",
        isDefault: false,
        headerTitle: "TIMESHEET",
        invoiceFormat: "detailed",
      });
    }
    if (!hasTimesheetTemplates) {
      await storage.createDocumentTemplate({
        tenantId,
        name: "Timesheet Without Officer",
        documentType: "timesheet",
        isDefault: true,
        headerTitle: "ITEMISED TIMESHEET",
        invoiceFormat: "without_officer",
      });
      await storage.createDocumentTemplate({
        tenantId,
        name: "Timesheet With Officer",
        documentType: "timesheet",
        isDefault: false,
        headerTitle: "ITEMISED TIMESHEET",
        invoiceFormat: "with_officer",
      });
      await storage.createDocumentTemplate({
        tenantId,
        name: "Timesheet Detailed",
        documentType: "timesheet",
        isDefault: false,
        headerTitle: "TIMESHEET",
        invoiceFormat: "detailed",
      });
    }
    // Ensure purchase ledger format templates exist
    const hasPurchaseLedgerTemplates = existing.some(t => t.documentType === "purchase_ledger");
    if (!hasPurchaseLedgerTemplates) {
      await storage.createDocumentTemplate({
        tenantId,
        name: "HMRC Audit Layout",
        documentType: "purchase_ledger",
        isDefault: true,
        headerTitle: "HMRC PURCHASE LEDGER",
        invoiceFormat: "hmrc_audit",
        sections: null, footerText: null, complianceText: null, paymentTermsText: null, headerSubtitle: null,
      });
      await storage.createDocumentTemplate({
        tenantId,
        name: "Accounting Software Layout",
        documentType: "purchase_ledger",
        isDefault: false,
        headerTitle: "Purchase Ledger",
        invoiceFormat: "accounting_style",
        sections: null, footerText: null, complianceText: null, paymentTermsText: null, headerSubtitle: null,
      });
    }

    // Ensure offer letter template exists
    const hasOfferLetter = existing.some(t => t.documentType === "offer_letter");
    if (!hasOfferLetter) {
      await storage.createDocumentTemplate({
        tenantId,
        name: "Standard Offer Letter",
        documentType: "offer_letter",
        isDefault: true,
        headerTitle: "OFFER OF EMPLOYMENT",
        headerSubtitle: "Private & Confidential",
        sections: [
          {
            heading: "Introduction",
            text: "Dear {{APPLICANT_NAME}},\n\nWe are delighted to offer you the position of {{JOB_TITLE}} at {{COMPANY_NAME}}. We were impressed by your background and believe you will be a valuable addition to our team.",
          },
          {
            heading: "Terms of Offer",
            text: "Position: {{JOB_TITLE}}\nAnnual Salary: {{SALARY}}\nProposed Start Date: {{START_DATE}}\nEmployment Type: Subject to employment contract",
          },
          {
            heading: "Pre-Employment Checks",
            text: "This offer is conditional upon the satisfactory completion of pre-employment vetting, including but not limited to: identity verification, right-to-work checks, DBS check, SIA licence verification (where required), and reference checks in accordance with BS7858.",
          },
          {
            heading: "Acceptance",
            text: "Please confirm your acceptance of this offer by signing and returning a copy of this letter within 5 working days. If you have any questions regarding this offer, please do not hesitate to contact us.",
          },
        ],
        footerText: "Yours sincerely,",
        complianceText: "This offer letter is issued in accordance with UK employment law. All data processed in connection with your employment is handled under GDPR and the Data Protection Act 2018. Generated electronically by Gardeo Workforce Management Platform.",
        paymentTermsText: null,
        invoiceFormat: null,
      });
    }

    return storage.getDocumentTemplatesByTenant(tenantId);
  }

  app.get("/api/document-templates", requireRole(...TEMPLATE_ROLES), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant associated" });
      const type = req.query.type as string | undefined;
      const templates = await ensureDefaultTemplates(user.tenantId);
      if (type) {
        res.json(templates.filter(t => t.documentType === type));
      } else {
        res.json(templates);
      }
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

