  app.get("/api/supplier-portal/invoices", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.json([]);

      const tenant = await storage.getTenant(supplier.tenantId!);
      const cutoffDate = computeSupplierCutoffDate(supplier.dataVisibilityMonths, tenant?.supplierDataVisibilityMonths);

      const allInvoices = await storage.getInvoicesByTenant(supplier.tenantId!);
      let supplierInvoices = allInvoices.filter(i => i.supplierId === supplier.id);
      if (cutoffDate) {
        supplierInvoices = supplierInvoices.filter(i => isInvoiceWithinCutoff(i, cutoffDate));
      }
      res.json(supplierInvoices);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/supplier-portal/financial-summary", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.json({ totalInvoices: 0, totalValue: "0.00", totalPaid: "0.00", totalOutstanding: "0.00", pending: { count: 0, amount: "0.00" }, accepted: { count: 0, amount: "0.00" }, paid: { count: 0, amount: "0.00" }, overdue: { count: 0, amount: "0.00" }, recentPayments: [] });

      const tenant = await storage.getTenant(supplier.tenantId!);
      const cutoffDate = computeSupplierCutoffDate(supplier.dataVisibilityMonths, tenant?.supplierDataVisibilityMonths);
      const cutoffCondition = cutoffDate ? ` AND period_end >= '${cutoffDate}'` : '';

      const { rows: invoiceStats } = await pool.query(
        `SELECT
           COUNT(*)::int as total_invoices,
           COALESCE(SUM(total_amount::numeric), 0) as total_value,
           COALESCE(SUM(CASE WHEN status = 'paid' THEN total_amount::numeric ELSE 0 END), 0) as total_paid,
           COALESCE(SUM(CASE WHEN status != 'paid' THEN total_amount::numeric ELSE 0 END), 0) as total_outstanding,
           COALESCE(SUM(CASE WHEN status IN ('draft', 'pending') THEN 1 ELSE 0 END), 0)::int as pending_count,
           COALESCE(SUM(CASE WHEN status IN ('draft', 'pending') THEN total_amount::numeric ELSE 0 END), 0) as pending_amount,
           COALESCE(SUM(CASE WHEN status IN ('approved', 'accepted') THEN 1 ELSE 0 END), 0)::int as accepted_count,
           COALESCE(SUM(CASE WHEN status IN ('approved', 'accepted') THEN total_amount::numeric ELSE 0 END), 0) as accepted_amount,
           COALESCE(SUM(CASE WHEN status = 'paid' THEN 1 ELSE 0 END), 0)::int as paid_count,
           COALESCE(SUM(CASE WHEN status = 'paid' THEN total_amount::numeric ELSE 0 END), 0) as paid_amount,
           COALESCE(SUM(CASE WHEN status = 'overdue' THEN 1 ELSE 0 END), 0)::int as overdue_count,
           COALESCE(SUM(CASE WHEN status = 'overdue' THEN total_amount::numeric ELSE 0 END), 0) as overdue_amount
         FROM invoices WHERE supplier_id = $1 AND tenant_id = $2${cutoffCondition}`,
        [supplier.id, supplier.tenantId]
      );

      const { rows: recentPayments } = await pool.query(
        `SELECT bt.transaction_date::text as date, bta.amount::numeric(12,2) as amount, bt.description as bank_reference
         FROM bank_transaction_allocations bta
         JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
         WHERE bta.supplier_id = $1 AND bta.tenant_id = $2
         ORDER BY bt.transaction_date DESC
         LIMIT 5`,
        [supplier.id, supplier.tenantId]
      );

      const stats = invoiceStats[0];
      res.json({
        totalInvoices: stats.total_invoices,
        totalValue: Number(stats.total_value).toFixed(2),
        totalPaid: Number(stats.total_paid).toFixed(2),
        totalOutstanding: Number(stats.total_outstanding).toFixed(2),
        pending: { count: stats.pending_count, amount: Number(stats.pending_amount).toFixed(2) },
        accepted: { count: stats.accepted_count, amount: Number(stats.accepted_amount).toFixed(2) },
        paid: { count: stats.paid_count, amount: Number(stats.paid_amount).toFixed(2) },
        overdue: { count: stats.overdue_count, amount: Number(stats.overdue_amount).toFixed(2) },
        recentPayments: recentPayments.map((p: any) => ({
          date: p.date,
          amount: p.amount,
          bank_reference: (p.bank_reference || "").trim(),
        })),
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

