  const REMITTANCE_ROLES = ["super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager"];

  async function buildRemittanceData(tenantId: number, supplierId: number, invoiceIds: number[], paymentMonthLabel: string, opts?: { isFm?: boolean }) {
    const tenantRes = await pool.query("SELECT * FROM tenants WHERE id = $1", [tenantId]);
    if (tenantRes.rows.length === 0) throw new Error("Tenant not found");
    const tenant = tenantRes.rows[0];

    let supplier: any;
    if (opts?.isFm) {
      const r = await pool.query("SELECT * FROM fm_suppliers WHERE id = $1 AND tenant_id = $2", [supplierId, tenantId]);
      if (r.rows.length === 0) throw new Error("FM supplier not found");
      const fm = r.rows[0];
      supplier = {
        company_name: fm.company_name,
        vat_number: fm.vat_number,
        company_reg_number: fm.company_number,
        address_line_1: fm.address,
        postcode: fm.postcode,
        bank_name: null, sort_code: null, account_number: null, account_name: null,
      };
    } else {
      const supplierRes = await pool.query("SELECT * FROM suppliers WHERE id = $1 AND tenant_id = $2", [supplierId, tenantId]);
      if (supplierRes.rows.length === 0) throw new Error("Supplier not found");
      supplier = supplierRes.rows[0];
    }

    const invoicesRes = await pool.query(
      `SELECT id, invoice_number, period_start, period_end, subtotal, vat_amount, total_amount, status, paid_at
      FROM invoices WHERE id = ANY($1) AND tenant_id = $2 ORDER BY period_start`,
      [invoiceIds, tenantId]
    );

    const allocRes = await pool.query(
      `SELECT bta.invoice_id, bta.amount, bt.transaction_date, bt.reference, bt.description, bt.amount as tx_amount
      FROM bank_transaction_allocations bta
      JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
      WHERE bta.invoice_id = ANY($1) AND bta.tenant_id = $2
      ORDER BY bt.transaction_date`,
      [invoiceIds, tenantId]
    );

    const bankTxRes = await pool.query(`
      SELECT DISTINCT bt.transaction_date, bt.reference, bt.description, ABS(bt.amount::numeric) as amount
      FROM bank_transactions bt
      WHERE bt.tenant_id = $1 AND bt.supplier_id = $2 AND bt.amount::numeric < 0
        AND bt.id IN (
          SELECT bank_transaction_id FROM bank_transaction_allocations WHERE invoice_id = ANY($3) AND tenant_id = $1
        )
      ORDER BY bt.transaction_date
    `, [tenantId, supplierId, invoiceIds]);

    const paidAmountsByInvoice: Record<number, number> = {};
    for (const alloc of allocRes.rows) {
      paidAmountsByInvoice[alloc.invoice_id] = (paidAmountsByInvoice[alloc.invoice_id] || 0) + parseFloat(alloc.amount);
    }

    const invoiceItems = invoicesRes.rows
      .map((inv: any) => ({
        invoiceNumber: inv.invoice_number,
        periodStart: inv.period_start,
        periodEnd: inv.period_end,
        subtotal: inv.subtotal,
        vatAmount: inv.vat_amount,
        totalAmount: inv.total_amount,
        amountPaid: String(paidAmountsByInvoice[inv.id] || 0),
        status: inv.status,
      }));

    const totalPaid = invoiceItems.reduce((s: number, inv: any) => s + parseFloat(inv.amountPaid), 0);

    const tenantAddress = [tenant.address_line_1, tenant.address_line_2, tenant.city, tenant.county, tenant.postcode].filter(Boolean).join(", ") || tenant.address;
    const supplierAddress = supplier.agreement_registered_address
      ? buildSupplierAddress(supplier.agreement_registered_address, supplier.agreement_registered_city, supplier.agreement_registered_postcode)
      : supplier.registered_office_address
        ? buildSupplierAddress(supplier.registered_office_address, supplier.registered_office_city, supplier.registered_office_postcode)
        : [supplier.address_line_1, supplier.address_line_2, supplier.city, supplier.county, supplier.postcode].filter(Boolean).join(", ") || supplier.address;

    return {
      buyerName: tenant.trading_name || tenant.name,
      buyerAddress: tenantAddress,
      buyerVatNumber: tenant.vat_number,
      buyerCompanyRegNumber: tenant.company_reg_number,
      buyerPhone: tenant.phone,
      buyerEmail: tenant.email,
      supplierName: supplier.company_name,
      supplierAddress: supplierAddress,
      supplierVatNumber: supplier.vat_number || undefined,
      supplierCompanyRegNumber: supplier.company_reg_number || undefined,
      supplierBankName: supplier.bank_name,
      supplierSortCode: supplier.sort_code,
      supplierAccountNumber: supplier.account_number,
      supplierAccountName: supplier.account_name || supplier.company_name,
      remittanceDate: new Date().toISOString(),
      paymentMonth: paymentMonthLabel,
      invoices: invoiceItems,
      bankTransactions: bankTxRes.rows.map((tx: any) => ({
        date: tx.transaction_date,
        reference: tx.reference || "",
        description: tx.description || "",
        amount: String(parseFloat(tx.amount)),
      })),
      totalPaid: String(Math.round(totalPaid * 100) / 100),
    };
  }

  app.get("/api/suppliers/:supplierId/remittance-pdf", requireRole(...REMITTANCE_ROLES), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const supplierId = parseInt(req.params.supplierId);
      const month = req.query.month as string;
      if (!month || !/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ message: "month query param required (YYYY-MM format)" });

      const workMonthStart = `${month}-01`;
      const workMonthEnd = new Date(parseInt(month.split("-")[0]), parseInt(month.split("-")[1]), 0).toISOString().split("T")[0];

      const invoicesRes = await pool.query(
        `SELECT id FROM invoices WHERE supplier_id = $1 AND tenant_id = $2
          AND period_start >= $3::date AND period_start <= $4::date ORDER BY period_start`,
        [supplierId, user.tenantId, workMonthStart, workMonthEnd]
      );
      if (invoicesRes.rows.length === 0) return res.status(404).json({ message: "No invoices found for this supplier in this month" });

      const invoiceIds = invoicesRes.rows.map((r: any) => r.id);

      const [pmYr, pmMo] = month.split("-").map(Number);
      const payMonth = new Date(pmYr, pmMo, 1);
      const paymentMonthLabel = `${payMonth.getFullYear()}-${String(payMonth.getMonth() + 1).padStart(2, "0")}`;

      const data = await buildRemittanceData(user.tenantId, supplierId, invoiceIds, paymentMonthLabel);
      const pdfBuffer = await generateRemittancePdf(data);

      res.set({
        "Content-Type": "application/pdf",
        "Content-Disposition": `attachment; filename="remittance-${supplierId}-${safeFilename(month)}.pdf"`,
        "Content-Length": String(pdfBuffer.length),
      });
      res.send(pdfBuffer);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

