  app.get("/api/supplier-portal/invoices/:id/pdf", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier not found" });

      const invoice = await storage.getInvoice(parseInt(req.params.id));
      if (!invoice) return res.status(404).json({ message: "Invoice not found" });
      if (invoice.supplierId !== supplier.id) return res.status(403).json({ message: "Access denied" });

      const cutoffDate = await getSupplierCutoff(supplier);
      if (!isInvoiceWithinCutoff(invoice, cutoffDate)) return res.status(403).json({ message: "This invoice is outside your data visibility window" });

      const tenant = supplier.tenantId ? await storage.getTenant(supplier.tenantId) : null;
      const lineItems = await storage.getInvoiceLineItems(invoice.id);

      const buyerAddress = tenant ? [tenant.addressLine1, tenant.addressLine2, tenant.city, tenant.county, tenant.postcode].filter(Boolean).join(", ") : undefined;
      const supplierAddr = getSupplierAddressForPeriod(supplier, invoice.periodEnd) || undefined;

      const timesheetItems2: Array<{ date: string; siteName: string; hours: string; rate: string; amount: string; officerName?: string; startTime?: string; endTime?: string }> = [];
      for (const li of lineItems) {
        if (li.shiftId) {
          const shift = await storage.getShift(li.shiftId);
          const site = shift?.siteId ? await storage.getSite(shift.siteId) : null;
          const emp = shift?.employeeId ? await storage.getEmployee(shift.employeeId) : null;
          timesheetItems2.push({
            date: shift?.date || "",
            siteName: site?.name || shift?.title || "—",
            hours: li.hours,
            rate: li.rate,
            amount: li.subtotal,
            officerName: emp ? `${emp.firstName || ""} ${emp.lastName || ""}`.trim() || undefined : undefined,
            startTime: shift?.startTime || undefined,
            endTime: shift?.endTime || undefined,
          });
        }
      }

      const pdfBuffer = await generateInvoicePdf({
        invoiceNumber: invoice.invoiceNumber,
        invoiceDate: (invoice.issuedAt || invoice.generatedAt || invoice.createdAt || new Date()).toISOString(),
        taxPointDate: invoice.periodEnd,
        periodStart: invoice.periodStart,
        periodEnd: invoice.periodEnd,
        status: invoice.status || "draft",
        buyerName: tenant?.name || "Gardeo Platform",
        buyerAddress,
        buyerVatNumber: tenant?.vatNumber || undefined,
        buyerCompanyRegNumber: tenant?.companyRegNumber || undefined,
        buyerPhone: tenant?.phone || undefined,
        buyerEmail: tenant?.email || undefined,
        supplierName: supplier.companyName || "Supplier",
        supplierAddress: supplierAddr || undefined,
        supplierVatNumber: supplier.vatNumber || undefined,
        supplierCompanyRegNumber: supplier.companyRegNumber || undefined,
        supplierPhone: supplier.phone || undefined,
        supplierEmail: supplier.email || undefined,
        supplierVatRegistered: supplier.vatStatus === "vat_registered",
        supplierBankName: supplier.bankName || undefined,
        supplierAccountName: supplier.accountName || undefined,
        supplierSortCode: supplier.sortCode || undefined,
        supplierAccountNumber: supplier.accountNumber || undefined,
        selfBillingAgreementRef: supplier.selfBillingAgreementRef || undefined,
        lineItems: lineItems.map(li => ({
          description: li.description,
          hours: li.hours,
          rate: li.rate,
          subtotal: li.subtotal,
          vatRate: li.vatRate,
          vatAmount: li.vatAmount,
          lineTotal: li.lineTotal,
        })),
        timesheetItems: timesheetItems2.length > 0 ? timesheetItems2 : undefined,
        subtotal: invoice.subtotal,
        vatRate: invoice.vatRate || "0",
        vatAmount: invoice.vatAmount,
        totalAmount: invoice.totalAmount,
        issuedAt: (invoice as any).issuedAt?.toISOString(),
        acceptedAt: (invoice as any).acceptedAt?.toISOString(),
        paidAt: invoice.paidAt?.toISOString(),
        dueDate: invoice.dueDate || undefined,
        currency: "GBP (£)",
        notes: invoice.notes || undefined,
      });

      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="${invoice.invoiceNumber}.pdf"`);
      res.send(pdfBuffer);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

