  // ── Supplier Bulk Timesheet Approve ──

  app.post("/api/supplier-portal/timesheets/bulk-approve", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const { shiftIds } = req.body;
      if (!Array.isArray(shiftIds) || shiftIds.length === 0) {
        return res.status(400).json({ message: "At least one shift ID is required" });
      }

      const allShifts = await storage.getShiftsByTenant(supplier.tenantId!);
      const results: { approved: number[]; skipped: number[]; errors: string[] } = { approved: [], skipped: [], errors: [] };

      const autoCompletedShiftIds: number[] = [];

      for (const shiftId of shiftIds) {
        const shift = allShifts.find(s => s.id === shiftId && s.supplierId === supplier.id);
        if (!shift) {
          results.errors.push(`Shift #${shiftId}: not found or not assigned to your company`);
          continue;
        }
        if (!["scheduled", "in_progress", "completed"].includes(shift.status)) {
          results.skipped.push(shiftId);
          continue;
        }
        if (shift.supplierApprovalStatus === "approved") {
          results.skipped.push(shiftId);
          continue;
        }
        const wasNotCompleted = shift.status !== "completed";
        const updateData: any = {
          supplierApprovalStatus: "approved",
          supplierApprovalComment: null,
          supplierApprovedAt: new Date(),
          supplierApprovedBy: user.id,
        };
        if (wasNotCompleted) {
          updateData.status = "completed";
          updateData.checkOutTime = new Date().toISOString();
          autoCompletedShiftIds.push(shiftId);
        }
        await storage.updateShift(shiftId, updateData);
        results.approved.push(shiftId);
      }

      if (results.approved.length > 0) {
        await storage.createAuditLog({
          tenantId: supplier.tenantId!,
          userId: user.id,
          action: "supplier_timesheets_bulk_approved",
          entityType: "shift",
          entityId: results.approved.join(","),
          details: { supplierId: supplier.id, count: results.approved.length },
        });
      }

      for (const shiftId of autoCompletedShiftIds) {
        await storage.createAuditLog({
          tenantId: supplier.tenantId!,
          userId: user.id,
          action: "shift_completed_via_supplier_approval",
          entityType: "shift",
          entityId: String(shiftId),
          details: { supplierId: supplier.id, supplierName: supplier.companyName },
        });
      }

      res.json(results);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/supplier-portal/timesheets/bulk-dispute", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      const { shiftIds, comment } = req.body;
      if (!Array.isArray(shiftIds) || shiftIds.length === 0) {
        return res.status(400).json({ message: "At least one shift ID is required" });
      }
      if (!comment || !comment.trim()) {
        return res.status(400).json({ message: "A dispute comment is required" });
      }

      const allShifts = await storage.getShiftsByTenant(supplier.tenantId!);
      const results: { disputed: number[]; skipped: number[]; errors: string[] } = { disputed: [], skipped: [], errors: [] };

      for (const shiftId of shiftIds) {
        const shift = allShifts.find(s => s.id === shiftId && s.supplierId === supplier.id);
        if (!shift) {
          results.errors.push(`Shift #${shiftId}: not found or not assigned to your company`);
          continue;
        }
        if (shift.supplierApprovalStatus === "disputed") {
          results.skipped.push(shiftId);
          continue;
        }
        await storage.updateShift(shiftId, {
          supplierApprovalStatus: "disputed",
          supplierApprovalComment: comment.trim(),
          supplierApprovedAt: new Date(),
          supplierApprovedBy: user.id,
        });
        results.disputed.push(shiftId);
      }

      if (results.disputed.length > 0) {
        await storage.createAuditLog({
          tenantId: supplier.tenantId!,
          userId: user.id,
          action: "supplier_timesheets_bulk_disputed",
          entityType: "shift",
          entityId: results.disputed.join(","),
          details: { supplierId: supplier.id, count: results.disputed.length, comment: comment.trim() },
        });
      }

      res.json(results);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

