  app.post("/api/supplier-portal/self-billing-agreement/accept", requireRole("supplier"), async (req, res) => {
    try {
      const user = req.user as User;
      const supplier = await storage.getSupplierByUserId(user.id);
      if (!supplier) return res.status(404).json({ message: "Supplier profile not found" });

      

      const { signatoryName, signatoryPosition, signatureData } = req.body;
      if (!signatoryName || !signatoryPosition) {
        return res.status(400).json({ message: "Signatory name and position are required" });
      }

      const clientIp = (req.headers["x-forwarded-for"] as string)?.split(",")[0]?.trim() || req.ip || "Unknown";
      const now = new Date();
      const expiryDate = new Date(now);
      expiryDate.setFullYear(expiryDate.getFullYear() + 1);
      const agreementRef = generateAgreementRef(now);

      await storage.updateSupplier(supplier.id, {
        selfBillingAgreementStatus: "active",
        selfBillingSignatoryName: signatoryName.trim(),
        selfBillingSignatoryPosition: signatoryPosition.trim(),
        selfBillingAcceptedAt: now,
        selfBillingExpiryDate: expiryDate,
        selfBillingAgreementRef: agreementRef,
        selfBillingSignatureData: signatureData || null,
        selfBillingSignedIp: clientIp,
      });

      const tenant = await storage.getTenant(supplier.tenantId!);

      await storage.createSupplierDocument({
        supplierId: supplier.id,
        documentType: "self_billing_agreement",
        fileName: `Self-Billing-Agreement-${agreementRef}.pdf`,
        fileUrl: `/api/supplier-portal/self-billing-agreement/document/${agreementRef}`,
        fileSize: 0,
        mimeType: "application/pdf",
        version: 1,
        uploadedBy: user.id,
        status: "approved",
        displayName: `Self-Billing Agreement - ${agreementRef}`,
        expiryDate: expiryDate.toISOString().split("T")[0],
        notes: `HMRC-compliant self-billing agreement signed by ${signatoryName} (${signatoryPosition}). Valid until ${expiryDate.toLocaleDateString("en-GB")}.`,
      });

      await storage.createAuditLog({
        tenantId: supplier.tenantId!,
        userId: user.id,
        action: "self_billing_agreement_signed",
        entityType: "supplier",
        entityId: String(supplier.id),
        details: {
          agreementRef,
          signatoryName,
          signatoryPosition,
          supplierName: supplier.companyName,
          supplierVat: supplier.vatNumber,
          buyerName: tenant?.name || "Company",
          expiryDate: expiryDate.toISOString(),
          signedAt: now.toISOString(),
          signedFromIp: clientIp,
          hasSignatureImage: !!signatureData,
        },
      });

      res.json({
        message: "Self-billing agreement signed successfully",
        agreementRef,
        expiryDate,
        status: "active",
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

