      const pwCheck = validatePassword(newPassword);
      if (!pwCheck.valid) return res.status(400).json({ message: pwCheck.message });
      const resetRecord = await storage.getPasswordResetTokenByToken(token);
      if (!resetRecord) return res.status(400).json({ message: "Invalid or expired reset link" });
      if (new Date() > resetRecord.expiresAt) return res.status(400).json({ message: "Reset link has expired" });

      const hashed = await bcrypt.hash(newPassword, 10);
      await storage.updateUser(resetRecord.userId, { password: hashed });
      await storage.deletePasswordResetTokensByUserId(resetRecord.userId);
      const meta = getClientMeta(req);
      const supplier = await storage.getSupplierByUserId(resetRecord.userId);
      if (supplier && meta.ipAddress) {
        await storage.createAuditLog({
          tenantId: supplier.tenantId!,
          userId: resetRecord.userId,
          action: "supplier_password_reset_completed",
          entityType: "supplier",
          entityId: String(supplier.id),
          details: { ipAddress: meta.ipAddress },
          ipAddress: meta.ipAddress,
        });
      }
      res.json({ message: "Password updated. You can now log in." });
