  app.post("/api/invoices", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (req.body.supplierId) {
        const supplier = await storage.getSupplier(req.body.supplierId);
        if (supplier) {
          const agreementActive = supplier.selfBillingAgreementStatus === "active";
          const agreementExpired = supplier.selfBillingExpiryDate && new Date(supplier.selfBillingExpiryDate) < new Date();
          if (!agreementActive || agreementExpired) {
            return res.status(400).json({
              message: `Cannot create a self-billed invoice for ${supplier.companyName}. A valid, active self-billing agreement is required (HMRC VAT Notice 700/62). Please ensure the supplier has signed the self-billing agreement before proceeding.`
            });
          }
        }
      }
      const invoice = await storage.createInvoice({ ...req.body, tenantId: user.tenantId, createdBy: user.id });
      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: "invoice_created", entityType: "invoice",
        entityId: String(invoice.id), details: { invoiceNumber: invoice.invoiceNumber, totalAmount: invoice.totalAmount },
      });
      res.status(201).json(invoice);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.patch("/api/invoices/:id", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const invoiceId = parseInt(req.params.id);

      const existingInvoice = await storage.getInvoice(invoiceId);
      if (!existingInvoice) return res.status(404).json({ message: "Invoice not found" });

      if (existingInvoice.tenantId !== user.tenantId) {
        return res.status(403).json({ message: "Access denied: invoice belongs to a different organisation" });
      }

      const allowedFields = ["status", "notes", "dueDate", "paidAt"];
      const updates: Record<string, any> = {};
      for (const key of allowedFields) {
        if (req.body[key] !== undefined) updates[key] = req.body[key];
      }

      if (Object.keys(updates).length === 0) {
        return res.status(400).json({ message: "No valid fields to update" });
      }

      const validStatuses = ["draft", "pending", "approved", "paid", "overdue", "cancelled"];
      if (updates.status && !validStatuses.includes(updates.status)) {
        return res.status(400).json({ message: "Invalid invoice status" });
      }

      if (updates.status === "paid" && !updates.paidAt) {
        updates.paidAt = new Date();
      }

      const updated = await storage.updateInvoice(invoiceId, updates);
      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: "invoice_updated", entityType: "invoice",
        entityId: req.params.id, details: { changes: updates, previousStatus: existingInvoice.status },
      });
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/finance/summary", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "accountant", "payroll_manager", "hr_manager", "compliance_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json({});
      const allInvoices = await storage.getInvoicesByTenant(user.tenantId);
      const totalInvoiced = allInvoices.reduce((sum, inv) => sum + parseFloat(inv.totalAmount || "0"), 0);
      const totalVat = allInvoices.reduce((sum, inv) => sum + parseFloat(inv.vatAmount || "0"), 0);
      const paid = allInvoices.filter(i => i.status === "paid");
      const pending = allInvoices.filter(i => i.status === "pending" || i.status === "approved");
      const overdue = allInvoices.filter(i => i.status === "overdue");
      res.json({
        totalInvoiced: totalInvoiced.toFixed(2),
        totalVat: totalVat.toFixed(2),
        totalPaid: paid.reduce((sum, inv) => sum + parseFloat(inv.totalAmount || "0"), 0).toFixed(2),
        totalPending: pending.reduce((sum, inv) => sum + parseFloat(inv.totalAmount || "0"), 0).toFixed(2),
        totalOverdue: overdue.reduce((sum, inv) => sum + parseFloat(inv.totalAmount || "0"), 0).toFixed(2),
        invoiceCount: allInvoices.length,
        paidCount: paid.length,
        pendingCount: pending.length,
        overdueCount: overdue.length,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

