  app.get("/api/payroll/pending", requireRole(...payrollRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json([]);
      const pendingShifts = await storage.getPayrollPendingShifts(user.tenantId);
      const enriched = await Promise.all(pendingShifts.map(async (s) => {
        const emp = s.employeeId ? await storage.getEmployee(s.employeeId) : null;
        const empUser = emp?.userId ? await storage.getUser(emp.userId) : null;
        const site = s.siteId ? await storage.getSite(s.siteId) : null;
        const startH = parseInt(s.startTime.split(":")[0]) + parseInt(s.startTime.split(":")[1]) / 60;
        const endH = parseInt(s.endTime.split(":")[0]) + parseInt(s.endTime.split(":")[1]) / 60;
        let hours = endH - startH;
        if (hours < 0) hours += 24;
        hours -= (s.breakMinutes || 0) / 60;
        // Prefer the pay rate stored on the shift (auto-populated on verify), then check pay rates history, then fall back to employee default
        let hourlyRate = emp?.hourlyRate ? parseFloat(emp.hourlyRate) : 0;
        if (s.payRate) {
          hourlyRate = parseFloat(s.payRate);
        } else if (emp) {
          const { rows: empRates } = await pool.query(
            `SELECT * FROM employee_pay_rates WHERE employee_id = $1 AND tenant_id = $2 AND effective_from <= $3 AND (effective_to IS NULL OR effective_to >= $3) ORDER BY effective_from DESC LIMIT 1`,
            [emp.id, user.tenantId, s.date]
          );
          if (empRates.length > 0) hourlyRate = parseFloat(empRates[0].hourly_rate);
        }
        const grossAmount = hours * hourlyRate;
        return {
          ...s,
          employeeName: empUser ? `${empUser.firstName} ${empUser.lastName}` : "Unknown",
          siteName: site?.name || "Unknown",
          hoursWorked: parseFloat(hours.toFixed(2)),
          hourlyRate: hourlyRate.toFixed(2),
          grossAmount: grossAmount.toFixed(2),
        };
      }));
      res.json(enriched);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

