  app.post("/api/payroll/runs", requireRole(...payrollRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const { periodStart, periodEnd, notes } = req.body;
      if (!periodStart || !periodEnd) {
        return res.status(400).json({ message: "periodStart and periodEnd are required" });
      }
      const approvedShifts = await storage.getApprovedShiftsForPayroll(user.tenantId, periodStart, periodEnd);
      if (approvedShifts.length === 0) {
        return res.status(400).json({ message: "No approved shifts found in the specified period" });
      }
      const employeeIds = new Set<number>();
      let totalHours = 0;
      let totalGross = 0;
      const shiftData: Array<{ shift: typeof approvedShifts[0]; hours: number; rate: number; gross: number; empId: number }> = [];
      for (const s of approvedShifts) {
        if (s.payrollRunId) continue;
        const emp = s.employeeId ? await storage.getEmployee(s.employeeId) : null;
        if (!emp) continue;
        const startH = parseInt(s.startTime.split(":")[0]) + parseInt(s.startTime.split(":")[1]) / 60;
        const endH = parseInt(s.endTime.split(":")[0]) + parseInt(s.endTime.split(":")[1]) / 60;
        let hours = endH - startH;
        if (hours < 0) hours += 24;
        hours -= (s.breakMinutes || 0) / 60;
        // Prefer the pay rate stored on the shift (auto-populated on verify), then look up pay rate history, then fall back to employee default
        let rate = emp.hourlyRate ? parseFloat(emp.hourlyRate) : 0;
        if (s.payRate) {
          rate = parseFloat(s.payRate);
        } else {
          const { rows: empRates } = await pool.query(
            `SELECT * FROM employee_pay_rates WHERE employee_id = $1 AND tenant_id = $2 AND effective_from <= $3 AND (effective_to IS NULL OR effective_to >= $3) ORDER BY effective_from DESC LIMIT 1`,
            [emp.id, user.tenantId, s.date]
          );
          if (empRates.length > 0) rate = parseFloat(empRates[0].hourly_rate);
        }
        const gross = hours * rate;
        employeeIds.add(emp.id);
        totalHours += hours;
        totalGross += gross;
        shiftData.push({ shift: s, hours, rate, gross, empId: emp.id });
      }
      if (shiftData.length === 0) {
        return res.status(400).json({ message: "No eligible shifts for payroll run (some may already be in a run)" });
      }
      const run = await storage.createPayrollRun({
        tenantId: user.tenantId,
        periodStart,
        periodEnd,
        totalHours: totalHours.toFixed(2),
        totalGross: totalGross.toFixed(2),
        totalDeductions: "0",
        totalNet: totalGross.toFixed(2),
        shiftCount: shiftData.length,
        employeeCount: employeeIds.size,
        status: "draft",
        notes: notes || null,
        createdBy: user.id,
      });
      for (const sd of shiftData) {
        await storage.createPayrollRunItem({
          payrollRunId: run.id,
          shiftId: sd.shift.id,
          employeeId: sd.empId,
          hours: sd.hours.toFixed(2),
          hourlyRate: sd.rate.toFixed(2),
          grossAmount: sd.gross.toFixed(2),
          deductions: "0",
          netAmount: sd.gross.toFixed(2),
        });
        await storage.updateShift(sd.shift.id, { payrollRunId: run.id } as any);
      }
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "payroll_run_created",
        entityType: "payroll_run",
        entityId: String(run.id),
        details: { runCode: run.runCode, shiftCount: shiftData.length, totalGross: totalGross.toFixed(2), periodStart, periodEnd },
      });
      res.status(201).json(run);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

