  app.get("/api/payroll/runs/:id/export-csv", requireRole(...payrollRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });
      const id = parseInt(req.params.id);
      const run = await storage.getPayrollRun(id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      if (run.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
      if (run.status !== "finalised" && run.status !== "paid") {
        return res.status(400).json({ message: "Only finalised or paid payroll runs can be exported" });
      }

      const items = await storage.getPayrollRunItems(run.id);

      // Group items by employee, aggregating totals for the BACS payment file
      const employeeMap = new Map<number, {
        employeeId: number;
        employeeName: string;
        accountName: string;
        sortCode: string;
        accountNumber: string;
        bankName: string;
        totalGross: number;
        totalNet: number;
        totalHours: number;
        shiftCount: number;
      }>();

      for (const item of items) {
        const emp = await storage.getEmployee(item.employeeId);
        const empUser = emp?.userId ? await storage.getUser(emp.userId) : null;
        const bankDetail = emp ? await storage.getBankDetails(emp.id) : null;
        const employeeName = empUser ? `${empUser.firstName} ${empUser.lastName}` : "Unknown";

        if (!employeeMap.has(item.employeeId)) {
          employeeMap.set(item.employeeId, {
            employeeId: item.employeeId,
            employeeName,
            accountName: bankDetail?.accountName || employeeName,
            sortCode: bankDetail?.sortCode ? bankDetail.sortCode.replace(/-/g, "") : "",
            accountNumber: bankDetail?.accountNumber || "",
            bankName: bankDetail?.bankName || "",
            totalGross: 0,
            totalNet: 0,
            totalHours: 0,
            shiftCount: 0,
          });
        }
        const entry = employeeMap.get(item.employeeId)!;
        entry.totalGross += parseFloat(String(item.grossAmount) || "0");
        entry.totalNet += parseFloat(String(item.netAmount) || "0");
        entry.totalHours += parseFloat(String(item.hours) || "0");
        entry.shiftCount += 1;
      }

      const employees = Array.from(employeeMap.values());
      const runCode = run.runCode || `PAY-${run.id}`;
      const periodLabel = `${run.periodStart} to ${run.periodEnd}`;

      // CSV export for import into external payroll / BACS submission software
      // Amounts in GBP decimal (e.g. 1234.56); sort codes as 6-digit string (no dashes)
      // BACS payment reference max 18 characters
      const csvHeader = [
        "Employee Name",
        "Account Name",
        "Sort Code",
        "Account Number",
        "Bank Name",
        "Payment Amount (GBP)",
        "Payment Reference",
        "Gross Amount (GBP)",
        "Total Hours",
        "Shift Count",
        "Payroll Run",
        "Pay Period",
      ].join(",");

      const csvRows = employees.map((e) => {
        const ref = `${runCode}-${e.employeeId}`.substring(0, 18);
        return [
          `"${e.employeeName}"`,
          `"${e.accountName}"`,
          `"${e.sortCode}"`,
          `"${e.accountNumber}"`,
          `"${e.bankName}"`,
          e.totalNet.toFixed(2),
          `"${ref}"`,
          e.totalGross.toFixed(2),
          e.totalHours.toFixed(2),
          e.shiftCount,
          `"${runCode}"`,
          `"${periodLabel}"`,
        ].join(",");
      });

      const csvContent = [csvHeader, ...csvRows].join("\n");
      const filename = `Payroll-${safeFilename(runCode)}-BACS-export.csv`;

      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.send(csvContent);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

