  app.patch("/api/payroll/runs/:id/pay", requireRole(...payrollRoles), async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const run = await storage.getPayrollRun(id);
      if (!run) return res.status(404).json({ message: "Payroll run not found" });
      if (run.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
      if (run.status !== "finalised") return res.status(400).json({ message: "Only finalised runs can be marked as paid" });
      const updated = await storage.updatePayrollRun(id, {
        status: "paid",
        paidAt: new Date(),
        paidBy: user.id,
      } as any);
      const items = await storage.getPayrollRunItems(id);
      const employeePayTotals: Record<number, { gross: number; net: number; shiftCount: number }> = {};
      for (const item of items) {
        await storage.updateShift(item.shiftId, {
          payrollStatus: "paid",
          payrollPaidAt: new Date(),
        } as any);
        if (!employeePayTotals[item.employeeId]) employeePayTotals[item.employeeId] = { gross: 0, net: 0, shiftCount: 0 };
        employeePayTotals[item.employeeId].gross += parseFloat(String(item.grossAmount) || "0");
        employeePayTotals[item.employeeId].net += parseFloat(String(item.netAmount) || "0");
        employeePayTotals[item.employeeId].shiftCount += 1;
      }
      for (const [empIdStr, totals] of Object.entries(employeePayTotals)) {
        const emp = await storage.getEmployee(parseInt(empIdStr));
        if (emp?.userId) {
          const grossStr = new Intl.NumberFormat("en-GB", { style: "currency", currency: "GBP" }).format(totals.gross);
          await storage.createNotification({
            userId: emp.userId,
            type: "pay_processed",
            title: "Pay Processed",
            body: `Your pay for payroll run ${run.runCode || id} has been processed. ${totals.shiftCount} shift${totals.shiftCount !== 1 ? "s" : ""} totalling ${grossStr} gross.`,
            link: "/my-pay",
            relatedEntityType: "payroll_run",
            relatedEntityId: String(id),
            metadata: { payrollRunId: id, runCode: run.runCode, grossAmount: totals.gross, netAmount: totals.net, shiftCount: totals.shiftCount },
          });
        }
      }
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "payroll_run_paid",
        entityType: "payroll_run",
        entityId: String(id),
        details: { runCode: run.runCode, paidBy: `${user.firstName} ${user.lastName}`, totalNet: run.totalNet },
      });
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/payroll/summary", requireRole(...payrollRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json({});
      const allShifts = await storage.getShiftsByTenant(user.tenantId);
      const eligibleShifts = allShifts.filter(s => s.status === "completed" || s.status === "verified");
      const pendingShifts = eligibleShifts.filter(s => s.payrollStatus === "pending");
      const approvedShifts = eligibleShifts.filter(s => s.payrollStatus === "approved");
      const paidShifts = eligibleShifts.filter(s => s.payrollStatus === "paid");

      const calcHoursAndGross = async (shiftsArr: typeof eligibleShifts) => {
        let totalHours = 0;
        let totalGross = 0;
        for (const s of shiftsArr) {
          const startH = parseInt(s.startTime.split(":")[0]) + parseInt(s.startTime.split(":")[1]) / 60;
          const endH = parseInt(s.endTime.split(":")[0]) + parseInt(s.endTime.split(":")[1]) / 60;
          let hours = endH - startH;
          if (hours < 0) hours += 24;
          hours -= (s.breakMinutes || 0) / 60;
          totalHours += hours;
          // Use stored payRate if available, otherwise look up from pay rates
          if (s.payRate) {
            totalGross += hours * parseFloat(s.payRate);
          } else if (s.employeeId) {
            const { rows: empRates } = await pool.query(
              `SELECT hourly_rate FROM employee_pay_rates WHERE employee_id = $1 AND tenant_id = $2 AND effective_from <= $3 AND (effective_to IS NULL OR effective_to >= $3) ORDER BY effective_from DESC LIMIT 1`,
              [s.employeeId, user.tenantId, s.date]
            );
            if (empRates.length > 0) {
              totalGross += hours * parseFloat(empRates[0].hourly_rate);
            } else {
              const emp = await storage.getEmployee(s.employeeId);
              if (emp?.hourlyRate) totalGross += hours * parseFloat(emp.hourlyRate);
            }
          }
        }
        return { hours: totalHours, gross: totalGross };
      };

      const [pendingCalc, approvedCalc] = await Promise.all([
        calcHoursAndGross(pendingShifts),
        calcHoursAndGross(approvedShifts),
      ]);

      const allInvoices = await storage.getInvoicesByTenant(user.tenantId);
      const totalBilled = allInvoices.reduce((sum, inv) => sum + parseFloat(inv.totalAmount || "0"), 0);

      const runs = await storage.getPayrollRuns(user.tenantId);
      const totalPayrollApproved = runs.filter(r => r.status === "finalised" || r.status === "paid")
        .reduce((sum, r) => sum + parseFloat(r.totalGross || "0"), 0);
      const totalPaid = runs.filter(r => r.status === "paid")
        .reduce((sum, r) => sum + parseFloat(r.totalGross || "0"), 0);
      const variance = totalBilled - totalPaid;

      res.json({
        pendingCount: pendingShifts.length,
        pendingHours: pendingCalc.hours.toFixed(2),
        pendingValue: pendingCalc.gross.toFixed(2),
        approvedCount: approvedShifts.length,
        approvedHours: approvedCalc.hours.toFixed(2),
        approvedValue: approvedCalc.gross.toFixed(2),
        paidCount: paidShifts.length,
        totalBilled: totalBilled.toFixed(2),
        totalPayrollApproved: totalPayrollApproved.toFixed(2),
        totalPaid: totalPaid.toFixed(2),
        variance: variance.toFixed(2),
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

