  app.patch("/api/applicants/:id", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "compliance_manager", "training_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const applicantId = parseInt(req.params.id);
      const updated = await storage.updateApplicant(applicantId, req.body);
      // Auto-create probation record when applicant is hired
      if (req.body.status === "hired" && user.tenantId) {
        try {
          const applicant = updated as any;
          // Try to find a matching employee by email within the same tenant
          if (applicant?.email) {
            const empRows = await pool.query(
              `SELECT e.id FROM employees e
               JOIN users u ON e.user_id = u.id
               WHERE u.email = $1 AND e.tenant_id = $2
               ORDER BY e.id DESC LIMIT 1`,
              [applicant.email, user.tenantId]
            );
            if (empRows.rows.length > 0) {
              const employeeId = empRows.rows[0].id;
              // Check if a probation record already exists
              const existing = await pool.query(
                `SELECT id FROM probation_records WHERE employee_id = $1 AND tenant_id = $2 LIMIT 1`,
                [employeeId, user.tenantId]
              );
              if (existing.rows.length === 0) {
                const tenantRow = await pool.query(
                  `SELECT default_probation_weeks FROM tenants WHERE id = $1`,
                  [user.tenantId]
                );
                const weeks = tenantRow.rows[0]?.default_probation_weeks ?? 12;
                const startDate = new Date();
                const reviewDate = new Date(startDate);
                reviewDate.setDate(reviewDate.getDate() + weeks * 7);
                await storage.createProbationRecord({
                  tenantId: user.tenantId,
                  employeeId,
                  startDate: startDate.toISOString().split("T")[0],
                  reviewDate: reviewDate.toISOString().split("T")[0],
                  status: "active",
                });
              }
            }
          }
        } catch (_err) {
          // Non-fatal: probation auto-creation failure should not block hiring
        }
      }
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/admin/applicants/import", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "compliance_manager", "training_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const { rows } = req.body as { rows: { firstName: string; lastName: string; email: string; phone?: string; jobPostingId?: number | null; source?: string }[] };
      if (!Array.isArray(rows) || rows.length === 0) {
        return res.status(400).json({ message: "No rows provided" });
      }
      const existing = await storage.getApplicantsByTenant(user.tenantId!);
      const existingEmails = new Set(existing.map((a) => a.email.toLowerCase()));
      let imported = 0;
      const duplicates: string[] = [];
      const errors: string[] = [];
      for (const row of rows) {
        if (!row.firstName || !row.lastName || !row.email) {
          errors.push(`Row missing required fields (first_name, last_name, email): ${JSON.stringify(row)}`);
          continue;
        }
        if (existingEmails.has(row.email.toLowerCase())) {
          duplicates.push(row.email);
          continue;
        }
        await storage.createApplicant({
          tenantId: user.tenantId!,
          firstName: row.firstName,
          lastName: row.lastName,
          email: row.email,
          phone: row.phone || null,
          jobPostingId: row.jobPostingId || null,
          source: row.source || null,
          status: "applied",
        } as any);
        existingEmails.add(row.email.toLowerCase());
        imported++;
      }
      res.json({ imported, duplicates, errors });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

