  // Make Offer + generate offer letter PDF
  app.post("/api/admin/applicants/:id/offer", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const applicantId = parseInt(req.params.id);
      const applicant = await storage.getApplicant(applicantId);
      if (!applicant || applicant.tenantId !== user.tenantId) return res.status(404).json({ message: "Applicant not found" });
      if (applicant.status !== "interview") {
        return res.status(400).json({ message: "Offer can only be made to applicants in interview stage" });
      }
      const { offerSalary, startDate, notes } = req.body;
      const [job, tenant, offerTemplate] = await Promise.all([
        applicant.jobPostingId ? storage.getJobPosting(applicant.jobPostingId) : Promise.resolve(null),
        user.tenantId ? storage.getTenant(user.tenantId) : Promise.resolve(null),
        user.tenantId ? storage.getDefaultTemplate(user.tenantId, "offer_letter") : Promise.resolve(undefined),
      ]);

      const offerDate = new Date().toISOString().split("T")[0];
      const { randomUUID: genToken } = await import("crypto");
      const offerResponseToken = genToken();
      const updated = await storage.updateApplicant(applicantId, {
        status: "offer",
        offerDate,
        offerSalary: offerSalary || null,
        offerStatus: "pending",
        notes: notes || undefined,
        offerResponseToken,
      } as any);

      // Generate offer letter PDF using document template system
      const templateSections = offerTemplate?.sections as Array<{ heading: string; text: string }> | null | undefined;
      const pdfBuffer = await generateOfferLetterPdf({
        applicantName: `${applicant.firstName} ${applicant.lastName}`,
        jobTitle: job?.title || "Position",
        salary: offerSalary || null,
        startDate: startDate || null,
        companyName: tenant?.name || "Gardeo",
        companyAddress: (tenant as any)?.address || undefined,
        offerDate: new Date().toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" }),
        notes: notes || null,
        templateHeaderTitle: offerTemplate?.headerTitle || null,
        templateHeaderSubtitle: offerTemplate?.headerSubtitle || null,
        templateSections: templateSections || null,
        templateFooterText: offerTemplate?.footerText || null,
        templateComplianceText: offerTemplate?.complianceText || null,
      });

      // Upload PDF to object storage and link to applicant record
      let offerLetterUrl: string | null = null;
      try {
        const { ObjectStorageService, objectStorageClient } = await import("./replit_integrations/object_storage/objectStorage");
        const svc = new ObjectStorageService();
        const privateDir = svc.getPrivateObjectDir();
        const dirParts = privateDir.split("/").filter(Boolean);
        const bucketName = dirParts[0];
        const basePath = dirParts.slice(1).join("/");
        const { randomUUID } = await import("crypto");
        const uuid = randomUUID();
        const objectName = `${basePath}/offer-letters/${uuid}.pdf`;
        const file = objectStorageClient.bucket(bucketName).file(objectName);
        await file.save(pdfBuffer, { contentType: "application/pdf" });
        offerLetterUrl = `/objects/offer-letters/${uuid}.pdf`;
        await storage.updateApplicant(applicantId, { offerLetterUrl } as any);
      } catch (storageErr: any) {
        console.error("[offer-letter] Object storage upload failed:", storageErr.message);
      }

      // Send offer letter email to applicant
      let offerEmailSentAt: Date | null = null;
      try {
        const emailResult = await emailService.sendOfferLetterEmail({
          to: applicant.email,
          applicantName: `${applicant.firstName} ${applicant.lastName}`,
          jobTitle: job?.title || "Position",
          companyName: tenant?.name || "Gardeo",
          pdfBuffer,
        });
        if (emailResult.ok) {
          offerEmailSentAt = new Date();
          await storage.updateApplicant(applicantId, { offerEmailSentAt } as any);
          await storage.createAuditLog({
            tenantId: user.tenantId!,
            userId: user.id,
            action: "offer_email_sent",
            entityType: "applicant",
            entityId: String(applicantId),
            details: `Offer letter email sent to ${applicant.email} for applicant ${applicant.firstName} ${applicant.lastName}`,
          });
        } else {
          console.warn("[offer-letter] Email send failed:", emailResult.error);
        }
      } catch (emailErr: any) {
        console.error("[offer-letter] Email send error:", emailErr.message);
      }

      const pdfBase64 = pdfBuffer.toString("base64");
      res.json({ applicant: { ...updated, offerLetterUrl, offerEmailSentAt, offerResponseToken }, pdfBase64, message: "Offer made successfully", emailSent: !!offerEmailSentAt });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

