  // Mark as Hired — creates employee + onboarding record
  app.post("/api/admin/applicants/:id/hire", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const applicantId = parseInt(req.params.id);
      const applicant = await storage.getApplicant(applicantId);
      if (!applicant) return res.status(404).json({ message: "Applicant not found" });
      if (applicant.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
      if (applicant.status === "hired") {
        return res.status(409).json({ message: "Applicant has already been hired" });
      }
      if (!["offer", "interview"].includes(applicant.status || "")) {
        return res.status(400).json({ message: "Applicant must be in offer or interview stage to be hired" });
      }

      // Create a placeholder user for the new employee
      const baseUsername = `${applicant.firstName.toLowerCase()}.${applicant.lastName.toLowerCase()}`.replace(/[^a-z0-9.]/g, "");
      let username = baseUsername;
      let suffix = 1;
      while (await storage.getUserByUsername(username, user.tenantId)) {
        username = `${baseUsername}${suffix++}`;
      }
      const tempPassword = crypto.randomBytes(8).toString("hex");
      const hashedPassword = await bcrypt.hash(tempPassword, 10);
      const newUser = await storage.createUser({
        username,
        email: applicant.email,
        password: hashedPassword,
        firstName: applicant.firstName,
        lastName: applicant.lastName,
        role: "employee",
        tenantId: user.tenantId,
        phone: applicant.phone || undefined,
      });

      const employee = await storage.createEmployee({
        userId: newUser.id,
        tenantId: user.tenantId,
      } as any);

      const onboarding = await storage.createOnboarding({
        userId: newUser.id,
        tenantId: user.tenantId,
        status: "invited",
        currentStep: 1,
      });

      // Mark applicant as hired
      await storage.updateApplicant(applicantId, {
        status: "hired",
        hiredAt: new Date(),
        offerStatus: "accepted",
      } as any);

      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "applicant_hired",
        entityType: "applicant",
        entityId: String(applicantId),
        details: { applicantName: `${applicant.firstName} ${applicant.lastName}`, employeeId: employee.id, onboardingId: onboarding.id },
      });

      res.json({ employee, onboarding, message: "Applicant hired and employee record created" });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // Recruitment Pipeline Metrics
  app.get("/api/admin/recruitment/metrics", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json({ funnel: [], stageTransitions: [], sources: [], conversionRates: [], monthlyHires: [], avgTimeToHire: null, total: 0 });
      const allApplicants = await storage.getApplicantsByTenant(user.tenantId);

      // Date range filter — cohort filtered by createdAt (when they applied)
      const days = req.query.days ? parseInt(req.query.days as string) : null;
      const cutoff = days ? new Date(Date.now() - days * 24 * 60 * 60 * 1000) : null;
      const cohort = cutoff
        ? allApplicants.filter(a => a.createdAt && new Date(a.createdAt) >= cutoff)
        : allApplicants;

      // Funnel counts — based on cohort (applicants who applied in the window)
      const stages = ["applied", "screening", "interview", "offer", "hired"];
      const funnel = stages.map(stage => ({
        stage,
        label: stage.charAt(0).toUpperCase() + stage.slice(1),
        count: cohort.filter(a => a.status === stage || (stage === "applied" && !a.status)).length,
      }));

      // Cohort-based conversion rates
      // Counts applicants in the cohort that reached each stage or beyond
      const stageOrder = ["applied", "screening", "interview", "offer", "hired"];
      const stageRank = (status: string | null) => {
        const s = status ?? "applied";
        const idx = stageOrder.indexOf(s);
        return idx === -1 ? -1 : idx; // -1 for rejected/withdrawn
      };
      const atOrBeyond = (minStage: string) => {
        const minRank = stageOrder.indexOf(minStage);
        return cohort.filter(a => stageRank(a.status) >= minRank).length;
      };
      const cohortTotal = cohort.length;
      const reachedScreening = atOrBeyond("screening");
      const reachedInterview = atOrBeyond("interview");
      const reachedOffer = atOrBeyond("offer");
      const reachedHired = atOrBeyond("hired");
      const conversionRates: { from: string; to: string; fromLabel: string; toLabel: string; rate: number; fromCount: number; toCount: number }[] = [
        { from: "applied", to: "screening", fromLabel: "Applied", toLabel: "Screening", rate: cohortTotal > 0 ? Math.round((reachedScreening / cohortTotal) * 100) : 0, fromCount: cohortTotal, toCount: reachedScreening },
        { from: "screening", to: "interview", fromLabel: "Screening", toLabel: "Interview", rate: reachedScreening > 0 ? Math.round((reachedInterview / reachedScreening) * 100) : 0, fromCount: reachedScreening, toCount: reachedInterview },
        { from: "interview", to: "offer", fromLabel: "Interview", toLabel: "Offer", rate: reachedInterview > 0 ? Math.round((reachedOffer / reachedInterview) * 100) : 0, fromCount: reachedInterview, toCount: reachedOffer },
        { from: "offer", to: "hired", fromLabel: "Offer", toLabel: "Hired", rate: reachedOffer > 0 ? Math.round((reachedHired / reachedOffer) * 100) : 0, fromCount: reachedOffer, toCount: reachedHired },
      ];

      // Stage transition durations — using actual timestamp pairs (not applicant age)
      // Applied → Interview: interviewDate - createdAt
      // Interview → Offer: offerDate - interviewDate
      // Offer → Hired: hiredAt - offerDate
      // Applied → Hired (overall): hiredAt - createdAt
      const daysBetween = (a: Date | null | undefined, b: Date | null | undefined) =>
        a && b ? (b.getTime() - a.getTime()) / (1000 * 60 * 60 * 24) : null;

      const appsWithInterview = cohort.filter(a => a.createdAt && a.interviewDate);
      const appsWithOffer = cohort.filter(a => a.interviewDate && a.offerDate);
      const appsWithHiredAndOffer = cohort.filter(a => a.hiredAt && a.offerDate);
      const hiredApps = allApplicants.filter(a => a.status === "hired" && a.hiredAt && a.createdAt &&
        (!cutoff || new Date(a.hiredAt) >= cutoff));

      const avgTransition = (apps: typeof cohort, getStart: (a: typeof cohort[0]) => Date | null | undefined, getEnd: (a: typeof cohort[0]) => Date | null | undefined) => {
        const valid = apps.map(a => daysBetween(getStart(a) ? new Date(getStart(a)!) : null, getEnd(a) ? new Date(getEnd(a)!) : null)).filter((d): d is number => d !== null && d >= 0);
        return valid.length > 0 ? Math.round(valid.reduce((s, d) => s + d, 0) / valid.length) : null;
      };

      const stageTransitions = [
        { label: "Applied → Interview", avgDays: avgTransition(appsWithInterview, a => a.createdAt, a => a.interviewDate), sampleSize: appsWithInterview.length },
        { label: "Interview → Offer", avgDays: avgTransition(appsWithOffer, a => a.interviewDate, a => a.offerDate), sampleSize: appsWithOffer.length },
        { label: "Offer → Hired", avgDays: avgTransition(appsWithHiredAndOffer, a => a.offerDate, a => a.hiredAt), sampleSize: appsWithHiredAndOffer.length },
      ];

      // Average time-to-hire: filtered by hiredAt date (regardless of when they applied)
      const avgTimeToHire = hiredApps.length > 0
        ? Math.round(hiredApps.reduce((sum, a) => {
            const d = daysBetween(new Date(a.createdAt!), new Date(a.hiredAt!));
            return sum + (d ?? 0);
          }, 0) / hiredApps.length)
        : null;

      // Monthly hires trend (last 12 months, by hiredAt — always from all applicants)
      const monthlyMap: Record<string, number> = {};
      const twelveMonthsAgo = new Date();
      twelveMonthsAgo.setMonth(twelveMonthsAgo.getMonth() - 11);
      twelveMonthsAgo.setDate(1);
      twelveMonthsAgo.setHours(0, 0, 0, 0);
      allApplicants
        .filter(a => a.status === "hired" && a.hiredAt && new Date(a.hiredAt) >= twelveMonthsAgo)
        .forEach(a => {
          const d = new Date(a.hiredAt!);
          const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
          monthlyMap[key] = (monthlyMap[key] || 0) + 1;
        });
      const monthlyHires: { month: string; label: string; count: number }[] = [];
      for (let i = 11; i >= 0; i--) {
        const d = new Date();
        d.setMonth(d.getMonth() - i);
        const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
        const label = d.toLocaleDateString("en-GB", { month: "short", year: "2-digit" });
        monthlyHires.push({ month: key, label, count: monthlyMap[key] || 0 });
      }

      // Source breakdown
      const sourceMap: Record<string, number> = {};
      cohort.forEach(a => {
        const src = (a as any).source || "direct";
        sourceMap[src] = (sourceMap[src] || 0) + 1;
      });
      const sources = Object.entries(sourceMap).map(([source, count]) => ({ source, count }));

      res.json({ funnel, stageTransitions, sources, conversionRates, monthlyHires, avgTimeToHire, total: cohort.length });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

