  app.post("/api/admin/invitations", requireRole("super_admin", "tenant_admin", "ceo", "admin"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const { email, role, firstName, lastName } = req.body;
      if (!email || !role) return res.status(400).json({ message: "Email and role required" });

      const existing = await storage.getTenantInvitationsByTenant(user.tenantId);
      const alreadyInvited = existing.find(i => i.email === email && i.status === "pending");
      if (alreadyInvited) return res.status(400).json({ message: "This email has already been invited" });

      const token = crypto.randomUUID();
      const invitation = await storage.createTenantInvitation({
        tenantId: user.tenantId,
        email,
        role,
        firstName: firstName || null,
        lastName: lastName || null,
        token,
        invitedBy: user.id,
        status: "pending",
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
      });

      await storage.createAuditLog({
        tenantId: user.tenantId, userId: user.id,
        action: "team_invitation_sent", entityType: "invitation",
        entityId: String(invitation.id), details: { email, role },
      });

      res.json(invitation);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

