  app.post("/api/admin/renumber-vat-invoices", requireRole("super_admin", "tenant_admin"), async (req, res) => {
    const user = req.user as User;
    if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
    const tenantId = user.tenantId;
    const client = await pool.connect();
    try {
      await client.query("BEGIN");

      const invoicesResult = await client.query(
        `SELECT i.id, i.invoice_number, i.period_start, s.company_name
         FROM invoices i
         JOIN suppliers s ON s.id = i.supplier_id
         WHERE i.tenant_id = $1
           AND i.invoice_number LIKE 'SBI-GUA%'
           AND CAST(i.vat_rate AS NUMERIC) > 0
         ORDER BY i.period_start ASC, s.company_name ASC, i.id ASC`,
        [tenantId]
      );

      const rows = invoicesResult.rows;
      if (rows.length === 0) {
        await client.query("ROLLBACK");
        return res.json({ message: "No VAT invoices found to renumber", count: 0 });
      }

      let seq = 225;
      let prevMonth: string | null = null;
      const mappings: { invoiceId: number; oldNumber: string; newNumber: string }[] = [];

      for (const row of rows) {
        const periodMonth = row.period_start.substring(0, 7).replace("-", "");
        if (prevMonth !== null && periodMonth !== prevMonth) {
          seq += 3;
        }
        prevMonth = periodMonth;

        const newNumber = `SBI-GUA-${periodMonth}-${String(seq).padStart(4, "0")}`;
        mappings.push({ invoiceId: row.id, oldNumber: row.invoice_number, newNumber });
        seq++;
      }

      for (const m of mappings) {
        await client.query(
          `UPDATE invoices SET invoice_number = $1 WHERE id = $2`,
          [m.newNumber, m.invoiceId]
        );
        await client.query(
          `INSERT INTO invoice_number_audit_log (tenant_id, invoice_id, old_number, new_number, series, reason) VALUES ($1, $2, $3, $4, $5, $6)`,
          [tenantId, m.invoiceId, m.oldNumber, m.newNumber, 'SBI-GUA', 'chronological_renumbering']
        );
      }

      await client.query("COMMIT");
      res.json({ message: `Renumbered ${mappings.length} VAT invoices`, count: mappings.length, mappings });
    } catch (err: any) {
      await client.query("ROLLBACK");
      res.status(500).json({ message: err.message });
    } finally {
      client.release();
    }
  });

