  // ─── Predictive Analytics ───
  app.get("/api/analytics/predictions", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "controller", "scheduler", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json({});

      const allEmployees = await storage.getEmployeesByTenant(user.tenantId);
      const allSites = await storage.getSitesByTenant(user.tenantId);
      const allShifts = await storage.getShiftsByTenant(user.tenantId);
      const aiDecisionList = await storage.getAiDecisions(user.tenantId, 500);

      const now = new Date();
      const thirtyDays = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
      const sixtyDays = new Date(now.getTime() + 60 * 24 * 60 * 60 * 1000);
      const ninetyDays = new Date(now.getTime() + 90 * 24 * 60 * 60 * 1000);

      const siaExpiring30 = allEmployees.filter(e => e.siaExpiryDate && new Date(e.siaExpiryDate) <= thirtyDays && new Date(e.siaExpiryDate) > now);
      const siaExpiring60 = allEmployees.filter(e => e.siaExpiryDate && new Date(e.siaExpiryDate) <= sixtyDays && new Date(e.siaExpiryDate) > thirtyDays);
      const siaExpiring90 = allEmployees.filter(e => e.siaExpiryDate && new Date(e.siaExpiryDate) <= ninetyDays && new Date(e.siaExpiryDate) > sixtyDays);

      const shiftsBySite: Record<string, number[]> = {};
      const shiftsByDay: Record<string, number> = {};
      for (const shift of allShifts) {
        const siteKey = shift.siteId ? String(shift.siteId) : "unassigned";
        if (!shiftsBySite[siteKey]) shiftsBySite[siteKey] = [];
        shiftsBySite[siteKey].push(1);
        if (shift.date) {
          const dayOfWeek = new Date(shift.date).toLocaleDateString("en-GB", { weekday: "long" });
          shiftsByDay[dayOfWeek] = (shiftsByDay[dayOfWeek] || 0) + 1;
        }
      }

      const siteStaffing = allSites.map(site => {
        const siteShiftCount = shiftsBySite[String(site.id)]?.length || 0;
        return {
          siteId: site.id,
          siteName: site.name,
          totalShifts: siteShiftCount,
          avgShiftsPerWeek: allShifts.length > 0 ? Math.round(siteShiftCount / Math.max(1, Math.ceil(allShifts.length / 7)) * 10) / 10 : 0,
        };
      }).sort((a, b) => b.totalShifts - a.totalShifts);

      const dayDistribution = Object.entries(shiftsByDay).sort((a, b) => b[1] - a[1]);
      const busiestDay = dayDistribution[0]?.[0] || "N/A";
      const quietestDay = dayDistribution[dayDistribution.length - 1]?.[0] || "N/A";

      const accepted = aiDecisionList.filter(d => d.status === "accepted");
      const rejected = aiDecisionList.filter(d => d.status === "rejected");
      const aiAcceptRate = aiDecisionList.length > 0
        ? Math.round((accepted.length / Math.max(1, accepted.length + rejected.length)) * 100)
        : 0;

      const preferredEmployees: Record<string, number> = {};
      for (const d of accepted) {
        if (d.employeeName) preferredEmployees[d.employeeName] = (preferredEmployees[d.employeeName] || 0) + 1;
      }
      const topPreferred = Object.entries(preferredEmployees).sort((a, b) => b[1] - a[1]).slice(0, 5);

      const rejectionReasons: string[] = rejected.filter(d => d.feedback).map(d => d.feedback!).slice(0, 10);

      const alerts: Array<{ type: string; severity: string; title: string; description: string; items?: string[] }> = [];

      if (siaExpiring30.length > 0) {
        const siaItems = siaExpiring30.map(e => `${e.siaLicenseType || "SIA"} — expires ${new Date(e.siaExpiryDate!).toLocaleDateString("en-GB")}`);
        alerts.push({
          type: "compliance",
          severity: "critical",
          title: `${siaExpiring30.length} SIA licence${siaExpiring30.length !== 1 ? "s" : ""} expiring within 30 days`,
          description: siaItems.join("; "),
          items: siaItems,
        });
      }
      if (siaExpiring60.length > 0) {
        alerts.push({
          type: "compliance",
          severity: "warning",
          title: `${siaExpiring60.length} SIA licence${siaExpiring60.length !== 1 ? "s" : ""} expiring in 30-60 days`,
          description: "Schedule renewals to maintain compliance.",
        });
      }

      const understaffedSites = siteStaffing.filter(s => s.totalShifts > 0 && s.avgShiftsPerWeek < 2);
      if (understaffedSites.length > 0) {
        const siteNames = understaffedSites.map(s => s.siteName);
        alerts.push({
          type: "staffing",
          severity: "warning",
          title: `${understaffedSites.length} site${understaffedSites.length !== 1 ? "s" : ""} may be understaffed`,
          description: siteNames.join(", "),
          items: siteNames,
        });
      }

      if (aiAcceptRate > 0 && aiAcceptRate < 50 && (accepted.length + rejected.length) >= 5) {
        alerts.push({
          type: "ai_quality",
          severity: "info",
          title: `AI suggestion acceptance rate is ${aiAcceptRate}%`,
          description: "Continue providing feedback to help the AI learn your preferences.",
        });
      }

      const allVettingRecords = await storage.getVettingRecordsByTenant(user.tenantId!);
      const expiredVetting = allVettingRecords.filter(v => v.status === "expired");
      if (expiredVetting.length > 0) {
        alerts.push({
          type: "compliance",
          severity: "critical",
          title: `${expiredVetting.length} expired vetting check${expiredVetting.length !== 1 ? "s" : ""}`,
          description: "BS 7858 compliance requires up-to-date vetting for all staff.",
        });
      }

      res.json({
        complianceForecast: {
          siaExpiring30: siaExpiring30.length,
          siaExpiring60: siaExpiring60.length,
          siaExpiring90: siaExpiring90.length,
          expiredVetting: expiredVetting.length,
          siaExpiringDetails: siaExpiring30.map(e => ({
            employeeId: e.id,
            licenseType: e.siaLicenseType,
            expiryDate: e.siaExpiryDate,
          })),
        },
        staffingTrends: {
          totalShifts: allShifts.length,
          totalSites: allSites.length,
          totalEmployees: allEmployees.length,
          busiestDay,
          quietestDay,
          dayDistribution: Object.fromEntries(dayDistribution),
          siteStaffing: siteStaffing.slice(0, 10),
        },
        aiLearning: {
          totalSuggestions: aiDecisionList.length,
          accepted: accepted.length,
          rejected: rejected.length,
          pending: aiDecisionList.filter(d => d.status === "suggested").length,
          acceptanceRate: aiAcceptRate,
          topPreferredEmployees: topPreferred.map(([name, count]) => ({ name, timesAccepted: count })),
          recentRejectionReasons: rejectionReasons,
        },
        alerts,
      });
    } catch (err: any) {
      console.error("Predictive analytics error:", err);
      res.status(500).json({ message: err.message });
    }
  });

