  app.post("/api/communications/channels", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const { name, type, description, siteId, memberIds } = req.body;

      if (type !== "direct" && !["super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager", "controller"].includes(user.role)) {
        return res.status(403).json({ message: "Only managers can create team/site channels" });
      }

      if (!type) return res.status(400).json({ message: "Type is required" });

      if (type === "direct" && memberIds && Array.isArray(memberIds)) {
        const allMembers = [user.id, ...memberIds.filter((id: string) => id !== user.id)].sort();
        const existingChannels = await storage.getUserChannels(user.id, user.tenantId);
        for (const ch of existingChannels) {
          if (ch.type !== "direct") continue;
          const members = await storage.getChannelMembers(ch.id);
          const memberIdsSorted = members.map(m => m.userId).sort();
          if (memberIdsSorted.length === allMembers.length && memberIdsSorted.every((id, i) => id === allMembers[i])) {
            return res.json(ch);
          }
        }
      }

      const channelName = name || (type === "direct" ? "Direct Message" : "New Channel");

      const channel = await storage.createChannel({
        tenantId: user.tenantId,
        name: channelName,
        type,
        description: description || null,
        siteId: siteId || null,
        createdBy: user.id,
        isArchived: false,
      });

      await storage.addChannelMember({ channelId: channel.id, userId: user.id });

      if (memberIds && Array.isArray(memberIds)) {
        const uniqueMemberIds = [...new Set(memberIds.filter((id: string) => id !== user.id))];
        const tenantUsers = await storage.getUsersByTenant(user.tenantId);
        const validTenantUserIds = new Set(tenantUsers.filter(u => u.isActive).map(u => u.id));
        for (const memberId of uniqueMemberIds) {
          if (validTenantUserIds.has(memberId)) {
            await storage.addChannelMember({ channelId: channel.id, userId: memberId });
          }
        }
      }

      res.json(channel);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/communications/channels/:channelId/messages", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const channelId = parseInt(req.params.channelId);
      const channel = await storage.getChannel(channelId);
      if (!channel || channel.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
      const members = await storage.getChannelMembers(channelId);
      if (!members.some(m => m.userId === user.id)) return res.status(403).json({ message: "Not a member of this channel" });
      const msgs = await storage.getMessages(channelId, 100);
      await storage.updateChannelMemberLastRead(channelId, user.id);
      res.json(msgs.reverse());
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/communications/channels/:channelId/messages", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const channelId = parseInt(req.params.channelId);
      const channel = await storage.getChannel(channelId);
      if (!channel || channel.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
      const members = await storage.getChannelMembers(channelId);
      if (!members.some(m => m.userId === user.id)) return res.status(403).json({ message: "Not a member of this channel" });
      const { content, fileUrl, fileName, fileType, fileSize } = req.body;
      if (!content?.trim() && !fileUrl) return res.status(400).json({ message: "Message content or file is required" });

      if (fileUrl && typeof fileUrl === "string" && !fileUrl.startsWith("/objects/")) {
        return res.status(400).json({ message: "Invalid file URL" });
      }

      const senderDisplayName = user.firstName && user.lastName ? `${user.firstName} ${user.lastName}` : user.username;
      const msg = await storage.createMessage({
        channelId,
        senderId: user.id,
        senderName: senderDisplayName,
        content: (content || "").trim() || (fileName ? `Sent a file: ${fileName}` : "Sent a file"),
        isEdited: false,
        fileUrl: fileUrl || null,
        fileName: fileName || null,
        fileType: fileType || null,
        fileSize: fileSize || null,
      });

      if (io) {
        io.to(`channel_${channelId}`).emit("new-message", msg);
      }

      const otherMembers = members.filter(m => m.userId !== user.id);
      if (io && channel.type === "direct") {
        const allSockets = await io.fetchSockets();
        for (const member of otherMembers) {
          const memberSockets = allSockets.filter(s => s.data.userId === member.userId);
          const isViewingChannel = memberSockets.some(s => s.data.activeChannelId === channelId);
          if (!isViewingChannel) {
            sendPushToUser(member.userId, {
              title: senderDisplayName,
              body: msg.content.substring(0, 200),
              tag: `msg-${channelId}`,
              url: `/communications?channel=${channelId}`,
            }).catch(() => {});
          }
        }
      }

      res.json(msg);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

