  app.post("/api/accounting/allocate", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const { bankTransactionId, supplierId, allocations } = req.body;

      if (!bankTransactionId || !supplierId || !allocations || !Array.isArray(allocations) || allocations.length === 0) {
        return res.status(400).json({ message: "bankTransactionId, supplierId, and allocations array are required" });
      }

      const txn = await pool.query("SELECT * FROM bank_transactions WHERE id = $1 AND tenant_id = $2", [bankTransactionId, tenantId]);
      if (txn.rows.length === 0) return res.status(404).json({ message: "Transaction not found" });

      const transaction = txn.rows[0] as any;
      const txnAmount = Math.abs(parseFloat(transaction.amount));
      const currentAllocated = parseFloat(transaction.allocated_amount || '0');
      const totalNewAllocation = allocations.reduce((sum: number, a: any) => sum + parseFloat(a.amount), 0);

      if (currentAllocated + totalNewAllocation > txnAmount + 0.01) {
        return res.status(400).json({ message: `Total allocation (${(currentAllocated + totalNewAllocation).toFixed(2)}) exceeds transaction amount (${txnAmount.toFixed(2)})` });
      }

      const supplierCheck = await pool.query("SELECT id FROM suppliers WHERE id = $1 AND tenant_id = $2", [supplierId, tenantId]);
      if (supplierCheck.rows.length === 0) return res.status(404).json({ message: "Supplier not found" });

      const paidInvoiceIds: number[] = [];

      for (const alloc of allocations) {
        const invCheck = await pool.query(
          "SELECT id, total_amount, status FROM invoices WHERE id = $1 AND tenant_id = $2 AND supplier_id = $3",
          [alloc.invoiceId, tenantId, supplierId]
        );
        if (invCheck.rows.length === 0) return res.status(400).json({ message: `Invoice ${alloc.invoiceId} not found for this supplier/tenant` });
        if (invCheck.rows[0].status === 'cancelled') return res.status(400).json({ message: `Invoice ${alloc.invoiceId} is cancelled` });

        await pool.query(
          `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, invoice_id, supplier_id, amount, allocated_by, notes)
           VALUES ($1, $2, $3, $4, $5, $6, $7)`,
          [tenantId, bankTransactionId, alloc.invoiceId, supplierId, parseFloat(alloc.amount).toFixed(2), userId, alloc.notes || null]
        );

        const invoicePaid = await pool.query(
          "SELECT SUM(amount::numeric) as total_paid FROM bank_transaction_allocations WHERE invoice_id = $1 AND tenant_id = $2",
          [alloc.invoiceId, tenantId]
        );
        const totalPaid = parseFloat(invoicePaid.rows[0]?.total_paid) || 0;
        const invoiceTotal = parseFloat(invCheck.rows[0].total_amount) || 0;

        if (totalPaid >= invoiceTotal - 0.01) {
          await pool.query(
            "UPDATE invoices SET status = 'paid', paid_at = NOW(), payment_date = $1 WHERE id = $2 AND tenant_id = $3",
            [transaction.transaction_date, alloc.invoiceId, tenantId]
          );
          paidInvoiceIds.push(alloc.invoiceId);
        }
      }

      const newAllocated = currentAllocated + totalNewAllocation;
      const fullyAllocated = newAllocated >= txnAmount - 0.01;

      await pool.query(
        "UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2, supplier_id = $3 WHERE id = $4 AND tenant_id = $5",
        [newAllocated.toFixed(2), fullyAllocated, supplierId, bankTransactionId, tenantId]
      );

      let autoClassified = 0;
      try { autoClassified = await learnFromAllocation(tenantId, bankTransactionId, "supplier", supplierId, null); } catch (e) {}

      res.json({
        message: "Allocated successfully",
        allocated: newAllocated.toFixed(2),
        fullyAllocated,
        paidInvoiceIds,
        supplierId: parseInt(supplierId),
        autoClassified,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/accounting/auto-allocate-suppliers", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const { supplierIds } = req.body || {};

      const supplierFilter = Array.isArray(supplierIds) && supplierIds.length > 0
        ? `AND bt.supplier_id IN (${supplierIds.map(Number).filter(n => Number.isInteger(n) && n > 0).join(",")})`
        : "";

      const txnsResult = await pool.query(
        `SELECT bt.id, ABS(bt.amount::numeric) AS payment_amount, bt.supplier_id, bt.transaction_date,
                COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.bank_transaction_id = bt.id AND bta.tenant_id = $1), 0) AS alloc_sum
         FROM bank_transactions bt
         WHERE bt.tenant_id = $1 AND bt.amount::numeric < 0 AND bt.supplier_id IS NOT NULL ${supplierFilter}
         ORDER BY bt.transaction_date ASC`,
        [tenantId]
      );

      const supplierGroups = new Map<number, typeof txnsResult.rows>();
      for (const tx of txnsResult.rows) {
        const remaining = parseFloat(tx.payment_amount) - parseFloat(tx.alloc_sum);
        if (remaining < 0.01) continue;
        if (!supplierGroups.has(tx.supplier_id)) supplierGroups.set(tx.supplier_id, []);
        supplierGroups.get(tx.supplier_id)!.push({ ...tx, remaining });
      }

      let allocatedTxns = 0;
      let allocatedInvoices = 0;
      let totalAllocatedAmount = 0;
      const paidInvoiceNumbers: string[] = [];

      for (const [supplierId, payments] of supplierGroups) {
        const invsResult = await pool.query(
          `SELECT i.id, i.total_amount, i.invoice_number, i.period_start,
                  COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.invoice_id = i.id AND bta.tenant_id = $1), 0) AS paid_so_far
           FROM invoices i
           WHERE i.tenant_id = $1 AND i.supplier_id = $2 AND i.status NOT IN ('paid', 'cancelled')
           ORDER BY i.period_start ASC, i.id ASC`,
          [tenantId, supplierId]
        );

        const invoices = invsResult.rows.map((inv: any) => ({
          id: inv.id,
          invoiceNumber: inv.invoice_number,
          total: parseFloat(inv.total_amount),
          paidSoFar: parseFloat(inv.paid_so_far),
          remaining: parseFloat(inv.total_amount) - parseFloat(inv.paid_so_far),
          periodStart: inv.period_start,
          matched: false,
        })).filter((inv: any) => inv.remaining > 0.01);

        const paymentList = payments.map((p: any) => ({
          id: p.id,
          amount: parseFloat(p.payment_amount),
          allocSum: parseFloat(p.alloc_sum),
          remaining: p.remaining,
          txDate: p.transaction_date,
          matched: false,
        }));

        const allocations: Array<{ txId: number; invoiceId: number; amount: number; txDate: any; invoiceTotal: number; invoiceNumber: string }> = [];

        for (const payment of paymentList) {
          if (payment.matched || payment.remaining < 0.01) continue;
          const exactInv = invoices.find((inv: any) => !inv.matched && Math.abs(inv.remaining - payment.remaining) < 0.02);
          if (exactInv) {
            const allocAmt = Math.min(payment.remaining, exactInv.remaining);
            allocations.push({ txId: payment.id, invoiceId: exactInv.id, amount: allocAmt, txDate: payment.txDate, invoiceTotal: exactInv.total, invoiceNumber: exactInv.invoiceNumber });
            payment.remaining -= allocAmt;
            exactInv.remaining -= allocAmt;
            payment.matched = payment.remaining < 0.01;
            exactInv.matched = exactInv.remaining < 0.01;
          }
        }

        for (const payment of paymentList) {
          if (payment.remaining < 0.01) continue;
          for (const inv of invoices) {
            if (inv.remaining < 0.01) continue;
            if (payment.remaining < 0.01) break;
            const allocAmt = Math.min(payment.remaining, inv.remaining);
            allocations.push({ txId: payment.id, invoiceId: inv.id, amount: allocAmt, txDate: payment.txDate, invoiceTotal: inv.total, invoiceNumber: inv.invoiceNumber });
            payment.remaining -= allocAmt;
            inv.remaining -= allocAmt;
          }
        }

        for (const alloc of allocations) {
          await pool.query(
            `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, invoice_id, supplier_id, amount, allocated_by, notes)
             VALUES ($1, $2, $3, $4, $5, $6, 'Auto-allocated')`,
            [tenantId, alloc.txId, alloc.invoiceId, supplierId, alloc.amount.toFixed(2), userId]
          );
          totalAllocatedAmount += alloc.amount;
          allocatedInvoices++;
        }

        const touchedTxIds = new Set(allocations.map(a => a.txId));
        for (const txId of touchedTxIds) {
          const sumResult = await pool.query(
            "SELECT COALESCE(SUM(amount::numeric), 0) as total FROM bank_transaction_allocations WHERE bank_transaction_id = $1 AND tenant_id = $2",
            [txId, tenantId]
          );
          const txnTotal = parseFloat(sumResult.rows[0].total);
          const payment = paymentList.find((p: any) => p.id === txId);
          const fullyAllocated = payment && txnTotal >= payment.amount - 0.01;
          await pool.query(
            "UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2 WHERE id = $3 AND tenant_id = $4",
            [txnTotal.toFixed(2), !!fullyAllocated, txId, tenantId]
          );
          if (fullyAllocated) allocatedTxns++;
        }

        const touchedInvIds = new Set(allocations.map(a => a.invoiceId));
        for (const invId of touchedInvIds) {
          const sumResult = await pool.query(
            "SELECT COALESCE(SUM(amount::numeric), 0) as total FROM bank_transaction_allocations WHERE invoice_id = $1 AND tenant_id = $2",
            [invId, tenantId]
          );
          const totalPaid = parseFloat(sumResult.rows[0].total);
          const inv = invoices.find((i: any) => i.id === invId);
          if (inv && totalPaid >= inv.total - 0.01) {
            const lastAlloc = allocations.filter(a => a.invoiceId === invId).sort((a, b) => new Date(b.txDate).getTime() - new Date(a.txDate).getTime())[0];
            await pool.query(
              "UPDATE invoices SET status = 'paid', paid_at = NOW(), payment_date = $1 WHERE id = $2 AND tenant_id = $3",
              [lastAlloc?.txDate || new Date(), invId, tenantId]
            );
            paidInvoiceNumbers.push(inv.invoiceNumber);
          }
        }
      }

      res.json({
        message: `Auto-allocated ${allocatedTxns} transactions to ${allocatedInvoices} invoice allocations`,
        allocatedTransactions: allocatedTxns,
        allocatedInvoices,
        totalAmount: Math.round(totalAllocatedAmount * 100) / 100,
        paidInvoices: paidInvoiceNumbers,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/accounting/incremental-allocate-supplier", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const supplierId = 18;

      const client = await pool.connect();
      try {
        await client.query("BEGIN");

        const { rows: payments } = await client.query(
          `SELECT bt.id, bt.transaction_date, ABS(bt.amount::numeric)::numeric(12,2) as payment_amount,
                  bt.description,
                  COALESCE(bt.allocated_amount::numeric, 0) as already_allocated,
                  COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.bank_transaction_id = bt.id AND bta.tenant_id = $1), 0) as alloc_sum
           FROM bank_transactions bt
           WHERE bt.tenant_id = $1 AND bt.supplier_id = $2 AND bt.amount < 0
           ORDER BY bt.transaction_date ASC
           FOR UPDATE`,
          [tenantId, supplierId]
        );

        const paymentsWithRemaining = payments.map(p => {
          const total = parseFloat(p.payment_amount);
          const allocated = Math.max(parseFloat(p.already_allocated), parseFloat(p.alloc_sum));
          const remaining = Math.round((total - allocated) * 100) / 100;
          return { ...p, total, allocated, remaining };
        }).filter(p => p.remaining > 0.01);

        const { rows: invoices } = await client.query(
          `SELECT i.id, i.invoice_number, i.total_amount::numeric(12,2) as total_amount,
                  i.period_start, i.period_end, i.issued_at,
                  COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.invoice_id = i.id AND bta.tenant_id = $1), 0) as paid_so_far
           FROM invoices i
           WHERE i.tenant_id = $1 AND i.supplier_id = $2 AND i.status NOT IN ('paid', 'cancelled', 'void')
           ORDER BY i.period_start ASC, i.id ASC
           FOR UPDATE`,
          [tenantId, supplierId]
        );

        const invoicesWithBalance = invoices.map(inv => {
          const total = parseFloat(inv.total_amount);
          const paid = parseFloat(inv.paid_so_far);
          const outstanding = Math.round((total - paid) * 100) / 100;
          return { ...inv, total, paid, outstanding };
        }).filter(inv => inv.outstanding > 0.01);

        const newAllocations: Array<{ btId: number; invoiceId: number; invoiceNumber: string; amount: number; paymentDate: string; paymentTotal: number }> = [];

        const pmtRemaining: Record<number, number> = {};
        for (const p of paymentsWithRemaining) pmtRemaining[p.id] = p.remaining;

        const invOutstanding: Record<number, number> = {};
        for (const inv of invoicesWithBalance) invOutstanding[inv.id] = inv.outstanding;

        for (const pmt of paymentsWithRemaining) {
          if (pmtRemaining[pmt.id] <= 0.01) continue;

          for (const inv of invoicesWithBalance) {
            if (pmtRemaining[pmt.id] <= 0.01) break;
            if ((invOutstanding[inv.id] || 0) <= 0.01) continue;

            const allocAmount = Math.round(Math.min(pmtRemaining[pmt.id], invOutstanding[inv.id]) * 100) / 100;
            if (allocAmount <= 0) continue;

            newAllocations.push({
              btId: pmt.id,
              invoiceId: inv.id,
              invoiceNumber: inv.invoice_number,
              amount: allocAmount,
              paymentDate: pmt.transaction_date,
              paymentTotal: pmt.total,
            });

            pmtRemaining[pmt.id] = Math.round((pmtRemaining[pmt.id] - allocAmount) * 100) / 100;
            invOutstanding[inv.id] = Math.round((invOutstanding[inv.id] - allocAmount) * 100) / 100;
          }
        }

        for (const alloc of newAllocations) {
          await client.query(
            `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, invoice_id, supplier_id, amount, allocated_by, notes)
             VALUES ($1, $2, $3, $4, $5, $6, 'Incremental allocation')`,
            [tenantId, alloc.btId, alloc.invoiceId, supplierId, alloc.amount.toFixed(2), userId]
          );
        }

        await client.query("COMMIT");

        const unmatchedPayments = paymentsWithRemaining
          .filter(p => (pmtRemaining[p.id] || 0) > 0.01)
          .map(p => ({
            transactionId: p.id,
            transactionDate: p.transaction_date,
            originalAmount: p.total.toFixed(2),
            remainingUnallocated: (pmtRemaining[p.id] || 0).toFixed(2),
            description: p.description || "",
          }));

        const unpaidInvoices = invoicesWithBalance
          .filter(inv => (invOutstanding[inv.id] || 0) > 0.01)
          .map(inv => ({
            invoiceId: inv.id,
            invoiceNumber: inv.invoice_number,
            totalAmount: inv.total.toFixed(2),
            remainingBalance: (invOutstanding[inv.id] || 0).toFixed(2),
          }));

        const allocationDetails = newAllocations.map(a => ({
          paymentDate: a.paymentDate,
          paymentAmount: a.paymentTotal.toFixed(2),
          invoiceNumber: a.invoiceNumber,
          allocatedAmount: a.amount.toFixed(2),
        }));

        res.json({
          message: `Incremental allocation complete: ${newAllocations.length} new allocations created for supplier ${supplierId}`,
          allocationsCreated: newAllocations.length,
          totalAllocated: newAllocations.reduce((s, a) => s + a.amount, 0).toFixed(2),
          unmatchedPayments: unmatchedPayments.length,
          unpaidInvoices: unpaidInvoices.length,
          allocationDetails,
          unmatchedPaymentDetails: unmatchedPayments,
          unpaidInvoiceDetails: unpaidInvoices,
        });
      } catch (txErr) {
        await client.query("ROLLBACK");
        throw txErr;
      } finally {
        client.release();
      }
    } catch (err: any) {
      console.error("Incremental allocation error:", err);
      res.status(500).json({ message: err.message });
    }
  });

  app.delete("/api/accounting/allocations/:id", requireRole("super_admin", "tenant_admin", "admin"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const allocId = parseInt(req.params.id);

      const alloc = await pool.query("SELECT * FROM bank_transaction_allocations WHERE id = $1 AND tenant_id = $2", [allocId, tenantId]);
      if (alloc.rows.length === 0) return res.status(404).json({ message: "Allocation not found" });

      const allocation = alloc.rows[0] as any;
      const txnId = allocation.bank_transaction_id;
      const invoiceId = allocation.invoice_id;

      await pool.query("DELETE FROM bank_transaction_allocations WHERE id = $1 AND tenant_id = $2", [allocId, tenantId]);

      const remainingAllocs = await pool.query(
        "SELECT COALESCE(SUM(amount::numeric), 0) as total_allocated FROM bank_transaction_allocations WHERE bank_transaction_id = $1 AND tenant_id = $2",
        [txnId, tenantId]
      );
      const newAllocated = parseFloat(remainingAllocs.rows[0]?.total_allocated) || 0;
      const txn = await pool.query("SELECT amount FROM bank_transactions WHERE id = $1 AND tenant_id = $2", [txnId, tenantId]);
      const txnAmount = Math.abs(parseFloat(txn.rows[0]?.amount));
      const fullyAllocated = newAllocated >= txnAmount - 0.01;

      if (newAllocated <= 0.01) {
        await pool.query("UPDATE bank_transactions SET allocated_amount = '0', is_allocated = false, supplier_id = NULL WHERE id = $1 AND tenant_id = $2", [txnId, tenantId]);
      } else {
        await pool.query("UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2 WHERE id = $3 AND tenant_id = $4", [newAllocated.toFixed(2), fullyAllocated, txnId, tenantId]);
      }

      if (invoiceId) {
        const invoiceAllocTotal = await pool.query(
          "SELECT COALESCE(SUM(amount::numeric), 0) as total FROM bank_transaction_allocations WHERE invoice_id = $1 AND tenant_id = $2",
          [invoiceId, tenantId]
        );
        const invoicePaidTotal = parseFloat(invoiceAllocTotal.rows[0]?.total) || 0;
        const inv = await pool.query("SELECT total_amount FROM invoices WHERE id = $1 AND tenant_id = $2", [invoiceId, tenantId]);
        const invoiceTotal = parseFloat(inv.rows[0]?.total_amount || '0');
        if (invoicePaidTotal < invoiceTotal - 0.01) {
          await pool.query("UPDATE invoices SET status = 'approved', paid_at = NULL, payment_date = NULL WHERE id = $1 AND tenant_id = $2 AND status = 'paid'", [invoiceId, tenantId]);
        }
      }

      res.json({ message: "Allocation removed successfully" });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/accounting/allocations", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { supplierId } = req.query as any;

      let query = `SELECT bta.*, bt.transaction_date, bt.description as transaction_description, bt.amount as transaction_amount,
               i.invoice_number, i.total_amount as invoice_total, i.period_start, i.period_end,
               s.company_name as supplier_name
        FROM bank_transaction_allocations bta
        JOIN bank_transactions bt ON bta.bank_transaction_id = bt.id
        LEFT JOIN invoices i ON bta.invoice_id = i.id
        LEFT JOIN suppliers s ON bta.supplier_id = s.id
        WHERE bta.tenant_id = $1`;
      const params: any[] = [tenantId];

      if (supplierId) {
        query += " AND bta.supplier_id = $2";
        params.push(parseInt(supplierId));
      }
      query += " ORDER BY bta.allocated_at DESC";

      const result = await pool.query(query, params);
      res.json(result.rows);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/accounting/suggested-matches/:transactionId", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const transactionId = parseInt(req.params.transactionId);

      const txn = await pool.query("SELECT * FROM bank_transactions WHERE id = $1 AND tenant_id = $2", [transactionId, tenantId]);
      if (txn.rows.length === 0) return res.status(404).json({ message: "Transaction not found" });

      const txnAmount = Math.abs(parseFloat(txn.rows[0].amount));

      const result = await pool.query(
        `SELECT i.*, s.company_name as supplier_name,
           i.total_amount::numeric - COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.invoice_id = i.id), 0) as remaining,
           ABS(i.total_amount::numeric - COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.invoice_id = i.id), 0) - $1) as amount_diff
         FROM invoices i
         JOIN suppliers s ON i.supplier_id = s.id
         WHERE i.tenant_id = $2
           AND i.status != 'cancelled' AND i.status != 'paid'
           AND i.total_amount::numeric > COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.invoice_id = i.id), 0)
         ORDER BY amount_diff ASC
         LIMIT 10`,
        [txnAmount.toFixed(2), tenantId]
      );

      res.json(result.rows);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

