  app.get("/api/accounting/classification-suggestions", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const status = (req.query.status as string) || "pending";

      const result = await pool.query(
        `SELECT acs.*,
           bt.transaction_date, bt.description as txn_description, bt.amount as txn_amount, bt.reference as txn_reference,
           CASE
             WHEN acs.entity_type = 'supplier' THEN s.company_name
             WHEN acs.entity_type = 'client' THEN c.company_name
             WHEN acs.entity_type = 'vendor' THEN pv.name
             ELSE NULL
           END as entity_name,
           pv.name as vendor_name
         FROM auto_classification_suggestions acs
         JOIN bank_transactions bt ON acs.bank_transaction_id = bt.id
         LEFT JOIN suppliers s ON acs.entity_type = 'supplier' AND acs.entity_id = s.id
         LEFT JOIN clients c ON acs.entity_type = 'client' AND acs.entity_id = c.id
         LEFT JOIN purchase_vendors pv ON acs.vendor_id = pv.id
         WHERE acs.tenant_id = $1 AND acs.status = $2
         ORDER BY acs.confidence DESC, acs.created_at DESC`,
        [tenantId, status]
      );

      res.json(result.rows);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/accounting/classification-suggestions/:id/accept", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const suggestionId = parseInt(req.params.id);

      const sugResult = await pool.query(
        "SELECT * FROM auto_classification_suggestions WHERE id = $1 AND tenant_id = $2 AND status = 'pending'",
        [suggestionId, tenantId]
      );
      if (sugResult.rows.length === 0) return res.status(404).json({ message: "Suggestion not found or already processed" });

      const sug = sugResult.rows[0] as any;
      const txnResult = await pool.query("SELECT * FROM bank_transactions WHERE id = $1 AND tenant_id = $2", [sug.bank_transaction_id, tenantId]);
      if (txnResult.rows.length === 0) return res.status(404).json({ message: "Transaction not found" });

      const txn = txnResult.rows[0] as any;

      if (txn.is_allocated || txn.is_general_purchase) {
        await pool.query("UPDATE auto_classification_suggestions SET status = 'rejected' WHERE id = $1", [suggestionId]);
        return res.status(400).json({ message: "Transaction already allocated" });
      }

      if (sug.entity_type === "supplier" && sug.entity_id) {
        const txnAmount = Math.abs(parseFloat(txn.amount));

        if (sug.invoice_id) {
          const invCheck = await pool.query(
            "SELECT id, total_amount, status FROM invoices WHERE id = $1 AND tenant_id = $2",
            [sug.invoice_id, tenantId]
          );
          if (invCheck.rows.length > 0 && invCheck.rows[0].status !== 'cancelled' && invCheck.rows[0].status !== 'paid') {
            const remaining = parseFloat(invCheck.rows[0].total_amount) -
              (parseFloat((await pool.query("SELECT COALESCE(SUM(amount::numeric),0) as s FROM bank_transaction_allocations WHERE invoice_id=$1 AND tenant_id=$2", [sug.invoice_id, tenantId])).rows[0].s) || 0);
            const allocAmount = Math.min(txnAmount, remaining);

            await pool.query(
              `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, invoice_id, supplier_id, amount, allocated_by)
               VALUES ($1, $2, $3, $4, $5, $6)`,
              [tenantId, sug.bank_transaction_id, sug.invoice_id, sug.entity_id, allocAmount.toFixed(2), userId]
            );

            const totalPaid = (parseFloat((await pool.query("SELECT COALESCE(SUM(amount::numeric),0) as s FROM bank_transaction_allocations WHERE invoice_id=$1 AND tenant_id=$2", [sug.invoice_id, tenantId])).rows[0].s) || 0);
            if (totalPaid >= parseFloat(invCheck.rows[0].total_amount) - 0.01) {
              await pool.query("UPDATE invoices SET status = 'paid', paid_at = NOW(), payment_date = $1 WHERE id = $2 AND tenant_id = $3", [txn.transaction_date, sug.invoice_id, tenantId]);
            }

            const currentAllocated = parseFloat(txn.allocated_amount || '0');
            const newAllocated = currentAllocated + allocAmount;
            const fullyAllocated = newAllocated >= txnAmount - 0.01;
            await pool.query(
              "UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2, supplier_id = $3 WHERE id = $4 AND tenant_id = $5",
              [newAllocated.toFixed(2), fullyAllocated, sug.entity_id, sug.bank_transaction_id, tenantId]
            );
          } else {
            await pool.query(
              "UPDATE bank_transactions SET supplier_id = $1 WHERE id = $2 AND tenant_id = $3",
              [sug.entity_id, sug.bank_transaction_id, tenantId]
            );
          }
        } else {
          await pool.query(
            "UPDATE bank_transactions SET supplier_id = $1 WHERE id = $2 AND tenant_id = $3",
            [sug.entity_id, sug.bank_transaction_id, tenantId]
          );
        }
      } else if (sug.entity_type === "client" && sug.entity_id) {
        const txnAmount = Math.abs(parseFloat(txn.amount));

        if (sug.invoice_id) {
          const invCheck = await pool.query(
            "SELECT id, total_amount, status FROM client_invoices WHERE id = $1 AND tenant_id = $2",
            [sug.invoice_id, tenantId]
          );
          if (invCheck.rows.length > 0 && invCheck.rows[0].status !== 'cancelled' && invCheck.rows[0].status !== 'paid') {
            const remaining = parseFloat(invCheck.rows[0].total_amount) -
              (parseFloat((await pool.query("SELECT COALESCE(SUM(amount::numeric),0) as s FROM bank_transaction_allocations WHERE client_invoice_id=$1 AND tenant_id=$2", [sug.invoice_id, tenantId])).rows[0].s) || 0);
            const allocAmount = Math.min(txnAmount, remaining);

            await pool.query(
              `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, client_invoice_id, amount, allocated_by)
               VALUES ($1, $2, $3, $4, $5)`,
              [tenantId, sug.bank_transaction_id, sug.invoice_id, allocAmount.toFixed(2), userId]
            );

            const totalPaid = parseFloat((await pool.query("SELECT COALESCE(SUM(amount::numeric),0) as s FROM bank_transaction_allocations WHERE client_invoice_id=$1 AND tenant_id=$2", [sug.invoice_id, tenantId])).rows[0].s) || 0;
            if (totalPaid >= parseFloat(invCheck.rows[0].total_amount) - 0.01) {
              await pool.query("UPDATE client_invoices SET status = 'paid', paid_at = NOW() WHERE id = $1 AND tenant_id = $2", [sug.invoice_id, tenantId]);
            }

            const currentAllocated = parseFloat(txn.allocated_amount || '0');
            const newAllocated = currentAllocated + allocAmount;
            const fullyAllocated = newAllocated >= txnAmount - 0.01;
            await pool.query(
              "UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2, client_id = $3 WHERE id = $4 AND tenant_id = $5",
              [newAllocated.toFixed(2), fullyAllocated, sug.entity_id, sug.bank_transaction_id, tenantId]
            );
          } else {
            const isCreditTxn = parseFloat(txn.amount) > 0;
            await pool.query(
              "UPDATE bank_transactions SET client_id = $1, is_allocated = CASE WHEN $4 THEN true ELSE is_allocated END WHERE id = $2 AND tenant_id = $3",
              [sug.entity_id, sug.bank_transaction_id, tenantId, isCreditTxn]
            );
          }
        } else {
          const isCreditTxn = parseFloat(txn.amount) > 0;
          await pool.query(
            "UPDATE bank_transactions SET client_id = $1, is_allocated = CASE WHEN $4 THEN true ELSE is_allocated END WHERE id = $2 AND tenant_id = $3",
            [sug.entity_id, sug.bank_transaction_id, tenantId, isCreditTxn]
          );
        }
      } else if (sug.entity_type === "purchase" || sug.entity_type === "vendor") {
        const absAmount = Math.abs(parseFloat(txn.amount));
        let netAmount: number, vatAmount: number;
        if (sug.includes_vat) {
          netAmount = Math.floor((absAmount / 1.2) * 100) / 100;
          vatAmount = Math.floor((absAmount - netAmount) * 100) / 100;
        } else {
          netAmount = absAmount;
          vatAmount = 0;
        }
        await pool.query(
          `UPDATE bank_transactions SET is_general_purchase = true, net_amount = $1, vat_amount = $2,
           expense_category = $3, is_allocated = true, vendor_id = $4 WHERE id = $5 AND tenant_id = $6`,
          [netAmount.toFixed(2), vatAmount.toFixed(2), sug.expense_category, sug.vendor_id || null, sug.bank_transaction_id, tenantId]
        );
      }

      await pool.query("UPDATE auto_classification_suggestions SET status = 'accepted' WHERE id = $1", [suggestionId]);
      try { await learnFromAllocation(tenantId, sug.bank_transaction_id, sug.entity_type, sug.entity_id || sug.vendor_id, sug.expense_category, sug.includes_vat); } catch (e) {}

      res.json({ message: "Suggestion accepted and applied" });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

