  app.get("/api/accounting/reconciliation", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const result = await pool.query(
        `SELECT s.id, s.company_name,
           COALESCE(SUM(i.total_amount::numeric), 0) as total_invoiced,
           COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.supplier_id = s.id AND bta.tenant_id = $1), 0) as total_paid,
           COALESCE(SUM(i.total_amount::numeric), 0) - COALESCE((SELECT SUM(bta.amount::numeric) FROM bank_transaction_allocations bta WHERE bta.supplier_id = s.id AND bta.tenant_id = $1), 0) as outstanding
         FROM suppliers s
         LEFT JOIN invoices i ON i.supplier_id = s.id AND i.tenant_id = $1 AND i.status != 'cancelled'
         WHERE s.tenant_id = $1
         GROUP BY s.id, s.company_name
         HAVING COALESCE(SUM(i.total_amount::numeric), 0) > 0
         ORDER BY s.company_name ASC`,
        [tenantId]
      );
      res.json(result.rows);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/accounting/allocation-dashboard", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;

      const result = await pool.query(`
        SELECT 
          s.id as supplier_id,
          s.company_name,
          COALESCE(inv.inv_count, 0) as invoice_count,
          COALESCE(inv.paid_count, 0) as paid_invoice_count,
          COALESCE(inv.unpaid_count, 0) as unpaid_invoice_count,
          COALESCE(inv.inv_total, 0) as invoice_total,
          COALESCE(txn.txn_count, 0) as transaction_count,
          COALESCE(txn.alloc_txn_count, 0) as allocated_txn_count,
          COALESCE(txn.pay_total, 0) as payment_total,
          COALESCE(txn.alloc_total, 0) as allocated_total,
          COALESCE(alloc.alloc_record_count, 0) as allocation_count,
          COALESCE(alloc.alloc_amount, 0) as allocation_amount
        FROM suppliers s
        LEFT JOIN (
          SELECT i.supplier_id,
            COUNT(*) as inv_count,
            SUM(CASE WHEN i.status = 'paid' THEN 1 ELSE 0 END) as paid_count,
            SUM(CASE WHEN i.status NOT IN ('paid','cancelled') THEN 1 ELSE 0 END) as unpaid_count,
            SUM(CASE WHEN i.status != 'cancelled' THEN i.total_amount::numeric ELSE 0 END) as inv_total
          FROM invoices i
          WHERE i.tenant_id = $1 AND i.invoice_type = 'self_billed'
          GROUP BY i.supplier_id
        ) inv ON inv.supplier_id = s.id
        LEFT JOIN (
          SELECT bt.supplier_id,
            COUNT(*) as txn_count,
            SUM(CASE WHEN bt.is_allocated THEN 1 ELSE 0 END) as alloc_txn_count,
            SUM(ABS(bt.amount::numeric)) as pay_total,
            SUM(bt.allocated_amount::numeric) as alloc_total
          FROM bank_transactions bt
          WHERE bt.tenant_id = $1 AND bt.supplier_id IS NOT NULL AND bt.amount < 0
          GROUP BY bt.supplier_id
        ) txn ON txn.supplier_id = s.id
        LEFT JOIN (
          SELECT bta.supplier_id,
            COUNT(*) as alloc_record_count,
            SUM(bta.amount::numeric) as alloc_amount
          FROM bank_transaction_allocations bta
          WHERE bta.tenant_id = $1
          GROUP BY bta.supplier_id
        ) alloc ON alloc.supplier_id = s.id
        WHERE s.tenant_id = $1
          AND (COALESCE(inv.inv_count, 0) > 0 OR COALESCE(txn.txn_count, 0) > 0)
        ORDER BY COALESCE(txn.pay_total, 0) + COALESCE(inv.inv_total, 0) DESC
      `, [tenantId]);

      const suppliers = result.rows.map((r: any) => {
        const invTotal = parseFloat(r.invoice_total);
        const payTotal = parseFloat(r.payment_total);
        const allocTotal = parseFloat(r.allocated_total);
        const allocPct = payTotal > 0 ? Math.min(100, (allocTotal / payTotal) * 100) : (invTotal > 0 ? 0 : 100);
        const invPaidPct = parseInt(r.invoice_count) > 0 ? (parseInt(r.paid_invoice_count) / parseInt(r.invoice_count)) * 100 : 0;
        
        let status = 'fully_allocated';
        if (parseInt(r.invoice_count) === 0 && parseInt(r.transaction_count) > 0) status = 'no_invoices';
        else if (parseInt(r.unpaid_invoice_count) > 0 && parseInt(r.transaction_count) === 0) status = 'no_payments';
        else if (parseInt(r.unpaid_invoice_count) > 0 && allocPct < 50) status = 'needs_attention';
        else if (parseInt(r.unpaid_invoice_count) > 0 || allocPct < 99) status = 'partial';
        else if (allocPct < 50) status = 'needs_attention';
        else if (allocPct < 99) status = 'partial';

        return {
          supplierId: r.supplier_id,
          companyName: r.company_name,
          invoiceCount: parseInt(r.invoice_count),
          paidInvoiceCount: parseInt(r.paid_invoice_count),
          unpaidInvoiceCount: parseInt(r.unpaid_invoice_count),
          invoiceTotal: invTotal,
          transactionCount: parseInt(r.transaction_count),
          allocatedTxnCount: parseInt(r.allocated_txn_count),
          paymentTotal: payTotal,
          allocatedTotal: allocTotal,
          allocationCount: parseInt(r.allocation_count),
          allocationPct: Math.round(allocPct),
          invoicePaidPct: Math.round(invPaidPct),
          difference: invTotal - payTotal,
          status,
        };
      });

      const summary = {
        totalSuppliers: suppliers.length,
        fullyAllocated: suppliers.filter((s: any) => s.status === 'fully_allocated').length,
        partial: suppliers.filter((s: any) => s.status === 'partial').length,
        needsAttention: suppliers.filter((s: any) => s.status === 'needs_attention').length,
        noInvoices: suppliers.filter((s: any) => s.status === 'no_invoices').length,
        totalInvoiced: suppliers.reduce((s: number, r: any) => s + r.invoiceTotal, 0),
        totalPayments: suppliers.reduce((s: number, r: any) => s + r.paymentTotal, 0),
        totalAllocated: suppliers.reduce((s: number, r: any) => s + r.allocatedTotal, 0),
        overallPct: 0,
      };
      summary.overallPct = summary.totalPayments > 0 ? Math.min(100, Math.round((summary.totalAllocated / summary.totalPayments) * 100)) : 0;

      res.json({ summary, suppliers });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/accounting/allocation-dashboard/export", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const format = (req.query.format as string || "csv").toLowerCase();
      if (format !== "csv" && format !== "pdf") {
        return res.status(400).json({ message: "Invalid format. Use 'csv' or 'pdf'." });
      }

      const result = await pool.query(`
        SELECT 
          s.id as supplier_id,
          s.company_name,
          COALESCE(inv.inv_count, 0) as invoice_count,
          COALESCE(inv.paid_count, 0) as paid_invoice_count,
          COALESCE(inv.unpaid_count, 0) as unpaid_invoice_count,
          COALESCE(inv.inv_total, 0) as invoice_total,
          COALESCE(txn.txn_count, 0) as transaction_count,
          COALESCE(txn.alloc_txn_count, 0) as allocated_txn_count,
          COALESCE(txn.pay_total, 0) as payment_total,
          COALESCE(txn.alloc_total, 0) as allocated_total
        FROM suppliers s
        LEFT JOIN (
          SELECT i.supplier_id,
            COUNT(*) as inv_count,
            SUM(CASE WHEN i.status = 'paid' THEN 1 ELSE 0 END) as paid_count,
            SUM(CASE WHEN i.status NOT IN ('paid','cancelled') THEN 1 ELSE 0 END) as unpaid_count,
            SUM(CASE WHEN i.status != 'cancelled' THEN i.total_amount::numeric ELSE 0 END) as inv_total
          FROM invoices i
          WHERE i.tenant_id = $1 AND i.invoice_type = 'self_billed'
          GROUP BY i.supplier_id
        ) inv ON inv.supplier_id = s.id
        LEFT JOIN (
          SELECT bt.supplier_id,
            COUNT(*) as txn_count,
            SUM(CASE WHEN bt.is_allocated THEN 1 ELSE 0 END) as alloc_txn_count,
            SUM(ABS(bt.amount::numeric)) as pay_total,
            SUM(bt.allocated_amount::numeric) as alloc_total
          FROM bank_transactions bt
          WHERE bt.tenant_id = $1 AND bt.supplier_id IS NOT NULL AND bt.amount < 0
          GROUP BY bt.supplier_id
        ) txn ON txn.supplier_id = s.id
        WHERE s.tenant_id = $1
          AND (COALESCE(inv.inv_count, 0) > 0 OR COALESCE(txn.txn_count, 0) > 0)
        ORDER BY COALESCE(txn.pay_total, 0) + COALESCE(inv.inv_total, 0) DESC
      `, [tenantId]);

      const suppliers = result.rows.map((r: any) => {
        const invTotal = parseFloat(r.invoice_total);
        const payTotal = parseFloat(r.payment_total);
        const allocTotal = parseFloat(r.allocated_total);
        const allocPct = payTotal > 0 ? Math.min(100, (allocTotal / payTotal) * 100) : (invTotal > 0 ? 0 : 100);

        let status = 'Fully Allocated';
        if (parseInt(r.invoice_count) === 0 && parseInt(r.transaction_count) > 0) status = 'No Invoices';
        else if (parseInt(r.unpaid_invoice_count) > 0 && parseInt(r.transaction_count) === 0) status = 'No Payments';
        else if (parseInt(r.unpaid_invoice_count) > 0 && allocPct < 50) status = 'Needs Attention';
        else if (parseInt(r.unpaid_invoice_count) > 0 || allocPct < 99) status = 'Partial';
        else if (allocPct < 50) status = 'Needs Attention';
        else if (allocPct < 99) status = 'Partial';

        return {
          companyName: r.company_name,
          status,
          invoiceCount: parseInt(r.invoice_count),
          paidInvoiceCount: parseInt(r.paid_invoice_count),
          unpaidInvoiceCount: parseInt(r.unpaid_invoice_count),
          invoiceTotal: invTotal,
          transactionCount: parseInt(r.transaction_count),
          allocatedTxnCount: parseInt(r.allocated_txn_count),
          paymentTotal: payTotal,
          allocatedTotal: allocTotal,
          allocationPct: Math.round(allocPct),
          difference: invTotal - payTotal,
        };
      });

      const totInvoiced = suppliers.reduce((s, r) => s + r.invoiceTotal, 0);
      const totPayments = suppliers.reduce((s, r) => s + r.paymentTotal, 0);
      const totAllocated = suppliers.reduce((s, r) => s + r.allocatedTotal, 0);
      const overallPct = totPayments > 0 ? Math.min(100, Math.round((totAllocated / totPayments) * 100)) : 0;
      const fullyCount = suppliers.filter(s => s.status === 'Fully Allocated').length;
      const partialCount = suppliers.filter(s => s.status === 'Partial').length;
      const attentionCount = suppliers.filter(s => s.status === 'Needs Attention').length;
      const noInvCount = suppliers.filter(s => s.status === 'No Invoices').length;

      if (format === "csv") {
        function csvEsc(val: string): string {
          if (val.includes(",") || val.includes('"') || val.includes("\n")) return '"' + val.replace(/"/g, '""') + '"';
          return val;
        }
        const rows: string[] = [];
        rows.push("Supplier Allocation Progress Report");
        rows.push(`Generated,${new Date().toLocaleDateString("en-GB")}`);
        rows.push("");
        rows.push(`Total Suppliers,${suppliers.length}`);
        rows.push(`Fully Allocated,${fullyCount}`);
        rows.push(`Partial,${partialCount}`);
        rows.push(`Needs Attention,${attentionCount}`);
        rows.push(`No Invoices,${noInvCount}`);
        rows.push("");
        rows.push(`Total Invoiced,${totInvoiced.toFixed(2)}`);
        rows.push(`Total Payments,${totPayments.toFixed(2)}`);
        rows.push(`Total Allocated,${totAllocated.toFixed(2)}`);
        rows.push(`Overall Allocation %,${overallPct}%`);
        rows.push("");
        rows.push("Supplier,Status,Invoices,Inv Paid,Inv Unpaid,Invoice Total,Payments,Txn Count,Txns Allocated,Payment Total,Allocated Total,Allocation %,Difference");
        for (const s of suppliers) {
          rows.push([
            csvEsc(s.companyName), s.status, s.invoiceCount, s.paidInvoiceCount, s.unpaidInvoiceCount,
            s.invoiceTotal.toFixed(2), s.paymentTotal.toFixed(2), s.transactionCount, s.allocatedTxnCount,
            s.paymentTotal.toFixed(2), s.allocatedTotal.toFixed(2), s.allocationPct + "%", s.difference.toFixed(2)
          ].join(","));
        }

        const csv = rows.join("\r\n");
        res.set({ "Content-Type": "text/csv", "Content-Disposition": `attachment; filename="allocation-overview-${new Date().toISOString().slice(0,10)}.csv"` });
        return res.send(csv);
      }

      // PDF
      const fmtGBP = (v: number) => "£" + v.toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      let html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Allocation Overview</title>
        <style>
          body{font-family:Arial,sans-serif;margin:30px;color:#1a1a2e;font-size:11px}
          h1{font-size:18px;color:#1F3A5F;margin-bottom:4px}
          .subtitle{color:#666;font-size:11px;margin-bottom:20px}
          .summary-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:16px}
          .summary-box{border:1px solid #e0e0e0;border-radius:6px;padding:12px;text-align:center}
          .summary-box .num{font-size:22px;font-weight:bold}
          .summary-box .lbl{font-size:9px;color:#666;margin-top:4px}
          .totals-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:20px}
          .totals-box{border:1px solid #e0e0e0;border-radius:6px;padding:12px}
          .totals-box .lbl{font-size:9px;color:#666}
          .totals-box .val{font-size:15px;font-weight:bold;font-family:monospace}
          table{width:100%;border-collapse:collapse;font-size:10px}
          th{background:#f5f5f5;border:1px solid #ddd;padding:6px 8px;text-align:left;font-weight:600}
          td{border:1px solid #ddd;padding:5px 8px}
          tr:nth-child(even){background:#fafafa}
          .right{text-align:right}
          .mono{font-family:monospace}
          .green{color:#16a34a}.orange{color:#ea580c}.blue{color:#2563eb}.red{color:#dc2626}
          .status-badge{padding:2px 6px;border-radius:10px;font-size:9px;font-weight:600}
          .badge-full{background:#dcfce7;color:#166534}
          .badge-partial{background:#dbeafe;color:#1e40af}
          .badge-attention{background:#ffedd5;color:#9a3412}
          .badge-noinv{background:#fee2e2;color:#991b1b}
          .badge-nopay{background:#f3f4f6;color:#374151}
          @media print{body{margin:10px}th{background:#f5f5f5 !important;-webkit-print-color-adjust:exact}}
        </style></head><body>
        <h1>Supplier Allocation Progress</h1>
        <div class="subtitle">Generated: ${new Date().toLocaleDateString("en-GB", { day: "2-digit", month: "long", year: "numeric" })}</div>
        <div class="summary-grid">
          <div class="summary-box"><div class="num">${suppliers.length}</div><div class="lbl">Total Suppliers</div></div>
          <div class="summary-box"><div class="num green">${fullyCount}</div><div class="lbl">Fully Allocated</div></div>
          <div class="summary-box"><div class="num blue">${partialCount}</div><div class="lbl">Partial</div></div>
          <div class="summary-box"><div class="num orange">${attentionCount}</div><div class="lbl">Needs Attention</div></div>
          <div class="summary-box"><div class="num red">${noInvCount}</div><div class="lbl">No Invoices</div></div>
        </div>
        <div class="totals-grid">
          <div class="totals-box"><div class="lbl">Total Invoiced</div><div class="val">${fmtGBP(totInvoiced)}</div></div>
          <div class="totals-box"><div class="lbl">Total Payments</div><div class="val">${fmtGBP(totPayments)}</div></div>
          <div class="totals-box"><div class="lbl">Overall Allocation</div><div class="val">${overallPct}% <span style="font-size:10px;color:#666">(${fmtGBP(totAllocated)})</span></div></div>
        </div>
        <table><thead><tr>
          <th>Supplier</th><th>Status</th><th class="right">Invoices</th>
          <th class="right">Invoice Total</th><th class="right">Payments</th>
          <th class="right">Txns</th><th class="right">Allocated</th>
          <th class="right">Alloc %</th><th class="right">Difference</th>
        </tr></thead><tbody>`;

      for (const s of suppliers) {
        const badgeClass = s.status === 'Fully Allocated' ? 'badge-full' : s.status === 'Partial' ? 'badge-partial' : s.status === 'Needs Attention' ? 'badge-attention' : s.status === 'No Invoices' ? 'badge-noinv' : 'badge-nopay';
        const diffClass = s.difference > 0.5 ? 'orange' : s.difference < -0.5 ? 'blue' : 'green';
        html += `<tr>
          <td><strong>${s.companyName}</strong><br><span style="font-size:9px;color:#888">${s.paidInvoiceCount}/${s.invoiceCount} inv paid &middot; ${s.allocatedTxnCount}/${s.transactionCount} txns alloc</span></td>
          <td><span class="status-badge ${badgeClass}">${s.status}</span></td>
          <td class="right mono">${fmtGBP(s.invoiceTotal)}</td>
          <td class="right">${s.unpaidInvoiceCount > 0 ? '<span style="color:#ea580c;font-size:9px">' + s.unpaidInvoiceCount + ' unpaid</span>' : ''}</td>
          <td class="right mono">${fmtGBP(s.paymentTotal)}<br><span style="font-size:9px;color:#888">${s.transactionCount} txns</span></td>
          <td class="right mono">${fmtGBP(s.allocatedTotal)}</td>
          <td class="right mono">${s.allocationPct}%</td>
          <td class="right"></td>
          <td class="right mono ${diffClass}">${s.difference > 0 ? '+' : ''}${fmtGBP(s.difference)}</td>
        </tr>`;
      }
      html += `</tbody></table></body></html>`;
      res.set({ "Content-Type": "text/html", "Content-Disposition": `attachment; filename="allocation-overview-${new Date().toISOString().slice(0,10)}.html"` });
      return res.send(html);

    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

