  app.patch("/api/accounting/client-invoices/bulk", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { invoiceIds, status } = req.body;
      if (!invoiceIds || !Array.isArray(invoiceIds) || !status) {
        return res.status(400).json({ message: "invoiceIds array and status are required" });
      }
      let updated = 0;
      for (const id of invoiceIds) {
        if (status === 'issued') {
          const r = await pool.query("UPDATE client_invoices SET status = 'issued', issued_at = NOW() WHERE id = $1 AND tenant_id = $2 AND status = 'draft'", [id, tenantId]);
          updated += r.rowCount || 0;
        } else if (status === 'paid') {
          const r = await pool.query("UPDATE client_invoices SET status = 'paid', paid_at = NOW() WHERE id = $1 AND tenant_id = $2 AND status IN ('draft', 'issued')", [id, tenantId]);
          updated += r.rowCount || 0;
        }
      }
      res.json({ updated });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

