  app.post("/api/accounting/allocate-client", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const { bankTransactionId, clientId, allocations } = req.body;

      if (!bankTransactionId || !clientId || !allocations || !Array.isArray(allocations) || allocations.length === 0) {
        return res.status(400).json({ message: "bankTransactionId, clientId, and allocations array are required" });
      }

      const txn = await pool.query("SELECT * FROM bank_transactions WHERE id = $1 AND tenant_id = $2", [bankTransactionId, tenantId]);
      if (txn.rows.length === 0) return res.status(404).json({ message: "Transaction not found" });

      const transaction = txn.rows[0] as any;
      const txnAmount = Math.abs(parseFloat(transaction.amount));
      const currentAllocated = parseFloat(transaction.allocated_amount || '0');
      const totalNewAllocation = allocations.reduce((sum: number, a: any) => sum + parseFloat(a.amount), 0);

      if (currentAllocated + totalNewAllocation > txnAmount + 0.01) {
        return res.status(400).json({ message: `Total allocation (${(currentAllocated + totalNewAllocation).toFixed(2)}) exceeds transaction amount (${txnAmount.toFixed(2)})` });
      }

      const clientCheck = await pool.query("SELECT id FROM clients WHERE id = $1 AND tenant_id = $2", [clientId, tenantId]);
      if (clientCheck.rows.length === 0) return res.status(404).json({ message: "Client not found" });

      for (const alloc of allocations) {
        const invCheck = await pool.query(
          "SELECT id, total_amount, status FROM client_invoices WHERE id = $1 AND tenant_id = $2 AND client_id = $3",
          [alloc.invoiceId, tenantId, clientId]
        );
        if (invCheck.rows.length === 0) return res.status(400).json({ message: `Client invoice ${alloc.invoiceId} not found` });
        if (invCheck.rows[0].status === 'cancelled') return res.status(400).json({ message: `Client invoice ${alloc.invoiceId} is cancelled` });

        await pool.query(
          `INSERT INTO bank_transaction_allocations (tenant_id, bank_transaction_id, client_invoice_id, amount, allocated_by, notes)
           VALUES ($1, $2, $3, $4, $5, $6)`,
          [tenantId, bankTransactionId, alloc.invoiceId, parseFloat(alloc.amount).toFixed(2), userId, alloc.notes || null]
        );

        const invoicePaid = await pool.query(
          "SELECT SUM(amount::numeric) as total_paid FROM bank_transaction_allocations WHERE client_invoice_id = $1 AND tenant_id = $2",
          [alloc.invoiceId, tenantId]
        );
        const totalPaid = parseFloat(invoicePaid.rows[0]?.total_paid) || 0;
        const invoiceTotal = parseFloat(invCheck.rows[0].total_amount) || 0;

        if (totalPaid >= invoiceTotal - 0.01) {
          await pool.query(
            "UPDATE client_invoices SET status = 'paid', paid_at = NOW() WHERE id = $1 AND tenant_id = $2",
            [alloc.invoiceId, tenantId]
          );
        }
      }

      const newAllocated = currentAllocated + totalNewAllocation;
      const fullyAllocated = newAllocated >= txnAmount - 0.01;

      await pool.query(
        "UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2, client_id = $3 WHERE id = $4 AND tenant_id = $5",
        [newAllocated.toFixed(2), fullyAllocated, clientId, bankTransactionId, tenantId]
      );

      let autoClassified = 0;
      try { autoClassified = await learnFromAllocation(tenantId, bankTransactionId, "client", clientId, null); } catch (e) {}

      res.json({ message: "Allocated to client successfully", allocated: newAllocated.toFixed(2), fullyAllocated, autoClassified });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/accounting/bulk-assign-supplier", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { transactionIds, supplierId } = req.body;

      if (!transactionIds || !Array.isArray(transactionIds) || transactionIds.length === 0 || !supplierId) {
        return res.status(400).json({ message: "transactionIds array and supplierId are required" });
      }

      const supplierCheck = await pool.query("SELECT id FROM suppliers WHERE id = $1 AND tenant_id = $2", [supplierId, tenantId]);
      if (supplierCheck.rows.length === 0) return res.status(404).json({ message: "Supplier not found" });

      const txns = await pool.query(
        `SELECT id FROM bank_transactions WHERE id = ANY($1) AND tenant_id = $2 AND is_allocated = false AND is_general_purchase = false`,
        [transactionIds, tenantId]
      );

      let assigned = 0;
      let autoClassified = 0;
      for (const txn of txns.rows) {
        await pool.query(
          "UPDATE bank_transactions SET supplier_id = $1 WHERE id = $2 AND tenant_id = $3",
          [supplierId, txn.id, tenantId]
        );
        assigned++;
        try {
          autoClassified += await learnFromAllocation(tenantId, txn.id, "supplier", supplierId, null);
        } catch (e) {}
      }

      res.json({ message: `${assigned} transactions assigned to supplier`, assigned, autoClassified });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/accounting/bulk-assign-client", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { transactionIds, clientId } = req.body;

      if (!transactionIds || !Array.isArray(transactionIds) || transactionIds.length === 0 || !clientId) {
        return res.status(400).json({ message: "transactionIds array and clientId are required" });
      }

      const clientCheck = await pool.query("SELECT id FROM clients WHERE id = $1 AND tenant_id = $2", [clientId, tenantId]);
      if (clientCheck.rows.length === 0) return res.status(404).json({ message: "Client not found" });

      const txns = await pool.query(
        `SELECT id FROM bank_transactions WHERE id = ANY($1) AND tenant_id = $2 AND is_allocated = false AND is_general_purchase = false`,
        [transactionIds, tenantId]
      );

      let assigned = 0;
      let autoClassified = 0;
      for (const txn of txns.rows) {
        const txnData = await pool.query("SELECT amount FROM bank_transactions WHERE id = $1", [txn.id]);
        const isCredit = txnData.rows.length > 0 && parseFloat(txnData.rows[0].amount) > 0;
        await pool.query(
          "UPDATE bank_transactions SET client_id = $1, is_allocated = CASE WHEN $4 THEN true ELSE is_allocated END WHERE id = $2 AND tenant_id = $3",
          [clientId, txn.id, tenantId, isCredit]
        );
        assigned++;
        try {
          autoClassified += await learnFromAllocation(tenantId, txn.id, "client", clientId, null);
        } catch (e) {}
      }

      res.json({ message: `${assigned} transactions assigned to client`, assigned, autoClassified });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/accounting/bulk-categorise-purchase", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { transactionIds, expenseCategory, includesVat } = req.body;

      if (!transactionIds || !Array.isArray(transactionIds) || transactionIds.length === 0 || !expenseCategory) {
        return res.status(400).json({ message: "transactionIds array and expenseCategory are required" });
      }

      const txns = await pool.query(
        `SELECT id, amount FROM bank_transactions WHERE id = ANY($1) AND tenant_id = $2 AND is_allocated = false AND is_general_purchase = false`,
        [transactionIds, tenantId]
      );

      let assigned = 0;
      let autoClassified = 0;
      for (const txn of txns.rows) {
        const total = Math.abs(parseFloat(txn.amount));
        let net: number, vat: number;
        if (includesVat) {
          net = Math.floor((total / 1.2) * 100) / 100;
          vat = Math.floor((total - net) * 100) / 100;
        } else {
          net = total;
          vat = 0;
        }

        await pool.query(
          `UPDATE bank_transactions
           SET is_general_purchase = true, net_amount = $1, vat_amount = $2,
               expense_category = $3, is_allocated = true
           WHERE id = $4 AND tenant_id = $5`,
          [net.toFixed(2), vat.toFixed(2), expenseCategory, txn.id, tenantId]
        );
        assigned++;
        try {
          autoClassified += await learnFromAllocation(tenantId, txn.id, "purchase", null, expenseCategory, !!includesVat);
        } catch (e) {}
      }

      res.json({ message: `${assigned} transactions categorised as purchases`, assigned, autoClassified });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/accounting/client-transactions/:clientId", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const tenantId = (req.user as User).tenantId!;
      const clientId = parseInt(req.params.clientId);
      if (isNaN(clientId)) return res.status(400).json({ message: "Invalid client ID" });

      const clientCheck = await pool.query("SELECT id FROM clients WHERE id = $1 AND tenant_id = $2", [clientId, tenantId]);
      if (clientCheck.rows.length === 0) return res.status(404).json({ message: "Client not found" });

      const result = await pool.query(
        `SELECT bt.id, bt.transaction_date, bt.description, bt.amount, bt.type, bt.reference,
                bt.is_allocated, bt.allocated_amount,
                COALESCE(
                  json_agg(
                    json_build_object(
                      'id', bta.id,
                      'amount', bta.amount,
                      'client_invoice_id', bta.client_invoice_id,
                      'invoice_number', ci.invoice_number,
                      'notes', bta.notes
                    )
                  ) FILTER (WHERE bta.id IS NOT NULL), '[]'
                ) as allocations
         FROM bank_transactions bt
         LEFT JOIN bank_transaction_allocations bta ON bta.bank_transaction_id = bt.id AND bta.tenant_id = $1
         LEFT JOIN client_invoices ci ON ci.id = bta.client_invoice_id
         WHERE bt.tenant_id = $1 AND bt.client_id = $2
         GROUP BY bt.id
         ORDER BY bt.transaction_date DESC`,
        [tenantId, clientId]
      );

      res.json(result.rows);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

