  const computeVatReturnData = async (tenantId: number, quarter: string) => {
      const tenantRes = await pool.query("SELECT vat_calculation_type FROM tenants WHERE id = $1", [tenantId]);
      const vatCalcType = tenantRes.rows[0]?.vat_calculation_type || "accrual";

      const [yearStr, qStr] = quarter.split('-');
      const year = parseInt(yearStr);
      const q = parseInt(qStr.replace('Q', ''));

      let startMonth: number, startYear: number, endMonth: number, endYear: number;
      if (q === 1) { startMonth = 11; startYear = year - 1; endMonth = 1; endYear = year; }
      else if (q === 2) { startMonth = 2; startYear = year; endMonth = 4; endYear = year; }
      else if (q === 3) { startMonth = 5; startYear = year; endMonth = 7; endYear = year; }
      else { startMonth = 8; startYear = year; endMonth = 10; endYear = year; }

      const periodStart = `${startYear}-${String(startMonth).padStart(2, '0')}-01`;
      const lastDay = new Date(endYear, endMonth, 0).getDate();
      const periodEnd = `${endYear}-${String(endMonth).padStart(2, '0')}-${lastDay}`;

      const vendorNameExpr = `UPPER(TRIM(
        CASE
          WHEN POSITION(' ' IN TRIM(bt.description)) = 0 THEN TRIM(bt.description)
          WHEN POSITION(' ' IN TRIM(SUBSTRING(bt.description FROM POSITION(' ' IN TRIM(bt.description)) + 1))) = 0
            THEN TRIM(bt.description)
          ELSE TRIM(SUBSTRING(TRIM(bt.description) FROM 1 FOR
            POSITION(' ' IN TRIM(bt.description)) - 1 +
            POSITION(' ' IN TRIM(SUBSTRING(bt.description FROM POSITION(' ' IN TRIM(bt.description)) + 1)))
          ))
        END
      ))`;

      const querySalesVat = async (dStart: string, dEnd: string) => {
        if (vatCalcType === "cash") {
          const r = await pool.query(
            `SELECT COALESCE(SUM(amount::numeric / 6), 0) as total_vat,
                    COALESCE(SUM(amount::numeric - amount::numeric / 6), 0) as total_net
             FROM bank_transactions
             WHERE tenant_id = $1
               AND amount::numeric > 0
               AND transaction_date >= $2 AND transaction_date <= $3`,
            [tenantId, dStart, dEnd]
          );
          return r.rows[0];
        } else {
          const r = await pool.query(
            `SELECT COALESCE(SUM(vat_amount::numeric), 0) as total_vat,
                    COALESCE(SUM(subtotal::numeric), 0) as total_net
             FROM client_invoices
             WHERE tenant_id = $1
               AND status != 'cancelled' AND status != 'draft'
               AND period_start >= $2 AND period_end <= $3`,
            [tenantId, dStart, dEnd]
          );
          return r.rows[0];
        }
      };

      const querySupplierVat = async (dStart: string, dEnd: string) => {
        if (vatCalcType === "cash") {
          const r = await pool.query(
            `SELECT
               COALESCE(SUM(
                 CASE WHEN s.vat_status = 'vat_registered'
                   AND (s.vat_registered_from IS NULL OR bt.transaction_date >= s.vat_registered_from::date)
                 THEN ABS(bt.amount::numeric) / 6 ELSE 0 END
               ), 0) as total_vat,
               COALESCE(SUM(
                 CASE WHEN s.vat_status = 'vat_registered'
                   AND (s.vat_registered_from IS NULL OR bt.transaction_date >= s.vat_registered_from::date)
                 THEN ABS(bt.amount::numeric) - ABS(bt.amount::numeric) / 6
                 ELSE ABS(bt.amount::numeric) END
               ), 0) as total_net
             FROM bank_transactions bt
             JOIN suppliers s ON bt.supplier_id = s.id
             WHERE bt.tenant_id = $1
               AND bt.supplier_id IS NOT NULL
               AND bt.amount::numeric < 0
               AND bt.transaction_date >= $2 AND bt.transaction_date <= $3`,
            [tenantId, dStart, dEnd]
          );
          return r.rows[0];
        } else {
          const r = await pool.query(
            `SELECT COALESCE(SUM(vat_amount::numeric), 0) as total_vat,
                    COALESCE(SUM(subtotal::numeric), 0) as total_net
             FROM invoices
             WHERE tenant_id = $1
               AND status != 'cancelled'
               AND period_start >= $2 AND period_end <= $3`,
            [tenantId, dStart, dEnd]
          );
          return r.rows[0];
        }
      };

      const queryPurchasesVat = async (dStart: string, dEnd: string) => {
        if (vatCalcType === "cash") {
          const r = await pool.query(
            `SELECT
               COALESCE(SUM(
                 CASE WHEN vc.vat_qualifying = true THEN ABS(bt.amount::numeric) / 6 ELSE 0 END
               ), 0) as total_vat,
               COALESCE(SUM(
                 CASE WHEN vc.vat_qualifying = true
                 THEN ABS(bt.amount::numeric) - ABS(bt.amount::numeric) / 6
                 ELSE 0 END
               ), 0) as total_net
             FROM bank_transactions bt
             LEFT JOIN vendor_classifications vc ON vc.tenant_id = bt.tenant_id
               AND vc.vendor_name = ${vendorNameExpr}
             WHERE bt.tenant_id = $1
               AND bt.amount::numeric < 0
               AND bt.supplier_id IS NULL
               AND bt.transaction_date >= $2 AND bt.transaction_date <= $3`,
            [tenantId, dStart, dEnd]
          );
          return r.rows[0];
        } else {
          const r = await pool.query(
            `SELECT COALESCE(SUM(vat_amount::numeric), 0) as total_vat,
                    COALESCE(SUM(net_amount::numeric), 0) as total_net
             FROM bank_transactions
             WHERE tenant_id = $1
               AND is_general_purchase = true
               AND transaction_date >= $2 AND transaction_date <= $3`,
            [tenantId, dStart, dEnd]
          );
          return r.rows[0];
        }
      };

      const [outputVatRow, inputVatSupplierRow, inputVatGeneralRow] = await Promise.all([
        querySalesVat(periodStart, periodEnd),
        querySupplierVat(periodStart, periodEnd),
        queryPurchasesVat(periodStart, periodEnd),
      ]);

      const generalByCategory = await pool.query(
        `SELECT expense_category, SUM(net_amount::numeric) as net_total, SUM(vat_amount::numeric) as vat_total, COUNT(*) as count
         FROM bank_transactions
         WHERE tenant_id = $1 AND is_general_purchase = true
           AND transaction_date >= $2 AND transaction_date <= $3
         GROUP BY expense_category
         ORDER BY expense_category`,
        [tenantId, periodStart, periodEnd]
      );

      // Wages ledger is explicitly excluded from VAT (no input VAT claimed and not
      // part of Box 7 "total value of purchases"). We surface the period total as a
      // memo line so accountants can reconcile completeness of the purchase side.
      const wagesRes = await pool.query(
        `SELECT COALESCE(SUM(gross_amount::numeric), 0) as total, COUNT(*) as count
         FROM wages_ledger
         WHERE tenant_id = $1
           AND entry_date >= $2 AND entry_date <= $3`,
        [tenantId, periodStart, periodEnd]
      );
      const wagesTotal = parseFloat(wagesRes.rows[0]?.total || '0');
      const wagesCount = parseInt(wagesRes.rows[0]?.count || '0');

      let unclassifiedVendorCount = 0;
      if (vatCalcType === "cash") {
        const ucRes = await pool.query(
          `SELECT COUNT(DISTINCT ${vendorNameExpr.replace(/bt\./g, '')}) as c
           FROM bank_transactions bt
           WHERE bt.tenant_id = $1
             AND bt.amount::numeric < 0
             AND bt.supplier_id IS NULL
             AND ${vendorNameExpr} NOT IN (
               SELECT UPPER(vendor_name) FROM vendor_classifications WHERE tenant_id = $1
             )`,
          [tenantId]
        );
        unclassifiedVendorCount = parseInt(ucRes.rows[0]?.c || '0');
      }

      const monthlyBreakdown: any[] = [];
      for (let m = 0; m < 3; m++) {
        const mMonth = startMonth + m;
        const mYear = mMonth > 12 ? startYear + 1 : startYear;
        const actualMonth = mMonth > 12 ? mMonth - 12 : mMonth;
        const mStart = `${mYear}-${String(actualMonth).padStart(2, '0')}-01`;
        const mLastDay = new Date(mYear, actualMonth, 0).getDate();
        const mEnd = `${mYear}-${String(actualMonth).padStart(2, '0')}-${mLastDay}`;

        const [mOutput, mInputSupplier, mInputGeneral] = await Promise.all([
          querySalesVat(mStart, mEnd),
          querySupplierVat(mStart, mEnd),
          queryPurchasesVat(mStart, mEnd),
        ]);

        monthlyBreakdown.push({
          month: `${mYear}-${String(actualMonth).padStart(2, '0')}`,
          outputVat: parseFloat(mOutput?.total_vat || '0'),
          outputNet: parseFloat(mOutput?.total_net || '0'),
          inputVatSupplier: parseFloat(mInputSupplier?.total_vat || '0'),
          inputNetSupplier: parseFloat(mInputSupplier?.total_net || '0'),
          inputVatGeneral: parseFloat(mInputGeneral?.total_vat || '0'),
          inputNetGeneral: parseFloat(mInputGeneral?.total_net || '0'),
        });
      }

      const salesVat = parseFloat(outputVatRow?.total_vat || '0');
      const supplierVat = parseFloat(inputVatSupplierRow?.total_vat || '0');
      const generalPurchasesVat = parseFloat(inputVatGeneralRow?.total_vat || '0');
      const netVat = salesVat - (generalPurchasesVat + supplierVat);
      const salesNet = parseFloat(outputVatRow?.total_net || '0');
      const supplierNet = parseFloat(inputVatSupplierRow?.total_net || '0');
      const generalNet = parseFloat(inputVatGeneralRow?.total_net || '0');

      return {
        quarter,
        periodStart,
        periodEnd,
        vatCalculationType: vatCalcType,
        unclassifiedVendorCount,
        salesVat: Math.round(salesVat * 100) / 100,
        generalPurchasesVat: Math.round(generalPurchasesVat * 100) / 100,
        supplierVat: Math.round(supplierVat * 100) / 100,
        netVat: Math.round(netVat * 100) / 100,
        salesNet: Math.round(salesNet),
        supplierNet: Math.round(supplierNet),
        generalNet: Math.round(generalNet),
        box1: Math.round(salesVat * 100) / 100,
        box4: Math.round(generalPurchasesVat * 100) / 100,
        box5: Math.round(netVat * 100) / 100,
        box6: Math.round(salesNet),
        box7: Math.round(supplierNet + generalNet),
        wagesTotal: Math.round(wagesTotal * 100) / 100,
        wagesCount,
        breakdown: {
          outputVatTotal: salesVat,
          inputVatSuppliers: supplierVat,
          inputVatGeneralPurchases: generalPurchasesVat,
          totalSalesNet: salesNet,
          totalPurchasesNetSuppliers: supplierNet,
          totalPurchasesNetGeneral: generalNet,
          wagesExcludedFromVat: wagesTotal,
        },
        generalPurchasesByCategory: generalByCategory.rows,
        monthlyBreakdown,
      };
  };

