  app.get("/api/accounting/supplier-transactions/:supplierId", requireRole("super_admin", "tenant_admin", "admin", "accountant"), async (req, res) => {
    try {
      const user = req.user as User;
      const tenantId = user.tenantId;
      if (!tenantId) return res.status(400).json({ message: "No tenant" });
      const supplierId = parseInt(req.params.supplierId, 10);
      if (isNaN(supplierId)) return res.status(400).json({ message: "Invalid supplier ID" });

      const unallocatedOnly = req.query.unallocated === "true";

      const txResult = await pool.query(
        `SELECT bt.*, 
                COALESCE(
                  json_agg(
                    json_build_object(
                      'id', bta.id,
                      'invoiceId', bta.invoice_id,
                      'amount', bta.amount,
                      'notes', bta.notes,
                      'allocatedAt', bta.allocated_at
                    )
                  ) FILTER (WHERE bta.id IS NOT NULL), '[]'
                ) as allocations
         FROM bank_transactions bt
         LEFT JOIN bank_transaction_allocations bta ON bta.bank_transaction_id = bt.id
         WHERE bt.tenant_id = $1 AND bt.supplier_id = $2
         GROUP BY bt.id
         ORDER BY bt.transaction_date DESC`,
        [tenantId, supplierId]
      );

      if (unallocatedOnly) {
        const filtered = txResult.rows
          .filter((tx: any) => {
            const totalAmount = Math.abs(parseFloat(tx.amount || "0"));
            const allocated = parseFloat(tx.allocated_amount || "0");
            return allocated < totalAmount - 0.01;
          })
          .map((tx: any) => ({
            id: tx.id,
            transactionDate: tx.transaction_date,
            description: tx.description,
            amount: tx.amount,
            allocatedAmount: tx.allocated_amount || "0",
            isAllocated: tx.is_allocated,
          }));
        return res.json(filtered);
      }

      const invoiceIds = new Set<number>();
      for (const tx of txResult.rows) {
        if (Array.isArray(tx.allocations)) {
          for (const alloc of tx.allocations) {
            if (alloc.invoiceId) invoiceIds.add(alloc.invoiceId);
          }
        }
      }

      let invoiceMap: Record<number, string> = {};
      if (invoiceIds.size > 0) {
        const invResult = await pool.query(
          `SELECT id, invoice_number FROM invoices WHERE id = ANY($1)`,
          [Array.from(invoiceIds)]
        );
        for (const inv of invResult.rows) {
          invoiceMap[inv.id] = inv.invoice_number;
        }
      }

      const transactions = txResult.rows.map((tx: any) => {
        const allocations = (tx.allocations || []).map((a: any) => ({
          ...a,
          invoiceNumber: a.invoiceId ? invoiceMap[a.invoiceId] || null : null,
        }));
        const totalAllocated = parseFloat(tx.allocated_amount || "0");
        const totalAmount = Math.abs(parseFloat(tx.amount || "0"));
        let status = "Unallocated";
        if (tx.is_allocated) status = "Allocated";
        else if (totalAllocated > 0) status = "Partial";
        return {
          id: tx.id,
          transactionDate: tx.transaction_date,
          description: tx.description,
          amount: tx.amount,
          reference: tx.reference,
          isAllocated: tx.is_allocated,
          allocatedAmount: tx.allocated_amount,
          status,
          allocations,
        };
      });

      const totalPayments = transactions.reduce((sum: number, t: any) => sum + Math.abs(parseFloat(t.amount || "0")), 0);

      res.json({ transactions, totalPayments, transactionCount: transactions.length });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

