  app.get("/api/admin/suppliers/:supplierId/audit-trail-pdf", requireRole(...hmrcAuditRoles), async (req, res) => {
    try {
      const user = req.user as User;
      const supplierId = Number(req.params.supplierId);
      const supplier = await storage.getSupplier(supplierId);
      if (!supplier || (user.tenantId && supplier.tenantId !== user.tenantId)) {
        return res.status(404).json({ message: "Supplier not found" });
      }
      const events = await storage.getSupplierAuditEvents(supplierId, { limit: 1000 });
      const PDFDocument = (await import("pdfkit")).default;
      const doc = new PDFDocument({ margin: 40, size: "A4", layout: "landscape" });
      const buffers: Buffer[] = [];
      doc.on("data", (chunk: Buffer) => buffers.push(chunk));
      const pdfReady = new Promise<Buffer>((resolve) => {
        doc.on("end", () => resolve(Buffer.concat(buffers)));
      });

      doc.fontSize(14).font("Helvetica-Bold").text(`Audit Trail — ${supplier.companyName}`, { align: "center" });
      doc.fontSize(9).font("Helvetica").text(`Supplier Code: ${supplier.supplierCode || "N/A"}  |  Generated: ${new Date().toLocaleDateString("en-GB")}  |  Total Events: ${events.length}`, { align: "center" });
      doc.moveDown(0.8);

      const colX = [40, 130, 260, 440, 620, 700];
      const colW = [88, 128, 178, 178, 78, 108];
      const headers = ["Date", "Event Type", "Summary", "Details", "IP Address", "Actor"];

      doc.fontSize(8).font("Helvetica-Bold").fillColor("#1F3A5F");
      headers.forEach((h, i) => doc.text(h, colX[i], doc.y, { width: colW[i], continued: i < headers.length - 1 }));
      doc.text("", 40);
      doc.moveDown(0.3);
      doc.moveTo(40, doc.y).lineTo(800, doc.y).strokeColor("#ccc").lineWidth(0.5).stroke();
      doc.moveDown(0.3);

      doc.font("Helvetica").fontSize(7).fillColor("#333");
      for (const ev of events) {
        if (doc.y > 520) {
          doc.addPage({ layout: "landscape" });
          doc.fontSize(8).font("Helvetica-Bold").fillColor("#1F3A5F");
          headers.forEach((h, i) => doc.text(h, colX[i], doc.y, { width: colW[i], continued: i < headers.length - 1 }));
          doc.text("", 40);
          doc.moveDown(0.3);
          doc.moveTo(40, doc.y).lineTo(800, doc.y).strokeColor("#ccc").lineWidth(0.5).stroke();
          doc.moveDown(0.3);
          doc.font("Helvetica").fontSize(7).fillColor("#333");
        }
        const rowY = doc.y;
        const dateStr = ev.createdAt ? new Date(ev.createdAt).toLocaleDateString("en-GB") + " " + new Date(ev.createdAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }) : "—";
        const eventType = (ev.eventType || "").replace(/_/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase());
        const summary = ev.summary || "—";
        const details = ev.entityType ? `${ev.entityType}: ${ev.entityId || ""}` : "—";
        doc.text(dateStr, colX[0], rowY, { width: colW[0] });
        doc.text(eventType, colX[1], rowY, { width: colW[1] });
        doc.text(summary, colX[2], rowY, { width: colW[2] });
        doc.text(details, colX[3], rowY, { width: colW[3] });
        doc.text(ev.ipAddress || "—", colX[4], rowY, { width: colW[4] });
        doc.text(ev.actorName || "System", colX[5], rowY, { width: colW[5] });
        const maxH = Math.max(doc.y - rowY, 12);
        doc.y = rowY + maxH + 3;
      }

      doc.end();
      const pdfBuffer = await pdfReady;
      const filename = `audit-trail-${safeFilename(String(supplier.supplierCode || supplierId))}-${new Date().toISOString().slice(0, 10)}.pdf`;
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.send(pdfBuffer);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  async function buildRemittanceSummaryForAuditPack(tenantId: number, supplierId: number, dateFrom?: string, dateTo?: string): Promise<Buffer | null> {
    const allocCheck = await pool.query(
      `SELECT COUNT(*)::int as cnt FROM bank_transaction_allocations bta
       WHERE bta.tenant_id = $1
         AND (bta.supplier_id = $2 OR (bta.supplier_id IS NULL AND bta.invoice_id IN (SELECT id FROM invoices WHERE supplier_id = $2 AND tenant_id = $1)))`,
      [tenantId, supplierId]
    );
    if (allocCheck.rows[0].cnt === 0) return null;

    const tenantRes = await pool.query("SELECT * FROM tenants WHERE id = $1", [tenantId]);
    if (tenantRes.rows.length === 0) return null;
    const tenant = tenantRes.rows[0];

    const supplierRes = await pool.query("SELECT * FROM suppliers WHERE id = $1 AND tenant_id = $2", [supplierId, tenantId]);
    if (supplierRes.rows.length === 0) return null;
    const supplier = supplierRes.rows[0];

    let invoiceQuery = `SELECT id, invoice_number, period_start, period_end, total_amount, status
       FROM invoices WHERE supplier_id = $1 AND tenant_id = $2`;
    const invoiceParams: any[] = [supplierId, tenantId];
    if (dateFrom) {
      invoiceParams.push(dateFrom);
      invoiceQuery += ` AND period_start >= $${invoiceParams.length}`;
    }
    if (dateTo) {
      invoiceParams.push(dateTo);
      invoiceQuery += ` AND period_end <= $${invoiceParams.length}`;
    }
    invoiceQuery += ` ORDER BY period_start, invoice_number`;
    const invoicesRes = await pool.query(invoiceQuery, invoiceParams);
    if (invoicesRes.rows.length === 0) return null;

    const invoiceIds = invoicesRes.rows.map((r: any) => r.id);

    let allocationsByInvoice: Record<number, Array<{ bankRef: string; amountPaid: string; datePaid: string }>> = {};
    let paidTotalsByInvoice: Record<number, number> = {};

    const allocRes = await pool.query(
      `SELECT bta.invoice_id, bta.amount, bt.transaction_date, bt.reference, bt.description
       FROM bank_transaction_allocations bta
       JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
       WHERE bta.invoice_id = ANY($1) AND bta.tenant_id = $2
       ORDER BY bt.transaction_date`,
      [invoiceIds, tenantId]
    );

    for (const alloc of allocRes.rows) {
      if (!allocationsByInvoice[alloc.invoice_id]) allocationsByInvoice[alloc.invoice_id] = [];
      const rawRef = alloc.reference && !/^0+$/.test(String(alloc.reference).trim()) ? String(alloc.reference).trim() : "";
      const rawDesc = alloc.description ? alloc.description.replace(/\s+/g, " ").trim() : "";
      allocationsByInvoice[alloc.invoice_id].push({
        bankRef: rawDesc || rawRef || "",
        amountPaid: alloc.amount,
        datePaid: alloc.transaction_date,
      });
      paidTotalsByInvoice[alloc.invoice_id] = (paidTotalsByInvoice[alloc.invoice_id] || 0) + parseFloat(alloc.amount);
    }

    let totalInvoiced = 0;
    let totalPaid = 0;

    const pdfInvoices: Array<{ invoiceNumber: string; periodStart: string; periodEnd: string; invoiceAmount: string; bankRef: string; amountPaid: string; datePaid: string; status: string }> = [];

    for (const inv of invoicesRes.rows) {
      const invoiceAmount = parseFloat(inv.total_amount);
      const paidAmount = paidTotalsByInvoice[inv.id] || 0;
      totalInvoiced += invoiceAmount;
      totalPaid += paidAmount;

      const paymentStatus = Math.round(paidAmount * 100) >= Math.round(invoiceAmount * 100) ? "Paid" : paidAmount > 0 ? "Partial" : "Unpaid";
      const payments = allocationsByInvoice[inv.id] || [];

      if (payments.length === 0) {
        pdfInvoices.push({
          invoiceNumber: inv.invoice_number, periodStart: inv.period_start, periodEnd: inv.period_end,
          invoiceAmount: inv.total_amount, bankRef: "", amountPaid: "0", datePaid: "", status: paymentStatus,
        });
      } else {
        for (const p of payments) {
          pdfInvoices.push({
            invoiceNumber: inv.invoice_number, periodStart: inv.period_start, periodEnd: inv.period_end,
            invoiceAmount: inv.total_amount, bankRef: p.bankRef, amountPaid: p.amountPaid, datePaid: p.datePaid, status: paymentStatus,
          });
        }
      }
    }

    const tenantAddress = [tenant.address_line_1, tenant.address_line_2, tenant.city, tenant.county, tenant.postcode].filter(Boolean).join(", ") || tenant.address;
    const supplierAddress = supplier.agreement_registered_address
      ? buildSupplierAddress(supplier.agreement_registered_address, supplier.agreement_registered_city, supplier.agreement_registered_postcode)
      : supplier.registered_office_address
        ? buildSupplierAddress(supplier.registered_office_address, supplier.registered_office_city, supplier.registered_office_postcode)
        : [supplier.address_line_1, supplier.address_line_2, supplier.city, supplier.county, supplier.postcode].filter(Boolean).join(", ") || supplier.address;

    const minStart = invoicesRes.rows[0].period_start;
    const maxEnd = invoicesRes.rows[invoicesRes.rows.length - 1].period_end;

    return generateRemittanceSummaryPdf({
      buyerName: tenant.trading_name || tenant.name,
      buyerAddress: tenantAddress,
      buyerVatNumber: tenant.vat_number,
      buyerCompanyRegNumber: tenant.company_reg_number,
      buyerPhone: tenant.phone,
      buyerEmail: tenant.email,
      supplierName: supplier.company_name,
      supplierAddress: supplierAddress,
      supplierVatNumber: supplier.vat_number || undefined,
      supplierCompanyRegNumber: supplier.company_reg_number || undefined,
      periodFrom: typeof minStart === "string" ? minStart : new Date(minStart).toISOString().split("T")[0],
      periodTo: typeof maxEnd === "string" ? maxEnd : new Date(maxEnd).toISOString().split("T")[0],
      invoices: pdfInvoices,
      totalInvoiced: String(Math.round(totalInvoiced * 100) / 100),
      totalPaid: String(Math.round(totalPaid * 100) / 100),
      outstanding: String(Math.round((totalInvoiced - totalPaid) * 100) / 100),
    });
  }

  async function generateSupplierProfilePdf(supplier: any): Promise<Buffer> {
    const PDFDocument = (await import("pdfkit")).default;
    const doc = new PDFDocument({ margin: 40, size: "A4" });
    const buffers: Buffer[] = [];
    doc.on("data", (chunk: Buffer) => buffers.push(chunk));
    const pdfReady = new Promise<Buffer>((resolve) => {
      doc.on("end", () => resolve(Buffer.concat(buffers)));
    });

    const navy = "#1F3A5F";
    const drawSection = (title: string, fields: Array<[string, string | null | undefined]>) => {
      if (doc.y > 700) doc.addPage();
      doc.fontSize(11).font("Helvetica-Bold").fillColor(navy).text(title);
      doc.moveDown(0.2);
      doc.moveTo(40, doc.y).lineTo(555, doc.y).strokeColor("#ccc").lineWidth(0.5).stroke();
      doc.moveDown(0.4);
      doc.font("Helvetica").fontSize(9).fillColor("#333");
      for (const [label, value] of fields) {
        if (doc.y > 750) doc.addPage();
        const displayVal = value || "—";
        doc.font("Helvetica-Bold").text(`${label}: `, { continued: true });
        doc.font("Helvetica").text(displayVal);
        doc.moveDown(0.15);
      }
      doc.moveDown(0.6);
    };

    doc.fontSize(16).font("Helvetica-Bold").fillColor(navy).text("Supplier Profile", { align: "center" });
    doc.fontSize(10).font("Helvetica").fillColor("#666").text(`Generated: ${new Date().toLocaleDateString("en-GB")}`, { align: "center" });
    doc.moveDown(1);

    drawSection("Company Information", [
      ["Company Name", supplier.companyName],
      ["Supplier Code", supplier.supplierCode],
      ["Status", (supplier.status || "").replace(/_/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase())],
      ["Supplier Type", supplier.supplierType === "labour" ? "Labour Supplier" : supplier.supplierType === "non_labour" ? "Non-Labour Supplier" : supplier.supplierType],
      ["Nature of Supply", supplier.natureOfSupply],
    ]);

    drawSection("Contact Details", [
      ["Contact Name", supplier.contactName],
      ["Email", supplier.email],
      ["Phone", supplier.phone],
      ["Finance Contact Name", supplier.financeContactName],
      ["Finance Contact Email", supplier.financeContactEmail],
    ]);

    const regAddr = [supplier.registeredOfficeAddress, supplier.registeredOfficeCity, supplier.registeredOfficePostcode, supplier.registeredOfficeCountry].filter(Boolean).join(", ");
    const tradAddr = supplier.tradingSameAsRegistered ? "Same as Registered Office" : [supplier.tradingAddress, supplier.tradingCity, supplier.tradingPostcode].filter(Boolean).join(", ");
    drawSection("Addresses", [
      ["Registered Office", regAddr || undefined],
      ["Trading Address", tradAddr || undefined],
    ]);

    drawSection("VAT & Registration", [
      ["VAT Status", supplier.vatStatus === "vat_registered" ? "VAT Registered" : "Not VAT Registered"],
      ["VAT Number", supplier.vatNumber],
      ["VAT Registered From", supplier.vatRegisteredFrom ? new Date(supplier.vatRegisteredFrom).toLocaleDateString("en-GB") : undefined],
      ["Default VAT Rate", supplier.defaultVatRate ? `${supplier.defaultVatRate}%` : undefined],
      ["Company Registration Number", supplier.companyRegNumber],
    ]);

    if (supplier.companyCategory || supplier.companyStatus || supplier.incorporationDate || supplier.sicCodes) {
      drawSection("Companies House Data", [
        ["Company Category", supplier.companyCategory],
        ["Company Status", supplier.companyStatus],
        ["Country of Origin", supplier.countryOfOrigin],
        ["Incorporation Date", supplier.incorporationDate ? new Date(supplier.incorporationDate).toLocaleDateString("en-GB") : undefined],
        ["SIC Codes", Array.isArray(supplier.sicCodes) ? supplier.sicCodes.join(", ") : supplier.sicCodes],
        ["Accounts Next Due", supplier.accountsNextDue ? new Date(supplier.accountsNextDue).toLocaleDateString("en-GB") : undefined],
        ["Returns Next Due", supplier.returnsNextDue ? new Date(supplier.returnsNextDue).toLocaleDateString("en-GB") : undefined],
      ]);
    }

    const maskValue = (val: string | null | undefined) => val ? val.slice(0, -4).replace(/./g, "*") + val.slice(-4) : undefined;
    drawSection("Bank Details", [
      ["Bank Name", supplier.bankName],
      ["Account Name", supplier.accountName],
      ["Sort Code", supplier.sortCode],
      ["Account Number", maskValue(supplier.accountNumber)],
    ]);

    drawSection("Self-Billing Agreement", [
      ["Agreement Status", (supplier.selfBillingAgreementStatus || "").replace(/_/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase())],
      ["Agreement Reference", supplier.selfBillingAgreementRef],
      ["Signatory Name", supplier.selfBillingSignatoryName],
      ["Signatory Position", supplier.selfBillingSignatoryPosition],
      ["Accepted At", supplier.selfBillingAcceptedAt ? new Date(supplier.selfBillingAcceptedAt).toLocaleDateString("en-GB") : undefined],
      ["Expiry Date", supplier.selfBillingExpiryDate ? new Date(supplier.selfBillingExpiryDate).toLocaleDateString("en-GB") : undefined],
    ]);

    const { rows: docSummary } = await pool.query(
      `SELECT status, COUNT(*)::int as count FROM supplier_documents WHERE supplier_id = $1 GROUP BY status`,
      [supplier.id]
    );
    const docCounts = docSummary.reduce((acc: Record<string, number>, r: any) => { acc[r.status] = r.count; return acc; }, {});
    drawSection("Document Compliance Summary", [
      ["Approved Documents", String(docCounts.approved || 0)],
      ["Pending Documents", String(docCounts.pending || 0)],
      ["Rejected Documents", String(docCounts.rejected || 0)],
      ["Total Documents", String((docCounts.approved || 0) + (docCounts.pending || 0) + (docCounts.rejected || 0))],
    ]);

    doc.end();
    return pdfReady;
  }

  app.get("/api/admin/suppliers/:supplierId/audit-pack-zip", requireRole(...hmrcAuditRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });
      const supplierId = Number(req.params.supplierId);
      const supplier = await storage.getSupplier(supplierId);
      if (!supplier || supplier.tenantId !== user.tenantId) {
        return res.status(404).json({ message: "Supplier not found" });
      }

      const includeAgreement = req.query.agreement === "true";
      const includeInvoices = req.query.invoices === "true";
      const includeAuditTrail = req.query.auditTrail === "true";
      const includeRemittance = req.query.remittance === "true";
      const includeTimesheets = req.query.timesheets === "true";
      const includeDueDiligence = req.query.dueDiligence === "true";
      const includeSupplierProfile = req.query.supplierProfile === "true";
      const dateFrom = typeof req.query.from === "string" ? req.query.from : undefined;
      const dateTo = typeof req.query.to === "string" ? req.query.to : undefined;

      if (!includeAgreement && !includeInvoices && !includeAuditTrail && !includeRemittance && !includeTimesheets && !includeDueDiligence && !includeSupplierProfile) {
        return res.status(400).json({ message: "No document types selected" });
      }

      const tenant = await storage.getTenant(user.tenantId);
      const sanitizedName = supplier.companyName.replace(/[^a-zA-Z0-9]/g, "_").replace(/_+/g, "_").replace(/^_|_$/g, "");
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
      let periodLabel = new Date().toISOString().slice(0, 10);

      let periodQuery = `SELECT MIN(period_start) as min_start, MAX(period_end) as max_end FROM invoices WHERE supplier_id = $1 AND tenant_id = $2`;
      const periodParams: any[] = [supplierId, user.tenantId];
      if (dateFrom) { periodParams.push(dateFrom); periodQuery += ` AND period_start >= $${periodParams.length}`; }
      if (dateTo) { periodParams.push(dateTo); periodQuery += ` AND period_end <= $${periodParams.length}`; }
      const { rows: periodRows } = await pool.query(periodQuery, periodParams);
      if (periodRows[0]?.min_start && periodRows[0]?.max_end) {
        const s = new Date(periodRows[0].min_start);
        const e = new Date(periodRows[0].max_end);
        periodLabel = `${monthNames[s.getMonth()]}${s.getFullYear()}-${monthNames[e.getMonth()]}${e.getFullYear()}`;
      }
      const filename = `${safeFilename(sanitizedName)}_${safeFilename(periodLabel)}.zip`;

      res.setHeader("Content-Type", "application/zip");
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);

      const archive = archiver("zip", { zlib: { level: 5 } });
      archive.on("error", (err) => {
        if (!res.headersSent) {
          res.status(500).json({ message: err.message });
        } else {
          res.end();
        }
      });
      archive.on("warning", (err) => {
        if (err.code !== "ENOENT") console.error("Archiver warning:", err);
      });
      res.on("close", () => {
        archive.abort();
      });
      archive.pipe(res);

      if (includeAgreement && supplier.selfBillingAgreementStatus === "active") {
        const adminAgreementTemplate = await storage.getDefaultTemplate(user.tenantId, "self_billing_agreement");
        const adminBuyerAddress = [tenant?.addressLine1, tenant?.addressLine2, tenant?.city, tenant?.county, tenant?.postcode].filter(Boolean).join(", ");
        const agreementPdf = await generateSelfBillingAgreementPdf({
          agreementRef: supplier.selfBillingAgreementRef || `SBA-${supplier.id}`,
          buyerName: tenant?.name || "Company",
          buyerAddress: adminBuyerAddress || undefined,
          buyerVatNumber: tenant?.vatNumber || undefined,
          buyerCompanyRegNumber: tenant?.companyRegNumber || undefined,
          supplierName: supplier.companyName,
          supplierAddress: supplier.agreementRegisteredAddress
            ? buildSupplierAddress(supplier.agreementRegisteredAddress, supplier.agreementRegisteredCity, supplier.agreementRegisteredPostcode)
            : buildSupplierAddress(supplier.address, supplier.city, supplier.postcode),
          supplierVatNumber: supplier.vatNumber || undefined,
          supplierCompanyRegNumber: supplier.companyRegNumber || undefined,
          signatoryName: supplier.selfBillingSignatoryName || "N/A",
          signatoryPosition: supplier.selfBillingSignatoryPosition || "N/A",
          signedDate: supplier.selfBillingAcceptedAt ? new Date(supplier.selfBillingAcceptedAt).toISOString() : undefined,
          expiryDate: supplier.selfBillingExpiryDate ? new Date(supplier.selfBillingExpiryDate).toISOString() : undefined,
          signatureImage: supplier.selfBillingSignatureData || undefined,
          signedIp: supplier.selfBillingSignedIp || undefined,
          signedTimestamp: supplier.selfBillingAcceptedAt ? new Date(supplier.selfBillingAcceptedAt).toISOString() : undefined,
          buyerSignatoryName: tenant?.selfBillingSignatoryName || undefined,
          buyerSignatoryPosition: tenant?.selfBillingSignatoryPosition || undefined,
          buyerSignatureImage: tenant?.selfBillingSignatureData || undefined,
          buyerSignatureDate: tenant?.selfBillingSignatureDate ? new Date(tenant.selfBillingSignatureDate).toISOString() : undefined,
        }, adminAgreementTemplate || null);
        archive.append(agreementPdf, { name: `agreement-${supplier.selfBillingAgreementRef || supplier.supplierCode || supplier.id}.pdf` });
      }

      if (includeInvoices) {
        let allInvoices = await storage.getInvoicesBySupplierId(supplierId);
        if (dateFrom) allInvoices = allInvoices.filter(inv => inv.periodStart >= dateFrom);
        if (dateTo) allInvoices = allInvoices.filter(inv => inv.periodEnd <= dateTo);
        const invoiceTemplate = await storage.getDefaultTemplate(user.tenantId, "self_billing_invoice");
        const buyerAddress = tenant ? [tenant.addressLine1, tenant.addressLine2, tenant.city, tenant.county, tenant.postcode].filter(Boolean).join(", ") : undefined;

        const allInvoiceIds = allInvoices.map(inv => inv.id);
        let allLineItemsByInvoice: Record<number, any[]> = {};
        let allShiftsById: Record<number, any> = {};
        let allSitesById: Record<number, any> = {};
        let allEmployeesById: Record<number, any> = {};

        if (allInvoiceIds.length > 0) {
          const { rows: allLiRows } = await pool.query(
            `SELECT * FROM invoice_line_items WHERE invoice_id = ANY($1) ORDER BY invoice_id, id`,
            [allInvoiceIds]
          );
          for (const li of allLiRows) {
            if (!allLineItemsByInvoice[li.invoice_id]) allLineItemsByInvoice[li.invoice_id] = [];
            allLineItemsByInvoice[li.invoice_id].push(li);
          }

          const shiftIds = [...new Set(allLiRows.filter(li => li.shift_id).map(li => li.shift_id))];
          if (shiftIds.length > 0) {
            const { rows: shiftRows } = await pool.query(
              `SELECT * FROM shifts WHERE id = ANY($1)`,
              [shiftIds]
            );
            for (const s of shiftRows) allShiftsById[s.id] = s;

            const siteIds = [...new Set(shiftRows.filter(s => s.site_id).map(s => s.site_id))];
            if (siteIds.length > 0) {
              const { rows: siteRows } = await pool.query(
                `SELECT * FROM sites WHERE id = ANY($1)`,
                [siteIds]
              );
              for (const s of siteRows) allSitesById[s.id] = s;
            }

            const empIds = [...new Set(shiftRows.filter(s => s.employee_id).map(s => s.employee_id))];
            if (empIds.length > 0) {
              const { rows: empRows } = await pool.query(
                `SELECT * FROM employees WHERE id = ANY($1)`,
                [empIds]
              );
              for (const e of empRows) allEmployeesById[e.id] = e;
            }
          }
        }

        for (const invoice of allInvoices) {
          const supplierAddr = getSupplierAddressForPeriod(supplier, invoice.periodEnd);
          const lineItems = allLineItemsByInvoice[invoice.id] || [];
          const timesheetItems: Array<{ date: string; siteName: string; hours: string; rate: string; amount: string; officerName?: string; startTime?: string; endTime?: string }> = [];
          for (const li of lineItems) {
            if (li.shift_id) {
              const shift = allShiftsById[li.shift_id];
              const site = shift?.site_id ? allSitesById[shift.site_id] : null;
              const emp = shift?.employee_id ? allEmployeesById[shift.employee_id] : null;
              timesheetItems.push({
                date: shift?.date || "",
                siteName: site?.name || shift?.title || "—",
                hours: li.hours,
                rate: li.rate,
                amount: li.subtotal,
                officerName: emp ? `${emp.first_name || ""} ${emp.last_name || ""}`.trim() || undefined : undefined,
                startTime: shift?.start_time || undefined,
                endTime: shift?.end_time || undefined,
              });
            }
          }
          let singleRemitItems: Array<{ date: string; description: string; amount: string; type: string }> | undefined;
          if (invoiceTemplate?.invoiceFormat === "with_remittance" || invoiceTemplate?.invoiceFormat === "summary_with_remittance") {
            const { rows: sAllocRows } = await pool.query(
              `SELECT bt.transaction_date::text as d, bt.description, bta.amount::numeric(12,2) as amt
               FROM bank_transaction_allocations bta
               JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
               WHERE bta.invoice_id = $1 ORDER BY bt.transaction_date`,
              [invoice.id]
            );
            if (sAllocRows.length > 0) {
              singleRemitItems = sAllocRows.map((r: any) => ({
                date: r.d, description: (r.description || "").trim(), amount: r.amt,
                type: (r.description || "").includes("FT") ? "FT" : (r.description || "").includes("BBP") ? "BBP" : "OTHER",
              }));
            }
          }

          const singleInvData = {
            invoiceNumber: invoice.invoiceNumber,
            invoiceDate: (invoice.issuedAt || invoice.generatedAt || invoice.createdAt || new Date()).toISOString(),
            taxPointDate: invoice.periodEnd,
            periodStart: invoice.periodStart,
            periodEnd: invoice.periodEnd,
            status: invoice.status || "draft",
            buyerName: tenant?.name || "Gardeo Platform",
            buyerAddress,
            buyerVatNumber: tenant?.vatNumber || undefined,
            buyerCompanyRegNumber: tenant?.companyRegNumber || undefined,
            buyerPhone: tenant?.phone || undefined,
            buyerEmail: tenant?.email || undefined,
            supplierName: supplier.companyName,
            supplierAddress: supplierAddr || undefined,
            supplierVatNumber: supplier.vatNumber || undefined,
            supplierCompanyRegNumber: supplier.companyRegNumber || undefined,
            supplierPhone: supplier.phone || undefined,
            supplierEmail: supplier.email || undefined,
            supplierVatRegistered: supplier.vatStatus === "vat_registered",
            supplierBankName: supplier.bankName || undefined,
            supplierAccountName: supplier.accountName || undefined,
            supplierSortCode: supplier.sortCode || undefined,
            supplierAccountNumber: supplier.accountNumber || undefined,
            selfBillingAgreementRef: supplier.selfBillingAgreementRef || undefined,
            lineItems: lineItems.map((li: any) => ({
              description: li.description, hours: li.hours, rate: li.rate, subtotal: li.subtotal,
              vatRate: li.vat_rate, vatAmount: li.vat_amount, lineTotal: li.line_total,
            })),
            timesheetItems: timesheetItems.length > 0 ? timesheetItems : undefined,
            remittanceItems: singleRemitItems,
            subtotal: invoice.subtotal,
            vatRate: invoice.vatRate || "0",
            vatAmount: invoice.vatAmount,
            totalAmount: invoice.totalAmount,
            issuedAt: (invoice as any).issuedAt?.toISOString(),
            acceptedAt: (invoice as any).acceptedAt?.toISOString(),
            paidAt: invoice.paidAt?.toISOString(),
            dueDate: invoice.dueDate || undefined,
            currency: "GBP (£)",
            notes: invoice.notes || undefined,
          };

          const invoicePdf = await generateInvoicePdf(singleInvData, invoiceTemplate || null);
          archive.append(invoicePdf, { name: `invoice-${invoice.invoiceNumber || invoice.id}.pdf` });
        }
      }

      if (includeAuditTrail) {
        const events = await storage.getSupplierAuditEvents(supplierId, { limit: 1000 });
        const PDFDocument = (await import("pdfkit")).default;
        const doc = new PDFDocument({ margin: 40, size: "A4", layout: "landscape" });
        const buffers: Buffer[] = [];
        doc.on("data", (chunk: Buffer) => buffers.push(chunk));
        const pdfReady = new Promise<Buffer>((resolve) => {
          doc.on("end", () => resolve(Buffer.concat(buffers)));
        });
        doc.fontSize(14).font("Helvetica-Bold").text(`Audit Trail — ${supplier.companyName}`, { align: "center" });
        doc.fontSize(9).font("Helvetica").text(`Supplier Code: ${supplier.supplierCode || supplier.id}  |  Generated: ${new Date().toLocaleDateString("en-GB")}  |  Total Events: ${events.length}`, { align: "center" });
        doc.moveDown(0.8);
        const colX = [40, 130, 260, 440, 620, 700];
        const colW = [88, 128, 178, 178, 78, 108];
        const headers = ["Date", "Event Type", "Summary", "Details", "IP Address", "Actor"];
        doc.fontSize(8).font("Helvetica-Bold").fillColor("#1F3A5F");
        headers.forEach((h, i) => doc.text(h, colX[i], doc.y, { width: colW[i], continued: i < headers.length - 1 }));
        doc.text("", 40);
        doc.moveDown(0.3);
        doc.moveTo(40, doc.y).lineTo(800, doc.y).strokeColor("#ccc").lineWidth(0.5).stroke();
        doc.moveDown(0.3);
        doc.font("Helvetica").fontSize(7).fillColor("#333");
        for (const ev of events) {
          if (doc.y > 520) {
            doc.addPage({ layout: "landscape" });
            doc.fontSize(8).font("Helvetica-Bold").fillColor("#1F3A5F");
            headers.forEach((h, i) => doc.text(h, colX[i], doc.y, { width: colW[i], continued: i < headers.length - 1 }));
            doc.text("", 40);
            doc.moveDown(0.3);
            doc.moveTo(40, doc.y).lineTo(800, doc.y).strokeColor("#ccc").lineWidth(0.5).stroke();
            doc.moveDown(0.3);
            doc.font("Helvetica").fontSize(7).fillColor("#333");
          }
          const rowY = doc.y;
          const evDateStr = ev.createdAt ? new Date(ev.createdAt).toLocaleDateString("en-GB") + " " + new Date(ev.createdAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }) : "—";
          const eventType = (ev.eventType || "").replace(/_/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase());
          const summary = ev.summary || "—";
          const details = ev.entityType ? `${ev.entityType}: ${ev.entityId || ""}` : "—";
          doc.text(evDateStr, colX[0], rowY, { width: colW[0] });
          doc.text(eventType, colX[1], rowY, { width: colW[1] });
          doc.text(summary, colX[2], rowY, { width: colW[2] });
          doc.text(details, colX[3], rowY, { width: colW[3] });
          doc.text(ev.ipAddress || "—", colX[4], rowY, { width: colW[4] });
          doc.text(ev.actorName || "System", colX[5], rowY, { width: colW[5] });
          const maxH = Math.max(doc.y - rowY, 12);
          doc.y = rowY + maxH + 3;
        }
        doc.end();
        const auditPdf = await pdfReady;
        archive.append(auditPdf, { name: `audit-trail-${supplier.supplierCode || supplier.id}.pdf` });
      }

      if (includeRemittance) {
        const remittancePdf = await buildRemittanceSummaryForAuditPack(user.tenantId, supplierId, dateFrom, dateTo);
        if (remittancePdf) {
          archive.append(remittancePdf, { name: `remittance-summary-${supplier.supplierCode || supplier.id}.pdf` });
        }
      }

      if (includeTimesheets) {
        let tsInvoices = await storage.getInvoicesBySupplierId(supplierId);
        if (dateFrom) tsInvoices = tsInvoices.filter(inv => inv.periodStart >= dateFrom);
        if (dateTo) tsInvoices = tsInvoices.filter(inv => inv.periodEnd <= dateTo);
        const tsInvIds = tsInvoices.map(inv => inv.id);
        if (tsInvIds.length > 0) {
          const { rows: tsLiRows } = await pool.query(
            `SELECT * FROM invoice_line_items WHERE invoice_id = ANY($1) ORDER BY invoice_id, id`,
            [tsInvIds]
          );
          const tsLiByInvoice: Record<number, any[]> = {};
          for (const li of tsLiRows) {
            if (!tsLiByInvoice[li.invoice_id]) tsLiByInvoice[li.invoice_id] = [];
            tsLiByInvoice[li.invoice_id].push(li);
          }
          const tsShiftIds = [...new Set(tsLiRows.filter(li => li.shift_id).map(li => li.shift_id))];
          let tsShiftsById: Record<number, any> = {};
          let tsSitesById: Record<number, any> = {};
          let tsEmployeesById: Record<number, any> = {};
          if (tsShiftIds.length > 0) {
            const { rows: shiftRows } = await pool.query(`SELECT * FROM shifts WHERE id = ANY($1)`, [tsShiftIds]);
            for (const s of shiftRows) tsShiftsById[s.id] = s;
            const tsSiteIds = [...new Set(shiftRows.filter(s => s.site_id).map(s => s.site_id))];
            if (tsSiteIds.length > 0) {
              const { rows: siteRows } = await pool.query(`SELECT * FROM sites WHERE id = ANY($1)`, [tsSiteIds]);
              for (const s of siteRows) tsSitesById[s.id] = s;
            }
            const tsEmpIds = [...new Set(shiftRows.filter(s => s.employee_id).map(s => s.employee_id))];
            if (tsEmpIds.length > 0) {
              const { rows: empRows } = await pool.query(`SELECT * FROM employees WHERE id = ANY($1)`, [tsEmpIds]);
              for (const e of empRows) tsEmployeesById[e.id] = e;
            }
          }
          const singleTsTemplate = await storage.getDefaultTemplate(user.tenantId, "timesheet");

          for (const invoice of tsInvoices) {
            const lineItems = tsLiByInvoice[invoice.id] || [];
            const timesheetItems: Array<{ date: string; siteName: string; hours: string; rate: string; amount: string; officerName?: string; startTime?: string; endTime?: string }> = [];
            for (const li of lineItems) {
              if (li.shift_id) {
                const shift = tsShiftsById[li.shift_id];
                const site = shift?.site_id ? tsSitesById[shift.site_id] : null;
                const emp = shift?.employee_id ? tsEmployeesById[shift.employee_id] : null;
                timesheetItems.push({ date: shift?.date || "", siteName: site?.name || shift?.title || "—", hours: li.hours, rate: li.rate, amount: li.subtotal, officerName: emp ? `${emp.first_name || ""} ${emp.last_name || ""}`.trim() || undefined : undefined, startTime: shift?.start_time || undefined, endTime: shift?.end_time || undefined });
              }
            }
            if (timesheetItems.length > 0) {
              const tsPdf = await generateTimesheetPdf({
                invoiceNumber: invoice.invoiceNumber,
                periodStart: invoice.periodStart,
                periodEnd: invoice.periodEnd,
                supplierName: supplier.companyName,
                timesheetItems,
                format: (singleTsTemplate?.invoiceFormat as any) || "without_officer",
              });
              archive.append(tsPdf, { name: `timesheet-${invoice.invoiceNumber || invoice.id}.pdf` });
            }
          }
        }
      }

      if (includeSupplierProfile) {
        const profilePdf = await generateSupplierProfilePdf(supplier);
        archive.append(profilePdf, { name: `supplier-profile-${supplier.supplierCode || supplier.id}.pdf` });
      }

      if (includeDueDiligence) {
        const { rows: docs } = await pool.query(
          `SELECT DISTINCT ON (document_type) id, document_type, file_name, file_url, mime_type, status
           FROM supplier_documents WHERE supplier_id = $1
           ORDER BY document_type, created_at DESC, id DESC`,
          [supplierId]
        );
        const localUploadsDir = path.join(process.cwd(), "uploads");
        for (const doc of docs) {
          try {
            const fileUrl = doc.file_url || "";
            const objectPath = fileUrl.startsWith("/objects/") ? fileUrl : fileUrl.replace(/^.*?(\/objects\/)/, "$1");
            if (!objectPath.startsWith("/objects/")) continue;
            const localFileName = objectPath.replace(/^\/objects\/uploads\//, "");
            const localFilePath = path.join(localUploadsDir, localFileName);
            let fileContents: Buffer;
            if (fs.existsSync(localFilePath)) {
              fileContents = fs.readFileSync(localFilePath);
            } else {
              const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
              const objService = new ObjectStorageService();
              const objectFile = await objService.getObjectEntityFile(objectPath);
              const [downloaded] = await objectFile.download();
              fileContents = downloaded;
            }
            const docTypeLabel = (doc.document_type || "other").replace(/_/g, "-");
            const safeFileName = (doc.file_name || `${docTypeLabel}.pdf`).replace(/[^a-zA-Z0-9._-]/g, "_");
            archive.append(fileContents, { name: `due-diligence/${docTypeLabel}-${safeFileName}` });
          } catch (ddErr: any) {
            console.error(`Failed to fetch due diligence doc ${doc.id}: ${ddErr.message}`);
          }
        }
      }

      await archive.finalize();
    } catch (err: any) {
      if (!res.headersSent) {
        res.status(500).json({ message: err.message });
      }
    }
  });

  const bulkAuditPackSchema = z.object({
    suppliers: z.array(z.object({
      id: z.number().int().positive(),
      agreement: z.boolean(),
      invoices: z.boolean(),
      remittance: z.boolean().optional(),
      auditTrail: z.boolean(),
      timesheets: z.boolean().optional(),
      dueDiligence: z.boolean().optional(),
      supplierProfile: z.boolean().optional(),
    })).min(1).max(200),
    from: z.string().optional(),
    to: z.string().optional(),
  });

  app.post("/api/admin/suppliers/bulk-audit-pack-zip", requireRole(...hmrcAuditRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });
      const parsed = bulkAuditPackSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid request body", errors: parsed.error.flatten() });
      }
      const { suppliers: supplierRequests, from: dateFrom, to: dateTo } = parsed.data;

      const tenant = await storage.getTenant(user.tenantId);
      const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

      res.setHeader("Content-Type", "application/zip");
      res.setHeader("Content-Disposition", `attachment; filename="Audit_Pack.zip"`);

      const archive = archiver("zip", { zlib: { level: 5 } });
      archive.on("error", (err) => {
        if (!res.headersSent) res.status(500).json({ message: err.message });
        else res.end();
      });
      archive.on("warning", (err) => {
        if (err.code !== "ENOENT") console.error("Archiver warning:", err);
      });
      res.on("close", () => { archive.abort(); });
      archive.pipe(res);

      for (const sr of supplierRequests) {
        const supplierId = Number(sr.id);
        const supplier = await storage.getSupplier(supplierId);
        if (!supplier || supplier.tenantId !== user.tenantId) continue;

        const includeAgreement = !!sr.agreement;
        const includeInvoices = !!sr.invoices;
        const includeAuditTrail = !!sr.auditTrail;
        const includeRemittance = !!sr.remittance;
        const includeTimesheets = !!(sr as any).timesheets;
        const includeDueDiligence = !!(sr as any).dueDiligence;
        const includeSupplierProfile = !!(sr as any).supplierProfile;
        if (!includeAgreement && !includeInvoices && !includeAuditTrail && !includeRemittance && !includeTimesheets && !includeDueDiligence && !includeSupplierProfile) continue;

        const sanitizedName = supplier.companyName.replace(/[^a-zA-Z0-9]/g, "_").replace(/_+/g, "_").replace(/^_|_$/g, "");
        const code = supplier.supplierCode || `SUP-${supplierId}`;
        const vatPrefix = supplier.vatStatus === "vat_registered" ? "VAT_Registered" : "Non_VAT_Registered";
        let periodLabel = "";
        let bulkPeriodQuery = `SELECT MIN(period_start) as min_start, MAX(period_end) as max_end FROM invoices WHERE supplier_id = $1 AND tenant_id = $2`;
        const bulkPeriodParams: any[] = [supplierId, user.tenantId];
        if (dateFrom) { bulkPeriodParams.push(dateFrom); bulkPeriodQuery += ` AND period_start >= $${bulkPeriodParams.length}`; }
        if (dateTo) { bulkPeriodParams.push(dateTo); bulkPeriodQuery += ` AND period_end <= $${bulkPeriodParams.length}`; }
        const { rows: periodRows } = await pool.query(bulkPeriodQuery, bulkPeriodParams);
        if (periodRows[0]?.min_start && periodRows[0]?.max_end) {
          const s = new Date(periodRows[0].min_start);
          const e = new Date(periodRows[0].max_end);
          periodLabel = `_${monthNames[s.getMonth()]}${s.getFullYear()}-${monthNames[e.getMonth()]}${e.getFullYear()}`;
        }
        const folderName = `${vatPrefix}/${sanitizedName}${periodLabel}`;

        if (includeAgreement && supplier.selfBillingAgreementStatus === "active") {
          const adminAgreementTemplate = await storage.getDefaultTemplate(user.tenantId, "self_billing_agreement");
          const adminBuyerAddress = [tenant?.addressLine1, tenant?.addressLine2, tenant?.city, tenant?.county, tenant?.postcode].filter(Boolean).join(", ");
          const agreementPdf = await generateSelfBillingAgreementPdf({
            agreementRef: supplier.selfBillingAgreementRef || `SBA-${supplier.id}`,
            buyerName: tenant?.name || "Company",
            buyerAddress: adminBuyerAddress || undefined,
            buyerVatNumber: tenant?.vatNumber || undefined,
            buyerCompanyRegNumber: tenant?.companyRegNumber || undefined,
            supplierName: supplier.companyName,
            supplierAddress: supplier.agreementRegisteredAddress
              ? buildSupplierAddress(supplier.agreementRegisteredAddress, supplier.agreementRegisteredCity, supplier.agreementRegisteredPostcode)
              : buildSupplierAddress(supplier.address, supplier.city, supplier.postcode),
            supplierVatNumber: supplier.vatNumber || undefined,
            supplierCompanyRegNumber: supplier.companyRegNumber || undefined,
            signatoryName: supplier.selfBillingSignatoryName || "N/A",
            signatoryPosition: supplier.selfBillingSignatoryPosition || "N/A",
            signedDate: supplier.selfBillingAcceptedAt ? new Date(supplier.selfBillingAcceptedAt).toISOString() : undefined,
            expiryDate: supplier.selfBillingExpiryDate ? new Date(supplier.selfBillingExpiryDate).toISOString() : undefined,
            signatureImage: supplier.selfBillingSignatureData || undefined,
            signedIp: supplier.selfBillingSignedIp || undefined,
            signedTimestamp: supplier.selfBillingAcceptedAt ? new Date(supplier.selfBillingAcceptedAt).toISOString() : undefined,
            buyerSignatoryName: tenant?.selfBillingSignatoryName || undefined,
            buyerSignatoryPosition: tenant?.selfBillingSignatoryPosition || undefined,
            buyerSignatureImage: tenant?.selfBillingSignatureData || undefined,
            buyerSignatureDate: tenant?.selfBillingSignatureDate ? new Date(tenant.selfBillingSignatureDate).toISOString() : undefined,
          }, adminAgreementTemplate || null);
          archive.append(agreementPdf, { name: `${folderName}/agreement-${supplier.selfBillingAgreementRef || supplier.supplierCode || supplier.id}.pdf` });
        }

        if (includeInvoices) {
          let invoices = await storage.getInvoicesBySupplierId(supplierId);
          if (dateFrom) invoices = invoices.filter(inv => inv.periodStart >= dateFrom);
          if (dateTo) invoices = invoices.filter(inv => inv.periodEnd <= dateTo);
          const invoiceTemplate = await storage.getDefaultTemplate(user.tenantId, "self_billing_invoice");
          const buyerAddress = tenant ? [tenant.addressLine1, tenant.addressLine2, tenant.city, tenant.county, tenant.postcode].filter(Boolean).join(", ") : undefined;

          const bulkInvIds = invoices.map(inv => inv.id);
          let bulkLiByInvoice: Record<number, any[]> = {};
          let bulkShiftsById: Record<number, any> = {};
          let bulkSitesById: Record<number, any> = {};
          let bulkEmployeesById: Record<number, any> = {};

          if (bulkInvIds.length > 0) {
            const { rows: bulkLiRows } = await pool.query(
              `SELECT * FROM invoice_line_items WHERE invoice_id = ANY($1) ORDER BY invoice_id, id`,
              [bulkInvIds]
            );
            for (const li of bulkLiRows) {
              if (!bulkLiByInvoice[li.invoice_id]) bulkLiByInvoice[li.invoice_id] = [];
              bulkLiByInvoice[li.invoice_id].push(li);
            }

            const bulkShiftIds = [...new Set(bulkLiRows.filter(li => li.shift_id).map(li => li.shift_id))];
            if (bulkShiftIds.length > 0) {
              const { rows: shiftRows } = await pool.query(
                `SELECT * FROM shifts WHERE id = ANY($1)`,
                [bulkShiftIds]
              );
              for (const s of shiftRows) bulkShiftsById[s.id] = s;

              const bulkSiteIds = [...new Set(shiftRows.filter(s => s.site_id).map(s => s.site_id))];
              if (bulkSiteIds.length > 0) {
                const { rows: siteRows } = await pool.query(
                  `SELECT * FROM sites WHERE id = ANY($1)`,
                  [bulkSiteIds]
                );
                for (const s of siteRows) bulkSitesById[s.id] = s;
              }

              const bulkEmpIds = [...new Set(shiftRows.filter(s => s.employee_id).map(s => s.employee_id))];
              if (bulkEmpIds.length > 0) {
                const { rows: empRows } = await pool.query(
                  `SELECT * FROM employees WHERE id = ANY($1)`,
                  [bulkEmpIds]
                );
                for (const e of empRows) bulkEmployeesById[e.id] = e;
              }
            }
          }

          for (const invoice of invoices) {
            const supplierAddr = getSupplierAddressForPeriod(supplier, invoice.periodEnd);
            const lineItems = bulkLiByInvoice[invoice.id] || [];
            const timesheetItems: Array<{ date: string; siteName: string; hours: string; rate: string; amount: string; officerName?: string; startTime?: string; endTime?: string }> = [];
            for (const li of lineItems) {
              if (li.shift_id) {
                const shift = bulkShiftsById[li.shift_id];
                const site = shift?.site_id ? bulkSitesById[shift.site_id] : null;
                const emp = shift?.employee_id ? bulkEmployeesById[shift.employee_id] : null;
                timesheetItems.push({ date: shift?.date || "", siteName: site?.name || shift?.title || "—", hours: li.hours, rate: li.rate, amount: li.subtotal, officerName: emp ? `${emp.first_name || ""} ${emp.last_name || ""}`.trim() || undefined : undefined, startTime: shift?.start_time || undefined, endTime: shift?.end_time || undefined });
              }
            }
            let bulkRemitItems: Array<{ date: string; description: string; amount: string; type: string }> | undefined;
            if (invoiceTemplate?.invoiceFormat === "with_remittance" || invoiceTemplate?.invoiceFormat === "summary_with_remittance") {
              const { rows: bAllocRows } = await pool.query(
                `SELECT bt.transaction_date::text as d, bt.description, bta.amount::numeric(12,2) as amt
                 FROM bank_transaction_allocations bta
                 JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
                 WHERE bta.invoice_id = $1 ORDER BY bt.transaction_date`,
                [invoice.id]
              );
              if (bAllocRows.length > 0) {
                bulkRemitItems = bAllocRows.map((r: any) => ({
                  date: r.d, description: (r.description || "").trim(), amount: r.amt,
                  type: (r.description || "").includes("FT") ? "FT" : (r.description || "").includes("BBP") ? "BBP" : "OTHER",
                }));
              }
            }

            const bulkInvData = {
              invoiceNumber: invoice.invoiceNumber,
              invoiceDate: (invoice.issuedAt || invoice.generatedAt || invoice.createdAt || new Date()).toISOString(),
              taxPointDate: invoice.periodEnd,
              periodStart: invoice.periodStart,
              periodEnd: invoice.periodEnd,
              status: invoice.status || "draft",
              buyerName: tenant?.name || "Gardeo Platform",
              buyerAddress,
              buyerVatNumber: tenant?.vatNumber || undefined,
              buyerCompanyRegNumber: tenant?.companyRegNumber || undefined,
              buyerPhone: tenant?.phone || undefined,
              buyerEmail: tenant?.email || undefined,
              supplierName: supplier.companyName,
              supplierAddress: supplierAddr || undefined,
              supplierVatNumber: supplier.vatNumber || undefined,
              supplierCompanyRegNumber: supplier.companyRegNumber || undefined,
              supplierPhone: supplier.phone || undefined,
              supplierEmail: supplier.email || undefined,
              supplierVatRegistered: supplier.vatStatus === "vat_registered",
              supplierBankName: supplier.bankName || undefined,
              supplierAccountName: supplier.accountName || undefined,
              supplierSortCode: supplier.sortCode || undefined,
              supplierAccountNumber: supplier.accountNumber || undefined,
              selfBillingAgreementRef: supplier.selfBillingAgreementRef || undefined,
              lineItems: lineItems.map((li: any) => ({
                description: li.description, hours: li.hours, rate: li.rate, subtotal: li.subtotal,
                vatRate: li.vat_rate, vatAmount: li.vat_amount, lineTotal: li.line_total,
              })),
              timesheetItems: timesheetItems.length > 0 ? timesheetItems : undefined,
              remittanceItems: bulkRemitItems,
              subtotal: invoice.subtotal,
              vatRate: invoice.vatRate || "0",
              vatAmount: invoice.vatAmount,
              totalAmount: invoice.totalAmount,
              issuedAt: (invoice as any).issuedAt?.toISOString(),
              acceptedAt: (invoice as any).acceptedAt?.toISOString(),
              paidAt: invoice.paidAt?.toISOString(),
              dueDate: invoice.dueDate || undefined,
              currency: "GBP (£)",
              notes: invoice.notes || undefined,
            };

            const invoicePdf = await generateInvoicePdf(bulkInvData, invoiceTemplate || null);
            archive.append(invoicePdf, { name: `${folderName}/invoice-${invoice.invoiceNumber || invoice.id}.pdf` });
          }
        }

        if (includeAuditTrail) {
          const events = await storage.getSupplierAuditEvents(supplierId, { limit: 1000 });
          const PDFDocument = (await import("pdfkit")).default;
          const doc = new PDFDocument({ margin: 40, size: "A4", layout: "landscape" });
          const buffers: Buffer[] = [];
          doc.on("data", (chunk: Buffer) => buffers.push(chunk));
          const pdfReady = new Promise<Buffer>((resolve) => {
            doc.on("end", () => resolve(Buffer.concat(buffers)));
          });
          doc.fontSize(14).font("Helvetica-Bold").text(`Audit Trail — ${supplier.companyName}`, { align: "center" });
          doc.fontSize(9).font("Helvetica").text(`Supplier Code: ${supplier.supplierCode || supplier.id}  |  Generated: ${new Date().toLocaleDateString("en-GB")}  |  Total Events: ${events.length}`, { align: "center" });
          doc.moveDown(0.8);
          const colX = [40, 130, 260, 440, 620, 700];
          const colW = [88, 128, 178, 178, 78, 108];
          const headers = ["Date", "Event Type", "Summary", "Details", "IP Address", "Actor"];
          doc.fontSize(8).font("Helvetica-Bold").fillColor("#1F3A5F");
          headers.forEach((h, i) => doc.text(h, colX[i], doc.y, { width: colW[i], continued: i < headers.length - 1 }));
          doc.text("", 40);
          doc.moveDown(0.3);
          doc.moveTo(40, doc.y).lineTo(800, doc.y).strokeColor("#ccc").lineWidth(0.5).stroke();
          doc.moveDown(0.3);
          doc.font("Helvetica").fontSize(7).fillColor("#333");
          for (const ev of events) {
            if (doc.y > 520) {
              doc.addPage({ layout: "landscape" });
              doc.fontSize(8).font("Helvetica-Bold").fillColor("#1F3A5F");
              headers.forEach((h, i) => doc.text(h, colX[i], doc.y, { width: colW[i], continued: i < headers.length - 1 }));
              doc.text("", 40);
              doc.moveDown(0.3);
              doc.moveTo(40, doc.y).lineTo(800, doc.y).strokeColor("#ccc").lineWidth(0.5).stroke();
              doc.moveDown(0.3);
              doc.font("Helvetica").fontSize(7).fillColor("#333");
            }
            const rowY = doc.y;
            const evDateStr = ev.createdAt ? new Date(ev.createdAt).toLocaleDateString("en-GB") + " " + new Date(ev.createdAt).toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" }) : "—";
            const eventType = (ev.eventType || "").replace(/_/g, " ").replace(/\b\w/g, (c: string) => c.toUpperCase());
            const summary = ev.summary || "—";
            const details = ev.entityType ? `${ev.entityType}: ${ev.entityId || ""}` : "—";
            doc.text(evDateStr, colX[0], rowY, { width: colW[0] });
            doc.text(eventType, colX[1], rowY, { width: colW[1] });
            doc.text(summary, colX[2], rowY, { width: colW[2] });
            doc.text(details, colX[3], rowY, { width: colW[3] });
            doc.text(ev.ipAddress || "—", colX[4], rowY, { width: colW[4] });
            doc.text(ev.actorName || "System", colX[5], rowY, { width: colW[5] });
            const maxH = Math.max(doc.y - rowY, 12);
            doc.y = rowY + maxH + 3;
          }
          doc.end();
          const auditPdf = await pdfReady;
          archive.append(auditPdf, { name: `${folderName}/audit-trail-${supplier.supplierCode || supplier.id}.pdf` });
        }

        if (includeRemittance) {
          const remittancePdf = await buildRemittanceSummaryForAuditPack(user.tenantId, supplierId, dateFrom, dateTo);
          if (remittancePdf) {
            archive.append(remittancePdf, { name: `${folderName}/remittance-summary-${supplier.supplierCode || supplier.id}.pdf` });
          }
        }

        if (includeTimesheets) {
          let tsInvoices = await storage.getInvoicesBySupplierId(supplierId);
          if (dateFrom) tsInvoices = tsInvoices.filter(inv => inv.periodStart >= dateFrom);
          if (dateTo) tsInvoices = tsInvoices.filter(inv => inv.periodEnd <= dateTo);
          const tsInvIds = tsInvoices.map(inv => inv.id);
          if (tsInvIds.length > 0) {
            const { rows: tsLiRows } = await pool.query(
              `SELECT * FROM invoice_line_items WHERE invoice_id = ANY($1) ORDER BY invoice_id, id`,
              [tsInvIds]
            );
            const tsLiByInvoice: Record<number, any[]> = {};
            for (const li of tsLiRows) {
              if (!tsLiByInvoice[li.invoice_id]) tsLiByInvoice[li.invoice_id] = [];
              tsLiByInvoice[li.invoice_id].push(li);
            }
            const tsShiftIds = [...new Set(tsLiRows.filter(li => li.shift_id).map(li => li.shift_id))];
            let tsShiftsById: Record<number, any> = {};
            let tsSitesById: Record<number, any> = {};
            let tsEmployeesById2: Record<number, any> = {};
            if (tsShiftIds.length > 0) {
              const { rows: shiftRows } = await pool.query(`SELECT * FROM shifts WHERE id = ANY($1)`, [tsShiftIds]);
              for (const s of shiftRows) tsShiftsById[s.id] = s;
              const tsSiteIds = [...new Set(shiftRows.filter(s => s.site_id).map(s => s.site_id))];
              if (tsSiteIds.length > 0) {
                const { rows: siteRows } = await pool.query(`SELECT * FROM sites WHERE id = ANY($1)`, [tsSiteIds]);
                for (const s of siteRows) tsSitesById[s.id] = s;
              }
              const tsEmpIds2 = [...new Set(shiftRows.filter(s => s.employee_id).map(s => s.employee_id))];
              if (tsEmpIds2.length > 0) {
                const { rows: empRows } = await pool.query(`SELECT * FROM employees WHERE id = ANY($1)`, [tsEmpIds2]);
                for (const e of empRows) tsEmployeesById2[e.id] = e;
              }
            }
            const bulkTsTemplate = await storage.getDefaultTemplate(user.tenantId, "timesheet");

            for (const invoice of tsInvoices) {
              const lineItems = tsLiByInvoice[invoice.id] || [];
              const timesheetItems: Array<{ date: string; siteName: string; hours: string; rate: string; amount: string; officerName?: string; startTime?: string; endTime?: string }> = [];
              for (const li of lineItems) {
                if (li.shift_id) {
                  const shift = tsShiftsById[li.shift_id];
                  const site = shift?.site_id ? tsSitesById[shift.site_id] : null;
                  const emp = shift?.employee_id ? tsEmployeesById2[shift.employee_id] : null;
                  timesheetItems.push({ date: shift?.date || "", siteName: site?.name || shift?.title || "—", hours: li.hours, rate: li.rate, amount: li.subtotal, officerName: emp ? `${emp.first_name || ""} ${emp.last_name || ""}`.trim() || undefined : undefined, startTime: shift?.start_time || undefined, endTime: shift?.end_time || undefined });
                }
              }
              if (timesheetItems.length > 0) {
                const tsPdf = await generateTimesheetPdf({
                  invoiceNumber: invoice.invoiceNumber,
                  periodStart: invoice.periodStart,
                  periodEnd: invoice.periodEnd,
                  supplierName: supplier.companyName,
                  timesheetItems,
                  format: (bulkTsTemplate?.invoiceFormat as any) || "without_officer",
                });
                archive.append(tsPdf, { name: `${folderName}/timesheet-${invoice.invoiceNumber || invoice.id}.pdf` });
              }
            }
          }
        }

        if (includeSupplierProfile) {
          const profilePdf = await generateSupplierProfilePdf(supplier);
          archive.append(profilePdf, { name: `${folderName}/supplier-profile-${supplier.supplierCode || supplier.id}.pdf` });
        }

        if (includeDueDiligence) {
          const { rows: docs } = await pool.query(
            `SELECT DISTINCT ON (document_type) id, document_type, file_name, file_url, mime_type, status
             FROM supplier_documents WHERE supplier_id = $1
             ORDER BY document_type, created_at DESC, id DESC`,
            [supplierId]
          );
          const localUploadsDir = path.join(process.cwd(), "uploads");
          for (const doc of docs) {
            try {
              const fileUrl = doc.file_url || "";
              const objectPath = fileUrl.startsWith("/objects/") ? fileUrl : fileUrl.replace(/^.*?(\/objects\/)/, "$1");
              if (!objectPath.startsWith("/objects/")) continue;
              const localFileName = objectPath.replace(/^\/objects\/uploads\//, "");
              const localFilePath = path.join(localUploadsDir, localFileName);
              let fileContents: Buffer;
              if (fs.existsSync(localFilePath)) {
                fileContents = fs.readFileSync(localFilePath);
              } else {
                const { ObjectStorageService } = await import("./replit_integrations/object_storage/objectStorage");
                const objService = new ObjectStorageService();
                const objectFile = await objService.getObjectEntityFile(objectPath);
                const [downloaded] = await objectFile.download();
                fileContents = downloaded;
              }
              const docTypeLabel = (doc.document_type || "other").replace(/_/g, "-");
              const safeFileName = (doc.file_name || `${docTypeLabel}.pdf`).replace(/[^a-zA-Z0-9._-]/g, "_");
              archive.append(fileContents, { name: `${folderName}/due-diligence/${docTypeLabel}-${safeFileName}` });
            } catch (ddErr: any) {
              console.error(`Failed to fetch due diligence doc ${doc.id}: ${ddErr.message}`);
            }
          }
        }
      }

      await archive.finalize();
    } catch (err: any) {
      if (!res.headersSent) {
        res.status(500).json({ message: err.message });
      }
    }
  });

