  app.get("/api/vat-check/:vatNumber", requireRole(...hmrcAuditRoles), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });

      let vatNumber = req.params.vatNumber.toUpperCase().trim().replace(/\s+/g, "");
      if (vatNumber.startsWith("GB")) vatNumber = vatNumber.slice(2);
      const vatNumberForApi = vatNumber.replace(/[^0-9]/g, "");

      if (!/^\d{9}$/.test(vatNumberForApi)) {
        return res.status(400).json({ message: "Invalid VAT number format. Expected 9 digits (with or without GB prefix)." });
      }

      // supplierId to save the record
      const supplierId = req.query.supplierId ? Number(req.query.supplierId) : null;

      const digits = vatNumberForApi.split("").map(Number);
      const weights = [8, 7, 6, 5, 4, 3, 2];
      let checksum = 0;
      for (let i = 0; i < 7; i++) checksum += digits[i] * weights[i];
      const checkDigits = digits[7] * 10 + digits[8];
      const total = checksum + checkDigits;
      const isValid = total % 97 === 0 || (total + 55) % 97 === 0;
      const verificationResult = isValid ? "valid" : "invalid_checksum";

      const responsePayload: any = {
        vatNumber: vatNumberForApi,
        isValid,
        verificationResult,
        verificationMethod: "modulus_97",
      };

      if (supplierId) {
        const supplier = await storage.getSupplier(supplierId);
        if (supplier && supplier.tenantId === user.tenantId) {
          const savedVerification = await storage.createVatVerification({
            tenantId: user.tenantId,
            supplierId,
            vatNumber: vatNumberForApi,
            verificationResult,
            verificationMethod: "modulus_97",
            verifiedBy: user.id,
            verifiedByName: `${user.firstName} ${user.lastName}`,
            notes: isValid
              ? "VAT number passes UK modulus 97 checksum validation"
              : "VAT number fails UK modulus 97 checksum validation — number structure is invalid",
          });
          await storage.createSupplierAuditEvent({
            tenantId: user.tenantId,
            supplierId,
            eventType: "vat_verification_checked",
            entityType: "vat_verification",
            entityId: String(savedVerification.id),
            actorUserId: user.id,
            actorName: `${user.firstName} ${user.lastName}`,
            actorRole: user.role,
            summary: `VAT number ${vatNumberForApi} validated via modulus 97: ${verificationResult}`,
            newValues: { vatNumber: vatNumberForApi, result: verificationResult, method: "modulus_97" },
          });
          responsePayload.savedVerificationId = savedVerification.id;
        }
      }

      res.json(responsePayload);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });


