  // ── AI Controller Mode Endpoints ──

  async function requireAiController(req: Request, res: Response, next: NextFunction) {
    const user = req.user as User;
    if (!user?.tenantId) return res.status(403).json({ message: "No tenant" });
    const { rows } = await pool.query(
      "SELECT status FROM tenant_addons WHERE tenant_id = $1 AND addon_key = 'ai_controller' AND status = 'active'",
      [user.tenantId]
    );
    if (rows.length === 0) return res.status(403).json({ message: "AI Controller add-on not active" });
    next();
  }

  async function callOpenAI(systemPrompt: string, userContent: string): Promise<string> {
    const OpenAI = (await import("openai")).default;
    const openai = new OpenAI({
      apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
      baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
    });
    const response = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userContent },
      ],
      temperature: 0.7,
      response_format: { type: "json_object" },
    });
    return response.choices[0]?.message?.content || "{}";
  }

  app.post("/api/ai-controller/situational", requireAuth, requireAiController as any, async (req, res) => {
    try {
      const { shiftCount, incidentCount, activeShifts, lateShifts, noShows } = req.body;
      const coverageRate = shiftCount > 0 ? Math.round((activeShifts / shiftCount) * 100) : 0;
      const prompt = `You are an AI Controller for a security workforce management platform. Analyze the current operational status and provide a JSON response with: summary (string, 2-3 sentence natural language briefing), riskLevel (low/medium/high/critical), riskScore (0-100), coverageGaps (array of {site, time, reason}), keyMetrics (array of {label, value, trend: up/down/stable}), recommendations (array of strings, max 4).`;
      const data = `Current operational data: ${shiftCount} total shifts today, ${activeShifts} active/booked-on, ${lateShifts} late officers, ${noShows} no-shows, ${incidentCount} incidents reported, ${coverageRate}% coverage rate.`;
      const result = await callOpenAI(prompt, data);
      res.json(JSON.parse(result));
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

