  app.post("/api/ai-controller/autonomous-scan", requireAuth, requireAiController as any, async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });

      const today = new Date().toISOString().split("T")[0];
      const allShifts = await storage.getShiftsByDate(user.tenantId, today);
      const now = new Date();
      const currentTime = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;

      const noShows: any[] = [];
      const lateShifts: any[] = [];
      const uncovered: any[] = [];

      for (const shift of allShifts) {
        if (shift.status === "cancelled" || shift.status === "completed") continue;
        if (!shift.employeeId && shift.status === "scheduled") {
          uncovered.push(shift);
          continue;
        }
        if (shift.status === "no_show") {
          noShows.push(shift);
          continue;
        }
        if (shift.status === "scheduled" && shift.startTime <= currentTime && !shift.checkInTime) {
          const startParts = shift.startTime.split(":");
          const startMinutes = parseInt(startParts[0]) * 60 + parseInt(startParts[1]);
          const nowMinutes = now.getHours() * 60 + now.getMinutes();
          if (nowMinutes - startMinutes >= 15) {
            noShows.push(shift);
          } else {
            lateShifts.push(shift);
          }
        }
      }

      const allEmployees = await storage.getEmployeesByTenant(user.tenantId);
      const assignedEmployeeIds = new Set(allShifts.filter(s => s.employeeId && s.status !== "cancelled").map(s => s.employeeId));
      const availableOfficers = allEmployees.filter(emp => {
        if (assignedEmployeeIds.has(emp.id)) return false;
        const siaValid = emp.siaExpiryDate ? new Date(emp.siaExpiryDate) > now : false;
        return siaValid;
      });

      const actions: any[] = [];
      const batchId = `auto-${Date.now()}`;

      for (const shift of noShows) {
        const siteName = shift.siteId ? (await storage.getSite(shift.siteId))?.name || `Site #${shift.siteId}` : "Unknown Site";
        const candidates = availableOfficers.slice(0, 3).map(emp => ({
          id: emp.id,
          name: `${emp.userId ? "" : ""}${emp.employeeNumber || `EMP-${emp.id}`}`,
          siaLicense: emp.siaLicenseNumber || "N/A",
          siaExpiry: emp.siaExpiryDate || "N/A",
        }));

        const empNames = await Promise.all(
          candidates.map(async (c) => {
            const e = await storage.getEmployee(c.id);
            const u = e?.userId ? await storage.getUser(e.userId) : null;
            return { ...c, name: u ? `${u.firstName || ""} ${u.lastName || ""}`.trim() || u.username : `Officer #${c.id}` };
          })
        );

        const action = {
          type: "no_show_detected",
          shiftId: shift.id,
          shiftTitle: shift.title,
          siteName,
          shiftTime: `${shift.startTime} - ${shift.endTime}`,
          originalEmployee: shift.employeeId,
          candidates: empNames,
          severity: "critical",
          aiRecommendation: empNames.length > 0
            ? `Recommend assigning ${empNames[0].name} (SIA: ${empNames[0].siaLicense}) as replacement.`
            : "No available officers with valid SIA. Consider contacting supplier pool.",
          batchId,
        };
        actions.push(action);

        await storage.createAiDecision({
          tenantId: user.tenantId,
          userId: user.id,
          siteId: shift.siteId || undefined,
          siteName,
          shiftDate: today,
          employeeId: empNames.length > 0 ? empNames[0].id : undefined,
          employeeName: empNames.length > 0 ? empNames[0].name : undefined,
          suggestedShiftTime: `${shift.startTime} - ${shift.endTime}`,
          reason: `No-show detected for shift "${shift.title}". Officer did not check in within 15 minutes of start time.`,
          priority: "high",
          status: "suggested",
          requirements: `SIA license required. Original shift: ${shift.startTime}-${shift.endTime}`,
          batchId,
        });
      }

      for (const shift of uncovered) {
        const siteName = shift.siteId ? (await storage.getSite(shift.siteId))?.name || `Site #${shift.siteId}` : "Unknown Site";
        actions.push({
          type: "uncovered_shift",
          shiftId: shift.id,
          shiftTitle: shift.title,
          siteName,
          shiftTime: `${shift.startTime} - ${shift.endTime}`,
          severity: "warning",
          aiRecommendation: "No officer assigned. AI recommends assigning from available pool.",
          batchId,
        });
      }

      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "ai_autonomous_scan",
        entityType: "ai_controller",
        entityId: batchId,
        details: {
          totalShifts: allShifts.length,
          noShowsDetected: noShows.length,
          lateShifts: lateShifts.length,
          uncoveredShifts: uncovered.length,
          availableOfficers: availableOfficers.length,
          actionsGenerated: actions.length,
          scanTime: now.toISOString(),
        },
      });

      res.json({
        scanTime: now.toISOString(),
        batchId,
        summary: {
          totalShifts: allShifts.length,
          activeShifts: allShifts.filter(s => s.status === "in_progress").length,
          noShows: noShows.length,
          lateShifts: lateShifts.length,
          uncoveredShifts: uncovered.length,
          availableOfficers: availableOfficers.length,
        },
        actions,
        decisions: await storage.getAiDecisions(user.tenantId, 20),
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

