  app.post("/api/ai-controller/client-cover-request", requireAuth, requireAiController as any, async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(403).json({ message: "No tenant" });

      const { siteId, startDate, endDate, startTime, endTime, title, notes, repeatPattern } = req.body;
      if (!siteId || !startDate || !startTime || !endTime) {
        return res.status(400).json({ message: "siteId, startDate, startTime and endTime are required" });
      }

      const site = await storage.getSite(siteId);
      if (!site || site.tenantId !== user.tenantId) return res.status(404).json({ message: "Site not found" });

      const shiftTitle = title || `Cover - ${site.name}`;
      const dates: string[] = [];
      const start = new Date(startDate);
      const end = endDate ? new Date(endDate) : new Date(startDate);

      if (repeatPattern === "week") {
        for (let i = 0; i < 7; i++) {
          const d = new Date(start);
          d.setDate(d.getDate() + i);
          if (d <= end || !endDate) dates.push(d.toISOString().split("T")[0]);
          if (!endDate && i >= 6) break;
        }
      } else if (repeatPattern === "fortnight") {
        for (let i = 0; i < 14; i++) {
          const d = new Date(start);
          d.setDate(d.getDate() + i);
          if (d <= end || !endDate) dates.push(d.toISOString().split("T")[0]);
          if (!endDate && i >= 13) break;
        }
      } else if (repeatPattern === "month") {
        for (let i = 0; i < 28; i++) {
          const d = new Date(start);
          d.setDate(d.getDate() + i);
          if (d <= end || !endDate) dates.push(d.toISOString().split("T")[0]);
          if (!endDate && i >= 27) break;
        }
      } else {
        let d = new Date(start);
        while (d <= end) {
          dates.push(d.toISOString().split("T")[0]);
          d.setDate(d.getDate() + 1);
        }
      }

      const createdShifts: any[] = [];
      for (const date of dates) {
        const shift = await storage.createShift({
          tenantId: user.tenantId,
          siteId: Number(siteId),
          title: shiftTitle,
          date,
          startTime,
          endTime,
          notes: notes ? `[Client Cover Request] ${notes}` : "[Client Cover Request] AI-created from cover request",
          createdBy: user.id,
        });
        createdShifts.push(shift);
      }

      const allEmployees = await storage.getEmployeesByTenant(user.tenantId);
      const now = new Date();
      const availableOfficers = allEmployees.filter(emp => {
        const siaValid = emp.siaExpiryDate ? new Date(emp.siaExpiryDate) > now : false;
        return siaValid;
      });

      let aiSuggestion = "Shifts created but no officers auto-assigned. Review available officers and assign manually, or run autonomous scan to get AI recommendations.";
      if (availableOfficers.length > 0) {
        aiSuggestion = `${createdShifts.length} shifts created. ${availableOfficers.length} officers with valid SIA are available. Run autonomous scan to get AI assignment recommendations.`;
      }

      const batchId = `cover-${Date.now()}`;
      await storage.createAiDecision({
        tenantId: user.tenantId,
        userId: user.id,
        siteId: Number(siteId),
        siteName: site.name,
        shiftDate: startDate,
        reason: `Client cover request: ${createdShifts.length} shifts created for ${site.name} from ${startDate}${endDate ? ` to ${endDate}` : ""} (${startTime}-${endTime}).`,
        priority: "high",
        status: "accepted",
        requirements: notes || undefined,
        batchId,
      });

      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "ai_client_cover_request",
        entityType: "shift",
        entityId: batchId,
        details: {
          siteId,
          siteName: site.name,
          shiftsCreated: createdShifts.length,
          dateRange: `${startDate} to ${endDate || startDate}`,
          shiftTime: `${startTime} - ${endTime}`,
          repeatPattern: repeatPattern || "none",
          createdBy: "AI Autonomous Controller",
          timestamp: now.toISOString(),
        },
      });

      res.json({
        success: true,
        shiftsCreated: createdShifts.length,
        shifts: createdShifts,
        aiSuggestion,
        batchId,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

