  app.post("/api/addons/activate", requireRole("tenant_admin", "ceo", "operations_manager", "admin"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });

      const { addonKey, sessionId } = req.body;
      const addon = AVAILABLE_ADDONS.find(a => a.key === addonKey);
      if (!addon) return res.status(404).json({ message: "Add-on not found" });

      if ((addon as any).freeActivation) {
        const existing = await pool.query(
          "SELECT id FROM tenant_addons WHERE tenant_id = $1 AND addon_key = $2",
          [user.tenantId, addonKey]
        );
        if (existing.rows.length > 0) {
          await pool.query(
            "UPDATE tenant_addons SET status = 'active', purchased_at = NOW(), purchased_by_user_id = $3, updated_at = NOW() WHERE tenant_id = $1 AND addon_key = $2",
            [user.tenantId, addonKey, user.id]
          );
        } else {
          await pool.query(
            "INSERT INTO tenant_addons (tenant_id, addon_key, addon_name, status, purchased_at, purchased_by_user_id) VALUES ($1, $2, $3, 'active', NOW(), $4)",
            [user.tenantId, addonKey, addon.name, user.id]
          );
        }
        return res.json({ success: true, message: "Add-on activated" });
      }

      const { getUncachableStripeClient } = await import("./stripeClient");
      const stripe = await getUncachableStripeClient();

      let validSession: any = null;

      if (sessionId) {
        try {
          const session = await stripe.checkout.sessions.retrieve(sessionId);
          if (
            session.payment_status === "paid" &&
            session.metadata?.addonKey === addonKey &&
            session.metadata?.tenantId === String(user.tenantId)
          ) {
            validSession = session;
          }
        } catch (e) {
          console.error("Session retrieve error:", e);
        }
      }

      if (!validSession) {
        const sessions = await stripe.checkout.sessions.list({ limit: 20 });
        validSession = sessions.data.find(s =>
          s.payment_status === "paid" &&
          s.metadata?.addonKey === addonKey &&
          s.metadata?.tenantId === String(user.tenantId)
        );
      }

      if (!validSession) {
        return res.status(403).json({ message: "No valid payment found for this add-on. Please complete checkout first." });
      }

      const subscriptionId = validSession.subscription as string || null;
      const customerId = validSession.customer as string || null;

      const existing = await pool.query(
        "SELECT id FROM tenant_addons WHERE tenant_id = $1 AND addon_key = $2",
        [user.tenantId, addonKey]
      );

      if (existing.rows.length > 0) {
        await pool.query(
          "UPDATE tenant_addons SET status = 'active', purchased_at = NOW(), stripe_subscription_id = COALESCE($3, stripe_subscription_id), stripe_customer_id = COALESCE($4, stripe_customer_id), purchased_by_user_id = $5, updated_at = NOW() WHERE tenant_id = $1 AND addon_key = $2",
          [user.tenantId, addonKey, subscriptionId, customerId, user.id]
        );
      } else {
        await pool.query(
          "INSERT INTO tenant_addons (tenant_id, addon_key, addon_name, status, stripe_product_id, stripe_subscription_id, stripe_customer_id, purchased_at, purchased_by_user_id) VALUES ($1, $2, $3, 'active', $4, $5, $6, NOW(), $7)",
          [user.tenantId, addonKey, addon.name, addon.stripeProductId, subscriptionId, customerId, user.id]
        );
      }

      res.json({ success: true, message: "Add-on activated" });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

