  async function assertTenantOwns(table: string, id: number | null | undefined, tenantId: number): Promise<boolean> {
    if (id === null || id === undefined) return true;
    const { rows } = await pool.query(`SELECT 1 FROM ${table} WHERE id = $1 AND tenant_id = $2`, [id, tenantId]);
    return rows.length > 0;
  }
  // SLA hours by job type + priority. Returns null when no SLA applies.
  function fmSlaHours(jobType: string, priority: string): number | null {
    const t = (jobType || '').toLowerCase();
    const p = (priority || 'medium').toLowerCase();
    if (t === 'reactive_callout' || t === 'reactive') {
      if (p === 'critical') return 2;
      if (p === 'high') return 8;
      if (p === 'medium' || p === 'normal') return 24;
      return 72;
    }
    if (t === 'ppm' || t === 'inspection') {
      return p === 'critical' ? 24 : p === 'high' ? 48 : 168;
    }
    if (t === 'deep_clean' || t === 'window_clean' || t === 'survey') {
      return p === 'critical' ? 48 : p === 'high' ? 72 : 168;
    }
    return null;
  }
  function computeSlaDueAt(jobType: string, priority: string, scheduledDate?: string | null, scheduledStartTime?: string | null): Date | null {
    const hours = fmSlaHours(jobType, priority);
    if (hours == null) return null;
    const base = scheduledDate
      ? new Date(`${scheduledDate}T${scheduledStartTime || '09:00'}:00`)
      : new Date();
    return new Date(base.getTime() + hours * 3600 * 1000);
  }

