      if (!(await assertTenantOwns('fm_jobs', jobId, tenantId))) return res.status(404).json({ message: "Job not found" });
      if (!(await assertTenantOwns('fm_workers', workerId, tenantId))) return res.status(400).json({ message: "Invalid workerId" });
      const result = await pool.query(
        "INSERT INTO fm_job_assignments (tenant_id, job_id, worker_id, role, status) VALUES ($1,$2,$3,$4,'assigned') RETURNING *",
        [tenantId, jobId, workerId, role || 'worker']
      );
      // Auto-progress raised -> assigned
      await pool.query(
        "UPDATE fm_jobs SET status = 'assigned', updated_at = NOW() WHERE id = $1 AND tenant_id = $2 AND status = 'raised'",
        [jobId, tenantId]
      );
      res.json(result.rows[0]);
