  // Generate a job from a PPM schedule
  app.post("/api/fm/ppm/:id/generate-job", requireRole("tenant_admin", "ceo", "operations_manager", "admin", "controller", "supervisor"), requireFmAddon as any, async (req, res) => {
    try {
      const user = req.user as User;
      const tenantId = user.tenantId!;
      const ppmId = parseInt(req.params.id);
      const { rows: ppmRows } = await pool.query("SELECT * FROM fm_ppm_schedules WHERE id = $1 AND tenant_id = $2", [ppmId, tenantId]);
      const ppm = ppmRows[0];
      if (!ppm) return res.status(404).json({ message: "PPM schedule not found" });
      const scheduledDate = req.body.scheduledDate || ppm.next_due_date || new Date().toISOString().split('T')[0];
      const slaDueAt = computeSlaDueAt('ppm', 'medium', scheduledDate, ppm.default_start_time);
      const result = await pool.query(
        `INSERT INTO fm_jobs (tenant_id, site_id, title, description, job_type, service_line, priority, status, scheduled_date, scheduled_start_time, scheduled_end_time, sla_due_at, estimated_hours, supplier_id, ppm_schedule_id, created_by)
         VALUES ($1,$2,$3,$4,'ppm',$5,'medium','raised',$6,$7,$8,$9,$10,$11,$12,$13) RETURNING *`,
        [tenantId, ppm.site_id, ppm.name, ppm.description, ppm.service_line, scheduledDate, ppm.default_start_time, ppm.default_end_time, slaDueAt, ppm.estimated_hours, ppm.default_supplier_id, ppmId, user.id]
      );
      const job = result.rows[0];
      await pool.query("UPDATE fm_jobs SET job_number = $1 WHERE id = $2", [`FM-${String(job.id).padStart(5, '0')}`, job.id]);
      await pool.query("UPDATE fm_ppm_schedules SET last_generated_date = $1 WHERE id = $2", [scheduledDate, ppmId]);
      res.json(job);
    } catch (err: any) { res.status(400).json({ message: err.message }); }
  });

  // FM Dashboard stats — spec KPIs: SLA breach, PPM compliance %, worker utilisation %, jobs completed this month, top-5 overdue
  app.get("/api/fm/dashboard", requireRole("tenant_admin", "ceo", "operations_manager", "admin", "controller", "supervisor"), requireFmAddon as any, async (req, res) => {
    try {
      const tenantId = (req.user as User).tenantId!;
      const today = new Date().toISOString().split('T')[0];
      const monthStart = today.slice(0, 7) + '-01';
      const [workers, jobs, suppliers, ppm, statusBreakdown, serviceBreakdown, upcoming, slaBreach, completedThisMonth, ppmCompliance, workerUtil, topOverdue] = await Promise.all([
        pool.query("SELECT COUNT(*)::int AS total, COUNT(*) FILTER (WHERE is_active)::int AS active FROM fm_workers WHERE tenant_id = $1", [tenantId]),
        pool.query("SELECT COUNT(*)::int AS total, COUNT(*) FILTER (WHERE status IN ('completed','signed_off'))::int AS completed, COUNT(*) FILTER (WHERE status IN ('raised','assigned','in_progress'))::int AS open, COUNT(*) FILTER (WHERE scheduled_date < $2 AND status NOT IN ('completed','signed_off','cancelled'))::int AS overdue FROM fm_jobs WHERE tenant_id = $1", [tenantId, today]),
        pool.query("SELECT COUNT(*)::int AS total FROM fm_suppliers WHERE tenant_id = $1 AND is_active = true", [tenantId]),
        pool.query("SELECT COUNT(*)::int AS total, COUNT(*) FILTER (WHERE next_due_date <= $2 AND is_active)::int AS due_now FROM fm_ppm_schedules WHERE tenant_id = $1", [tenantId, today]),
        pool.query("SELECT status, COUNT(*)::int AS count FROM fm_jobs WHERE tenant_id = $1 GROUP BY status", [tenantId]),
        pool.query("SELECT service_line, COUNT(*)::int AS count FROM fm_jobs WHERE tenant_id = $1 GROUP BY service_line", [tenantId]),
        pool.query(`SELECT j.*, s.name AS site_name FROM fm_jobs j LEFT JOIN sites s ON s.id = j.site_id AND s.tenant_id = j.tenant_id WHERE j.tenant_id = $1 AND j.status IN ('raised','assigned','in_progress') ORDER BY j.scheduled_date ASC NULLS LAST LIMIT 10`, [tenantId]),
        // SLA breaches: open jobs where sla_due_at passed
        pool.query("SELECT COUNT(*)::int AS count FROM fm_jobs WHERE tenant_id = $1 AND sla_due_at IS NOT NULL AND sla_due_at < NOW() AND status NOT IN ('completed','signed_off','cancelled')", [tenantId]),
        pool.query("SELECT COUNT(*)::int AS count FROM fm_jobs WHERE tenant_id = $1 AND status IN ('completed','signed_off') AND completed_at >= $2::date", [tenantId, monthStart]),
        // PPM compliance: of PPM-derived jobs scheduled in last 30 days, what % completed by SLA due
        pool.query(`SELECT
            COUNT(*)::int AS total,
            COUNT(*) FILTER (WHERE status IN ('completed','signed_off'))::int AS completed
          FROM fm_jobs
          WHERE tenant_id = $1 AND job_type = 'ppm' AND scheduled_date >= (NOW() - INTERVAL '30 days')::date`, [tenantId]),
        // Worker utilisation: workers with at least one active assignment vs active workers
        pool.query(`SELECT
            (SELECT COUNT(*)::int FROM fm_workers WHERE tenant_id = $1 AND is_active = true) AS active_workers,
            (SELECT COUNT(DISTINCT a.worker_id)::int FROM fm_job_assignments a
              JOIN fm_jobs j ON j.id = a.job_id AND j.tenant_id = a.tenant_id
              WHERE a.tenant_id = $1 AND j.status IN ('assigned','in_progress')) AS busy_workers`, [tenantId]),
        pool.query(`SELECT j.id, j.job_number, j.title, j.priority, j.status, j.scheduled_date, j.sla_due_at, s.name AS site_name
          FROM fm_jobs j
          LEFT JOIN sites s ON s.id = j.site_id AND s.tenant_id = j.tenant_id
          WHERE j.tenant_id = $1 AND j.status NOT IN ('completed','signed_off','cancelled')
            AND ((j.sla_due_at IS NOT NULL AND j.sla_due_at < NOW()) OR (j.scheduled_date IS NOT NULL AND j.scheduled_date < $2::date))
          ORDER BY j.sla_due_at ASC NULLS LAST, j.scheduled_date ASC NULLS LAST
          LIMIT 5`, [tenantId, today]),
      ]);
      const ppmTotal = ppmCompliance.rows[0]?.total || 0;
      const ppmCompleted = ppmCompliance.rows[0]?.completed || 0;
      const ppmCompliancePct = ppmTotal > 0 ? Math.round((ppmCompleted / ppmTotal) * 100) : 100;
      const activeWorkers = workerUtil.rows[0]?.active_workers || 0;
      const busyWorkers = workerUtil.rows[0]?.busy_workers || 0;
      const workerUtilisationPct = activeWorkers > 0 ? Math.round((busyWorkers / activeWorkers) * 100) : 0;
      res.json({
        workers: workers.rows[0],
        jobs: jobs.rows[0],
        suppliers: suppliers.rows[0],
        kpis: {
          slaBreachCount: slaBreach.rows[0]?.count || 0,
          ppmCompliancePct,
          ppmCompliance: { total: ppmTotal, completed: ppmCompleted },
          workerUtilisationPct,
          workerUtilisation: { active: activeWorkers, busy: busyWorkers },
          jobsCompletedThisMonth: completedThisMonth.rows[0]?.count || 0,
        },
        topOverdue: topOverdue.rows,
        ppm: ppm.rows[0],
        statusBreakdown: statusBreakdown.rows,
        serviceBreakdown: serviceBreakdown.rows,
        upcomingJobs: upcoming.rows,
      });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // ── FM Worker self-service portal ──
  // Resolve current FM worker from the logged-in user (by linked user_id, falling back to email match)
  async function getFmWorkerForUser(user: User): Promise<any | null> {
    if (!user?.tenantId) return null;
    const direct = await pool.query(
      "SELECT * FROM fm_workers WHERE tenant_id = $1 AND user_id = $2 AND is_active = true LIMIT 1",
      [user.tenantId, user.id]
    );
    if (direct.rows[0]) return direct.rows[0];
    if (user.email) {
      const byEmail = await pool.query(
        "SELECT * FROM fm_workers WHERE tenant_id = $1 AND LOWER(email) = LOWER($2) AND is_active = true ORDER BY user_id NULLS LAST LIMIT 1",
        [user.tenantId, user.email]
      );
      if (byEmail.rows[0]) {
        if (!byEmail.rows[0].user_id) {
          await pool.query("UPDATE fm_workers SET user_id = $1 WHERE id = $2", [user.id, byEmail.rows[0].id]);
          byEmail.rows[0].user_id = user.id;
        }
        return byEmail.rows[0];
      }
    }
    return null;
  }

