  // Worker-driven status update: start, complete (with notes + photos), or pause.
  app.patch("/api/fm/my-jobs/:id", requireAuth, requireFmAddon as any, async (req, res) => {
    try {
      const user = req.user as User;
      const tenantId = user.tenantId!;
      const worker = await getFmWorkerForUser(user);
      if (!worker) return res.status(403).json({ message: "Not an FM worker" });
      const id = parseInt(req.params.id);
      const { status, completionNotes, photoUrls, lat, lng } = req.body || {};

      const own = await pool.query(
        "SELECT a.id, j.site_id FROM fm_job_assignments a JOIN fm_jobs j ON j.id = a.job_id AND j.tenant_id = a.tenant_id WHERE a.tenant_id = $1 AND a.worker_id = $2 AND a.job_id = $3 LIMIT 1",
        [tenantId, worker.id, id]
      );
      if (!own.rows[0]) return res.status(404).json({ message: "Job not assigned to you" });
      const assignmentId = own.rows[0].id;
      const jobSiteId = own.rows[0].site_id as number | null;

      const allowed = ['in_progress', 'completed', 'on_hold'];
      if (status && !allowed.includes(status)) {
        return res.status(400).json({ message: `Workers can only set: ${allowed.join(', ')}` });
      }

      // Geolocation validation for check-in (start) and check-out (complete)
      const isCheckIn = status === 'in_progress';
      const isCheckOut = status === 'completed';
      let parsedLat: number | null = null;
      let parsedLng: number | null = null;
      let distanceMetres: number | null = null;
      let withinRange = true;
      let geofenceRadius = 200;
      if (isCheckIn || isCheckOut) {
        const tenant = await storage.getTenant(tenantId);
        geofenceRadius = (tenant as any)?.geofenceRadiusMetres ?? 200;
        if (lat == null || lng == null || isNaN(parseFloat(lat)) || isNaN(parseFloat(lng))) {
          return res.status(400).json({ message: "Location is required. Please enable GPS and try again." });
        }
        parsedLat = parseFloat(lat);
        parsedLng = parseFloat(lng);
        if (parsedLat < -90 || parsedLat > 90 || parsedLng < -180 || parsedLng > 180) {
          return res.status(400).json({ message: "Invalid GPS coordinates." });
        }
        if (jobSiteId) {
          const site = await storage.getSite(jobSiteId);
          if ((site as any)?.geofenceRadiusMetres != null) geofenceRadius = (site as any).geofenceRadiusMetres;
          if (site?.latitude && site?.longitude) {
            distanceMetres = Math.round(haversineDistanceMetres(parsedLat, parsedLng, parseFloat(site.latitude), parseFloat(site.longitude)) * 100) / 100;
            if (distanceMetres > geofenceRadius) withinRange = false;
          }
        }
      }

      const fields: string[] = []; const vals: any[] = []; let i = 1;
      if (status) { fields.push(`status = $${i++}`); vals.push(status); }
      if (isCheckIn) {
        fields.push(`started_at = COALESCE(started_at, NOW())`);
        await pool.query(
          `UPDATE fm_job_assignments SET status = 'in_progress', check_in_at = COALESCE(check_in_at, NOW()),
             check_in_lat = $2, check_in_lng = $3, check_in_distance_metres = $4, check_in_within_range = $5 WHERE id = $1`,
          [assignmentId, parsedLat != null ? String(parsedLat) : null, parsedLng != null ? String(parsedLng) : null, distanceMetres != null ? String(distanceMetres) : null, withinRange]
        );
      }
      if (isCheckOut) {
        fields.push(`completed_at = NOW()`);
        fields.push(`completed_by_worker_id = $${i++}`); vals.push(worker.id);
        await pool.query(
          `UPDATE fm_job_assignments SET status = 'completed', check_out_at = COALESCE(check_out_at, NOW()),
             check_out_lat = $2, check_out_lng = $3, check_out_distance_metres = $4, check_out_within_range = $5 WHERE id = $1`,
          [assignmentId, parsedLat != null ? String(parsedLat) : null, parsedLng != null ? String(parsedLng) : null, distanceMetres != null ? String(distanceMetres) : null, withinRange]
        );
      }
      if (typeof completionNotes === 'string') { fields.push(`completion_notes = $${i++}`); vals.push(completionNotes); }
      if (Array.isArray(photoUrls)) {
        const clean = photoUrls.filter((p: any) => typeof p === 'string' && p.length > 0).slice(0, 12);
        fields.push(`photo_urls = $${i++}`); vals.push(clean);
      }
      if (fields.length === 0) return res.status(400).json({ message: "Nothing to update" });
      fields.push(`updated_at = NOW()`);
      vals.push(id, tenantId);
      const result = await pool.query(
        `UPDATE fm_jobs SET ${fields.join(', ')} WHERE id = $${i++} AND tenant_id = $${i} RETURNING *`,
        vals
      );
      if (isCheckIn || isCheckOut) {
        await storage.createAuditLog({
          tenantId,
          userId: user.id,
          action: isCheckIn ? "fm_worker_checkin" : "fm_worker_checkout",
          entityType: "fm_job",
          entityId: String(id),
          details: { workerId: worker.id, lat: parsedLat, lng: parsedLng, distanceMetres, withinRange },
        });
      }
      res.json({ ...result.rows[0], distanceFromSite: distanceMetres, withinRange, geofenceRadius });
    } catch (err: any) { res.status(400).json({ message: err.message }); }
  });

  // FM Scheduler: jobs within a date range grouped for calendar/list view
  app.get("/api/fm/scheduler", requireAuth, requireFmAddon as any, async (req, res) => {
    try {
      const tenantId = (req.user as User).tenantId!;
      const from = (req.query.from as string) || new Date().toISOString().split('T')[0];
      const to = (req.query.to as string) || new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0];
      const serviceLine = req.query.serviceLine as string | undefined;
      const params: any[] = [tenantId, from, to];
      let where = "j.tenant_id = $1 AND j.scheduled_date BETWEEN $2 AND $3";
      if (serviceLine) { params.push(serviceLine); where += ` AND j.service_line = $${params.length}`; }
      const { rows } = await pool.query(
        `SELECT j.id, j.job_number, j.title, j.job_type, j.service_line, j.priority, j.status,
                j.scheduled_date, j.scheduled_start_time, j.scheduled_end_time, j.sla_due_at,
                j.estimated_hours, s.name AS site_name, sup.company_name AS supplier_name,
                (j.sla_due_at IS NOT NULL AND j.sla_due_at < NOW() AND j.status NOT IN ('completed','signed_off','cancelled')) AS sla_overdue,
                COALESCE(json_agg(json_build_object('id', a.id, 'workerId', a.worker_id, 'workerName', w.first_name || ' ' || w.last_name, 'status', a.status))
                         FILTER (WHERE a.id IS NOT NULL), '[]') AS assignments
         FROM fm_jobs j
         LEFT JOIN sites s ON s.id = j.site_id AND s.tenant_id = j.tenant_id
         LEFT JOIN fm_suppliers sup ON sup.id = j.supplier_id AND sup.tenant_id = j.tenant_id
         LEFT JOIN fm_job_assignments a ON a.job_id = j.id AND a.tenant_id = j.tenant_id
         LEFT JOIN fm_workers w ON w.id = a.worker_id AND w.tenant_id = j.tenant_id
         WHERE ${where}
         GROUP BY j.id, s.name, sup.company_name
         ORDER BY j.scheduled_date ASC, j.scheduled_start_time ASC NULLS LAST`,
        params
      );
      res.json({ from, to, jobs: rows });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // FM Reports: aggregated operational reports for a date range
  app.get("/api/fm/reports", requireAuth, requireFmAddon as any, async (req, res) => {
    try {
      const tenantId = (req.user as User).tenantId!;
      const from = (req.query.from as string) || new Date(Date.now() - 30 * 86400000).toISOString().split('T')[0];
      const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
      const [byStatus, byServiceLine, byPriority, byType, slaPerformance, workerLoad, supplierLoad, sitesLoad] = await Promise.all([
        pool.query("SELECT status, COUNT(*)::int AS count FROM fm_jobs WHERE tenant_id = $1 AND scheduled_date BETWEEN $2 AND $3 GROUP BY status ORDER BY status", [tenantId, from, to]),
        pool.query("SELECT service_line, COUNT(*)::int AS count, COUNT(*) FILTER (WHERE status IN ('completed','signed_off'))::int AS completed FROM fm_jobs WHERE tenant_id = $1 AND scheduled_date BETWEEN $2 AND $3 GROUP BY service_line", [tenantId, from, to]),
        pool.query("SELECT priority, COUNT(*)::int AS count FROM fm_jobs WHERE tenant_id = $1 AND scheduled_date BETWEEN $2 AND $3 GROUP BY priority", [tenantId, from, to]),
        pool.query("SELECT job_type, COUNT(*)::int AS count FROM fm_jobs WHERE tenant_id = $1 AND scheduled_date BETWEEN $2 AND $3 GROUP BY job_type", [tenantId, from, to]),
        pool.query(`SELECT
            COUNT(*) FILTER (WHERE sla_due_at IS NOT NULL)::int AS total_with_sla,
            COUNT(*) FILTER (WHERE sla_due_at IS NOT NULL AND completed_at IS NOT NULL AND completed_at <= sla_due_at)::int AS met_sla,
            COUNT(*) FILTER (WHERE sla_due_at IS NOT NULL AND (completed_at IS NULL OR completed_at > sla_due_at))::int AS breached_sla
          FROM fm_jobs WHERE tenant_id = $1 AND scheduled_date BETWEEN $2 AND $3`, [tenantId, from, to]),
        pool.query(`SELECT w.id, w.first_name || ' ' || w.last_name AS worker_name, w.trade,
            COUNT(a.id)::int AS assigned_jobs,
            COUNT(a.id) FILTER (WHERE j.status IN ('completed','signed_off'))::int AS completed_jobs
          FROM fm_workers w
          LEFT JOIN fm_job_assignments a ON a.worker_id = w.id AND a.tenant_id = w.tenant_id
          LEFT JOIN fm_jobs j ON j.id = a.job_id AND j.tenant_id = w.tenant_id AND j.scheduled_date BETWEEN $2 AND $3
          WHERE w.tenant_id = $1 AND w.is_active = true
          GROUP BY w.id, w.first_name, w.last_name, w.trade
          ORDER BY assigned_jobs DESC LIMIT 20`, [tenantId, from, to]),
        pool.query(`SELECT sup.id, sup.company_name, COUNT(j.id)::int AS jobs,
            COUNT(j.id) FILTER (WHERE j.status IN ('completed','signed_off'))::int AS completed
          FROM fm_suppliers sup
          LEFT JOIN fm_jobs j ON j.supplier_id = sup.id AND j.tenant_id = sup.tenant_id AND j.scheduled_date BETWEEN $2 AND $3
          WHERE sup.tenant_id = $1
          GROUP BY sup.id, sup.company_name
          HAVING COUNT(j.id) > 0
          ORDER BY jobs DESC LIMIT 20`, [tenantId, from, to]),
        pool.query(`SELECT s.id, s.name AS site_name, COUNT(j.id)::int AS jobs
          FROM sites s
          JOIN fm_jobs j ON j.site_id = s.id AND j.tenant_id = s.tenant_id
          WHERE s.tenant_id = $1 AND j.scheduled_date BETWEEN $2 AND $3
          GROUP BY s.id, s.name ORDER BY jobs DESC LIMIT 20`, [tenantId, from, to]),
      ]);
      const sla = slaPerformance.rows[0];
      const slaMetPct = sla.total_with_sla > 0 ? Math.round((sla.met_sla / sla.total_with_sla) * 100) : 100;
      res.json({
        from, to,
        byStatus: byStatus.rows,
        byServiceLine: byServiceLine.rows,
        byPriority: byPriority.rows,
        byType: byType.rows,
        slaPerformance: { ...sla, slaMetPct },
        workerLoad: workerLoad.rows,
        supplierLoad: supplierLoad.rows,
        sitesLoad: sitesLoad.rows,
      });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // ── FM Billing — wires FM jobs into the existing invoice / self-billing engine ──
  const FM_BILLING_ROLES = ["super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "accountant"] as const;

  async function loadBillableFmJobsForSupplier(tenantId: number, fmSupplierId: number, periodStart: string, periodEnd: string, jobIds?: number[]) {
    const params: any[] = [tenantId, fmSupplierId, periodStart, periodEnd];
    let where = `j.tenant_id = $1 AND j.supplier_id = $2
      AND j.status IN ('completed','signed_off')
      AND COALESCE(j.completed_at::date, j.scheduled_date) BETWEEN $3::date AND $4::date
      AND NOT EXISTS (SELECT 1 FROM invoice_line_items ili WHERE ili.fm_job_id = j.id)`;
    if (Array.isArray(jobIds) && jobIds.length > 0) {
      params.push(jobIds);
      where += ` AND j.id = ANY($${params.length}::int[])`;
    }
    const { rows } = await pool.query(
      `SELECT j.id, j.job_number, j.title, j.service_line, j.job_type, j.scheduled_date, j.completed_at,
              j.estimated_hours, j.actual_hours, j.site_id,
              COALESCE(s.name, 'Site') AS site_name, s.client_id,
              sup.company_name AS supplier_name, sup.default_hourly_rate, sup.vat_number AS supplier_vat
       FROM fm_jobs j
       LEFT JOIN sites s ON s.id = j.site_id AND s.tenant_id = j.tenant_id
       LEFT JOIN fm_suppliers sup ON sup.id = j.supplier_id AND sup.tenant_id = j.tenant_id
       WHERE ${where}
       ORDER BY COALESCE(j.completed_at::date, j.scheduled_date) ASC, j.id ASC`,
      params
    );
    return rows as any[];
  }

  async function loadBillableFmJobsForClient(tenantId: number, clientId: number, periodStart: string, periodEnd: string, jobIds?: number[]) {
    const params: any[] = [tenantId, clientId, periodStart, periodEnd];
    let where = `j.tenant_id = $1 AND s.client_id = $2
      AND j.status IN ('completed','signed_off')
      AND COALESCE(j.completed_at::date, j.scheduled_date) BETWEEN $3::date AND $4::date
      AND NOT EXISTS (SELECT 1 FROM client_invoice_line_items cili WHERE cili.fm_job_id = j.id)`;
    if (Array.isArray(jobIds) && jobIds.length > 0) {
      params.push(jobIds);
      where += ` AND j.id = ANY($${params.length}::int[])`;
    }
    const { rows } = await pool.query(
      `SELECT j.id, j.job_number, j.title, j.service_line, j.job_type, j.scheduled_date, j.completed_at,
              j.estimated_hours, j.actual_hours, j.site_id,
              s.name AS site_name, s.client_id,
              sup.company_name AS supplier_name, sup.default_hourly_rate
       FROM fm_jobs j
       JOIN sites s ON s.id = j.site_id AND s.tenant_id = j.tenant_id
       LEFT JOIN fm_suppliers sup ON sup.id = j.supplier_id AND sup.tenant_id = j.tenant_id
       WHERE ${where}
       ORDER BY COALESCE(j.completed_at::date, j.scheduled_date) ASC, j.id ASC`,
      params
    );
    return rows as any[];
  }

  function fmJobHours(row: any): number {
    const v = parseFloat(row.actual_hours ?? row.estimated_hours ?? '0');
    return isFinite(v) && v > 0 ? Math.round(v * 100) / 100 : 0;
  }

  function fmJobDescription(row: any): string {
    const dateStr = row.completed_at ? new Date(row.completed_at).toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" })
      : row.scheduled_date ? new Date(row.scheduled_date).toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" })
      : "";
    const jobRef = row.job_number || `FM-${String(row.id).padStart(5, '0')}`;
    return `${dateStr ? dateStr + " — " : ""}${jobRef}: ${row.title} (${row.site_name})`;
  }

