  // Generate self-bill invoice from completed FM jobs
  app.post("/api/fm/billing/self-bill/generate", requireRole(...FM_BILLING_ROLES), requireFmAddon as any, async (req, res) => {
    try {
      const user = req.user as User;
      const tenantId = user.tenantId!;
      const { fmSupplierId, periodStart, periodEnd, jobIds } = req.body || {};
      if (!fmSupplierId || !periodStart || !periodEnd) return res.status(400).json({ message: "fmSupplierId, periodStart, periodEnd required" });
      if (!(await assertTenantOwns('fm_suppliers', fmSupplierId, tenantId))) return res.status(404).json({ message: "FM supplier not found" });

      const supRes = await pool.query("SELECT * FROM fm_suppliers WHERE id = $1 AND tenant_id = $2", [fmSupplierId, tenantId]);
      const fmSupplier = supRes.rows[0];
      if (!fmSupplier) return res.status(404).json({ message: "FM supplier not found" });

      const jobs = await loadBillableFmJobsForSupplier(tenantId, fmSupplierId, periodStart, periodEnd, jobIds);
      if (jobs.length === 0) return res.status(400).json({ message: "No completed, un-invoiced FM jobs found for this supplier in the period" });

      const tenant = await storage.getTenant(tenantId);
      const tenantHasValidVat = !!(tenant?.vatNumber && tenant.vatNumber.trim().length > 0);
      const supplierHasVat = !!(fmSupplier.vat_number && String(fmSupplier.vat_number).trim().length > 0);
      const vatRate = (tenantHasValidVat && supplierHasVat) ? 20 : 0;

      const lineItemsData: Array<{ jobId: number; hours: number; rate: number; description: string; subtotal: number; lineVatAmount: number; lineTotal: number }> = [];
      let subtotal = 0;
      for (const j of jobs) {
        const hours = fmJobHours(j);
        const rate = parseFloat(j.default_hourly_rate || '0');
        if (hours <= 0 || rate <= 0) continue;
        const lineSubtotal = Math.round(hours * rate * 100) / 100;
        const lineVatAmount = Math.round(lineSubtotal * (vatRate / 100) * 100) / 100;
        subtotal += lineSubtotal;
        lineItemsData.push({ jobId: j.id, hours, rate, description: fmJobDescription(j), subtotal: lineSubtotal, lineVatAmount, lineTotal: lineSubtotal + lineVatAmount });
      }
      if (lineItemsData.length === 0) return res.status(400).json({ message: "No FM jobs have both hours and a supplier rate configured" });

      subtotal = Math.round(subtotal * 100) / 100;
      const vatAmount = Math.round(subtotal * (vatRate / 100) * 100) / 100;
      const totalAmount = Math.round((subtotal + vatAmount) * 100) / 100;
      const totalHours = Math.round(lineItemsData.reduce((s, l) => s + l.hours, 0) * 100) / 100;

      const tenantPrefix = (tenant?.name || "GRD").substring(0, 3).toUpperCase();
      const periodLabel = new Date(periodStart).toISOString().substring(0, 7).replace("-", "");
      const seriesPrefix = vatRate > 0 ? `FM-SBI-${tenantPrefix}` : `FM-SBI-NV`;
      const { rows: [{ max_seq }] } = await pool.query(
        `SELECT COALESCE(MAX(CAST(SUBSTRING(invoice_number FROM '[0-9]+$') AS INT)), 0) as max_seq
         FROM invoices WHERE invoice_number LIKE $1 AND tenant_id = $2`,
        [seriesPrefix + '-%', tenantId]
      );
      const invoiceNumber = `${seriesPrefix}-${periodLabel}-${String((max_seq as number) + 1).padStart(4, "0")}`;

      const invRes = await pool.query(
        `INSERT INTO invoices (tenant_id, fm_supplier_id, invoice_number, invoice_type, period_start, period_end,
                              total_hours, hourly_rate, subtotal, vat_rate, vat_amount, total_amount,
                              status, approved_timesheet_count, billing_period, generated_at, created_by, notes)
         VALUES ($1,$2,$3,'self_billed',$4,$5,$6,$7,$8,$9,$10,$11,'pending',$12,$13,NOW(),$14,$15) RETURNING *`,
        [tenantId, fmSupplierId, invoiceNumber, periodStart, periodEnd,
         String(totalHours), String(parseFloat(fmSupplier.default_hourly_rate || '0')),
         String(subtotal), String(vatRate), String(vatAmount), String(totalAmount),
         lineItemsData.length, `${periodStart} to ${periodEnd}`, user.id,
         `FM self-billed invoice for ${fmSupplier.company_name} — ${lineItemsData.length} completed FM job${lineItemsData.length === 1 ? '' : 's'}`]
      );
      const invoice = invRes.rows[0];

      for (const item of lineItemsData) {
        await pool.query(
          `INSERT INTO invoice_line_items (invoice_id, fm_job_id, description, hours, rate, subtotal, vat_rate, vat_amount, line_total)
           VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
          [invoice.id, item.jobId, item.description, String(item.hours), String(item.rate),
           String(item.subtotal), String(vatRate), String(item.lineVatAmount), String(item.lineTotal)]
        );
      }

      await storage.createAuditLog({
        tenantId, userId: user.id,
        action: "fm_self_billing_invoice_generated", entityType: "invoice",
        entityId: String(invoice.id),
        details: { fmSupplierId, periodStart, periodEnd, jobCount: lineItemsData.length, totalAmount: totalAmount.toFixed(2) },
      });

      res.json({ ...invoice, lineItemCount: lineItemsData.length });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // Preview FM jobs available for client invoicing
  app.post("/api/fm/billing/client-invoice/preview", requireRole(...FM_BILLING_ROLES), requireFmAddon as any, async (req, res) => {
    try {
      const tenantId = (req.user as User).tenantId!;
      const { clientId, periodStart, periodEnd, jobIds } = req.body || {};
      if (!clientId || !periodStart || !periodEnd) return res.status(400).json({ message: "clientId, periodStart, periodEnd required" });
      if (!(await assertTenantOwns('clients', clientId, tenantId))) return res.status(404).json({ message: "Client not found" });

      const jobs = await loadBillableFmJobsForClient(tenantId, clientId, periodStart, periodEnd, jobIds);
      const { rows: chargeRates } = await pool.query(
        `SELECT * FROM client_rate_cards WHERE tenant_id = $1 AND client_id = $2 ORDER BY effective_from DESC`,
        [tenantId, clientId]
      );

      const lines = jobs.map(j => {
        const hours = fmJobHours(j);
        const jobDate = new Date(j.completed_at || j.scheduled_date || new Date());
        const applicable = chargeRates.find((c: any) => {
          if (c.site_id && c.site_id !== j.site_id) return false;
          const from = new Date(c.effective_from);
          const to = c.effective_to ? new Date(c.effective_to) : new Date('2099-12-31');
          return jobDate >= from && jobDate <= to;
        });
        const fallbackRate = parseFloat(j.default_hourly_rate || '0');
        const chargeRate = applicable ? parseFloat(applicable.hourly_charge_rate) : fallbackRate;
        const subtotal = Math.round(hours * chargeRate * 100) / 100;
        return {
          jobId: j.id, jobNumber: j.job_number, description: fmJobDescription(j),
          hours, chargeRate, subtotal,
          rateSource: applicable ? 'client_rate_card' : (fallbackRate > 0 ? 'fm_supplier_default' : 'none'),
        };
      });
      const subtotal = Math.round(lines.reduce((s, l) => s + l.subtotal, 0) * 100) / 100;
      res.json({ jobs: lines, subtotal, jobCount: lines.length });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

  // Generate client invoice from completed FM jobs
  app.post("/api/fm/billing/client-invoice/generate", requireRole(...FM_BILLING_ROLES), requireFmAddon as any, async (req, res) => {
    try {
      const user = req.user as User;
      const tenantId = user.tenantId!;
      const { clientId, periodStart, periodEnd, jobIds, vatRate = 20 } = req.body || {};
      if (!clientId || !periodStart || !periodEnd) return res.status(400).json({ message: "clientId, periodStart, periodEnd required" });
      if (!(await assertTenantOwns('clients', clientId, tenantId))) return res.status(404).json({ message: "Client not found" });

      const jobs = await loadBillableFmJobsForClient(tenantId, clientId, periodStart, periodEnd, jobIds);
      if (jobs.length === 0) return res.status(400).json({ message: "No completed, un-invoiced FM jobs found for this client in the period" });

      const { rows: chargeRates } = await pool.query(
        `SELECT * FROM client_rate_cards WHERE tenant_id = $1 AND client_id = $2 ORDER BY effective_from DESC`,
        [tenantId, clientId]
      );

      const items: any[] = [];
      let subtotal = 0;
      for (const j of jobs) {
        const hours = fmJobHours(j);
        const jobDate = new Date(j.completed_at || j.scheduled_date || new Date());
        const applicable = chargeRates.find((c: any) => {
          if (c.site_id && c.site_id !== j.site_id) return false;
          const from = new Date(c.effective_from);
          const to = c.effective_to ? new Date(c.effective_to) : new Date('2099-12-31');
          return jobDate >= from && jobDate <= to;
        });
        const fallbackRate = parseFloat(j.default_hourly_rate || '0');
        const chargeRate = applicable ? parseFloat(applicable.hourly_charge_rate) : fallbackRate;
        if (hours <= 0 || chargeRate <= 0) continue;
        const lineSubtotal = Math.round(hours * chargeRate * 100) / 100;
        const lineVat = Math.round(lineSubtotal * (vatRate / 100) * 100) / 100;
        items.push({
          jobId: j.id, description: fmJobDescription(j),
          hours, chargeRate, subtotal: lineSubtotal, vatAmount: lineVat, lineTotal: lineSubtotal + lineVat,
        });
        subtotal += lineSubtotal;
      }
      if (items.length === 0) return res.status(400).json({ message: "No FM jobs have both hours and a client charge rate" });

      subtotal = Math.round(subtotal * 100) / 100;
      const vatAmount = Math.round(subtotal * (vatRate / 100) * 100) / 100;
      const totalAmount = Math.round((subtotal + vatAmount) * 100) / 100;

      const { rows: [{ cnt }] } = await pool.query(
        "SELECT COUNT(*)::int as cnt FROM client_invoices WHERE tenant_id = $1 AND invoice_number LIKE 'FM-CINV-%'",
        [tenantId]
      );
      const invoiceNumber = `FM-CINV-${String((cnt as number) + 1).padStart(5, '0')}`;

      const invRes = await pool.query(
        `INSERT INTO client_invoices (tenant_id, client_id, invoice_number, period_start, period_end, subtotal, vat_rate, vat_amount, total_amount, status, created_by, notes)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,'draft',$10,$11) RETURNING *`,
        [tenantId, clientId, invoiceNumber, periodStart, periodEnd,
         subtotal.toFixed(2), vatRate, vatAmount.toFixed(2), totalAmount.toFixed(2), user.id,
         `FM client invoice — ${items.length} completed FM job${items.length === 1 ? '' : 's'}`]
      );
      const invoice = invRes.rows[0];

      for (const it of items) {
        await pool.query(
          `INSERT INTO client_invoice_line_items (client_invoice_id, fm_job_id, description, hours, charge_rate, subtotal, vat_amount, line_total)
           VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
          [invoice.id, it.jobId, it.description, it.hours.toFixed(2), it.chargeRate.toFixed(2),
           it.subtotal.toFixed(2), it.vatAmount.toFixed(2), it.lineTotal.toFixed(2)]
        );
      }

      await storage.createAuditLog({
        tenantId, userId: user.id,
        action: "fm_client_invoice_generated", entityType: "client_invoice",
        entityId: String(invoice.id),
        details: { clientId, periodStart, periodEnd, jobCount: items.length, totalAmount: totalAmount.toFixed(2) },
      });

      res.json({ ...invoice, lineItemCount: items.length });
    } catch (err: any) { res.status(500).json({ message: err.message }); }
  });

