  app.post("/api/ai-contact/twiml-response", express.urlencoded({ extended: false }), async (req: Request, res: Response) => {
    try {
      const digits = req.body.Digits;
      const { shiftId, tenantId } = req.query;
      let responseMessage = "";

      if (digits === "1") {
        responseMessage = "Thank you for confirming. We've noted that you are on your way. Please check in via the app when you arrive.";
        if (shiftId && tenantId) {
          await pool.query(
            `INSERT INTO contact_logs (tenant_id, shift_id, channel, trigger_type, message_body, status, employee_response) 
             VALUES ($1, $2, 'voice_call', 'call_response', 'Employee pressed 1 - confirming attendance', 'sent', 'confirmed')`,
            [Number(tenantId), Number(shiftId)]
          );
        }
      } else if (digits === "2") {
        responseMessage = "Understood, we've noted that you cannot attend. The control room will arrange cover. Thank you for letting us know.";
        if (shiftId && tenantId) {
          await pool.query(
            `INSERT INTO contact_logs (tenant_id, shift_id, channel, trigger_type, message_body, status, employee_response) 
             VALUES ($1, $2, 'voice_call', 'call_response', 'Employee pressed 2 - cannot attend', 'sent', 'declined')`,
            [Number(tenantId), Number(shiftId)]
          );
        }
      } else if (digits === "3") {
        responseMessage = "Please hold while we connect you to the control room.";
      } else {
        responseMessage = "We didn't recognise that option. Goodbye.";
      }

      const twiml = generateTwiML(responseMessage);
      res.type("text/xml").send(twiml);
    } catch (err: any) {
      console.error("TwiML response error:", err);
      const fallback = generateTwiML("An error occurred. Please try again later.");
      res.type("text/xml").send(fallback);
    }
  });

