  io.use((socket, next) => {
    const req = socket.request as any;
    sessionMiddleware(req, {} as any, () => {
      passport.initialize()(req, {} as any, () => {
        passport.session()(req, {} as any, () => {
          if (req.session?.passport?.user) {
            socket.data.userId = req.session.passport.user;
            next();
          } else {
            next(new Error("Unauthorized"));
          }
        });
      });
    });
  });

  io.on("connection", async (socket) => {
    const userId = socket.data.userId;
    if (!userId) return socket.disconnect();

    try {
      const user = await storage.getUser(userId);
      if (!user || !user.tenantId) return socket.disconnect();

      socket.join(`tenant_${user.tenantId}`);
      socket.data.tenantId = user.tenantId;
      socket.data.username = user.firstName && user.lastName ? `${user.firstName} ${user.lastName}` : user.username;

      io.to(`tenant_${user.tenantId}`).emit("user-online", { userId, username: socket.data.username });

      socket.on("join-channel", async (channelId: number) => {
        try {
          const channel = await storage.getChannel(channelId);
          if (!channel || channel.tenantId !== user.tenantId) return;
          const members = await storage.getChannelMembers(channelId);
          if (!members.some(m => m.userId === userId)) return;
          socket.join(`channel_${channelId}`);
          socket.data.activeChannelId = channelId;
        } catch {}
      });

      socket.on("leave-channel", (channelId: number) => {
        socket.leave(`channel_${channelId}`);
        if (socket.data.activeChannelId === channelId) {
          socket.data.activeChannelId = null;
        }
      });

      socket.on("typing", (data: { channelId: number }) => {
        socket.to(`channel_${data.channelId}`).emit("user-typing", {
          userId,
          username: socket.data.username,
          channelId: data.channelId,
        });
      });

      socket.on("disconnect", () => {
        io.to(`tenant_${user.tenantId}`).emit("user-offline", { userId });
      });
    } catch {
      socket.disconnect();
    }
  });

  app.get("/api/admin/timesheets", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "controller", "scheduler"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const tenantId = user.tenantId;
      const page = Math.max(1, parseInt(req.query.page as string) || 1);
      const limit = Math.min(200, Math.max(10, parseInt(req.query.limit as string) || 25));
      const offset = (page - 1) * limit;
      const startDate = req.query.startDate as string || null;
      const endDate = req.query.endDate as string || null;
      const search = req.query.search as string || null;
      const siteId = req.query.siteId as string || null;

      let whereClause = "WHERE s.tenant_id = $1 AND s.status = 'completed'";
      const params: any[] = [tenantId];
      let paramIdx = 2;

      if (startDate) {
        whereClause += ` AND s.date >= $${paramIdx}`;
        params.push(startDate);
        paramIdx++;
      }
      if (endDate) {
        whereClause += ` AND s.date <= $${paramIdx}`;
        params.push(endDate);
        paramIdx++;
      }
      if (siteId) {
        whereClause += ` AND s.site_id = $${paramIdx}`;
        params.push(parseInt(siteId));
        paramIdx++;
      }
      if (search) {
        whereClause += ` AND (si.name ILIKE $${paramIdx} OR CONCAT(u.first_name, ' ', u.last_name) ILIKE $${paramIdx})`;
        params.push(`%${search}%`);
        paramIdx++;
      }

      const countResult = await pool.query(
        `SELECT COUNT(*) as total FROM shifts s
         LEFT JOIN sites si ON si.id = s.site_id
         LEFT JOIN employees e ON e.id = s.employee_id
         LEFT JOIN users u ON u.id = e.user_id
         ${whereClause}`,
        params
      );
      const total = parseInt(countResult.rows[0].total);

      const dataParams = [...params, limit, offset];
      const { rows } = await pool.query(
        `SELECT s.id, s.date, s.start_time, s.end_time,
                s.booked_on_at, s.booked_off_at, s.late_minutes,
                s.last_check_in_lat, s.last_check_in_lng, s.last_check_in_address,
                si.name as site_name, si.postcode as site_postcode,
                u.first_name as officer_first_name, u.last_name as officer_last_name,
                s.break_minutes
         FROM shifts s
         LEFT JOIN sites si ON si.id = s.site_id
         LEFT JOIN employees e ON e.id = s.employee_id
         LEFT JOIN users u ON u.id = e.user_id
         ${whereClause}
         ORDER BY s.date DESC, s.start_time ASC
         LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`,
        dataParams
      );

      const timesheets = rows.map(r => {
        let hoursWorked: number | null = null;
        if (r.booked_on_at && r.booked_off_at) {
          const onTime = new Date(r.booked_on_at).getTime();
          const offTime = new Date(r.booked_off_at).getTime();
          const diffMs = offTime - onTime;
          const breakMs = (r.break_minutes || 0) * 60000;
          hoursWorked = Math.round(((diffMs - breakMs) / 3600000) * 100) / 100;
        }
        return {
          id: r.id,
          date: r.date,
          siteName: r.site_name || "Unknown Site",
          sitePostcode: r.site_postcode || "",
          officerName: r.officer_first_name && r.officer_last_name
            ? `${r.officer_first_name} ${r.officer_last_name}` : "Unassigned",
          startTime: r.start_time,
          endTime: r.end_time,
          bookedOnAt: r.booked_on_at,
          bookedOffAt: r.booked_off_at,
          hoursWorked,
          lateMinutes: r.late_minutes || 0,
          lat: r.last_check_in_lat,
          lng: r.last_check_in_lng,
          checkInAddress: r.last_check_in_address,
          breakMinutes: r.break_minutes || 0,
        };
      });

      res.json({ timesheets, total, page, limit, totalPages: Math.ceil(total / limit) });
    } catch (err: any) {
      console.error("admin timesheets error:", err);
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/admin/timesheets/export-csv", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "controller", "scheduler"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const tenantId = user.tenantId;
      const startDate = req.query.startDate as string || null;
      const endDate = req.query.endDate as string || null;
      const search = req.query.search as string || null;

      let whereClause = "WHERE s.tenant_id = $1 AND s.status = 'completed'";
      const params: any[] = [tenantId];
      let paramIdx = 2;

      if (startDate) { whereClause += ` AND s.date >= $${paramIdx}`; params.push(startDate); paramIdx++; }
      if (endDate) { whereClause += ` AND s.date <= $${paramIdx}`; params.push(endDate); paramIdx++; }
      if (search) {
        whereClause += ` AND (si.name ILIKE $${paramIdx} OR CONCAT(u.first_name, ' ', u.last_name) ILIKE $${paramIdx})`;
        params.push(`%${search}%`);
        paramIdx++;
      }

      const { rows } = await pool.query(
        `SELECT s.id, s.date, s.start_time, s.end_time,
                s.booked_on_at, s.booked_off_at, s.late_minutes, s.break_minutes,
                s.last_check_in_lat, s.last_check_in_lng,
                si.name as site_name, si.postcode as site_postcode,
                u.first_name as officer_first_name, u.last_name as officer_last_name
         FROM shifts s
         LEFT JOIN sites si ON si.id = s.site_id
         LEFT JOIN employees e ON e.id = s.employee_id
         LEFT JOIN users u ON u.id = e.user_id
         ${whereClause}
         ORDER BY s.date DESC, s.start_time ASC
         LIMIT 50000`,
        params
      );

      const csvHeader = "Date,Site Name,Site Postcode,Officer Name,Scheduled Start,Scheduled End,Actual Book-On,Actual Book-Off,Hours Worked,Late (mins),Break (mins),Latitude,Longitude\n";
      const csvRows = rows.map(r => {
        let hours = "";
        if (r.booked_on_at && r.booked_off_at) {
          const diffMs = new Date(r.booked_off_at).getTime() - new Date(r.booked_on_at).getTime();
          const breakMs = (r.break_minutes || 0) * 60000;
          hours = (Math.round(((diffMs - breakMs) / 3600000) * 100) / 100).toFixed(2);
        }
        const fmtTs = (ts: string | null) => ts ? new Date(ts).toISOString().replace("T", " ").substring(0, 16) : "";
        const esc = (v: string) => { let s = (v || "").replace(/"/g, '""'); if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; return `"${s}"`; };
        return [
          r.date, esc(r.site_name || ""), esc(r.site_postcode || ""),
          esc(`${r.officer_first_name || ""} ${r.officer_last_name || ""}`.trim()),
          r.start_time || "", r.end_time || "",
          fmtTs(r.booked_on_at), fmtTs(r.booked_off_at),
          hours, r.late_minutes || 0, r.break_minutes || 0,
          r.last_check_in_lat || "", r.last_check_in_lng || ""
        ].join(",");
      }).join("\n");

      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", `attachment; filename="timesheets_${safeFilename(startDate || "all")}_${safeFilename(endDate || "all")}.csv"`);
      res.send(csvHeader + csvRows);
    } catch (err: any) {
      console.error("timesheets csv export error:", err);
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/admin/timesheets/export-pdf", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "controller", "scheduler"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const tenantId = user.tenantId;
      const startDate = req.query.startDate as string || null;
      const endDate = req.query.endDate as string || null;
      const search = req.query.search as string || null;

      let whereClause = "WHERE s.tenant_id = $1 AND s.status = 'completed'";
      const params: any[] = [tenantId];
      let paramIdx = 2;

      if (startDate) { whereClause += ` AND s.date >= $${paramIdx}`; params.push(startDate); paramIdx++; }
      if (endDate) { whereClause += ` AND s.date <= $${paramIdx}`; params.push(endDate); paramIdx++; }
      if (search) {
        whereClause += ` AND (si.name ILIKE $${paramIdx} OR CONCAT(u.first_name, ' ', u.last_name) ILIKE $${paramIdx})`;
        params.push(`%${search}%`);
        paramIdx++;
      }

      const { rows } = await pool.query(
        `SELECT s.date, s.start_time, s.end_time,
                s.booked_on_at, s.booked_off_at, s.late_minutes, s.break_minutes,
                s.last_check_in_lat, s.last_check_in_lng,
                si.name as site_name,
                u.first_name as officer_first_name, u.last_name as officer_last_name
         FROM shifts s
         LEFT JOIN sites si ON si.id = s.site_id
         LEFT JOIN employees e ON e.id = s.employee_id
         LEFT JOIN users u ON u.id = e.user_id
         ${whereClause}
         ORDER BY s.date DESC, s.start_time ASC
         LIMIT 10000`,
        params
      );

      const PDFDocument = require("pdfkit");
      const doc = new PDFDocument({ size: "A4", layout: "landscape", margin: 30 });
      const buffers: Buffer[] = [];
      doc.on("data", (chunk: Buffer) => buffers.push(chunk));
      doc.on("end", () => {
        const pdf = Buffer.concat(buffers);
        res.setHeader("Content-Type", "application/pdf");
        res.setHeader("Content-Disposition", `attachment; filename="timesheets_${safeFilename(startDate || "all")}_${safeFilename(endDate || "all")}.pdf"`);
        res.send(pdf);
      });

      doc.rect(30, 25, 782, 28).fill("#1F3A5F");
      doc.fillColor("#fff").fontSize(12).font("Helvetica-Bold").text("TIMESHEET REPORT", 30, 30, { align: "center", width: 782 });
      doc.fillColor("#000");
      doc.moveDown(0.5);

      doc.fontSize(8).font("Helvetica").fillColor("#666");
      const periodText = startDate && endDate ? `${startDate} to ${endDate}` : "All Dates";
      doc.text(`Period: ${periodText}  |  Total Records: ${rows.length}`, { align: "center" });
      doc.moveDown(1);

      const cols = { date: 30, site: 90, officer: 250, start: 370, end: 420, bookOn: 470, bookOff: 540, hours: 610, late: 660, coords: 700 };
      const drawHeader = (y: number) => {
        doc.rect(30, y - 2, 782, 14).fill("#1F3A5F");
        doc.fillColor("#fff").fontSize(7).font("Helvetica-Bold");
        doc.text("Date", cols.date, y, { width: 55 });
        doc.text("Site Name", cols.site, y, { width: 155 });
        doc.text("Officer", cols.officer, y, { width: 115 });
        doc.text("Start", cols.start, y, { width: 45 });
        doc.text("End", cols.end, y, { width: 45 });
        doc.text("Book-On", cols.bookOn, y, { width: 65 });
        doc.text("Book-Off", cols.bookOff, y, { width: 65 });
        doc.text("Hours", cols.hours, y, { width: 45, align: "right" });
        doc.text("Late", cols.late, y, { width: 35, align: "right" });
        doc.text("Coordinates", cols.coords, y, { width: 112 });
        doc.fillColor("#000").font("Helvetica").fontSize(7);
      };

      let tableTop = doc.y;
      drawHeader(tableTop);
      let rowY = tableTop + 18;

      const fmtTs = (ts: string | null) => ts ? new Date(ts).toISOString().replace("T", " ").substring(11, 16) : "—";
      const fmtDate = (d: string) => { const dt = new Date(d); return `${String(dt.getDate()).padStart(2,"0")}/${String(dt.getMonth()+1).padStart(2,"0")}/${dt.getFullYear()}`; };

      for (let i = 0; i < rows.length; i++) {
        if (rowY > 550) {
          doc.addPage();
          rowY = 30;
          drawHeader(rowY);
          rowY += 18;
        }
        const r = rows[i];
        if (i % 2 === 0) { doc.rect(30, rowY - 2, 782, 12).fill("#f8f9fa"); doc.fillColor("#000"); }

        let hours = "—";
        if (r.booked_on_at && r.booked_off_at) {
          const diffMs = new Date(r.booked_off_at).getTime() - new Date(r.booked_on_at).getTime();
          const breakMs = (r.break_minutes || 0) * 60000;
          hours = (Math.round(((diffMs - breakMs) / 3600000) * 100) / 100).toFixed(2);
        }

        const late = r.late_minutes || 0;
        if (late > 5) doc.fillColor("#e74c3c");
        else if (late > 0) doc.fillColor("#f39c12");
        else doc.fillColor("#333");

        doc.text(fmtDate(r.date), cols.date, rowY, { width: 55 });
        doc.fillColor("#333");
        doc.text((r.site_name || "").substring(0, 30), cols.site, rowY, { width: 155 });
        doc.text(`${r.officer_first_name || ""} ${r.officer_last_name || ""}`.trim().substring(0, 22), cols.officer, rowY, { width: 115 });
        doc.text(r.start_time?.substring(0, 5) || "—", cols.start, rowY, { width: 45 });
        doc.text(r.end_time?.substring(0, 5) || "—", cols.end, rowY, { width: 45 });
        doc.text(fmtTs(r.booked_on_at), cols.bookOn, rowY, { width: 65 });
        doc.text(fmtTs(r.booked_off_at), cols.bookOff, rowY, { width: 65 });
        doc.text(hours, cols.hours, rowY, { width: 45, align: "right" });

        if (late > 5) doc.fillColor("#e74c3c");
        else if (late > 0) doc.fillColor("#f39c12");
        else doc.fillColor("#333");
        doc.text(String(late), cols.late, rowY, { width: 35, align: "right" });
        doc.fillColor("#333");

        const coordsText = r.last_check_in_lat && r.last_check_in_lng
          ? `${parseFloat(r.last_check_in_lat).toFixed(4)}, ${parseFloat(r.last_check_in_lng).toFixed(4)}` : "—";
        doc.text(coordsText, cols.coords, rowY, { width: 112 });

        rowY += 14;
      }

      doc.end();
    } catch (err: any) {
      console.error("timesheets pdf export error:", err);
      res.status(500).json({ message: err.message });
    }
  });

