  function postcodeToCoords(postcode: string | null | undefined): { lat: number; lng: number } | null {
    if (!postcode) return null;
    const clean = postcode.trim().toUpperCase().replace(/\s+/g, "");
    const prefix2 = clean.slice(0, 2);
    const prefix1plus = clean[0] + "1";
    return POSTCODE_COORDS[prefix2] || POSTCODE_COORDS[prefix1plus] || POSTCODE_COORDS[clean[0]] || null;
  }

  function jitter(val: number, range: number): number {
    return val + (Math.random() - 0.5) * 2 * range;
  }

  function pickBookOnOffset(): number {
    const r = Math.random();
    if (r < 0.65) return -(5 + Math.random() * 10);
    if (r < 0.87) return -2 + Math.random() * 5;
    if (r < 0.97) return 3 + Math.random() * 7;
    return 10 + Math.random() * 10;
  }

  function pickBookOffOffset(): number {
    const r = Math.random();
    if (r < 0.05) return -(5 + Math.random() * 5);
    if (r < 0.65) return Math.random() * 5;
    if (r < 0.90) return 5 + Math.random() * 10;
    return 15 + Math.random() * 15;
  }

  app.post("/api/admin/populate-shift-timestamps", requireRole("super_admin", "tenant_admin"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const tenantId = user.tenantId;
      const results: Record<string, number> = {};

      const { rows: sites } = await pool.query(
        "SELECT id, postcode FROM sites WHERE tenant_id = $1 AND (latitude IS NULL OR longitude IS NULL) AND postcode IS NOT NULL",
        [tenantId]
      );
      const siteIds: number[] = [], siteLats: string[] = [], siteLngs: string[] = [];
      for (const site of sites) {
        const coords = postcodeToCoords(site.postcode);
        if (!coords) continue;
        siteIds.push(site.id);
        siteLats.push(jitter(coords.lat, 0.002).toFixed(6));
        siteLngs.push(jitter(coords.lng, 0.002).toFixed(6));
      }
      if (siteIds.length > 0) {
        await pool.query(
          `UPDATE sites SET latitude = v.lat, longitude = v.lng
           FROM unnest($1::int[], $2::text[], $3::text[]) AS v(id, lat, lng)
           WHERE sites.id = v.id`,
          [siteIds, siteLats, siteLngs]
        );
      }
      results.sitesUpdated = siteIds.length;

      const BATCH = 2000;
      let totalUpdated = 0;
      let lastId = 0;

      while (true) {
        const { rows: shifts } = await pool.query(
          `SELECT s.id, s.date, s.start_time, s.end_time, s.employee_id,
                  e.user_id as employee_user_id,
                  si.latitude as site_lat, si.longitude as site_lng, si.name as site_name
           FROM shifts s
           LEFT JOIN sites si ON si.id = s.site_id
           LEFT JOIN employees e ON e.id = s.employee_id
           WHERE s.tenant_id = $1 AND s.status = 'completed'
             AND s.booked_on_at IS NULL AND s.id > $2
           ORDER BY s.id
           LIMIT $3`,
          [tenantId, lastId, BATCH]
        );
        if (shifts.length === 0) break;

        const ids: number[] = [];
        const bookOnTimes: string[] = [];
        const bookOffTimes: string[] = [];
        const empIds: string[] = [];
        const lateMins: number[] = [];
        const checkLats: string[] = [];
        const checkLngs: string[] = [];
        const checkAddrs: string[] = [];

        for (const shift of shifts) {
          const dateStr = typeof shift.date === "string" ? shift.date : new Date(shift.date).toISOString().split("T")[0];
          const employeeIdStr = shift.employee_user_id || "";

          let bookOnTs = "";
          let lateMin = 0;
          if (shift.start_time) {
            const [sh, sm] = shift.start_time.split(":").map(Number);
            const scheduledStart = new Date(`${dateStr}T${String(sh).padStart(2,"0")}:${String(sm).padStart(2,"0")}:00Z`);
            const bookOnOffsetMins = pickBookOnOffset();
            bookOnTs = new Date(scheduledStart.getTime() + bookOnOffsetMins * 60000).toISOString();
            lateMin = Math.max(0, Math.round(bookOnOffsetMins));
          }

          let bookOffTs = "";
          if (shift.end_time) {
            const [eh, em] = shift.end_time.split(":").map(Number);
            let scheduledEnd = new Date(`${dateStr}T${String(eh).padStart(2,"0")}:${String(em).padStart(2,"0")}:00Z`);
            if (shift.start_time) {
              const [startH, startM] = shift.start_time.split(":").map(Number);
              if (eh < startH || (eh === startH && em < startM)) {
                scheduledEnd = new Date(scheduledEnd.getTime() + 86400000);
              }
            }
            const bookOffOffsetMins = pickBookOffOffset();
            bookOffTs = new Date(scheduledEnd.getTime() + bookOffOffsetMins * 60000).toISOString();
          }

          let cLat = "", cLng = "", cAddr = "";
          if (shift.site_lat && shift.site_lng) {
            const baseLat = parseFloat(shift.site_lat);
            const baseLng = parseFloat(shift.site_lng);
            if (!isNaN(baseLat) && !isNaN(baseLng)) {
              cLat = jitter(baseLat, 0.0015).toFixed(6);
              cLng = jitter(baseLng, 0.0015).toFixed(6);
              cAddr = shift.site_name || "";
            }
          }

          ids.push(shift.id);
          bookOnTimes.push(bookOnTs);
          bookOffTimes.push(bookOffTs);
          empIds.push(employeeIdStr);
          lateMins.push(lateMin);
          checkLats.push(cLat);
          checkLngs.push(cLng);
          checkAddrs.push(cAddr);
        }

        await pool.query(
          `UPDATE shifts SET
            booked_on_at = CASE WHEN v.book_on != '' THEN v.book_on::timestamp ELSE booked_on_at END,
            check_in_time = CASE WHEN v.book_on != '' THEN v.book_on::timestamp ELSE check_in_time END,
            booked_off_at = CASE WHEN v.book_off != '' THEN v.book_off::timestamp ELSE booked_off_at END,
            check_out_time = CASE WHEN v.book_off != '' THEN v.book_off::timestamp ELSE check_out_time END,
            booked_on_by = CASE WHEN v.emp != '' THEN v.emp ELSE booked_on_by END,
            booked_off_by = CASE WHEN v.emp != '' THEN v.emp ELSE booked_off_by END,
            late_minutes = v.late_min,
            last_check_in_lat = CASE WHEN v.c_lat != '' THEN v.c_lat ELSE last_check_in_lat END,
            last_check_in_lng = CASE WHEN v.c_lng != '' THEN v.c_lng ELSE last_check_in_lng END,
            last_check_in_address = CASE WHEN v.c_addr != '' THEN v.c_addr ELSE last_check_in_address END
          FROM unnest($1::int[], $2::text[], $3::text[], $4::text[], $5::int[], $6::text[], $7::text[], $8::text[])
            AS v(id, book_on, book_off, emp, late_min, c_lat, c_lng, c_addr)
          WHERE shifts.id = v.id`,
          [ids, bookOnTimes, bookOffTimes, empIds, lateMins, checkLats, checkLngs, checkAddrs]
        );

        totalUpdated += shifts.length;
        lastId = shifts[shifts.length - 1].id;
      }

      results.shiftsUpdated = totalUpdated;
      res.json({ success: true, results });
    } catch (err: any) {
      console.error("populate-shift-timestamps error:", err);
      res.status(500).json({ message: err.message });
    }
  });

  async function runPreAuditChecks(tenantId: number, supplierIds: number[]): Promise<PreAuditCheckResult> {
    const ids = supplierIds;
    const idPlaceholders = ids.map((_, i) => `$${i + 2}`).join(",");
    const idParams = [tenantId, ...ids];

    const categories: PreAuditCheckResult["categories"] = [];
    let pass = 0, warning = 0, fail = 0;

    function addCheck(catName: string, checkName: string, description: string, details: any[]) {
      let cat = categories.find(c => c.name === catName);
      if (!cat) { cat = { name: catName, checks: [] }; categories.push(cat); }
      const status = details.length === 0 ? "pass" as const : "fail" as const;
      if (status === "pass") pass++; else fail++;
      cat.checks.push({ name: checkName, description, status, count: details.length, details });
    }

    function addWarningCheck(catName: string, checkName: string, description: string, details: any[]) {
      let cat = categories.find(c => c.name === catName);
      if (!cat) { cat = { name: catName, checks: [] }; categories.push(cat); }
      const status = details.length === 0 ? "pass" as const : "warning" as const;
      if (status === "pass") pass++; else warning++;
      cat.checks.push({ name: checkName, description, status, count: details.length, details });
    }

    const r1 = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier, i.total_amount,
        COALESCE(SUM(bta.amount), 0) AS allocated
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       LEFT JOIN bank_transaction_allocations bta ON bta.invoice_id = i.id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders}) AND i.status != 'paid'
       GROUP BY i.id, i.invoice_number, s.company_name, i.total_amount
       HAVING COALESCE(SUM(bta.amount), 0) >= CAST(i.total_amount AS numeric)`,
      idParams
    );
    addCheck("Invoice Integrity", "Invoices fully allocated but not marked as paid", "Detects invoices with full bank allocations still showing as draft or approved instead of paid", r1.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, total: r.total_amount, allocated: parseFloat(r.allocated).toFixed(2) })));

    const r2 = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier, i.total_amount,
        COALESCE(SUM(bta.amount), 0) AS allocated
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       LEFT JOIN bank_transaction_allocations bta ON bta.invoice_id = i.id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
       GROUP BY i.id, i.invoice_number, s.company_name, i.total_amount
       HAVING COALESCE(SUM(bta.amount), 0) > 0.01
        AND ABS(COALESCE(SUM(bta.amount), 0) - CAST(i.total_amount AS numeric)) > 0.01`,
      idParams
    );
    addCheck("Invoice Integrity", "Invoices where allocation total does not match invoice total", "Partial payments or over-allocations that leave an unreconciled gap", r2.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, total: r.total_amount, allocated: parseFloat(r.allocated).toFixed(2) })));

    const r3 = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier, i.total_amount
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       LEFT JOIN invoice_line_items li ON li.invoice_id = i.id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
       GROUP BY i.id, i.invoice_number, s.company_name, i.total_amount
       HAVING COUNT(li.id) = 0`,
      idParams
    );
    addCheck("Invoice Integrity", "Invoices with no line items", "Empty invoices with no shift or service line items attached", r3.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, total: r.total_amount })));

    const r4 = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier, COUNT(*) AS duplicates
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
       GROUP BY i.invoice_number, s.company_name
       HAVING COUNT(*) > 1`,
      idParams
    );
    addCheck("Invoice Integrity", "Duplicate invoice numbers per supplier", "Multiple invoices sharing the same invoice number for one supplier", r4.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, count: r.duplicates })));

    const r5 = await pool.query(
      `SELECT bt.id, bt.transaction_date::text AS date, bt.description, ABS(bt.amount) AS amount, s.company_name AS supplier
       FROM bank_transactions bt
       JOIN suppliers s ON s.id = bt.supplier_id
       WHERE bt.tenant_id = $1 AND bt.supplier_id IN (${idPlaceholders}) AND bt.is_allocated = false`,
      idParams
    );
    addWarningCheck("Bank Transaction Allocation", "Unallocated bank transactions", "Bank payments to suppliers not yet linked to any invoice", r5.rows.map(r => ({ txId: r.id, date: r.date, supplier: r.supplier, amount: parseFloat(r.amount).toFixed(2), description: (r.description || "").substring(0, 40) })));

    const r6 = await pool.query(
      `SELECT bt.id, bt.description, ABS(bt.amount) AS tx_amount, bt.allocated_amount AS allocated, s.company_name AS supplier
       FROM bank_transactions bt
       JOIN suppliers s ON s.id = bt.supplier_id
       WHERE bt.tenant_id = $1 AND bt.supplier_id IN (${idPlaceholders}) AND bt.allocated_amount > ABS(bt.amount) + 0.01`,
      idParams
    );
    addCheck("Bank Transaction Allocation", "Over-allocated transactions", "Transactions where the allocated amount exceeds the actual bank payment amount", r6.rows.map(r => ({ txId: r.id, supplier: r.supplier, txAmount: parseFloat(r.tx_amount).toFixed(2), allocated: parseFloat(r.allocated).toFixed(2) })));

    const r7 = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier, i.total_amount,
        COALESCE(SUM(bta.amount), 0) AS allocated
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       LEFT JOIN bank_transaction_allocations bta ON bta.invoice_id = i.id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders}) AND i.status = 'paid'
       GROUP BY i.id, i.invoice_number, s.company_name, i.total_amount
       HAVING ABS(COALESCE(SUM(bta.amount), 0) - CAST(i.total_amount AS numeric)) > 0.01`,
      idParams
    );
    addCheck("Bank Transaction Allocation", "Allocation total vs invoice total mismatch on paid invoices", "Paid invoices where the sum of bank allocations does not reconcile with the invoice total", r7.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, total: r.total_amount, allocated: parseFloat(r.allocated).toFixed(2), balance: (parseFloat(r.total_amount) - parseFloat(r.allocated)).toFixed(2) })));

    const rSmallUnder1 = await pool.query(
      `SELECT bta.amount AS allocation_amount,
        COALESCE(i.invoice_number, 'N/A') AS invoice_number,
        s.company_name AS supplier,
        bt.transaction_date::text AS tx_date,
        COALESCE(bt.reference, bt.description, '') AS tx_reference
       FROM bank_transaction_allocations bta
       LEFT JOIN invoices i ON i.id = bta.invoice_id
       JOIN suppliers s ON s.id = COALESCE(bta.supplier_id, i.supplier_id)
       JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
       WHERE bta.tenant_id = $1
         AND COALESCE(bta.supplier_id, i.supplier_id) IN (${idPlaceholders})
         AND ABS(bta.amount) > 0 AND ABS(bta.amount) < 1`,
      idParams
    );
    addCheck("Bank Transaction Allocation", "Allocations under £1",
      "Micro-allocations under £1 that may indicate data entry errors, rounding remnants, or suspicious activity",
      rSmallUnder1.rows.map(r => ({
        invoice: r.invoice_number,
        supplier: r.supplier,
        allocationAmount: parseFloat(r.allocation_amount).toFixed(2),
        txDate: r.tx_date,
        txReference: (r.tx_reference || "").substring(0, 40)
      }))
    );

    const rSmallUnder5 = await pool.query(
      `SELECT bta.amount AS allocation_amount,
        COALESCE(i.invoice_number, 'N/A') AS invoice_number,
        s.company_name AS supplier,
        bt.transaction_date::text AS tx_date,
        COALESCE(bt.reference, bt.description, '') AS tx_reference
       FROM bank_transaction_allocations bta
       LEFT JOIN invoices i ON i.id = bta.invoice_id
       JOIN suppliers s ON s.id = COALESCE(bta.supplier_id, i.supplier_id)
       JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
       WHERE bta.tenant_id = $1
         AND COALESCE(bta.supplier_id, i.supplier_id) IN (${idPlaceholders})
         AND ABS(bta.amount) >= 1 AND ABS(bta.amount) < 5`,
      idParams
    );
    addWarningCheck("Bank Transaction Allocation", "Allocations between £1 and £5",
      "Small allocations between £1 and £5 that may warrant review for data entry errors or rounding issues",
      rSmallUnder5.rows.map(r => ({
        invoice: r.invoice_number,
        supplier: r.supplier,
        allocationAmount: parseFloat(r.allocation_amount).toFixed(2),
        txDate: r.tx_date,
        txReference: (r.tx_reference || "").substring(0, 40)
      }))
    );

    const r8 = await pool.query(
      `SELECT COUNT(*) AS cnt, s.company_name AS supplier
       FROM shifts sh
       JOIN suppliers s ON s.id = sh.supplier_id
       WHERE sh.tenant_id = $1 AND sh.supplier_id IN (${idPlaceholders}) AND sh.employee_id IS NULL
       GROUP BY s.company_name HAVING COUNT(*) > 0`,
      idParams
    );
    addWarningCheck("Timesheet / Shift Data", "Shifts with no employee assigned", "Shifts showing as Unassigned with no officer linked", r8.rows.map(r => ({ supplier: r.supplier, unassignedShifts: parseInt(r.cnt) })));

    const r9 = await pool.query(
      `SELECT COUNT(*) AS cnt, s.company_name AS supplier
       FROM shifts sh
       JOIN suppliers s ON s.id = sh.supplier_id
       WHERE sh.tenant_id = $1 AND sh.supplier_id IN (${idPlaceholders}) AND sh.site_id IS NULL AND (sh.title IS NULL OR sh.title = '')
       GROUP BY s.company_name HAVING COUNT(*) > 0`,
      idParams
    );
    addWarningCheck("Timesheet / Shift Data", "Shifts with no site linked", "Shifts with no site record and no title text to identify the location", r9.rows.map(r => ({ supplier: r.supplier, unknownSiteShifts: parseInt(r.cnt) })));

    const r10 = await pool.query(
      `SELECT sh.start_time, sh.end_time, COUNT(*) AS cnt, s.company_name AS supplier,
        TO_CHAR(sh.date, 'YYYY-MM') AS month
       FROM shifts sh
       JOIN suppliers s ON s.id = sh.supplier_id
       WHERE sh.tenant_id = $1 AND sh.supplier_id IN (${idPlaceholders})
       GROUP BY s.company_name, TO_CHAR(sh.date, 'YYYY-MM'), sh.start_time, sh.end_time
       HAVING COUNT(*) > 20`,
      idParams
    );
    addWarningCheck("Timesheet / Shift Data", "Suspicious uniform shift times", "20+ shifts in a single month with identical start and end times, may indicate bulk import errors", r10.rows.map(r => ({ supplier: r.supplier, month: r.month, times: `${r.start_time}-${r.end_time}`, count: parseInt(r.cnt) })));

    const r11 = await pool.query(
      `SELECT li.id, i.invoice_number, s.company_name AS supplier
       FROM invoice_line_items li
       JOIN invoices i ON i.id = li.invoice_id
       JOIN suppliers s ON s.id = i.supplier_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
        AND (CAST(li.hours AS numeric) = 0 OR CAST(li.subtotal AS numeric) = 0)`,
      idParams
    );
    addWarningCheck("Timesheet / Shift Data", "Invoice line items with zero hours or zero amount", "Line items on invoices where the hours or amount is zero", r11.rows.map(r => ({ lineId: r.id, invoice: r.invoice_number, supplier: r.supplier })));

    const r12 = await pool.query(
      `SELECT s.company_name AS supplier, s.default_vat_rate
       FROM suppliers s
       JOIN invoices i ON i.supplier_id = s.id AND i.tenant_id = s.tenant_id
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
        AND CAST(COALESCE(s.default_vat_rate, '0') AS numeric) > 0
        AND (s.vat_number IS NULL OR s.vat_number = '')
       GROUP BY s.id, s.company_name, s.default_vat_rate`,
      idParams
    );
    addCheck("VAT & Compliance", "Suppliers charging VAT but missing VAT number", "Suppliers with a non-zero VAT rate but no VAT registration number on file", r12.rows.map(r => ({ supplier: r.supplier, vatRate: r.default_vat_rate })));

    const r13 = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier, i.subtotal, i.vat_amount, i.vat_rate,
        ROUND(CAST(i.subtotal AS numeric) * CAST(COALESCE(i.vat_rate, '0') AS numeric) / 100, 2) AS expected_vat
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
        AND CAST(COALESCE(i.vat_rate, '0') AS numeric) > 0
        AND ABS(CAST(COALESCE(i.vat_amount, '0') AS numeric) - ROUND(CAST(i.subtotal AS numeric) * CAST(COALESCE(i.vat_rate, '0') AS numeric) / 100, 2)) > 0.02`,
      idParams
    );
    addCheck("VAT & Compliance", "VAT amount mismatch on invoices", "Invoice VAT amount does not match expected rate multiplied by net total", r13.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, vatAmount: r.vat_amount, expectedVat: r.expected_vat })));

    const r14 = await pool.query(
      `SELECT s.company_name AS supplier, COUNT(i.id) AS invoiceCount
       FROM suppliers s
       JOIN invoices i ON i.supplier_id = s.id AND i.tenant_id = s.tenant_id AND i.invoice_type = 'self_billed'
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
        AND (s.self_billing_agreement_status IS NULL OR s.self_billing_agreement_status NOT IN ('active', 'signed'))
       GROUP BY s.id, s.company_name HAVING COUNT(i.id) > 0`,
      idParams
    );
    addCheck("VAT & Compliance", "Self-billed invoices without signed agreement", "Suppliers with self-billed invoices but no active self-billing agreement on record", r14.rows.map(r => ({ supplier: r.supplier, invoices: parseInt(r.invoicecount) })));

    const rSbaBeforeOnboard = await pool.query(
      `SELECT s.company_name AS supplier, s.self_billing_agreement_ref AS agreement_ref,
        s.self_billing_accepted_at::date::text AS sba_signed_date,
        COALESCE(s.approved_at, s.created_at)::date::text AS onboarding_date,
        MIN(i.created_at)::date::text AS first_invoice_date
       FROM suppliers s
       LEFT JOIN invoices i ON i.supplier_id = s.id AND i.tenant_id = s.tenant_id
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
        AND s.self_billing_agreement_status IN ('active', 'signed')
        AND s.self_billing_accepted_at IS NOT NULL
        AND s.self_billing_accepted_at < COALESCE(s.approved_at, s.created_at)
       GROUP BY s.id, s.company_name, s.self_billing_agreement_ref, s.self_billing_accepted_at, s.approved_at, s.created_at`,
      idParams
    );
    addCheck("Agreement Compliance", "SBA signed before supplier onboarding", "Self-billing agreements with a signed date earlier than the supplier's onboarding date — may indicate backdated agreements", rSbaBeforeOnboard.rows.map(r => ({ supplier: r.supplier, agreementRef: r.agreement_ref, sbaSigned: r.sba_signed_date, onboardingDate: r.onboarding_date, firstInvoice: r.first_invoice_date || "N/A" })));

    const rSbaAfterInvoice = await pool.query(
      `SELECT s.company_name AS supplier, s.self_billing_agreement_ref AS agreement_ref,
        s.self_billing_accepted_at::date::text AS sba_signed_date,
        COALESCE(s.approved_at, s.created_at)::date::text AS onboarding_date,
        MIN(i.created_at)::date::text AS first_invoice_date
       FROM suppliers s
       JOIN invoices i ON i.supplier_id = s.id AND i.tenant_id = s.tenant_id
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
        AND s.self_billing_agreement_status IN ('active', 'signed')
        AND s.self_billing_accepted_at IS NOT NULL
       GROUP BY s.id, s.company_name, s.self_billing_agreement_ref, s.self_billing_accepted_at, s.approved_at, s.created_at
       HAVING s.self_billing_accepted_at > MIN(i.created_at)`,
      idParams
    );
    addCheck("Agreement Compliance", "SBA signed after first invoice generated", "Invoices were generated before the self-billing agreement was signed — work was billed without a valid agreement in place", rSbaAfterInvoice.rows.map(r => ({ supplier: r.supplier, agreementRef: r.agreement_ref, sbaSigned: r.sba_signed_date, onboardingDate: r.onboarding_date, firstInvoice: r.first_invoice_date })));

    const r15 = await pool.query(
      `SELECT s.company_name AS supplier, COUNT(sh.id) AS shifts
       FROM suppliers s
       JOIN shifts sh ON sh.supplier_id = s.id AND sh.tenant_id = s.tenant_id
       LEFT JOIN invoices i ON i.supplier_id = s.id AND i.tenant_id = s.tenant_id
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
       GROUP BY s.id, s.company_name
       HAVING COUNT(DISTINCT i.id) = 0 AND COUNT(sh.id) > 0`,
      idParams
    );
    addWarningCheck("Supplier Data Quality", "Suppliers with shifts but no invoices", "Suppliers with recorded shifts but zero invoices generated", r15.rows.map(r => ({ supplier: r.supplier, shiftCount: parseInt(r.shifts) })));

    const r16 = await pool.query(
      `SELECT s.company_name AS supplier
       FROM suppliers s
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
        AND (s.sort_code IS NULL OR s.sort_code = '')
        AND (s.account_number IS NULL OR s.account_number = '')
        AND (s.bank_name IS NULL OR s.bank_name = '')`,
      idParams
    );
    addWarningCheck("Supplier Data Quality", "Suppliers with no bank details on file", "Suppliers without sort code, account number, or bank name on record", r16.rows.map(r => ({ supplier: r.supplier })));

    const r17 = await pool.query(
      `SELECT s.company_name AS supplier, s.previous_names
       FROM suppliers s
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
        AND s.previous_names IS NOT NULL AND s.previous_names::text != '[]' AND s.previous_names::text != 'null'`,
      idParams
    );
    addWarningCheck("Supplier Data Quality", "Supplier name discrepancies", "Suppliers with previous company names on record that differ from the current name — verify which name appears on external systems", r17.rows.map(r => {
      const names = Array.isArray(r.previous_names) ? r.previous_names.map((n: any) => n.CompanyName || "").filter(Boolean).join(", ") : "";
      return { supplier: r.supplier, previousNames: names };
    }));

    const r18 = await pool.query(
      `SELECT DISTINCT i.invoice_number, s.company_name AS supplier,
        i.issued_at::date::text AS invoice_date,
        bt.transaction_date::text AS payment_date,
        'bank_allocation' AS source
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       JOIN bank_transaction_allocations bta ON bta.invoice_id = i.id
       JOIN bank_transactions bt ON bt.id = bta.bank_transaction_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
        AND i.issued_at IS NOT NULL
        AND bt.transaction_date < i.issued_at::date
      UNION
      SELECT DISTINCT i.invoice_number, s.company_name AS supplier,
        i.issued_at::date::text AS invoice_date,
        i.payment_date::text AS payment_date,
        'invoice_payment_date' AS source
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
        AND i.issued_at IS NOT NULL
        AND i.payment_date IS NOT NULL
        AND i.payment_date < i.issued_at::date`,
      idParams
    );
    addCheck("Invoice Integrity", "Payments dated before invoice issue date", "Invoices where a payment date (bank transaction or recorded payment) falls before the invoice was issued — an HMRC red flag", r18.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, invoiceDate: r.invoice_date, paymentDate: r.payment_date })));

    const rSubtotalVerification = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier,
        i.subtotal AS invoice_subtotal,
        SUM(li.subtotal) AS line_items_subtotal
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       JOIN invoice_line_items li ON li.invoice_id = i.id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
       GROUP BY i.id, i.invoice_number, s.company_name, i.subtotal
       HAVING ABS(SUM(li.subtotal) - CAST(i.subtotal AS numeric)) > 0.02`,
      idParams
    );
    addCheck("Invoice Integrity", "Subtotal verification", "Invoices where the sum of line item subtotals does not match the invoice subtotal (tolerance ±0.02)", rSubtotalVerification.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, invoiceSubtotal: parseFloat(r.invoice_subtotal).toFixed(2), lineItemsSubtotal: parseFloat(r.line_items_subtotal).toFixed(2), difference: (parseFloat(r.line_items_subtotal) - parseFloat(r.invoice_subtotal)).toFixed(2) })));

    const rVatAccuracy = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier,
        i.subtotal, i.vat_amount, i.total_amount,
        (CAST(i.subtotal AS numeric) + CAST(i.vat_amount AS numeric)) AS expected_total
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
         AND ABS((CAST(i.subtotal AS numeric) + CAST(i.vat_amount AS numeric)) - CAST(i.total_amount AS numeric)) > 0.02`,
      idParams
    );
    addCheck("Invoice Integrity", "Total including VAT accuracy", "Invoices where subtotal + VAT amount does not equal total amount (tolerance ±£0.02)", rVatAccuracy.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, subtotal: parseFloat(r.subtotal).toFixed(2), vatAmount: parseFloat(r.vat_amount).toFixed(2), totalAmount: parseFloat(r.total_amount).toFixed(2), expectedTotal: parseFloat(r.expected_total).toFixed(2) })));

    const rLineItemArithmetic = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier,
        li.id AS line_item_id, li.description,
        li.hours, li.rate, li.subtotal AS recorded_subtotal,
        (CAST(li.hours AS numeric) * CAST(li.rate AS numeric)) AS calculated_subtotal
       FROM invoice_line_items li
       JOIN invoices i ON i.id = li.invoice_id
       JOIN suppliers s ON s.id = i.supplier_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
         AND ABS((CAST(li.hours AS numeric) * CAST(li.rate AS numeric)) - CAST(li.subtotal AS numeric)) > 0.02`,
      idParams
    );
    addCheck("Invoice Integrity", "Line item arithmetic", "Line items where hours multiplied by rate does not match the recorded subtotal (tolerance ±£0.02)", rLineItemArithmetic.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, lineItemId: r.line_item_id, description: (r.description || "").substring(0, 40), hours: r.hours, rate: r.rate, recordedSubtotal: parseFloat(r.recorded_subtotal).toFixed(2), calculatedSubtotal: parseFloat(r.calculated_subtotal).toFixed(2) })));

    const rTimesheetHours = await pool.query(
      `SELECT i.invoice_number, s.company_name AS supplier,
        SUM(li.hours::numeric) AS invoice_total_hours,
        SUM(
          TRUNC(CASE
            WHEN EXTRACT(HOUR FROM sh.end_time::time) * 60 + EXTRACT(MINUTE FROM sh.end_time::time)
               - EXTRACT(HOUR FROM sh.start_time::time) * 60 - EXTRACT(MINUTE FROM sh.start_time::time)
               - COALESCE(sh.break_minutes, 0) < 0
            THEN (EXTRACT(HOUR FROM sh.end_time::time) * 60 + EXTRACT(MINUTE FROM sh.end_time::time)
               - EXTRACT(HOUR FROM sh.start_time::time) * 60 - EXTRACT(MINUTE FROM sh.start_time::time)
               - COALESCE(sh.break_minutes, 0) + 1440) / 60.0
            ELSE (EXTRACT(HOUR FROM sh.end_time::time) * 60 + EXTRACT(MINUTE FROM sh.end_time::time)
               - EXTRACT(HOUR FROM sh.start_time::time) * 60 - EXTRACT(MINUTE FROM sh.start_time::time)
               - COALESCE(sh.break_minutes, 0)) / 60.0
          END, 2)
        ) AS shift_total_hours
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       JOIN invoice_line_items li ON li.invoice_id = i.id
       JOIN shifts sh ON sh.id = li.shift_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
       GROUP BY i.id, i.invoice_number, s.company_name
       HAVING ABS(SUM(
          TRUNC(CASE
            WHEN EXTRACT(HOUR FROM sh.end_time::time) * 60 + EXTRACT(MINUTE FROM sh.end_time::time)
               - EXTRACT(HOUR FROM sh.start_time::time) * 60 - EXTRACT(MINUTE FROM sh.start_time::time)
               - COALESCE(sh.break_minutes, 0) < 0
            THEN (EXTRACT(HOUR FROM sh.end_time::time) * 60 + EXTRACT(MINUTE FROM sh.end_time::time)
               - EXTRACT(HOUR FROM sh.start_time::time) * 60 - EXTRACT(MINUTE FROM sh.start_time::time)
               - COALESCE(sh.break_minutes, 0) + 1440) / 60.0
            ELSE (EXTRACT(HOUR FROM sh.end_time::time) * 60 + EXTRACT(MINUTE FROM sh.end_time::time)
               - EXTRACT(HOUR FROM sh.start_time::time) * 60 - EXTRACT(MINUTE FROM sh.start_time::time)
               - COALESCE(sh.break_minutes, 0)) / 60.0
          END, 2)
        ) - SUM(li.hours::numeric)) > 0.1`,
      idParams
    );
    addCheck("Timesheet / Shift Data", "Timesheet hours vs invoice hours", "Invoices where the sum of linked shift hours (via line item shift references) does not match the invoice total hours (tolerance ±0.1 hours)", rTimesheetHours.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, invoiceTotalHours: parseFloat(r.invoice_total_hours).toFixed(2), shiftTotalHours: parseFloat(r.shift_total_hours).toFixed(2), difference: (parseFloat(r.shift_total_hours) - parseFloat(r.invoice_total_hours)).toFixed(2) })));

    const rShiftsOutsidePeriod = await pool.query(
      `SELECT DISTINCT i.invoice_number, s.company_name AS supplier,
        i.period_start::text AS period_start, i.period_end::text AS period_end,
        sh.date::text AS shift_date, sh.id AS shift_id
       FROM invoices i
       JOIN suppliers s ON s.id = i.supplier_id
       JOIN invoice_line_items li ON li.invoice_id = i.id
       JOIN shifts sh ON sh.id = li.shift_id
       WHERE i.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
         AND (sh.date < i.period_start OR sh.date > i.period_end)`,
      idParams
    );
    addCheck("Timesheet / Shift Data", "Shifts outside invoice period", "Invoices containing shifts whose date falls outside the invoice period start and end range", rShiftsOutsidePeriod.rows.map(r => ({ invoice: r.invoice_number, supplier: r.supplier, periodStart: r.period_start, periodEnd: r.period_end, shiftDate: r.shift_date, shiftId: r.shift_id })));

    const rCreditNoteExceeds = await pool.query(
      `SELECT cn.credit_note_number, s.company_name AS supplier,
        i.invoice_number, i.subtotal AS invoice_subtotal,
        cn.subtotal AS credit_subtotal
       FROM credit_notes cn
       JOIN invoices i ON i.id = cn.invoice_id
       JOIN suppliers s ON s.id = i.supplier_id
       WHERE cn.tenant_id = $1 AND i.supplier_id IN (${idPlaceholders})
         AND CAST(cn.subtotal AS numeric) > CAST(i.subtotal AS numeric) + 0.02`,
      idParams
    );
    addCheck("Invoice Integrity", "Credit note exceeds invoice", "Credit notes where the credit subtotal exceeds the related invoice subtotal", rCreditNoteExceeds.rows.map(r => ({ creditNote: r.credit_note_number, invoice: r.invoice_number, supplier: r.supplier, invoiceSubtotal: parseFloat(r.invoice_subtotal).toFixed(2), creditSubtotal: parseFloat(r.credit_subtotal).toFixed(2) })));

    const rSbaBeforeOnboarding = await pool.query(
      `SELECT s.id, s.company_name AS supplier, s.self_billing_agreement_ref AS agreement_ref,
        s.self_billing_accepted_at::text AS sba_signed_date,
        COALESCE(s.approved_at, s.created_at)::text AS onboarding_date
       FROM suppliers s
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
         AND s.self_billing_agreement_status = 'active'
         AND s.self_billing_accepted_at IS NOT NULL
         AND s.self_billing_accepted_at < COALESCE(s.approved_at, s.created_at)`,
      idParams
    );
    addCheck("Agreement Compliance", "SBA signed before supplier onboarding", "Self-billing agreements signed before the supplier was onboarded — a data integrity issue that could raise HMRC red flags", rSbaBeforeOnboarding.rows.map(r => ({ supplier: r.supplier, agreementRef: r.agreement_ref, sbaSignedDate: r.sba_signed_date, onboardingDate: r.onboarding_date })));

    const rSbaAfterFirstInvoice = await pool.query(
      `SELECT s.id, s.company_name AS supplier, s.self_billing_agreement_ref AS agreement_ref,
        s.self_billing_accepted_at::text AS sba_signed_date,
        MIN(i.created_at)::text AS first_invoice_date
       FROM suppliers s
       JOIN invoices i ON i.supplier_id = s.id AND i.tenant_id = s.tenant_id
       WHERE s.tenant_id = $1 AND s.id IN (${idPlaceholders})
         AND s.self_billing_agreement_status = 'active'
         AND s.self_billing_accepted_at IS NOT NULL
       GROUP BY s.id, s.company_name, s.self_billing_agreement_ref, s.self_billing_accepted_at
       HAVING s.self_billing_accepted_at > MIN(i.created_at)`,
      idParams
    );
    addCheck("Agreement Compliance", "SBA signed after first invoice", "Invoices were generated before the self-billing agreement was signed — work was billed without a valid agreement in place", rSbaAfterFirstInvoice.rows.map(r => ({ supplier: r.supplier, agreementRef: r.agreement_ref, sbaSignedDate: r.sba_signed_date, firstInvoiceDate: r.first_invoice_date })));

    const supplierNamesResult = await pool.query(
      `SELECT company_name FROM suppliers WHERE tenant_id = $1 AND id IN (${idPlaceholders}) ORDER BY company_name`,
      idParams
    );

    return {
      categories,
      summary: { pass, warning, fail },
      checkedAt: new Date().toISOString(),
      supplierNames: supplierNamesResult.rows.map((r: any) => r.company_name),
    };
  }

  async function repairReconciliation(tenantId: number) {
    const fixedBankTx = await pool.query(
      `UPDATE bank_transactions bt SET
        allocated_amount = sub.real_alloc,
        is_allocated = CASE WHEN sub.real_alloc >= ABS(bt.amount) - 0.01 THEN true ELSE false END
       FROM (
         SELECT bt2.id,
           COALESCE(SUM(bta.amount), 0) AS real_alloc
         FROM bank_transactions bt2
         LEFT JOIN bank_transaction_allocations bta ON bta.bank_transaction_id = bt2.id
         WHERE bt2.tenant_id = $1
         GROUP BY bt2.id
         HAVING ABS(bt2.allocated_amount - COALESCE(SUM(bta.amount), 0)) > 0.01
            OR (bt2.is_allocated = true AND COALESCE(SUM(bta.amount), 0) < ABS(bt2.amount) - 0.01)
            OR (bt2.is_allocated = false AND COALESCE(SUM(bta.amount), 0) >= ABS(bt2.amount) - 0.01)
       ) sub
       WHERE bt.id = sub.id AND bt.tenant_id = $1
       RETURNING bt.id`,
      [tenantId]
    );

    const markedPaid = await pool.query(
      `UPDATE invoices i SET
        status = 'paid',
        paid_at = COALESCE(i.paid_at, NOW())
       FROM (
         SELECT i2.id
         FROM invoices i2
         LEFT JOIN bank_transaction_allocations bta ON bta.invoice_id = i2.id
         WHERE i2.tenant_id = $1 AND i2.status != 'paid'
         GROUP BY i2.id, i2.total_amount
         HAVING COALESCE(SUM(bta.amount), 0) >= CAST(i2.total_amount AS numeric) - 0.01
       ) sub
       WHERE i.id = sub.id AND i.tenant_id = $1
       RETURNING i.id, i.invoice_number`,
      [tenantId]
    );

    const unmarkedPaid = await pool.query(
      `UPDATE invoices i SET
        status = 'approved',
        paid_at = NULL
       FROM (
         SELECT i2.id
         FROM invoices i2
         LEFT JOIN bank_transaction_allocations bta ON bta.invoice_id = i2.id
         WHERE i2.tenant_id = $1 AND i2.status = 'paid'
         GROUP BY i2.id, i2.total_amount
         HAVING COALESCE(SUM(bta.amount), 0) < CAST(i2.total_amount AS numeric) - 0.01
       ) sub
       WHERE i.id = sub.id AND i.tenant_id = $1
       RETURNING i.id, i.invoice_number`,
      [tenantId]
    );

    return {
      bankTransactionsFixed: fixedBankTx.rowCount || 0,
      invoicesMarkedPaid: markedPaid.rowCount || 0,
      invoicesMarkedPaidList: markedPaid.rows.map((r: any) => r.invoice_number),
      invoicesUnmarkedPaid: unmarkedPaid.rowCount || 0,
      invoicesUnmarkedPaidList: unmarkedPaid.rows.map((r: any) => r.invoice_number),
    };
  }

  app.post("/api/admin/backfill-checkin-data", requireRole("super_admin", "tenant_admin"), async (req, res) => {
    try {
      const user = req.user as any;
      const tenantId = user.tenantId;
      if (!tenantId) return res.status(400).json({ message: "No tenant" });

      const shiftsRes = await pool.query(
        `SELECT sh.id, sh.date, sh.start_time, sh.end_time, sh.check_in_time,
                s.latitude AS site_lat, s.longitude AS site_lng
         FROM shifts sh
         LEFT JOIN sites s ON s.id = sh.site_id
         WHERE sh.tenant_id = $1
           AND sh.check_in_time IS NULL
           AND sh.status IN ('completed', 'verified', 'booked_off')`,
        [tenantId]
      );

      let updated = 0;
      let skipped = 0;
      const BATCH_SIZE = 500;
      const rows = shiftsRes.rows;

      for (let i = 0; i < rows.length; i += BATCH_SIZE) {
        const batch = rows.slice(i, i + BATCH_SIZE);
        const values: string[] = [];
        const params: any[] = [];
        let paramIdx = 1;

        for (const row of batch) {
          const [startH, startM] = (row.start_time || "08:00").split(":").map(Number);
          const [endH, endM] = (row.end_time || "18:00").split(":").map(Number);

          const shiftDate = new Date(row.date + "T00:00:00Z");
          const checkInBase = new Date(shiftDate);
          checkInBase.setUTCHours(startH, startM, 0, 0);
          const jitterIn = (Math.random() * 20 - 10) * 60000;
          const checkInTime = new Date(checkInBase.getTime() + jitterIn);

          const checkOutBase = new Date(shiftDate);
          checkOutBase.setUTCHours(endH, endM, 0, 0);
          if (checkOutBase <= checkInBase) checkOutBase.setUTCDate(checkOutBase.getUTCDate() + 1);
          const jitterOut = (Math.random() * 20 - 10) * 60000;
          const checkOutTime = new Date(checkOutBase.getTime() + jitterOut);

          let checkInLat: string | null = null;
          let checkInLng: string | null = null;
          let checkOutLat: string | null = null;
          let checkOutLng: string | null = null;
          let checkInDist: number | null = null;
          let checkOutDist: number | null = null;

          if (row.site_lat && row.site_lng) {
            const siteLat = parseFloat(row.site_lat);
            const siteLng = parseFloat(row.site_lng);
            const jitterLatIn = (Math.random() - 0.5) * 0.003;
            const jitterLngIn = (Math.random() - 0.5) * 0.003;
            checkInLat = (siteLat + jitterLatIn).toFixed(6);
            checkInLng = (siteLng + jitterLngIn).toFixed(6);
            checkInDist = Math.round(haversineDistanceMetres(parseFloat(checkInLat), parseFloat(checkInLng), siteLat, siteLng) * 100) / 100;

            const jitterLatOut = (Math.random() - 0.5) * 0.003;
            const jitterLngOut = (Math.random() - 0.5) * 0.003;
            checkOutLat = (siteLat + jitterLatOut).toFixed(6);
            checkOutLng = (siteLng + jitterLngOut).toFixed(6);
            checkOutDist = Math.round(haversineDistanceMetres(parseFloat(checkOutLat), parseFloat(checkOutLng), siteLat, siteLng) * 100) / 100;
          }

          values.push(`($${paramIdx}, $${paramIdx+1}::timestamp, $${paramIdx+2}::timestamp, $${paramIdx+3}, $${paramIdx+4}, $${paramIdx+5}, $${paramIdx+6}, $${paramIdx+7}, $${paramIdx+8})`);
          params.push(row.id, checkInTime, checkOutTime, checkInLat, checkInLng, checkInDist, checkOutLat, checkOutLng, checkOutDist);
          paramIdx += 9;
          updated++;
        }

        if (values.length > 0) {
          await pool.query(
            `UPDATE shifts SET
              check_in_time = v.ci_time,
              check_out_time = v.co_time,
              last_check_in_lat = v.ci_lat,
              last_check_in_lng = v.ci_lng,
              check_in_distance_metres = v.ci_dist,
              last_check_out_lat = v.co_lat,
              last_check_out_lng = v.co_lng,
              check_out_distance_metres = v.co_dist
            FROM (VALUES ${values.join(",")})
              AS v(sid, ci_time, co_time, ci_lat, ci_lng, ci_dist, co_lat, co_lng, co_dist)
            WHERE shifts.id = v.sid::int`,
            params
          );
        }
      }

      res.json({ message: `Backfill complete. Updated ${updated} shifts, skipped ${skipped} (already had check-in data).` });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

