  app.post("/api/admin/fix-invoice-1517", requireRole("super_admin", "tenant_admin"), async (req, res) => {
    const client = await pool.connect();
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant associated" });

      await client.query("BEGIN");

      const { rows: invRows } = await client.query(
        `SELECT id, invoice_number, total_amount::numeric as total_amount, status, supplier_id FROM invoices WHERE id = 1517 AND tenant_id = $1`,
        [user.tenantId]
      );
      if (invRows.length === 0) {
        await client.query("ROLLBACK");
        return res.status(404).json({ message: "Invoice 1517 not found for this tenant" });
      }
      const invoice = invRows[0];

      if (invoice.status === "paid") {
        await client.query("ROLLBACK");
        return res.status(400).json({ message: "Invoice 1517 is already paid" });
      }

      if (invoice.supplier_id !== 14) {
        await client.query("ROLLBACK");
        return res.status(400).json({ message: "Invoice 1517 supplier mismatch - expected supplier 14 (DELTA FORCE GROUP LTD)" });
      }

      const invoiceTotal = parseFloat(invoice.total_amount);

      const { rows: allocRows } = await client.query(
        `SELECT id, amount::numeric as amount, bank_transaction_id, invoice_id FROM bank_transaction_allocations WHERE id = 1197 AND tenant_id = $1 AND invoice_id = 1517`,
        [user.tenantId]
      );
      if (allocRows.length === 0) {
        await client.query("ROLLBACK");
        return res.status(404).json({ message: "Allocation 1197 not found for this tenant/invoice" });
      }
      const oldAllocAmount = parseFloat(allocRows[0].amount);
      const bankTxId = allocRows[0].bank_transaction_id;

      if (bankTxId !== 5601) {
        await client.query("ROLLBACK");
        return res.status(400).json({ message: `Allocation 1197 linked to unexpected bank transaction ${bankTxId} - expected 5601` });
      }

      const { rows: btRows } = await client.query(
        `SELECT id, ABS(amount::numeric) as abs_amount FROM bank_transactions WHERE id = $1 AND tenant_id = $2`,
        [bankTxId, user.tenantId]
      );
      if (btRows.length === 0) {
        await client.query("ROLLBACK");
        return res.status(404).json({ message: "Bank transaction not found for this tenant" });
      }

      const allocDiff = Math.round((invoiceTotal - oldAllocAmount) * 100) / 100;

      await client.query(
        `UPDATE bank_transaction_allocations SET amount = $1 WHERE id = 1197 AND tenant_id = $2`,
        [invoiceTotal.toFixed(2), user.tenantId]
      );

      const { rows: btAllocSum } = await client.query(
        `SELECT COALESCE(SUM(amount::numeric), 0) as total FROM bank_transaction_allocations WHERE bank_transaction_id = $1 AND tenant_id = $2`,
        [bankTxId, user.tenantId]
      );
      const newBtAllocated = parseFloat(btAllocSum[0].total);

      const btAbsAmount = parseFloat(btRows[0].abs_amount);
      const fullyAllocated = newBtAllocated >= btAbsAmount - 0.01;

      await client.query(
        `UPDATE bank_transactions SET allocated_amount = $1, is_allocated = $2 WHERE id = $3 AND tenant_id = $4`,
        [newBtAllocated.toFixed(2), fullyAllocated, bankTxId, user.tenantId]
      );

      await client.query(
        `UPDATE invoices SET status = 'paid', paid_at = $1, payment_date = $2 WHERE id = 1517 AND tenant_id = $3`,
        [new Date('2023-01-25'), '2023-01-25', user.tenantId]
      );

      await client.query(
        `INSERT INTO audit_logs (tenant_id, user_id, action, entity_type, entity_id, details) VALUES ($1, $2, $3, $4, $5, $6)`,
        [
          user.tenantId, user.id, "invoice_payment_fix", "invoice", "1517",
          JSON.stringify({
            invoiceNumber: "SBI-GUA-202212-0345",
            allocationId: 1197,
            bankTransactionId: bankTxId,
            oldAllocationAmount: oldAllocAmount.toFixed(2),
            newAllocationAmount: invoiceTotal.toFixed(2),
            allocationDifference: allocDiff.toFixed(2),
            invoiceTotal: invoiceTotal.toFixed(2),
            paymentDate: "2023-01-25",
            statusChange: `${invoice.status} -> paid`,
          }),
        ]
      );

      await client.query("COMMIT");

      res.json({
        success: true,
        message: "Invoice 1517 fixed successfully",
        details: {
          invoiceNumber: "SBI-GUA-202212-0345",
          oldAllocationAmount: oldAllocAmount.toFixed(2),
          newAllocationAmount: invoiceTotal.toFixed(2),
          allocationDifference: allocDiff.toFixed(2),
          newStatus: "paid",
          paymentDate: "2023-01-25",
          bankTransactionAllocated: newBtAllocated.toFixed(2),
          bankTransactionFullyAllocated: fullyAllocated,
        },
      });
    } catch (err: any) {
      await client.query("ROLLBACK").catch(() => {});
      console.error("fix-invoice-1517 error:", err);
      res.status(500).json({ message: err.message });
    } finally {
      client.release();
    }
  });

  app.post("/api/admin/migrate-nv-invoices", requireRole("super_admin", "tenant_admin"), async (req, res) => {
    const user = req.user as User;
    if (!user?.tenantId) return res.status(401).json({ message: "Not authenticated" });
    const tenantId = user.tenantId;
    const client = await pool.connect();
    try {
      await client.query("BEGIN");

      await client.query(`
        CREATE TABLE IF NOT EXISTS invoice_number_audit_log (
          id SERIAL PRIMARY KEY,
          invoice_id INTEGER NOT NULL REFERENCES invoices(id),
          old_number TEXT NOT NULL,
          new_number TEXT NOT NULL,
          series TEXT NOT NULL,
          reason TEXT,
          changed_at TIMESTAMP DEFAULT NOW()
        )
      `);
      await client.query(`CREATE INDEX IF NOT EXISTS idx_inv_num_audit_invoice ON invoice_number_audit_log(invoice_id)`);
      await client.query(`CREATE INDEX IF NOT EXISTS idx_inv_num_audit_series ON invoice_number_audit_log(series)`);

      const invoiceIdsToMove = [1595, 1596, 1597, 1598, 1601, 1602, 1603, 1604, 1605, 1599, 1600, 1606];

      const verifyResult = await client.query(
        `SELECT i.id, i.invoice_number, i.period_start, i.vat_amount, s.company_name
         FROM invoices i
         JOIN suppliers s ON i.supplier_id = s.id
         WHERE i.id = ANY($1) AND i.tenant_id = $2
         ORDER BY i.id`,
        [invoiceIdsToMove, tenantId]
      );

      if (verifyResult.rows.length !== 12) {
        await client.query("ROLLBACK");
        return res.status(400).json({
          message: `Expected 12 invoices to move, found ${verifyResult.rows.length}`,
        });
      }

      for (const row of verifyResult.rows) {
        if (parseFloat(row.vat_amount) !== 0) {
          await client.query("ROLLBACK");
          return res.status(400).json({
            message: `Invoice ${row.id} (${row.invoice_number}) has non-zero VAT: ${row.vat_amount}`,
          });
        }
        if (!row.invoice_number.startsWith("SBI-GUA-")) {
          await client.query("ROLLBACK");
          return res.status(400).json({
            message: `Invoice ${row.id} (${row.invoice_number}) is not in GUA series`,
          });
        }
      }

      const existingNvResult = await client.query(
        `SELECT i.id, i.invoice_number, i.period_start, s.company_name
         FROM invoices i
         JOIN suppliers s ON i.supplier_id = s.id
         WHERE i.invoice_number LIKE 'SBI-NV-%' AND i.tenant_id = $1
         ORDER BY i.period_start, s.company_name, i.id`,
        [tenantId]
      );

      const allNvInvoices = [
        ...existingNvResult.rows.map((r: any) => ({
          id: r.id,
          invoiceNumber: r.invoice_number,
          periodStart: r.period_start,
          companyName: r.company_name,
          source: "existing-nv",
        })),
        ...verifyResult.rows.map((r: any) => ({
          id: r.id,
          invoiceNumber: r.invoice_number,
          periodStart: r.period_start,
          companyName: r.company_name,
          source: "moved-from-gua",
        })),
      ];

      allNvInvoices.sort((a, b) => {
        const dateA = new Date(a.periodStart).getTime();
        const dateB = new Date(b.periodStart).getTime();
        if (dateA !== dateB) return dateA - dateB;
        const nameCompare = a.companyName.localeCompare(b.companyName);
        if (nameCompare !== 0) return nameCompare;
        return a.id - b.id;
      });

      if (allNvInvoices.length !== 70) {
        await client.query("ROLLBACK");
        return res.status(400).json({
          message: `Expected 70 total NV invoices (58 existing + 12 moved), got ${allNvInvoices.length}`,
        });
      }

      let seq = 111;
      let currentMonth = "";
      const mappings: Array<{ id: number; oldNumber: string; newNumber: string; source: string }> = [];

      for (let i = 0; i < allNvInvoices.length; i++) {
        const inv = allNvInvoices[i];
        const invMonth = new Date(inv.periodStart).toISOString().substring(0, 7);

        if (currentMonth !== "" && invMonth !== currentMonth) {
          seq += 3;
        }
        currentMonth = invMonth;

        const periodLabel = invMonth.replace("-", "");
        const newNumber = `SBI-NV-${periodLabel}-${String(seq).padStart(4, "0")}`;

        mappings.push({
          id: inv.id,
          oldNumber: inv.invoiceNumber,
          newNumber,
          source: inv.source,
        });

        seq++;
      }

      for (const m of mappings) {
        await client.query(
          `UPDATE invoices SET invoice_number = $1, updated_at = NOW() WHERE id = $2 AND tenant_id = $3`,
          [m.newNumber, m.id, tenantId]
        );

        const reason = m.source === "moved-from-gua"
          ? "Moved from SBI-GUA to SBI-NV (non-VAT supplier, £0 VAT)"
          : "Renumbered as part of NV series consolidation";

        await client.query(
          `INSERT INTO invoice_number_audit_log (invoice_id, old_number, new_number, series, reason)
           VALUES ($1, $2, $3, 'SBI-NV', $4)`,
          [m.id, m.oldNumber, m.newNumber, reason]
        );
      }

      const verifyFinalResult = await client.query(
        `SELECT i.id, i.invoice_number, i.period_start, s.company_name
         FROM invoices i
         JOIN suppliers s ON i.supplier_id = s.id
         WHERE i.invoice_number LIKE 'SBI-NV-%' AND i.tenant_id = $1
         ORDER BY CAST(SUBSTRING(i.invoice_number FROM '[0-9]+$') AS INT)`,
        [tenantId]
      );

      let orderValid = true;
      let prevDate = "";
      for (const row of verifyFinalResult.rows) {
        const d = new Date(row.period_start).toISOString().substring(0, 10);
        if (d < prevDate) {
          orderValid = false;
          break;
        }
        prevDate = d;
      }

      if (!orderValid) {
        await client.query("ROLLBACK");
        return res.status(500).json({ message: "Post-migration chronological order check failed" });
      }

      await client.query("COMMIT");

      const moved = mappings.filter(m => m.source === "moved-from-gua");
      const renumbered = mappings.filter(m => m.oldNumber !== m.newNumber);

      res.json({
        success: true,
        totalNvInvoices: allNvInvoices.length,
        movedFromGua: moved.length,
        renumbered: renumbered.length,
        mappings: mappings.map(m => ({
          invoiceId: m.id,
          oldNumber: m.oldNumber,
          newNumber: m.newNumber,
          changed: m.oldNumber !== m.newNumber,
          source: m.source,
        })),
      });
    } catch (err: any) {
      await client.query("ROLLBACK").catch(() => {});
      console.error("migrate-nv-invoices error:", err);
      res.status(500).json({ message: err.message });
    } finally {
      client.release();
    }
  });

  app.get("/api/admin/invoice-number-audit-log", requireRole("super_admin", "tenant_admin", "ceo", "admin", "accountant"), async (req, res) => {
    const user = req.user as User;
    if (!user?.tenantId) return res.status(401).json({ message: "Not authenticated" });
    const tenantId = user.tenantId;
    try {
      const tableExists = await pool.query(
        `SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'invoice_number_audit_log') as exists`
      );
      if (!tableExists.rows[0].exists) {
        return res.json({ entries: [], totalCount: 0 });
      }

      const series = req.query.series as string | undefined;
      let query = `
        SELECT inal.id, inal.invoice_id, inal.old_number, inal.new_number,
               inal.series, inal.reason, inal.changed_at,
               s.company_name as supplier_name, i.period_start, i.period_end
        FROM invoice_number_audit_log inal
        JOIN invoices i ON i.id = inal.invoice_id
        JOIN suppliers s ON s.id = i.supplier_id
        WHERE i.tenant_id = $1
      `;
      const params: any[] = [tenantId];
      if (series) {
        params.push(series);
        query += ` AND inal.series = $${params.length}`;
      }
      query += ` ORDER BY inal.changed_at DESC, inal.id DESC`;

      const result = await pool.query(query, params);

      res.json({
        entries: result.rows.map((r: any) => ({
          id: r.id,
          invoiceId: r.invoice_id,
          oldNumber: r.old_number,
          newNumber: r.new_number,
          series: r.series,
          reason: r.reason,
          changedAt: r.changed_at,
          supplierName: r.supplier_name,
          periodStart: r.period_start,
          periodEnd: r.period_end,
        })),
        totalCount: result.rows.length,
      });
    } catch (err: any) {
      if (err.message?.includes("does not exist")) {
        return res.json({ entries: [], totalCount: 0 });
      }
      console.error("invoice-number-audit-log error:", err);
      res.status(500).json({ message: err.message });
    }
  });
