  // Available employees suggestions for shift creation
  app.get("/api/shifts/available-employees", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "controller", "scheduler", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const { date, startTime, endTime, siaLicenseType } = req.query as Record<string, string>;
      if (!date || !startTime || !endTime) return res.status(400).json({ message: "date, startTime, endTime required" });

      const allEmployees = await storage.getEmployeesByTenant(user.tenantId);
      const tenantAvailability = await storage.getAvailabilityByTenant(user.tenantId);

      const shiftDayOfWeek = new Date(date + "T00:00:00").getDay();

      const approvedLeaveOnDate = await storage.getApprovedTimeOffForDateRange(user.tenantId!, date, date);
      const approvedLeaveEmpIds = new Set(approvedLeaveOnDate.map(r => r.employeeId));

      const result = await Promise.all(allEmployees.map(async (emp) => {
        const u = emp.userId ? await storage.getUser(emp.userId) : null;
        const empAvailability = tenantAvailability.filter(a => a.employeeId === emp.id);
        const dayAvail = empAvailability.find(a => a.dayOfWeek === shiftDayOfWeek);
        const isAvailable = !dayAvail || dayAvail.isAvailable;

        const { conflict, conflictingShift } = await checkShiftConflict(user.tenantId!, emp.id, date, startTime, endTime);

        const licenseMatch = !siaLicenseType || !emp.siaLicenseType || emp.siaLicenseType === siaLicenseType;

        const onApprovedLeave = approvedLeaveEmpIds.has(emp.id);

        return {
          id: emp.id,
          name: u ? `${u.firstName} ${u.lastName}` : "Unknown",
          jobTitle: emp.jobTitle,
          siaLicenseType: emp.siaLicenseType,
          siaExpiryDate: emp.siaExpiryDate,
          hasFirstAid: emp.hasFirstAid,
          postcode: emp.postcode,
          hasConflict: conflict,
          conflictingShift: conflict ? conflictingShift : null,
          onApprovedLeave,
          markedAvailable: isAvailable,
          availabilityNote: dayAvail ? (dayAvail.isAvailable ? (dayAvail.startTime && dayAvail.endTime ? `Prefers ${dayAvail.startTime}–${dayAvail.endTime}` : "Available") : "Marked unavailable") : "No preference set",
          licenseMatch,
        };
      }));

      const sorted = result.sort((a, b) => {
        const scoreA = (a.markedAvailable ? 2 : 0) + (!a.hasConflict ? 4 : 0) + (!a.onApprovedLeave ? 3 : 0) + (a.licenseMatch ? 1 : 0);
        const scoreB = (b.markedAvailable ? 2 : 0) + (!b.hasConflict ? 4 : 0) + (!b.onApprovedLeave ? 3 : 0) + (b.licenseMatch ? 1 : 0);
        return scoreB - scoreA;
      });

      res.json(sorted);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

