  app.post("/api/shift-templates/:id/apply", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "controller", "scheduler", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const id = parseInt(req.params.id);
      const template = await storage.getShiftTemplate(id, user.tenantId);
      if (!template) return res.status(404).json({ message: "Template not found" });
      const { startDate, endDate } = req.body;
      if (!startDate || !endDate) return res.status(400).json({ message: "startDate and endDate required" });

      const start = new Date(startDate + "T00:00:00");
      const end = new Date(endDate + "T00:00:00");
      if (isNaN(start.getTime()) || isNaN(end.getTime())) return res.status(400).json({ message: "Invalid dates" });
      if (end < start) return res.status(400).json({ message: "endDate must be after startDate" });
      const diffDays = Math.round((end.getTime() - start.getTime()) / 86400000) + 1;
      if (diffDays > 90) return res.status(400).json({ message: "Date range cannot exceed 90 days" });

      const shiftsToCreate: any[] = [];
      for (let i = 0; i < diffDays; i++) {
        const d = new Date(start);
        d.setDate(d.getDate() + i);
        const dayOfWeek = d.getDay();
        if (template.daysOfWeek.includes(dayOfWeek)) {
          const dateStr = d.toISOString().split("T")[0];
          for (let c = 0; c < template.requiredCount; c++) {
            shiftsToCreate.push({
              tenantId: user.tenantId,
              siteId: template.siteId || null,
              title: template.title,
              date: dateStr,
              startTime: template.startTime,
              endTime: template.endTime,
              notes: template.notes || null,
              status: "scheduled",
              createdBy: user.id,
            });
          }
        }
      }

      if (shiftsToCreate.length === 0) {
        return res.json({ created: 0, message: "No matching days found in the date range" });
      }
      if (shiftsToCreate.length > 200) {
        return res.status(400).json({ message: "Too many shifts to create (max 200). Reduce date range." });
      }

      const created = await storage.createShiftsBulk(shiftsToCreate);
      res.json({ created: created.length, shifts: created });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

