  app.patch("/api/officers/me", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee profile not found" });

      const SENSITIVE_FIELDS = [
        "role", "hourlyRate", "siaLicenseNumber", "siaLicenseType", "siaExpiryDate",
        "dbsCertificateNumber", "dbsIssueDate", "nationalInsurance", "tenantId",
        "supplierId", "employeeNumber", "portalAccessEnabled", "isActive",
        "password", "email", "username",
      ];

      const ALLOWED_USER_FIELDS = ["phone"] as const;
      const ALLOWED_EMPLOYEE_FIELDS = [
        "addressLine1", "addressLine2", "city", "county", "postcode", "country",
        "uniformSize", "bootSize", "equipmentNotes",
      ] as const;

      const { emergencyContact, ...profileBody } = req.body;

      const rejectedFields = SENSITIVE_FIELDS.filter(f => f in profileBody);
      if (rejectedFields.length > 0) {
        return res.status(400).json({
          message: `Modification of the following fields is not allowed: ${rejectedFields.join(", ")}`,
        });
      }

      const userUpdate: Record<string, any> = {};
      for (const field of ALLOWED_USER_FIELDS) {
        if (field in profileBody) userUpdate[field] = profileBody[field];
      }

      const employeeUpdate: Record<string, any> = {};
      for (const field of ALLOWED_EMPLOYEE_FIELDS) {
        if (field in profileBody) employeeUpdate[field] = profileBody[field];
      }

      let updatedUser = user;
      if (Object.keys(userUpdate).length > 0) {
        updatedUser = (await storage.updateUser(user.id, userUpdate)) || user;
      }

      let updatedEmployee = employee;
      if (Object.keys(employeeUpdate).length > 0) {
        updatedEmployee = (await storage.updateEmployee(employee.id, employeeUpdate)) || employee;
      }

      let updatedEmergencyContacts = await storage.getEmergencyContacts(employee.id);
      if (emergencyContact && typeof emergencyContact === "object") {
        const { id: ecId, ...ecData } = emergencyContact;
        if (ecId) {
          const existing = updatedEmergencyContacts.find(c => c.id === ecId);
          if (!existing || existing.employeeId !== employee.id) {
            return res.status(400).json({ message: "Emergency contact not found or does not belong to you" });
          }
          await storage.updateEmergencyContact(ecId, ecData);
        } else {
          await storage.createEmergencyContact({ ...ecData, employeeId: employee.id });
        }
        updatedEmergencyContacts = await storage.getEmergencyContacts(employee.id);
      }

      const { password: _, ...safeUser } = updatedUser;
      res.json({ ...safeUser, employee: updatedEmployee, emergencyContacts: updatedEmergencyContacts });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

