  app.post("/api/officers/me/shifts/:id/book-on", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee profile not found" });
      const shiftId = parseInt(req.params.id);
      const shift = await storage.getShift(shiftId);
      if (!shift) return res.status(404).json({ message: "Shift not found" });
      if (shift.employeeId !== employee.id) return res.status(403).json({ message: "This shift is not assigned to you" });
      if (shift.status !== "scheduled") return res.status(400).json({ message: "Only scheduled shifts can be checked into" });
      const today = new Date().toISOString().split("T")[0];
      if (shift.date !== today) return res.status(400).json({ message: "You can only check in on the day of the shift" });

      const tenant = user.tenantId ? await storage.getTenant(user.tenantId) : null;
      const timeWindowMin = (tenant as any)?.checkinTimeWindowMinutes ?? 10;
      let geofenceRadius = (tenant as any)?.geofenceRadiusMetres ?? 200;

      const now = new Date();
      const [startH, startM] = (shift.startTime || "00:00").split(":").map(Number);
      const shiftStart = new Date(now);
      shiftStart.setHours(startH, startM, 0, 0);
      const diffMinutes = (now.getTime() - shiftStart.getTime()) / 60000;
      if (diffMinutes < -timeWindowMin) {
        return res.status(400).json({ message: `Too early to check in. You can check in from ${timeWindowMin} minutes before your shift starts at ${shift.startTime}.` });
      }
      if (diffMinutes > timeWindowMin) {
        return res.status(400).json({ message: `Check-in window has passed. Your shift started at ${shift.startTime} and the ${timeWindowMin}-minute window has expired. Contact your manager.` });
      }

      const { lat, lng } = req.body;
      if (!lat || !lng || isNaN(parseFloat(lat)) || isNaN(parseFloat(lng))) {
        return res.status(400).json({ message: "Location is required for check-in. Please enable GPS and try again." });
      }
      const parsedLat = parseFloat(lat);
      const parsedLng = parseFloat(lng);
      if (parsedLat < -90 || parsedLat > 90 || parsedLng < -180 || parsedLng > 180) {
        return res.status(400).json({ message: "Invalid GPS coordinates." });
      }
      let distanceMetres: number | null = null;
      let withinRange = true;
      if (shift.siteId) {
        const site = await storage.getSite(shift.siteId);
        if ((site as any)?.geofenceRadiusMetres != null) geofenceRadius = (site as any).geofenceRadiusMetres;
        if (site?.latitude && site?.longitude) {
          distanceMetres = Math.round(haversineDistanceMetres(parsedLat, parsedLng, parseFloat(site.latitude), parseFloat(site.longitude)) * 100) / 100;
          if (distanceMetres > geofenceRadius) withinRange = false;
        }
      }

      const existingOpsChecks = await storage.getOpsChecksForShift(shiftId);
      const passedCheck = existingOpsChecks.find(c => c.allPassed === true && c.employeeId === employee.id);
      if (!passedCheck) {
        return res.status(400).json({ message: "Pre-shift ops check must be completed with all items passed before checking in. Please complete the ops check first." });
      }

      const updated = await storage.updateShift(shiftId, {
        status: "in_progress",
        checkInTime: now,
        lastCheckInLat: String(parsedLat),
        lastCheckInLng: String(parsedLng),
        checkInDistanceMetres: distanceMetres != null ? String(distanceMetres) : null,
      } as any);
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "employee_self_checkin",
        entityType: "shift",
        entityId: String(shiftId),
        details: { employeeId: employee.id, lat: parsedLat, lng: parsedLng, distanceMetres, withinRange, source: "mobile_app" },
      });
      res.json({ ...updated, distanceFromSite: distanceMetres, withinRange, geofenceRadius });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/officers/me/shifts/:id/book-off", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee profile not found" });
      const shiftId = parseInt(req.params.id);
      const shift = await storage.getShift(shiftId);
      if (!shift) return res.status(404).json({ message: "Shift not found" });
      if (shift.employeeId !== employee.id) return res.status(403).json({ message: "This shift is not assigned to you" });
      if (shift.status !== "in_progress") return res.status(400).json({ message: "Only in-progress shifts can be checked out of" });

      const tenant = user.tenantId ? await storage.getTenant(user.tenantId) : null;
      const timeWindowMin = (tenant as any)?.checkinTimeWindowMinutes ?? 10;
      let geofenceRadius = (tenant as any)?.geofenceRadiusMetres ?? 200;

      const now = new Date();
      const [endH, endM] = (shift.endTime || "23:59").split(":").map(Number);
      const shiftEnd = new Date(now);
      shiftEnd.setHours(endH, endM, 0, 0);
      if (shiftEnd <= (shift.checkInTime || now)) {
        shiftEnd.setDate(shiftEnd.getDate() + 1);
      }
      const diffMinutes = (now.getTime() - shiftEnd.getTime()) / 60000;
      if (diffMinutes < -timeWindowMin) {
        return res.status(400).json({ message: `Too early to check out. You can check out from ${timeWindowMin} minutes before your shift ends at ${shift.endTime}.` });
      }
      if (diffMinutes > timeWindowMin) {
        return res.status(400).json({ message: `Check-out window has passed. Your shift ended at ${shift.endTime} and the ${timeWindowMin}-minute window has expired. Contact your manager.` });
      }

      const { lat, lng, handoverNotes } = req.body;
      if (!lat || !lng || isNaN(parseFloat(lat)) || isNaN(parseFloat(lng))) {
        return res.status(400).json({ message: "Location is required for check-out. Please enable GPS and try again." });
      }
      const parsedLat = parseFloat(lat);
      const parsedLng = parseFloat(lng);
      if (parsedLat < -90 || parsedLat > 90 || parsedLng < -180 || parsedLng > 180) {
        return res.status(400).json({ message: "Invalid GPS coordinates." });
      }
      let distanceMetres: number | null = null;
      let withinRange = true;
      if (shift.siteId) {
        const site = await storage.getSite(shift.siteId);
        if ((site as any)?.geofenceRadiusMetres != null) geofenceRadius = (site as any).geofenceRadiusMetres;
        if (site?.latitude && site?.longitude) {
          distanceMetres = Math.round(haversineDistanceMetres(parsedLat, parsedLng, parseFloat(site.latitude), parseFloat(site.longitude)) * 100) / 100;
          if (distanceMetres > geofenceRadius) withinRange = false;
        }
      }

      const updated = await storage.updateShift(shiftId, {
        status: "completed",
        checkOutTime: now,
        lastCheckOutLat: String(parsedLat),
        lastCheckOutLng: String(parsedLng),
        checkOutDistanceMetres: distanceMetres != null ? String(distanceMetres) : null,
        ...(handoverNotes ? { handoverNotes } : {}),
      } as any);
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "employee_self_checkout",
        entityType: "shift",
        entityId: String(shiftId),
        details: { employeeId: employee.id, lat: parsedLat, lng: parsedLng, distanceMetres, withinRange, source: "mobile_app" },
      });
      res.json({ ...updated, distanceFromSite: distanceMetres, withinRange, geofenceRadius });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/officers/me/shifts/:id/ops-check", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee profile not found" });
      const shiftId = parseInt(req.params.id);
      const { checklist, notes } = req.body;
      if (!checklist) return res.status(400).json({ message: "Checklist is required" });
      if (!Array.isArray(checklist) || checklist.length === 0) return res.status(400).json({ message: "Checklist must be a non-empty array" });
      const shift = await storage.getShift(shiftId);
      if (!shift) return res.status(404).json({ message: "Shift not found" });
      if (shift.tenantId !== user.tenantId) return res.status(403).json({ message: "Access denied" });
      if (shift.employeeId !== employee.id) return res.status(403).json({ message: "This shift is not assigned to you" });

      const tenantItems = await storage.getOpsCheckItems(user.tenantId!);
      const requiredItems = tenantItems.length > 0
        ? tenantItems
        : [
            { id: -1, label: "SIA Licence" },
            { id: -2, label: "DBS Certificate" },
            { id: -3, label: "Uniform" },
            { id: -4, label: "Equipment" },
            { id: -5, label: "Welfare Check" },
          ];

      if (checklist.length < requiredItems.length) {
        return res.status(400).json({ message: `Checklist must contain all ${requiredItems.length} required items` });
      }

      for (const item of checklist) {
        if (!item.label || typeof item.checked !== "boolean") {
          return res.status(400).json({ message: "Each checklist item must have a label and checked boolean" });
        }
      }

      for (const required of requiredItems) {
        const submitted = checklist.find((c: { itemId?: number; label: string }) =>
          c.itemId === required.id || c.label === required.label
        );
        if (!submitted || !submitted.checked) {
          return res.status(400).json({ message: `Required item "${required.label}" must be checked` });
        }
      }

      const check = await storage.createOpsCheck({
        tenantId: user.tenantId!,
        employeeId: employee.id,
        shiftId,
        checklist,
        allPassed: true,
        notes: notes || null,
        completedAt: new Date(),
      });
      res.json(check);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

