  app.get("/api/officers/me/conversations/:id/messages", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const channelId = parseInt(req.params.id);
      if (isNaN(channelId)) return res.status(400).json({ message: "Invalid conversation ID" });
      const members = await storage.getChannelMembers(channelId);
      if (!members.some(m => m.userId === user.id)) return res.status(403).json({ message: "Not a member" });
      const msgs = await storage.getMessages(channelId, 200);
      const senderIds = [...new Set(msgs.map(m => m.senderId))];
      const senderMap: Record<string, User> = {};
      for (const sid of senderIds) {
        if (sid) {
          const u = await storage.getUser(sid);
          if (u) senderMap[sid] = u;
        }
      }
      res.json(msgs.map(m => ({
        id: m.id,
        conversationId: channelId,
        senderId: m.senderId,
        senderName: m.senderId && senderMap[m.senderId] ? `${senderMap[m.senderId].firstName || ""} ${senderMap[m.senderId].lastName || ""}`.trim() || senderMap[m.senderId].username : "Unknown",
        content: m.content,
        createdAt: m.createdAt,
      })));
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/officers/me/conversations/:id/messages", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const channelId = parseInt(req.params.id);
      if (isNaN(channelId)) return res.status(400).json({ message: "Invalid conversation ID" });
      const members = await storage.getChannelMembers(channelId);
      if (!members.some(m => m.userId === user.id)) return res.status(403).json({ message: "Not a member" });
      const { content } = req.body;
      if (!content?.trim()) return res.status(400).json({ message: "Message content is required" });
      const senderName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.username;
      const msg = await storage.createMessage({
        channelId,
        senderId: user.id,
        senderName,
        content: content.trim(),
        isEdited: false,
        fileUrl: null,
        fileName: null,
        fileType: null,
        fileSize: null,
      });
      if (io) {
        io.to(`channel_${channelId}`).emit("new-message", msg);
      }
      res.status(201).json({
        id: msg.id,
        conversationId: channelId,
        senderId: msg.senderId,
        senderName,
        content: msg.content,
        createdAt: msg.createdAt,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

