  app.get("/api/officers/me/broadcasts", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.json([]);
      const allBroadcasts = await storage.getBroadcastsByTenant(user.tenantId);
      const userRole = user.role;
      const relevantBroadcasts = allBroadcasts.filter(b => {
        if (!b.targetRoles || b.targetRoles.length === 0) return true;
        return b.targetRoles.includes(userRole);
      });
      const results = await Promise.all(relevantBroadcasts.map(async (b) => {
        const hasRead = await storage.hasUserReadBroadcast(b.id, user.id);
        const reads = hasRead ? await storage.getBroadcastReads(b.id) : [];
        const userRead = reads.find(r => r.userId === user.id);
        return {
          id: b.id,
          title: b.title,
          body: b.content,
          senderName: b.senderName,
          createdAt: b.createdAt,
          readAt: hasRead ? (userRead?.readAt || b.createdAt) : null,
        };
      }));
      res.json(results);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

