  app.post("/api/officers/me/requests", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee record not found" });
      const { type, startDate, endDate, reason } = req.body;
      if (!type || !startDate || !endDate) return res.status(400).json({ message: "type, startDate, and endDate are required" });
      const validTypes = ["annual_leave", "sick_leave", "unpaid_leave", "other"];
      const leaveType = type === "unpaid_leave" ? "personal" : type === "other" ? "personal" : validTypes.includes(type) ? type : null;
      if (!leaveType) return res.status(400).json({ message: "Invalid request type" });
      const start = new Date(startDate);
      const end = new Date(endDate);
      if (isNaN(start.getTime()) || isNaN(end.getTime())) return res.status(400).json({ message: "Invalid dates" });
      if (end < start) return res.status(400).json({ message: "End date must be on or after start date" });
      const totalDays = Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;
      const request = await storage.createTimeOffRequest({
        employeeId: employee.id,
        tenantId: user.tenantId,
        leaveType,
        startDate,
        endDate,
        totalDays,
        notes: reason || null,
        status: "pending",
        requestedByUserId: user.id,
        reviewedByUserId: null,
        reviewedAt: null,
        reviewNote: null,
      });
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "time_off_request_submitted",
        entityType: "time_off_request",
        entityId: String(request.id),
        details: { leaveType, startDate, endDate, totalDays, source: "mobile_app" },
      });
      res.status(201).json({
        id: request.id,
        type: request.leaveType,
        startDate: request.startDate,
        endDate: request.endDate,
        reason: request.notes,
        status: request.status,
        createdAt: request.createdAt,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.use("/api/officers", (req, res, next) => {
    if (!res.headersSent) {
      res.status(404).json({ error: "Not found" });
    }
  });

  // ===================== TIME-OFF ROUTES =====================

  // Officer submits a time-off request
  app.post("/api/time-off/request", requireRole("employee", "super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "controller", "scheduler", "hr_manager", "compliance_manager", "accountant", "payroll_manager", "training_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee record not found" });

      const { leaveType, startDate, endDate, notes } = req.body;
      if (!leaveType || !startDate || !endDate) {
        return res.status(400).json({ message: "leaveType, startDate, and endDate are required" });
      }
      const validLeaveTypes = ["annual_leave", "sick_leave", "personal", "training"];
      if (!validLeaveTypes.includes(leaveType)) {
        return res.status(400).json({ message: "Invalid leave type" });
      }

      const start = new Date(startDate);
      const end = new Date(endDate);
      if (isNaN(start.getTime()) || isNaN(end.getTime())) {
        return res.status(400).json({ message: "Invalid dates" });
      }
      if (end < start) {
        return res.status(400).json({ message: "End date must be on or after start date" });
      }
      const totalDays = Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1;

      const request = await storage.createTimeOffRequest({
        employeeId: employee.id,
        tenantId: user.tenantId,
        leaveType,
        startDate,
        endDate,
        totalDays,
        notes: notes || null,
        status: "pending",
        requestedByUserId: user.id,
        reviewedByUserId: null,
        reviewedAt: null,
        reviewNote: null,
      });

      // Audit log
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "time_off_request_submitted",
        entityType: "time_off_request",
        entityId: String(request.id),
        details: { leaveType, startDate, endDate, totalDays },
      });
      const leaveTypeLabelSubmit = leaveType === "annual_leave" ? "Annual Leave" : leaveType === "sick_leave" ? "Sick Leave" : leaveType === "personal" ? "Personal" : "Training";
      await pool.query(
        `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
         VALUES ($1, $2, 'time_off_requested', 'leave', $3, $4, $5, $6)`,
        [employee.id, user.tenantId, "Time-Off Request Submitted", `${leaveTypeLabelSubmit} requested from ${startDate} to ${endDate} (${totalDays} day${totalDays !== 1 ? "s" : ""})`, user.id, `${user.firstName || ""} ${user.lastName || ""}`.trim()]
      ).catch(() => {});

      // Notify admins/managers
      const allUsers = await storage.getUsersByTenant(user.tenantId);
      const adminRoles = ["super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"];
      const managers = allUsers.filter(u => adminRoles.includes(u.role) && u.id !== user.id);
      const leaveTypeLabel = leaveType === "annual_leave" ? "Annual Leave" : leaveType === "sick_leave" ? "Sick Leave" : leaveType === "personal" ? "Personal" : "Training";
      for (const manager of managers) {
        await storage.createNotification({
          userId: manager.id,
          type: "time_off_request",
          title: "New Time-Off Request",
          body: `${user.firstName} ${user.lastName} has requested ${leaveTypeLabel} from ${new Date(startDate).toLocaleDateString("en-GB")} to ${new Date(endDate).toLocaleDateString("en-GB")} (${totalDays} day${totalDays !== 1 ? "s" : ""}).`,
          link: "/admin/leave-requests",
          relatedEntityType: "time_off_request",
          relatedEntityId: String(request.id),
          metadata: { requestId: request.id, employeeName: `${user.firstName} ${user.lastName}`, leaveType, startDate, endDate, totalDays },
        });
      }

      res.status(201).json(request);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // Officer views their own requests
  app.get("/api/time-off/my-requests", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee) return res.status(404).json({ message: "Employee record not found" });
      const requests = await storage.getTimeOffRequestsByEmployee(employee.id);
      res.json(requests);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // Officer cancels their own pending request
  app.post("/api/time-off/:id/cancel", requireAuth, async (req, res) => {
    try {
      const user = req.user as User;
      const id = parseInt(req.params.id);
      const request = await storage.getTimeOffRequest(id);
      if (!request) return res.status(404).json({ message: "Request not found" });
      const employee = await storage.getEmployeeByUserId(user.id);
      if (!employee || request.employeeId !== employee.id) {
        return res.status(403).json({ message: "Forbidden" });
      }
      if (request.status !== "pending") {
        return res.status(400).json({ message: "Only pending requests can be cancelled" });
      }
      const cancelled = await storage.cancelTimeOffRequest(id);

      if (user.tenantId) {
        await storage.createAuditLog({
          tenantId: user.tenantId,
          userId: user.id,
          action: "time_off_request_cancelled",
          entityType: "time_off_request",
          entityId: String(id),
          details: {},
        });
        const leaveTypeLabelCancel = request.leaveType === "annual_leave" ? "Annual Leave" : request.leaveType === "sick_leave" ? "Sick Leave" : request.leaveType === "personal" ? "Personal" : "Training";
        await pool.query(
          `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
           VALUES ($1, $2, 'time_off_cancelled', 'leave', $3, $4, $5, $6)`,
          [employee.id, user.tenantId, "Time-Off Request Cancelled", `${leaveTypeLabelCancel} request from ${request.startDate} to ${request.endDate} cancelled`, user.id, `${user.firstName || ""} ${user.lastName || ""}`.trim()]
        ).catch(() => {});
      }

      res.json(cancelled);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // Admin/manager lists all requests for their tenant
  app.get("/api/admin/time-off-requests", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const status = req.query.status as string | undefined;
      const requests = await storage.getTimeOffRequestsByTenant(user.tenantId, status);

      // Enrich with employee/user info
      const allEmployees = await storage.getEmployeesByTenant(user.tenantId);
      const allUsers = await storage.getUsersByTenant(user.tenantId);
      const empById = Object.fromEntries(allEmployees.map(e => [e.id, e]));
      const userById = Object.fromEntries(allUsers.map(u => [u.id, u]));

      const enriched = requests.map(r => {
        const emp = empById[r.employeeId];
        const empUser = emp?.userId ? userById[emp.userId] : null;
        const reviewer = r.reviewedByUserId ? userById[r.reviewedByUserId] : null;
        return {
          ...r,
          employeeName: empUser ? `${empUser.firstName} ${empUser.lastName}` : "Unknown",
          employeeNumber: emp?.employeeNumber || null,
          reviewerName: reviewer ? `${reviewer.firstName} ${reviewer.lastName}` : null,
        };
      });

      res.json(enriched);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // Admin/manager approves a request
  app.post("/api/admin/time-off-requests/:id/approve", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const id = parseInt(req.params.id);
      const { note } = req.body;
      const request = await storage.getTimeOffRequest(id);
      if (!request) return res.status(404).json({ message: "Request not found" });
      if (request.tenantId !== user.tenantId) return res.status(403).json({ message: "Forbidden" });

      if (request.status !== 'pending') {
        return res.status(409).json({ message: `Cannot approve a request with status '${request.status}'` });
      }
      const approved = await storage.approveTimeOffRequest(id, user.id, note);

      // Audit log
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "time_off_request_approved",
        entityType: "time_off_request",
        entityId: String(id),
        details: { note: note || null },
      });

      // Notify the requesting employee
      const emp = await storage.getEmployee(request.employeeId);
      const leaveTypeLabelApprove = request.leaveType === "annual_leave" ? "Annual Leave" : request.leaveType === "sick_leave" ? "Sick Leave" : request.leaveType === "personal" ? "Personal" : "Training";
      await pool.query(
        `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
         VALUES ($1, $2, 'time_off_approved', 'leave', $3, $4, $5, $6)`,
        [request.employeeId, user.tenantId, "Time-Off Request Approved", `${leaveTypeLabelApprove} from ${request.startDate} to ${request.endDate} approved${note ? `. Note: ${note}` : ""}`, user.id, `${user.firstName || ""} ${user.lastName || ""}`.trim()]
      ).catch(() => {});

      if (emp?.userId) {
        await storage.createNotification({
          userId: emp.userId,
          type: "time_off_reviewed",
          title: "Time-Off Request Approved",
          body: `Your ${leaveTypeLabelApprove} request from ${new Date(request.startDate).toLocaleDateString("en-GB")} to ${new Date(request.endDate).toLocaleDateString("en-GB")} has been approved.${note ? ` Note: ${note}` : ""}`,
          link: "/my-shifts",
          relatedEntityType: "time_off_request",
          relatedEntityId: String(id),
          metadata: { requestId: id, outcome: "approved" },
        });
      }

      res.json(approved);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // Admin/manager rejects a request
  app.post("/api/admin/time-off-requests/:id/reject", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "regional_manager", "admin", "hr_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      if (!user.tenantId) return res.status(400).json({ message: "No tenant" });
      const id = parseInt(req.params.id);
      const { note } = req.body;
      const request = await storage.getTimeOffRequest(id);
      if (!request) return res.status(404).json({ message: "Request not found" });
      if (request.tenantId !== user.tenantId) return res.status(403).json({ message: "Forbidden" });

      if (request.status !== 'pending') {
        return res.status(409).json({ message: `Cannot reject a request with status '${request.status}'` });
      }
      const rejected = await storage.rejectTimeOffRequest(id, user.id, note);

      // Audit log
      await storage.createAuditLog({
        tenantId: user.tenantId,
        userId: user.id,
        action: "time_off_request_rejected",
        entityType: "time_off_request",
        entityId: String(id),
        details: { note: note || null },
      });

      // Notify the requesting employee
      const emp = await storage.getEmployee(request.employeeId);
      const leaveTypeLabelReject = request.leaveType === "annual_leave" ? "Annual Leave" : request.leaveType === "sick_leave" ? "Sick Leave" : request.leaveType === "personal" ? "Personal" : "Training";
      await pool.query(
        `INSERT INTO employee_audit_trail (employee_id, tenant_id, event_type, event_category, title, description, performed_by, performed_by_name)
         VALUES ($1, $2, 'time_off_rejected', 'leave', $3, $4, $5, $6)`,
        [request.employeeId, user.tenantId, "Time-Off Request Rejected", `${leaveTypeLabelReject} from ${request.startDate} to ${request.endDate} rejected${note ? `. Note: ${note}` : ""}`, user.id, `${user.firstName || ""} ${user.lastName || ""}`.trim()]
      ).catch(() => {});

      if (emp?.userId) {
        await storage.createNotification({
          userId: emp.userId,
          type: "time_off_reviewed",
          title: "Time-Off Request Rejected",
          body: `Your ${leaveTypeLabelReject} request from ${new Date(request.startDate).toLocaleDateString("en-GB")} to ${new Date(request.endDate).toLocaleDateString("en-GB")} has been rejected.${note ? ` Note: ${note}` : ""}`,
          link: "/my-shifts",
          relatedEntityType: "time_off_request",
          relatedEntityId: String(id),
          metadata: { requestId: id, outcome: "rejected" },
        });
      }

      res.json(rejected);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

