  app.post("/api/email-command/actions/:id/approve", requireRole(...emailCommandRoles), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const actionId = parseInt(req.params.id);

      const action = await storage.getProposedAction(actionId);
      if (!action || action.tenantId !== tenantId) return res.status(404).json({ message: "Action not found" });
      if (action.status !== "pending") return res.status(400).json({ message: "Action already processed" });

      await storage.updateProposedAction(actionId, {
        status: "approved",
        decidedBy: userId,
        decidedAt: new Date(),
      });

      if (action.learningEventId) {
        await storage.updateAiLearningEvent(action.learningEventId, {
          status: "accepted",
          decidedAt: new Date(),
        });
      }

      try {
        const { executeAction } = await import("./email-action-executor");
        const result = await executeAction(action, tenantId);
        await storage.updateProposedAction(actionId, {
          status: result.success ? "executed" : "failed",
          executionResult: result,
        });
      } catch (execErr: any) {
        await storage.updateProposedAction(actionId, {
          status: "failed",
          executionResult: { success: false, error: execErr.message },
        });
      }

      const updated = await storage.getProposedAction(actionId);
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/email-command/actions/:id/reject", requireRole(...emailCommandRoles), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const actionId = parseInt(req.params.id);
      const { correction, correctedActionType } = req.body;

      if (!correction || typeof correction !== "string" || correction.trim().length === 0) {
        return res.status(400).json({ message: "Correction feedback is required when rejecting an action" });
      }

      const action = await storage.getProposedAction(actionId);
      if (!action || action.tenantId !== tenantId) return res.status(404).json({ message: "Action not found" });
      if (action.status !== "pending") return res.status(400).json({ message: "Action already processed" });

      const fullCorrection = correctedActionType
        ? `[Corrected action: ${correctedActionType}] ${correction}`
        : correction;

      await storage.updateProposedAction(actionId, {
        status: "rejected",
        decidedBy: userId,
        decidedAt: new Date(),
        rejectionReason: fullCorrection,
      });

      if (action.learningEventId) {
        await storage.updateAiLearningEvent(action.learningEventId, {
          status: "rejected",
          feedback: fullCorrection,
          operatorCorrection: fullCorrection,
          decidedAt: new Date(),
        });
      }

      const updated = await storage.getProposedAction(actionId);
      res.json(updated);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

