  app.get("/api/ai-learning/analytics", requireRole(...emailCommandRoles), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const events = await storage.getAiLearningEvents(tenantId, undefined, 500);

      const emailEvents = events.filter(e => e.domain === "email_classification" || e.domain === "email_action");
      const schedulingEvents = events.filter(e => e.domain === "scheduling");

      const accepted = events.filter(e => e.status === "accepted");
      const rejected = events.filter(e => e.status === "rejected");
      const approvalRate = events.length > 0 ? Math.round((accepted.length / (accepted.length + rejected.length)) * 100) : 0;

      const correctionReasons: Record<string, number> = {};
      rejected.forEach(e => {
        if (e.operatorCorrection) {
          const match = e.operatorCorrection.match(/\[Corrected action: (\w+)\]/);
          const key = match ? match[1] : "text_correction";
          correctionReasons[key] = (correctionReasons[key] || 0) + 1;
        }
      });
      const topCorrections = Object.entries(correctionReasons)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([reason, count]) => ({ reason, count }));

      const last7Days = events.filter(e => {
        const created = new Date(e.createdAt);
        return (Date.now() - created.getTime()) < 7 * 24 * 60 * 60 * 1000;
      });
      const last30Days = events.filter(e => {
        const created = new Date(e.createdAt);
        return (Date.now() - created.getTime()) < 30 * 24 * 60 * 60 * 1000;
      });

      const avgConfidence = emailEvents.reduce((sum, e) => {
        const proposal = e.aiProposal as any;
        return sum + (proposal?.confidence || 0);
      }, 0) / (emailEvents.length || 1);

      res.json({
        totalEvents: events.length,
        emailEvents: emailEvents.length,
        schedulingEvents: schedulingEvents.length,
        accepted: accepted.length,
        rejected: rejected.length,
        approvalRate,
        topCorrections,
        last7Days: last7Days.length,
        last30Days: last30Days.length,
        avgConfidence: Math.round(avgConfidence),
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.post("/api/ai-learning/backfill-decisions", requireRole("super_admin", "tenant_admin"), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const userId = req.user!.id;
      const decisions = await storage.getAiDecisions(tenantId, 500);

      let backfilled = 0;
      for (const d of decisions) {
        if (d.status === "accepted" || d.status === "rejected") {
          try {
            await storage.createAiLearningEvent({
              tenantId,
              userId,
              domain: "scheduling",
              inputContext: {
                decisionId: d.id,
                siteName: d.siteName,
                shiftDate: d.shiftDate,
                employeeName: d.employeeName,
                backfilled: true,
              },
              aiProposal: {
                action: d.action,
                employeeName: d.employeeName,
                siteName: d.siteName,
                reason: d.reason,
                confidence: d.confidence,
              },
              status: d.status === "accepted" ? "accepted" : "rejected",
              feedback: d.feedback || null,
              operatorCorrection: d.status === "rejected" ? (d.feedback || null) : null,
              decidedAt: d.decidedAt || new Date(),
              batchId: d.batchId || `backfill_${d.id}`,
            });
            backfilled++;
          } catch (err: any) {
            // skip duplicates
          }
        }
      }

      res.json({ message: `Backfilled ${backfilled} scheduling decisions to unified learning engine`, backfilled, total: decisions.length });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

