  app.post("/api/admin/training-records/bulk-assign", requireRole("super_admin", "tenant_admin", "ceo", "operations_manager", "admin", "hr_manager", "training_manager", "compliance_manager"), async (req, res) => {
    try {
      const user = req.user as User;
      const tenantId = user.tenantId!;
      const { employeeIds, trainingType, trainingName, provider, notes } = req.body;
      if (!Array.isArray(employeeIds) || employeeIds.length === 0) {
        return res.status(400).json({ message: "employeeIds array is required" });
      }
      // Verify all employeeIds belong to this tenant
      const tenantEmployees = await storage.getEmployeesByTenant(tenantId);
      const tenantEmployeeIdSet = new Set(tenantEmployees.map(e => e.id));
      const invalidIds = (employeeIds as number[]).filter(id => !tenantEmployeeIdSet.has(id));
      if (invalidIds.length > 0) {
        return res.status(403).json({ message: "One or more employees do not belong to this tenant" });
      }
      const created = [];
      for (const employeeId of employeeIds) {
        const record = await storage.createTrainingRecord({
          employeeId, tenantId, trainingType, trainingName, provider, notes,
          status: "not_started",
        });
        created.push(record);
      }
      res.status(201).json({ created: created.length, records: created });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });
