  app.get("/api/purchase-ledger/export/csv", requireRole(...LEDGER_ROLES), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { dateFrom, dateTo, source = "all", search = "", period = "" } = req.query as any;

      if (!dateFrom || !dateTo) return res.status(400).json({ message: "dateFrom and dateTo are required" });

      const { sql, params } = getPurchaseLedgerQuery(tenantId, dateFrom, dateTo, source, search);
      const result = await pool.query(sql, params);
      const entries = result.rows;

      const totalNet = entries.reduce((s: number, e: any) => s + parseFloat(e.net_amount || "0"), 0);
      const totalVat = entries.reduce((s: number, e: any) => s + parseFloat(e.vat_amount || "0"), 0);
      const totalGross = entries.reduce((s: number, e: any) => s + parseFloat(e.gross_amount || "0"), 0);

      const SOURCE_LABELS: Record<string, string> = {
        supplier_invoice: "Supplier Invoice",
        bank_general_purchase: "Bank Purchase",
        manual: "Bank Feed",
        financial_document: "Document/Receipt",
      };

      const escCsv = (v: any) => {
        const s = String(v ?? "");
        if (s.includes(",") || s.includes('"') || s.includes("\n")) return `"${s.replace(/"/g, '""')}"`;
        return s;
      };

      const formatDateISO = (d: any): string => {
        if (!d) return "";
        const s = d.toString();
        const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (m) return `${m[1]}-${m[2]}-${m[3]}`;
        const dt = new Date(s);
        if (!isNaN(dt.getTime())) {
          const day = String(dt.getDate()).padStart(2, "0");
          const month = String(dt.getMonth() + 1).padStart(2, "0");
          return `${dt.getFullYear()}-${month}-${day}`;
        }
        return s.substring(0, 10);
      };

      const headers = [
        "Date", "Vendor/Supplier", "Vendor VAT Number", "Description", "Expense Category",
        "Net Amount (GBP)", "VAT Rate (%)", "VAT Amount (GBP)", "Gross Amount (GBP)",
        "VAT Status", "Payment Status", "Bank Reference", "Source",
      ];

      const rows = [
        [`HMRC Purchase Ledger — ${period || `${dateFrom} to ${dateTo}`}`],
        [`Generated: ${new Date().toLocaleDateString("en-GB")}`],
        [],
        headers.map(escCsv),
        ...entries.map((e: any) => [
          formatDateISO(e.purchase_date),
          e.vendor_name || "",
          e.vendor_vat_number || "",
          e.source === "supplier_invoice" ? (e.description || "") : "",
          e.expense_category || "",
          parseFloat(e.net_amount || "0").toFixed(2),
          parseFloat(e.vat_rate || "0").toFixed(2),
          parseFloat(e.vat_amount || "0").toFixed(2),
          parseFloat(e.gross_amount || "0").toFixed(2),
          e.vat_status || "",
          e.payment_status || "",
          e.bank_reference || "",
          SOURCE_LABELS[e.source] || e.source,
        ].map(escCsv)),
        [],
        ["TOTALS", "", "", "", "", totalNet.toFixed(2), "", totalVat.toFixed(2), totalGross.toFixed(2)].map(escCsv),
      ];

      const csvContent = rows.map((r) => r.join(",")).join("\n");
      const fileName = `purchase-ledger-${safeFilename(String(period || dateFrom))}-to-${safeFilename(String(dateTo))}.csv`;

      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
      res.send(csvContent);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  app.get("/api/purchase-ledger/export/pdf", requireRole(...LEDGER_ROLES), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { dateFrom, dateTo, source = "all", search = "", period = "" } = req.query as any;

      if (!dateFrom || !dateTo) return res.status(400).json({ message: "dateFrom and dateTo are required" });

      const { sql, params } = getPurchaseLedgerQuery(tenantId, dateFrom, dateTo, source, search);
      const result = await pool.query(sql, params);
      const entries = result.rows;

      const totalNet = entries.reduce((s: number, e: any) => s + parseFloat(e.net_amount || "0"), 0);
      const totalVat = entries.reduce((s: number, e: any) => s + parseFloat(e.vat_amount || "0"), 0);
      const totalGross = entries.reduce((s: number, e: any) => s + parseFloat(e.gross_amount || "0"), 0);

      // Get tenant name
      const tenantResult = await pool.query("SELECT name FROM tenants WHERE id = $1", [tenantId]);
      const tenantName = tenantResult.rows[0]?.name || "Unknown Company";

      // VAT reconciliation
      let vatReturnInputVat: number | null = null;
      try {
        const vatR = await pool.query(
          `SELECT COALESCE(SUM(i.vat_amount::numeric), 0) as supplier_vat FROM invoices i
           WHERE i.tenant_id = $1 AND i.period_end::date BETWEEN $2::date AND $3::date
             AND i.status != 'cancelled' AND i.supplier_id IS NOT NULL`,
          [tenantId, dateFrom, dateTo]
        );
        const genR = await pool.query(
          `SELECT COALESCE(SUM(COALESCE(vat_amount, 0)::numeric), 0) as gen_vat FROM bank_transactions
           WHERE tenant_id = $1 AND transaction_date::date BETWEEN $2::date AND $3::date AND is_general_purchase = true`,
          [tenantId, dateFrom, dateTo]
        );
        vatReturnInputVat = parseFloat(vatR.rows[0]?.supplier_vat || "0") +
                            parseFloat(genR.rows[0]?.gen_vat || "0");
      } catch (_) {}

      // Look up tenant's selected Purchase Ledger format template
      const ledgerTemplate = await storage.getDefaultTemplate(tenantId, "purchase_ledger");
      const ledgerFormat = (ledgerTemplate as any)?.invoiceFormat || "hmrc_audit";

      const pdfData = {
        tenantName,
        periodLabel: String(period || `${dateFrom} to ${dateTo}`),
        dateFrom: String(dateFrom),
        dateTo: String(dateTo),
        generatedAt: new Date().toLocaleDateString("en-GB"),
        entries,
        totalNet: Math.round(totalNet * 100) / 100,
        totalVat: Math.round(totalVat * 100) / 100,
        totalGross: Math.round(totalGross * 100) / 100,
        vatReturnInputVat,
      };

      const pdfBuffer = ledgerFormat === "accounting_style"
        ? await generatePurchaseLedgerAccountingPdf(pdfData)
        : await generatePurchaseLedgerPdf(pdfData);

      const fileName = `purchase-ledger-${safeFilename(String(period || dateFrom))}-to-${safeFilename(String(dateTo))}.pdf`;
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
      res.send(pdfBuffer);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });


