  app.get("/api/wages-ledger", requireRole(...LEDGER_ROLES), async (req, res) => {
    try {
      const tenantId = req.user!.tenantId!;
      const { search = "", quarter = "", dateFrom = "", dateTo = "" } = req.query as any;

      const conditions: string[] = ["tenant_id = $1"];
      const params: any[] = [tenantId];
      let p = 2;

      if (quarter && quarter !== "all") {
        conditions.push(`vat_quarter = $${p++}`);
        params.push(quarter);
      }
      if (dateFrom) {
        conditions.push(`entry_date >= $${p++}::date`);
        params.push(dateFrom);
      }
      if (dateTo) {
        conditions.push(`entry_date <= $${p++}::date`);
        params.push(dateTo);
      }
      if (search) {
        conditions.push(`description ILIKE $${p++}`);
        params.push(`%${search}%`);
      }

      const where = conditions.join(" AND ");
      const result = await pool.query(
        `SELECT *,
           SUM(gross_amount) OVER (PARTITION BY tenant_id ORDER BY entry_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_total
         FROM wages_ledger WHERE ${where} ORDER BY entry_date DESC, id DESC`,
        params
      );
      const entries = result.rows;
      const total = entries.reduce((s: number, e: any) => s + parseFloat(e.gross_amount || "0"), 0);

      res.json({ entries, total: Math.round(total * 100) / 100, count: entries.length });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

